/**
 * Regression: agent-manager.resolveModelObj() must self-heal when
 * activeModel points at a removed/stale web provider. This protects
 * against the user upgrading from a build that had Kimi/DeepSeek
 * to a build that has only GLM.
 */
import 'fake-indexeddb/auto';
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { resolveSelectedWebModel } from '@/lib/ai-config/web-provider-models';
import { isValidActiveModel } from '@/lib/ai-config/web-provider-active-model-validation';

describe('agent-manager self-heal (resolveModelObj null branch)', () => {
  beforeEach(() => {
    // Reset the in-memory state for the activeModel mock
    (global as any).__activeModelStore = null;
  });

  it('resolveSelectedWebModel returns null for a stale web:deepseek: id', () => {
    expect(resolveSelectedWebModel(
      { provider: 'web', modelId: 'web:deepseek:deepseek-chat' },
      [{
        presetId: 'deepseek' as any,  // stale row, would have been deleted by web-provider-store:list() in production
        enabled: true,
        loginStatus: 'loggedIn',
        modelId: 'deepseek-chat',
        supportsToolCalls: false,
        supportsReasoning: false,
        lastCheckedAt: null,
        encryptedCookieBundle: null,
        userOverrides: null,
        loginAuditLog: [],
        createdAt: '2026-01-01T00:00:00Z',
        updatedAt: '2026-01-01T00:00:00Z',
      }],
    )).toBeNull();
  });

  it('isValidActiveModel rejects what resolveSelectedWebModel rejects', () => {
    // Defense in depth: if a stale value reaches the storage layer, both
    // the startup-pass (background/index.ts) and resolveSelectedWebModel
    // (here) would flag it.
    const stale = { provider: 'web', modelId: 'web:deepseek:deepseek-chat' };
    expect(isValidActiveModel(stale)).toBe(false);
    expect(resolveSelectedWebModel(stale, [])).toBeNull();
  });

  it('clears activeModel when resolveSelectedWebModel returns null (self-heal contract)', async () => {
    // Simulate the agent-manager self-heal behavior in isolation
    const mockStorage: Record<string, any> = {
      'local:activeModel': { provider: 'web', modelId: 'web:deepseek:deepseek-chat' },
    };
    (global as any).chrome = {
      storage: {
        local: {
          get: vi.fn((k: string) => Promise.resolve({ [k]: mockStorage[k] })),
          set: vi.fn((o: Record<string, any>) => {
            Object.assign(mockStorage, o);
            return Promise.resolve();
          }),
        },
      },
    };

    // Mirror the agent-manager self-heal logic (since we can't import the
    // full agent-manager in unit tests without WXT runtime)
    const modelCfg = mockStorage['local:activeModel'];
    if (modelCfg.provider === 'web' && !isValidActiveModel(modelCfg)) {
      // ...resolveSelectedWebModel would also return null here
      await new Promise<void>((resolve) => {
        mockStorage['local:activeModel'] = null;
        resolve();
      });
    }

    expect(mockStorage['local:activeModel']).toBeNull();
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import 'fake-indexeddb/auto';

// Mock chrome.storage.local so we don't depend on WXT runtime
let mockStorage: Record<string, any> = {};
beforeEach(() => {
  mockStorage = {};
  (global as any).chrome = {
    storage: {
      local: {
        get: vi.fn((keys: string | string[]) => {
          const arr = Array.isArray(keys) ? keys : [keys];
          const result: Record<string, any> = {};
          for (const k of arr) result[k] = mockStorage[k];
          return Promise.resolve(result);
        }),
        set: vi.fn((items: Record<string, any>) => {
          Object.assign(mockStorage, items);
          return Promise.resolve();
        }),
        remove: vi.fn((k: string) => {
          delete mockStorage[k];
          return Promise.resolve();
        }),
      },
    },
  };
});

/**
 * Simulates the SW startup-pass in `entrypoints/background/index.ts`.
 * We re-implement the logic here because the real `index.ts` uses
 * `defineBackground` from WXT which isn't available in unit tests.
 */
async function runStartupCleanup(): Promise<void> {
  // Re-create the import after chrome.storage.local is mocked
  const { isValidActiveModel } = await import(
    '@/lib/ai-config/web-provider-active-model-validation'
  );
  const current = mockStorage['local:activeModel'] ?? null;
  if (current !== null && !isValidActiveModel(current)) {
    delete mockStorage['local:activeModel'];
  }
}

describe('SW startup cleanup of activeModel', () => {
  it('clears an empty-object value (corrupted state)', async () => {
    mockStorage['local:activeModel'] = {};
    await runStartupCleanup();
    expect(mockStorage['local:activeModel']).toBeUndefined();
  });

  it('clears a stale web:deepseek: value', async () => {
    mockStorage['local:activeModel'] = {
      provider: 'web',
      modelId: 'web:deepseek:deepseek-chat',
    };
    await runStartupCleanup();
    expect(mockStorage['local:activeModel']).toBeUndefined();
  });

  it('clears a stale web:kimi: value', async () => {
    mockStorage['local:activeModel'] = {
      provider: 'web',
      modelId: 'web:kimi:moonshot-v1',
    };
    await runStartupCleanup();
    expect(mockStorage['local:activeModel']).toBeUndefined();
  });

  it('preserves a valid GLM web: value', async () => {
    mockStorage['local:activeModel'] = {
      provider: 'web',
      modelId: 'web:glm:GLM-4.6',
    };
    await runStartupCleanup();
    expect(mockStorage['local:activeModel']).toEqual({
      provider: 'web',
      modelId: 'web:glm:GLM-4.6',
    });
  });

  it('preserves a null value (no-op)', async () => {
    await runStartupCleanup();
    expect(mockStorage['local:activeModel']).toBeUndefined();
  });

  it('preserves a non-web provider (e.g. anthropic)', async () => {
    mockStorage['local:activeModel'] = {
      provider: 'anthropic',
      modelId: 'claude-3-7-sonnet',
    };
    await runStartupCleanup();
    expect(mockStorage['local:activeModel']).toEqual({
      provider: 'anthropic',
      modelId: 'claude-3-7-sonnet',
    });
  });
});

/**
 * Regression test: ChatPage must forward the `onOpenSettings` prop to
 * `useBackgroundAgent` so that the `web_provider_needs_relogin` flow
 * (which calls `callbacks.onOpenSettings?.()` in useBackgroundAgent.ts:255)
 * actually navigates the sidepanel to /settings when the session watcher
 * fires a 401 / needs-relogin.
 *
 * Bug history: 2026-06-07 real-E2E confirmed the toast fired but the
 * sidepanel did NOT navigate to Settings. Root cause: ChatPage was
 * destructuring `onOpenSettings` and only forwarding it to ChatInput's
 * "go to settings" button, never to `useBackgroundAgent`. The optional
 * chaining `callbacks.onOpenSettings?.()` silently no-op'd.
 *
 * This test catches the regression by mocking `useBackgroundAgent` and
 * asserting the callbacks object passed to it includes the same
 * `onOpenSettings` reference.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render } from '@testing-library/react';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import React from 'react';

// Capture the callbacks passed into useBackgroundAgent
const capturedCallbacks: { current: any } = { current: null };

vi.mock('@/hooks/useBackgroundAgent', () => ({
  useBackgroundAgent: (callbacks: any) => {
    capturedCallbacks.current = callbacks;
    return {
      state: { messages: [], isAgentRunning: false, sessionId: null, sessionTitle: '', connected: true, lastError: null },
      pendingTools: new Map(),
      send: vi.fn(),
      cancel: vi.fn(),
      retry: vi.fn(),
      subscribe: vi.fn(),
      unsubscribe: vi.fn(),
      resolveTool: vi.fn(),
    };
  },
}));

// Stub the rest of ChatPage's heavy imports
vi.mock('@/hooks/useStickToBottom', () => ({
  useStickToBottom: () => ({ scrollRef: { current: null }, isAtBottom: true, scrollToBottom: vi.fn() }),
}));
vi.mock('@/hooks/useStorageItem', () => ({
  // Return each item's declared fallback so the newly-mounted
  // <QuickActionsBar /> gets `[]` for `favoritePrompts` (its fallback) and
  // doesn't crash in `resolveFavorites(favorites).length` checking.
  useStorageItem: (_item: unknown, fallback: unknown) => [fallback, () => Promise.resolve()],
}));
vi.mock('@/lib/storage', () => ({
  activeModel: { getValue: vi.fn().mockResolvedValue(null), setValue: vi.fn() },
  // The page now mounts <QuickActionsBar />, which reads `favoritePrompts`.
  // The mock needs to expose it so the import doesn't throw, but its value
  // doesn't matter for these tests (we assert about captured useBackgroundAgent
  // callbacks, not the bar itself).
  favoritePrompts: { getValue: vi.fn().mockResolvedValue([]), setValue: vi.fn() },
}));
vi.mock('@/lib/i18n', () => ({
  t: (s: string) => s,
}));
vi.mock('@/lib/instance-id', () => ({
  myInstanceId: 'test-instance',
}));
vi.mock('@/components/chat/ChatInput', () => ({
  ChatInput: () => null,
}));
vi.mock('@/components/chat/Message', () => ({
  UserMessageBubble: () => null,
  AgentMessage: () => null,
  AgentTextBlock: () => null,
  ThinkingBlock: () => null,
}));
vi.mock('@/components/chat/ToolCard', () => ({
  ToolCard: () => null,
}));
vi.mock('@/components/chat/ToolCardWithUI', () => ({
  ToolCardWithUI: () => null,
}));

import { ChatPage } from '@/entrypoints/sidepanel/pages/chat';
import { TooltipProvider } from '@/components/ui/tooltip';

beforeEach(() => {
  capturedCallbacks.current = null;
});

describe('ChatPage forwards onOpenSettings to useBackgroundAgent', () => {
  it('passes the onOpenSettings prop into useBackgroundAgent (so 401 relogin navigates to /settings)', () => {
    const onOpenSettings = vi.fn();
    render(
      <TooltipProvider>
        <MemoryRouter initialEntries={['/chat/new']}>
          <Routes>
            <Route path="/chat/new" element={<ChatPage onOpenSettings={onOpenSettings} />} />
          </Routes>
        </MemoryRouter>
      </TooltipProvider>,
    );
    expect(capturedCallbacks.current).not.toBeNull();
    expect(capturedCallbacks.current.onOpenSettings).toBe(onOpenSettings);
  });

  it('tolerates missing onOpenSettings prop (no throw, callback is undefined)', () => {
    expect(() => {
      render(
        <TooltipProvider>
          <MemoryRouter initialEntries={['/chat/new']}>
            <Routes>
              <Route path="/chat/new" element={<ChatPage />} />
            </Routes>
          </MemoryRouter>
        </TooltipProvider>,
      );
    }).not.toThrow();
    expect(capturedCallbacks.current.onOpenSettings).toBeUndefined();
  });
});

import { describe, it, expect, vi } from 'vitest';
import {
  handleWebProviderNeedsRelogin,
  type WebProviderNeedsReloginDeps,
} from '@/hooks/handle-web-provider-needs-relogin';
import type { ServerMessage } from '@/lib/protocol';

function makeDeps(overrides: Partial<WebProviderNeedsReloginDeps> = {}): WebProviderNeedsReloginDeps {
  return {
    showToast: vi.fn(),
    openSettings: vi.fn(),
    ...overrides,
  };
}

function makeMsg(overrides: Partial<Extract<ServerMessage, { type: 'web_provider_needs_relogin' }>> = {}): Extract<ServerMessage, { type: 'web_provider_needs_relogin' }> {
  return {
    type: 'web_provider_needs_relogin',
    providerId: 'glm',
    status: 401,
    message: 'Please re-login to glm via Settings 鈫?Web Providers.',
    ...overrides,
  };
}

describe('handleWebProviderNeedsRelogin (鈶?4: sidepanel handler for 401/403)', () => {
  it('returns false for non-web_provider_needs_relogin messages (let other handlers process)', () => {
    const deps = makeDeps();
    const result = handleWebProviderNeedsRelogin({ type: 'connected' } as any, deps);
    expect(result).toBe(false);
    expect(deps.showToast).not.toHaveBeenCalled();
    expect(deps.openSettings).not.toHaveBeenCalled();
  });

  it('returns true for web_provider_needs_relogin messages (handled)', () => {
    const deps = makeDeps();
    const result = handleWebProviderNeedsRelogin(makeMsg(), deps);
    expect(result).toBe(true);
  });

  it('shows a toast with the user-friendly message (destructive variant for 401/403)', () => {
    const deps = makeDeps();
    handleWebProviderNeedsRelogin(
      makeMsg({ providerId: 'glm', status: 403, message: 'Forbidden' }),
      deps,
    );
    expect(deps.showToast).toHaveBeenCalledWith(
      expect.objectContaining({
        variant: 'destructive',
        description: expect.stringMatching(/GLM|re-login/i),
      }),
    );
  });

  it('calls openSettings to navigate the user to the Web providers section', () => {
    const deps = makeDeps();
    handleWebProviderNeedsRelogin(makeMsg({ providerId: 'glm' }), deps);
    expect(deps.openSettings).toHaveBeenCalledWith('glm');
  });

  it('handles the sole built-in provider (glm)', () => {
    for (const providerId of ['glm'] as const) {
      const deps = makeDeps();
      handleWebProviderNeedsRelogin(makeMsg({ providerId }), deps);
