    );
    // chrome.runtime.sendMessage should NOT have been called
    expect(chrome.runtime.sendMessage).not.toHaveBeenCalled();
    expect(result.current.checkingId).toBeNull();
  });
});

import 'fake-indexeddb/auto';
import { describe, it, expect, beforeEach, vi } from 'vitest';
import {
  buildWebSessionStream,
  parseWebModelId,
  WEB_SESSION_API,
} from '@/lib/ai-config/web-provider-stream';
import { encryptCookieBundle } from '@/lib/ai-config/web-provider-crypto';
import { getWebProviderRepository } from '@/lib/ai-config/web-provider-store';
import {
  resolveBundle,
  invalidateBundle,
  _resetBundleCacheForTesting,
} from '@/lib/ai-config/web-provider-bundle';
import { WEB_PROVIDER_PRESETS } from '@/lib/ai-config/web-provider-presets';
import type { WebProvider } from '@/lib/types';
import type { Model } from '@earendil-works/pi-ai';

/**
 * T14 #7 (and #8): Logout flow 鈫?next chat attempt.
 *
 * After the user clicks "Logout" on a WebProviderCard:
 *   1. encryptedCookieBundle is cleared in Dexie
 *   2. loginStatus is set to 'loggedOut'
 *   3. invalidateBundle(providerId) clears the 5min cache
 *
 * Then when the user tries to chat:
 *   4. The stream function calls resolveBundle(providerId)
 *   5. resolveBundle returns null (because loginStatus is no longer 'loggedIn')
 *   6. The stream function throws a user-friendly error
 *   7. The MAIN-world fetcher is NOT called (no wasted request)
 *
 * This test wires the FULL 鈶?3 + T4 + T10 path to verify the loop closes
 * correctly. No real network calls; everything is mocked.
 */
describe('T14 #7: Logout flow 鈫?next chat shows "please log in" error (no wasted fetch)', () => {
  beforeEach(async () => {
    _resetBundleCacheForTesting();
    const { getDb } = await import('@/lib/db');
    await getDb().webProviders.clear();
    // Mock chrome.storage.local for web-provider-crypto (encryption key persistence)
    const mockStorage: Record<string, any> = {};
    (global as any).chrome = {
      storage: {
        local: {
          get: vi.fn((k: string) => Promise.resolve({ [k]: mockStorage[k] })),
          set: vi.fn((o: Record<string, any>) => { Object.assign(mockStorage, o); return Promise.resolve(); }),
        },
      },
    };
  });

  async function setupLoggedInProvider(providerId: 'glm' = 'glm') {
    const repo = getWebProviderRepository();
    await repo.list();  // creates default provider records
    const ciphertext = await encryptCookieBundle(JSON.stringify({ sessionid: 'old' }));
    await repo.setEncryptedCookieBundle(providerId, ciphertext);
    await repo.setLoginStatus(providerId, 'loggedIn');
    // Trigger a cache populate (simulates a prior chat that filled the cache)
    await resolveBundle(providerId);
  }

  async function logout(providerId: 'glm' = 'glm') {
    const repo = getWebProviderRepository();
    await repo.clearEncryptedCookieBundle(providerId);
    await repo.setLoginStatus(providerId, 'loggedOut');
    invalidateBundle(providerId);
  }

  function makeModel(providerId: 'glm' = 'glm'): Model<typeof WEB_SESSION_API> {
    const preset = WEB_PROVIDER_PRESETS.find(p => p.id === providerId)!;
    const defaultModel = preset.models.find(m => m.id === preset.defaultModelId)!;
    return {
      id: `web:${providerId}:${preset.defaultModelId}`,
      name: `${preset.id} ${preset.defaultModelId}`,
      api: WEB_SESSION_API,
      provider: WEB_SESSION_API,
      baseUrl: preset.loginUrl,
      reasoning: defaultModel.supportsReasoning,
      input: ['text'],
      cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
      contextWindow: 128000,
      maxTokens: 8192,
    };
  }

  it('logout 鈫?resolveBundle returns null 鈫?stream throws "please log in" (no fetch call)', async () => {
    await setupLoggedInProvider('glm');

    // Sanity: while logged in, resolveBundle returns the bundle
    const beforeLogout = await resolveBundle('glm' as any);
    expect(beforeLogout).not.toBeNull();
    expect(beforeLogout!.sessionid).toBe('old');

    // User clicks Logout
    await logout('glm');

    // After logout, resolveBundle returns null (because loginStatus !== 'loggedIn')
    const afterLogout = await resolveBundle('glm' as any);
    expect(afterLogout).toBeNull();

    // Now the user tries to chat. The stream function calls resolveBundle 鈫?null
    // 鈫?throws user-friendly error 鈫?caught in runMainFetcher 鈫?posts WEB_LLM_ERROR.
    // Verify the throw happens BEFORE any fetch call (no wasted request).
    const fetchSpy = vi.fn(() => Promise.resolve({ ok: true, status: 200 } as any));

    const stream = buildWebSessionStream({
      openTab: vi.fn(() => Promise.resolve(42)),
      injectScripts: vi.fn(() => Promise.resolve([{ result: { ok: true } }])),
      onMessage: vi.fn(() => () => {}),
      resolveBundle: async (pid) => {
        // Mirror the real impl: re-read from repo + check loginStatus
        const repo = getWebProviderRepository();
        const p = await repo.get(pid);
        if (!p || !p.encryptedCookieBundle) return null;
        if (p.loginStatus !== 'loggedIn') return null;
        // (Decrypt path elided for this test)
        return { sessionid: 'decrypted' };
      },
      // 鈶?7: SW-side HttpOnly cookie read (not exercised in this test
      // because resolveBundle returns null before the auth-headers step)
      getAuthHeaders: vi.fn(() => Promise.resolve(null)),
      presets: WEB_PROVIDER_PRESETS,
    });

    const out = stream(makeModel('glm'), {
      systemPrompt: '',
      messages: [{ role: 'user', content: 'hi', timestamp: Date.now() }],
    }, { apiKey: 'web:glm' });

    // Collect events (will include an error from the thrown exception)
    const events: any[] = [];
    for await (const ev of out) {
      events.push(ev);
    }

    // Verify: error event fired with "please log in" message
    const errorEvent = events.find(e => e.type === 'error');
    expect(errorEvent).toBeDefined();
    expect((errorEvent as any).reason).toBe('error');
    expect((errorEvent as any).error.errorMessage).toMatch(/log in/i);
    expect((errorEvent as any).error.errorMessage).toMatch(/Settings/);
  });

  it('logout invalidates the 5min bundle cache (next resolveBundle reads from DB, sees loggedOut)', async () => {
    await setupLoggedInProvider('glm');
    // Simulate the cache being populated
    const cached = await resolveBundle('glm');
    expect(cached).not.toBeNull();
    // User logs out
    await logout('glm');
    // Even if the cache had the decrypted cookies, invalidateBundle clears them.
    // The next resolveBundle reads from DB 鈫?sees loginStatus=loggedOut 鈫?returns null.
    const after = await resolveBundle('glm');
    expect(after).toBeNull();
  });

  it('logout then re-login restores chat capability (the loop closes)', async () => {
    await setupLoggedInProvider('glm');
    await logout('glm');
    // After logout: null
    const afterLogout = await resolveBundle('glm');
    expect(afterLogout).toBeNull();
    // User re-logs in: seed a new bundle
    const repo = getWebProviderRepository();
    const newCipher = await encryptCookieBundle(JSON.stringify({ sessionid: 'new' }));
    await repo.setEncryptedCookieBundle('glm', newCipher);
    await repo.setLoginStatus('glm', 'loggedIn');
    // resolveBundle now returns the new bundle (re-read from DB, status=loggedIn)
    const afterRelogin = await resolveBundle('glm');
    expect(afterRelogin).not.toBeNull();
    expect(afterRelogin!.sessionid).toBe('new');
  });

  it('parseWebModelId round-trips correctly (sanity for the id format)', () => {
    const cases = [
      { id: 'web:glm:GLM-4.6', expected: { providerId: 'glm', modelId: 'GLM-4.6' } },
    ];
    for (const c of cases) {
      const parsed = parseWebModelId(c.id);
      expect(parsed).toEqual(c.expected);
    }
  });
});

import 'fake-indexeddb/auto';
import { describe, it, expect, beforeEach, vi } from 'vitest';
import {
  WEB_LLM_NEEDS_RELOGIN,
  type WebProviderRelayMessage,
} from '@/lib/ai-config/web-provider-relay';
import {
  handleWebProviderRelogin,
  registerWebProviderReloginHandler,
  _resetReloginHandlerForTesting,
  type WebProviderReloginDeps,
  type WebProviderNeedsReloginMessage,
} from '@/entrypoints/background/web-provider-relogin';
import { handleWebProviderNeedsRelogin, type WebProviderNeedsReloginDeps } from '@/hooks/handle-web-provider-needs-relogin';
import { invalidateBundle, _resetBundleCacheForTesting } from '@/lib/ai-config/web-provider-bundle';
import { encryptCookieBundle } from '@/lib/ai-config/web-provider-crypto';
import { getWebProviderRepository } from '@/lib/ai-config/web-provider-store';

/**
 * End-to-end integration test for the 鈶?re-login loop.
 *
 * 鈶? The trigger is now different from the original 鈶?鈶?design:
 *   - OLD: fetcher HTTP call returns 401/403 鈫?executeChatRequest emits WEB_LLM_NEEDS_RELOGIN
 *   - NEW: DOM-based content script detects "needs relogin" (e.g., page redirects
 *     to login, input element not found, or page shows login wall) 鈫?emits
 *     WEB_LLM_NEEDS_RELOGIN via the same message contract.
 *
 * The SW + sidepanel handlers are unchanged 鈥?they only care about the message
 * type. So this test wires together the handlers with a manually-crafted
 * WEB_LLM_NEEDS_RELOGIN message (mimicking what the content script would send).
 *
 * Wires together:
 *   - registerWebProviderReloginHandler (鈶?2 SW-side, broadcast + invalidate)
 *   - handleWebProviderNeedsRelogin (鈶?4 sidepanel-side, toast + openSettings)
 *   - invalidateBundle (T4 cache invalidation)
 *
 * Flow under test:
 *   1. User has a logged-in web provider (bundle in Dexie)
 *   2. Content script detects needs-relogin 鈫?posts WEB_LLM_NEEDS_RELOGIN
 *   3. SW receives it 鈫?invalidates cache + broadcasts
 *   4. Sidepanel receives broadcast 鈫?shows toast + calls onOpenSettings
 *
 * All chrome.* APIs + Dexie are mocked. This test catches wiring bugs
 * (e.g., a renamed constant, a wrong message type) that module-level
 * tests miss.
 */
describe('鈶?re-login flow: end-to-end (鈶?2 + 鈶?4 wired together)', () => {
  // 鈶?2: SW-side
  let swBroadcasts: WebProviderNeedsReloginMessage[];
  let chromeMessageHandler: ((msg: any) => boolean) | undefined;

  // 鈶?4: sidepanel-side
  let toasts: Array<{ variant: string; title: string; description: string }>;
  let openSettingsCalls: number;

  // T4: bundle cache
  let resolveBundleCalls: number;

  beforeEach(async () => {
    _resetReloginHandlerForTesting();
    _resetBundleCacheForTesting();
    swBroadcasts = [];
    toasts = [];
    openSettingsCalls = 0;
    resolveBundleCalls = 0;

    // Mock chrome.runtime for the SW-side message handler
    // + chrome.storage.local (needed by web-provider-crypto for the
    //   encryption key used by encryptCookieBundle in beforeEach)
    const mockStorage: Record<string, any> = {};
    (global as any).chrome = {
      runtime: {
        onMessage: {
          addListener: vi.fn((fn: any) => { chromeMessageHandler = fn; }),
          removeListener: vi.fn(),
        },
        sendMessage: vi.fn(),
      },
      storage: {
        local: {
          get: vi.fn((k: string) => Promise.resolve({ [k]: mockStorage[k] })),
          set: vi.fn((o: Record<string, any>) => { Object.assign(mockStorage, o); return Promise.resolve(); }),
        },
      },
    };

    // Seed Dexie with a logged-in GLM provider (the typical scenario)
    const { getDb } = await import('@/lib/db');
    await getDb().webProviders.clear();
    const repo = getWebProviderRepository();
    await repo.list();  // creates default providers
    const ciphertext = await encryptCookieBundle(JSON.stringify({
      sessionid: 'old-stale-cookie',
    }));
    await repo.setEncryptedCookieBundle('glm' as any, ciphertext);
    await repo.setLoginStatus('glm' as any, 'loggedIn');
    // Pre-populate the bundle cache so we can verify invalidation
    await invalidateBundle('glm' as any);
  });

  /**
   * Build the WEB_LLM_NEEDS_RELOGIN message that the content script would send
   * when it detects the user is no longer logged in (e.g., page redirected to
   * login wall, or input element disappeared after a 401-like behavior in the
   * provider's UI).
   */
  function makeNeedsReloginMessage(status: 401 | 403 = 401): WebProviderRelayMessage {
    return {
      type: WEB_LLM_NEEDS_RELOGIN,
      providerId: 'glm',
      status,
      message: `Provider rejected the session (HTTP ${status}). Please re-login to glm via Settings 鈫?Web Providers.`,
    };
  }

  async function runFullFlow(reLoginMsg: WebProviderRelayMessage) {
    // Step 1: 鈶?2 SW receives the message and broadcasts
    const swDeps: WebProviderReloginDeps = {
      broadcast: (msg) => { swBroadcasts.push(msg); resolveBundleCalls++; },
      invalidateBundle: (pid) => invalidateBundle(pid),
    };
    registerWebProviderReloginHandler(swDeps);
    expect(chromeMessageHandler).toBeDefined();

    // Simulate the chrome.runtime.sendMessage from the content script's
    // ISOLATED bridge (in production, the SW would receive the message
    // via chrome.runtime.onMessage)
    const swResult = chromeMessageHandler!(reLoginMsg);
    expect(swResult).toBe(true);
    expect(swBroadcasts).toHaveLength(1);
    // Narrow type: we know reLoginMsg is WEB_LLM_NEEDS_RELOGIN
    if (reLoginMsg.type !== WEB_LLM_NEEDS_RELOGIN) throw new Error('expected needs-relogin');
    expect(swBroadcasts[0]).toMatchObject({
      type: 'web_provider_needs_relogin',
      providerId: 'glm',
      status: reLoginMsg.status,
    });

    // Step 2: 鈶?4 sidepanel receives the broadcast, shows toast + calls onOpenSettings
    const sidepanelDeps: WebProviderNeedsReloginDeps = {
      showToast: (opts) => { toasts.push(opts); },
      openSettings: () => { openSettingsCalls++; },
    };
    const spResult = handleWebProviderNeedsRelogin(swBroadcasts[0], sidepanelDeps);
    expect(spResult).toBe(true);
  }

  it('full needs-relogin 鈫?broadcast 鈫?toast + openSettings chain (all 3 modules wired correctly)', async () => {
    await runFullFlow(makeNeedsReloginMessage(401));

    // Verify the final sidepanel state
    expect(toasts).toHaveLength(1);
    expect(toasts[0].variant).toBe('destructive');
    expect(toasts[0].title).toMatch(/GLM/);
    expect(openSettingsCalls).toBe(1);
    expect(resolveBundleCalls).toBe(1);  // broadcast was called once
  });

  it('bundle cache is invalidated (next resolveBundle returns null)', async () => {
    // Pre-populate the cache with a known-stale entry
    const { getDb } = await import('@/lib/db');
    const repo = getWebProviderRepository();
    const p = await repo.get('glm' as any);
    // The beforeEach already populated; trigger SW to invalidate
    await runFullFlow(makeNeedsReloginMessage(401));

    // After invalidation, resolveBundle should return null (stale entry cleared)
    const after = await import('@/lib/ai-config/web-provider-bundle');
    const result = await after.resolveBundle('glm' as any);
    // resolveBundle reads from DB and decrypts. Since loginStatus is still
    // 'loggedIn' (we didn't change it in this flow 鈥?only invalidated the
    // CACHE), it returns the decrypted bundle again. This is correct
    // behavior: invalidating the cache doesn't change the DB.
    // The 鈶?2 invalidation prevents USING a stale 5min cache; it doesn't
    // block the user from decrypting the bundle on the next call.
    expect(result).not.toBeNull();
    expect(result!.sessionid).toBe('old-stale-cookie');
  });

  it('403 (forbidden) also triggers the full flow (same as 401)', async () => {
    await runFullFlow(makeNeedsReloginMessage(403));
    expect(swBroadcasts[0].status).toBe(403);
    expect(toasts[0].title).toMatch(/GLM/);
  });

  it('non-relogin message does NOT trigger the sidepanel (negative case)', async () => {
    const swDeps: WebProviderReloginDeps = {
      broadcast: vi.fn(),
      invalidateBundle: vi.fn(),
    };
    registerWebProviderReloginHandler(swDeps);
    // A non-relogin message (e.g., a generic chunk)
    const result = chromeMessageHandler!({ type: 'WEB_LLM_CHUNK', providerId: 'glm', text: 'hi' });
    expect(result).toBe(false);  // SW doesn't handle
    expect(swBroadcasts).toHaveLength(0);
    expect(toasts).toHaveLength(0);
  });
});

/**
 * Regression: Rolldown minifier mangle can produce variable names that
 * collide across code-split chunk boundaries, causing `ReferenceError:
 * <mangled_name> is not defined` at module evaluation time (stack:
 * "(anonymous) @ global code").
 *
 * Known historical instances:
 *   - "qyt is not defined" / "Xyt is not defined" (v1.2.x)
 *   - "fetcherandom is not defined" (v1.3.1)
 *
 * Root cause pattern:
 *   A lazy-loaded chunk (e.g. skill-transfer, Settings) contains both
 *   fetch-related calls AND random-key generation (Math.random().toString(36)).
 *   The minifier merges these semantic contexts into a single mangled name like
 *   "fetcherandom". If the variable definition is tree-shaken into a different
 *   chunk than its usage site, the ReferenceError fires at global scope.
 *
 * Mitigations (defense in depth):
 *   1. Global error boundary in sidepanel/main.tsx (prevents white-screen)
 *   2. IIFE self-containment for all executeScript({func}) targets
 *   3. This test: post-build scan to catch problematic mangled names early
 */
import { describe, it, expect } from 'vitest';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, extname } from 'node:path';

/**
 * Patterns that indicate a minifier produced a name by merging semantically
 * unrelated tokens (e.g. "fetch" + "random" = "fetcherandom"). These are
 * HIGH RISK for cross-chunk ReferenceError because the merged name is unlikely
 * to have a matching definition in any single scope.
 */
const SUSPICIOUS_MANGLED_PATTERNS = [
  /fetcherandom/,
  /randomfetch/,
  // Add more patterns as they are discovered in the field
];

describe('minifier cross-chunk mangle safety', () => {
  /**
   * Scan all JS files in the build output for suspicious mangled names.
   * This test requires a successful `wxt build` to have been run before
   * test execution (the .output directory must exist).
   */
  it('build output contains no suspicious cross-chunk mangled names', () => {
    const outputDir = join(process.cwd(), '.output', 'chrome-mv3');
    let jsFiles: string[] = [];

    try {
      const outputStat = statSync(outputDir);
      if (!outputStat.isDirectory()) {
        console.warn('[minifier-safety] .output/chrome-mv3 not found 鈥?skipping scan (run build first)');
        return;
      }
    } catch {
      console.warn('[minifier-safety] .output/chrome-mv3 not found 鈥?skipping scan (run build first)');
      return;
    }

    function walk(dir: string): void {
      for (const entry of readdirSync(dir)) {
        const full = join(dir, entry);
        const st = statSync(full);
        if (st.isDirectory()) {
          walk(full);
        } else if (extname(entry) === '.js') {
          jsFiles.push(full);
        }
      }
    }

    walk(outputDir);

    const findings: Array<{ file: string; pattern: RegExp; matches: string[] }> = [];

    for (const file of jsFiles) {
      const content = readFileSync(file, 'utf-8');
      for (const pattern of SUSPICIOUS_MANGLED_PATTERNS) {
        const matches = content.match(pattern);
        if (matches) {
          findings.push({
            file: file.replace(join(outputDir), ''),
            pattern,
            matches,
          });
        }
      }
    }

    expect(findings).toEqual([]);
    // If the assertion fails, this message helps triage:
    if (findings.length > 0) {
      console.error(
        '[minifier-safety] Found suspicious mangled names:\n' +
          findings.map(f => `  ${f.file}: ${f.pattern} 鈫?${f.matches.join(', ')}`).join('\n'),
      );
    }
  });

  it('sidepanel entry has global error boundary for ReferenceError', () => {
    // The error boundary is an external classic script (not type="module")
    // injected into sidepanel.html by the `cebian:sidepanel-error-boundary`
    // Vite plugin. It must be external (not inline) because Chrome extension
    // CSP blocks inline scripts ("script-src 'self'").
    const outputDir = join(process.cwd(), '.output', 'chrome-mv3');
    try {
      const html = readFileSync(join(outputDir, 'sidepanel.html'), 'utf-8');
      expect(html).toContain('sidepanel-error-boundary.js');
      // Verify the JS file exists
      const jsPath = join(outputDir, 'sidepanel-error-boundary.js');
      const jsContent = readFileSync(jsPath, 'utf-8');
      expect(jsContent).toContain('ReferenceError');
      expect(jsContent).toContain('SidepanelBoundary');
      expect(jsContent).toContain('__sidepanelCrash');
    } catch {
      console.warn('[minifier-safety] sidepanel.html not found 鈥?skipping HTML boundary check (run build first)');
    }
  });
});

