      (global as any).chrome = {};
    }
    const mockStorage: Record<string, any> = {};
    (global as any).chrome.storage = {
      local: {
        get: vi.fn((k: string) => Promise.resolve({ [k]: mockStorage[k] })),
        set: vi.fn((o: Record<string, any>) => { Object.assign(mockStorage, o); return Promise.resolve(); }),
      },
    };
  });

  afterEach(() => {
    _resetBundleCacheForTesting();
    vi.useRealTimers();
  });

  it('returns null when provider has no stored bundle', async () => {
    const bundle = await resolveBundle('glm' as WebProvider['presetId']);
    expect(bundle).toBeNull();
  });

  it('returns null when provider is loggedOut', async () => {
    const repo = getWebProviderRepository();
    // Seed provider first
    await repo.list();
    await repo.setLoginStatus('glm' as WebProvider['presetId'], 'loggedOut');
    const bundle = await resolveBundle('glm' as WebProvider['presetId']);
    expect(bundle).toBeNull();
  });

  it('returns decrypted cookies when provider is loggedIn (cache miss 鈫?populate)', async () => {
    await makeLoggedIn();
    const bundle = await resolveBundle('glm' as WebProvider['presetId']);
    expect(bundle).not.toBeNull();
    expect(bundle!.sessionid).toBe('abc123');
    expect(bundle!['csrf_token']).toBe('xyz789');
  });

  it('uses 5-minute in-memory cache: second call within TTL returns SAME object reference', async () => {
    await makeLoggedIn();
    // First call: cache miss 鈫?decrypt + populate
    const b1 = await resolveBundle('glm' as WebProvider['presetId']);
    expect(b1!.sessionid).toBe('abc123');
    // Second call within 5 min: cache hit 鈫?returns the SAME object reference
    // (decrypt would produce a fresh object; same ref proves cache hit)
    const b2 = await resolveBundle('glm' as WebProvider['presetId']);
    expect(b2).toBe(b1);
  });

  it('cache expires after 5 minutes: new object reference on second call', async () => {
    await makeLoggedIn();
    // First call populates cache
    const b1 = await resolveBundle('glm' as WebProvider['presetId']);
    expect(b1).not.toBeNull();
    // Simulate cache expiry by rewinding cachedAt to 6 minutes ago (no fake timers 鈥?they leaked across tests)
    _setBundleCacheAgeForTesting('glm' as WebProvider['presetId'], 6 * 60 * 1000);
    // Second call: cache stale (> 5min) 鈫?re-decrypt 鈫?fresh object
    const b2 = await resolveBundle('glm' as WebProvider['presetId']);
    expect(b2).not.toBe(b1);  // different reference proves re-decrypt
    expect(b2!.sessionid).toBe('abc123');  // same content
  });

  it('7d stale bundle: console.warn fires but bundle is still returned (soft warn)', async () => {
    await makeLoggedIn();
    // Populate cache
    const b1 = await resolveBundle('glm' as WebProvider['presetId']);
    expect(b1).not.toBeNull();
    // Cache must be valid (cachedAt < 5min ago) but lastCheckedAt > 7d ago
    // This simulates: user logged in 8 days ago, used chat recently (<5min)
    _setBundleCacheAgeForTesting(
      'glm' as WebProvider['presetId'],
      60 * 1000,  // 1 min ago 鈫?cache still valid
      new Date(Date.now() - 8 * 24 * 60 * 60 * 1000).toISOString(),  // 8d ago
    );
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    const b2 = await resolveBundle('glm' as WebProvider['presetId']);
    expect(b2).toBe(b1);  // same reference (7d is a soft warn, not invalidation)
    expect(warn).toHaveBeenCalled();
    const msg = warn.mock.calls.find(c => String(c[0]).includes('web-provider-bundle') && String(c[0]).includes('8d old'));
    expect(msg).toBeDefined();
    warn.mockRestore();
  });

  it('invalidateBundle forces re-decrypt (new object reference)', async () => {
    await makeLoggedIn();
    const b1 = await resolveBundle('glm' as WebProvider['presetId']);
    invalidateBundle('glm' as WebProvider['presetId']);
    const b2 = await resolveBundle('glm' as WebProvider['presetId']);
    expect(b2).not.toBe(b1);  // new object = re-decrypted
    expect(b2!.sessionid).toBe('abc123');  // same content
  });

  it('invalidateAllBundles clears both providers (new object refs)', async () => {
    const repo = getWebProviderRepository();
    await repo.list();
    // Set up GLM provider with a bundle
    const c1 = await encryptCookieBundle(JSON.stringify({ sessionid: 'a' }));
    await repo.setEncryptedCookieBundle('glm' as WebProvider['presetId'], c1);
    await repo.setLoginStatus('glm' as WebProvider['presetId'], 'loggedIn');
    const b1g = await resolveBundle('glm' as WebProvider['presetId']);
    invalidateAllBundles();
    const b2g = await resolveBundle('glm' as WebProvider['presetId']);
    expect(b2g).not.toBe(b1g);
    expect(b2g!.sessionid).toBe('a');
  });
});

/**
 * 鈶? Unit tests for the port-based abort channel in the GLM adapter.
 *
 * Tests that `glmMainWorldFetch`:
 *   1. Initializes `window.__webProviderAbortFlag = false` on start
 *   2. Listens for `WEB_LLM_ABORT` events and sets the flag to `true`
 *   3. Breaks the SSE reading loop early when the flag is set mid-stream,
 *      posting `WEB_LLM_DONE` with truncated text (no residual chunks)
 */
import 'fake-indexeddb/auto';
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { glmMainWorldFetch } from '@/lib/ai-config/web-provider-content-fetch-glm';
import type { ContentFetchRequest } from '@/lib/ai-config/web-provider-content-fetch-main';

/**
 * Simulate the ISOLATED bridge forwarding a `WEB_LLM_ABORT` signal from
 * the SW to the MAIN world. This dispatches the same CustomEvent the
 * bridge would dispatch when it receives `{type:'abort'}` on the port.
 */
function sendAbortSignal(): void {
  document.dispatchEvent(new CustomEvent('ceb-web-provider-message', {
    detail: { type: 'WEB_LLM_ABORT' },
  }));
}

/**
 * Build a minimal ContentFetchRequest for the GLM adapter.
 */
function makeRequest(overrides: Partial<ContentFetchRequest> = {}): ContentFetchRequest {
  return {
    type: 'WEB_LLM_FETCH',
    requestId: 'test-req-' + Math.random().toString(36).slice(2),
    providerId: 'glm',
    modelId: 'glm-4.6',
    init: {
      method: 'POST',
      body: JSON.stringify({
        prompt: 'hello',
        chatId: '',
        assistantId: '65940acff94777010aa6b796',
      }),
    },
    ...overrides,
  };
}

/**
 * Set up a mock fetch that returns a ReadableStream we control.
 */
function setupControllableStream(): {
  request: ContentFetchRequest;
  push: (chunk: string) => void;
  close: () => void;
} {
  const request = makeRequest();
  let controller: ReadableStreamDefaultController<Uint8Array> | null = null;
  const stream = new ReadableStream<Uint8Array>({
    start(c) { controller = c; },
  });
  const push = (chunk: string) => {
    controller?.enqueue(new TextEncoder().encode(chunk));
  };
  const close = () => {
    controller?.close();
  };

  (globalThis as unknown as { fetch: unknown }).fetch = vi.fn(() =>
    Promise.resolve({
      ok: true,
      status: 200,
      statusText: 'OK',
      body: stream,
      text: () => Promise.resolve(''),
    } as unknown as Response),
  );

  Object.defineProperty(document, 'cookie', {
    get: vi.fn(() => 'chatglm_token=fake-token; chatglm_refresh_token=fake-refresh'),
    configurable: true,
  });

  return { request, push, close };
}

describe('glmMainWorldFetch (鈶? port-based abort channel)', () => {
  let capture: { events: Array<{ type: string; [k: string]: unknown }> };
  let captureFn: (event: Event) => void;

  beforeEach(() => {
    capture = { events: [] };
    captureFn = (event: Event) => {
      const ce = event as CustomEvent<Record<string, unknown>>;
      if (ce.detail && typeof ce.detail === 'object' && typeof ce.detail.type === 'string') {
        capture.events.push(ce.detail as { type: string; [k: string]: unknown });
      }
    };
    document.addEventListener('ceb-web-provider-message', captureFn);
    (window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag = undefined;
    // 鈶? jsdom defaults to `http://localhost`, but the GLM adapter
    // early-returns when `window.location.origin` doesn't include
    // `chatglm.cn`. Override `location` so the adapter proceeds past
    // the origin check and actually enters the SSE reading loop.
    const fakeLocation = {
      origin: 'https://chatglm.cn',
      href: 'https://chatglm.cn/main/chat/new',
      host: 'chatglm.cn',
      hostname: 'chatglm.cn',
      protocol: 'https:',
      port: '',
      pathname: '/main/chat/new',
      search: '',
      hash: '',
    };
    Object.defineProperty(window, 'location', {
      value: fakeLocation,
      writable: true,
      configurable: true,
    });
  });

  afterEach(() => {
    document.removeEventListener('ceb-web-provider-message', captureFn);
    vi.restoreAllMocks();
    (window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag = undefined;
  });

  it('initializes __webProviderAbortFlag to false on start', async () => {
    const { request, close } = setupControllableStream();
    const promise = glmMainWorldFetch(request);
    await new Promise((r) => setTimeout(r, 50));
    expect((window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag).toBe(false);
    sendAbortSignal();
    close();
    await promise;
  });

  it('sets __webProviderAbortFlag to true when WEB_LLM_ABORT event is received', async () => {
    const { request, close } = setupControllableStream();
    const promise = glmMainWorldFetch(request);
    await new Promise((r) => setTimeout(r, 50));
    expect((window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag).toBe(false);
    sendAbortSignal();
    await new Promise((r) => setTimeout(r, 50));
    expect((window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag).toBe(true);
    close();
    await promise;
  });

  it('breaks the SSE loop early when abort flag is set mid-stream (no residual chunks after abort)', async () => {
    const { request, push, close } = setupControllableStream();

    // Push an initial chunk BEFORE abort so the adapter has something
    const sseChunk1 = `data: ${JSON.stringify({
      parts: [{ logic_id: 'l1', content: [{ type: 'text', text: 'Hello' }] }],
    })}\n\n`;
    push(sseChunk1);

    const promise = glmMainWorldFetch(request);
    // Wait for the first chunk to be processed
    await new Promise((r) => setTimeout(r, 150));

    // Now send the abort signal
    sendAbortSignal();
    await new Promise((r) => setTimeout(r, 50));

    // Push more data AFTER abort 鈥?these should NOT produce chunks
    const sseChunk2 = `data: ${JSON.stringify({
      parts: [{ logic_id: 'l1', content: [{ type: 'text', text: 'Hello world this should not appear' }] }],
    })}\n\n`;
    push(sseChunk2);

    // Wait a bit to see if any post-abort chunks are emitted
    await new Promise((r) => setTimeout(r, 100));
    close();

    await promise;

    const chunks = capture.events.filter((e) => e.type === 'WEB_LLM_CHUNK');
    expect(chunks.length).toBeGreaterThanOrEqual(1);
    const allChunkText = chunks.map((c) => (c.chunk as string) ?? '').join('');
    expect(allChunkText).not.toContain('should not appear');
    const dones = capture.events.filter((e) => e.type === 'WEB_LLM_DONE');
    expect(dones.length).toBeGreaterThanOrEqual(1);
  });

  it('cleans up the abort listener after completion (no leak)', async () => {
    const { request, close } = setupControllableStream();
    const addSpy = vi.spyOn(document, 'addEventListener');
    const removeSpy = vi.spyOn(document, 'removeEventListener');

    const promise = glmMainWorldFetch(request);
    await new Promise((r) => setTimeout(r, 50));
    sendAbortSignal();
    close();
    await promise;

    const removedForCeb = removeSpy.mock.calls.filter((c) => c[0] === 'ceb-web-provider-message');
    expect(removedForCeb.length).toBeGreaterThanOrEqual(1);
  });
});

/**
 * 鈶? Unit tests for the content script's needs-relogin trigger.
 *
 * Tests the pre-flight + mid-call checks in runDomRelayMainWorld that
 * detect "user is no longer logged in" and emit WEB_LLM_NEEDS_RELOGIN
 * instead of a generic WEB_LLM_ERROR.
 */
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { runDomRelayMainWorld, type DomRelayRequest } from '@/lib/ai-config/web-provider-content-script';
import { GLM_DOM_STRATEGY } from '@/lib/ai-config/web-provider-dom-strategy';

/**
 * Spy on window.postMessage to capture the messages the content script sends
 * to the ISOLATED bridge.
 */
function installPostMessageSpy(): { messages: any[] } {
  const messages: any[] = [];
  const original = window.postMessage.bind(window);
  window.postMessage = vi.fn((data: any, targetOrigin: any) => {
    if (data && data.source === 'ceb-web-provider-main') {
      messages.push(data.payload);
    }
    // Also call original in case anything else listens.
    // Use the 2-arg overload (message + targetOrigin) which jsdom requires.
    // Cast through `unknown` to bypass TS overload picking (TS may prefer
    // the WindowPostMessageOptions overload which doesn't accept a string).
    return (original as unknown as (data: any, targetOrigin: any) => void)(data, targetOrigin);
  });
  return { messages };
}

function makeRequest(overrides: Partial<DomRelayRequest> = {}): DomRelayRequest {
  return {
    providerId: 'glm',
    modelId: 'glm-4.6',
    message: 'hello',
    domStrategy: GLM_DOM_STRATEGY,
    ...overrides,
  };
}

describe('runDomRelayMainWorld (鈶? needs-relogin detection)', () => {
  let postSpy: { messages: any[] };

  beforeEach(() => {
    postSpy = installPostMessageSpy();
  });

  afterEach(() => {
    document.body.innerHTML = '';
    // Restore any vi.spyOn mocks (e.g., document.querySelector) so they
    // don't leak to the next test.
    vi.restoreAllMocks();
  });

  it('emits WEB_LLM_NEEDS_RELOGIN when input element is not present (pre-flight check)', async () => {
    // No textarea on the page (user is on a login wall)
    await runDomRelayMainWorld(makeRequest());
    expect(postSpy.messages).toHaveLength(1);
    expect(postSpy.messages[0].type).toBe('WEB_LLM_NEEDS_RELOGIN');
    expect(postSpy.messages[0].providerId).toBe('glm');
    expect(postSpy.messages[0].status).toBe(401);
    expect(postSpy.messages[0].message).toContain('no longer logged in');
  });

  it('emits WEB_LLM_NEEDS_RELOGIN when input disappears between pre-flight and set', async () => {
    // Simulate a race: element exists at pre-flight but is removed before set.
    // We mock querySelector to return the element on the first call (pre-flight)
    // and null on subsequent calls.
    const original = document.querySelector.bind(document);
    let callCount = 0;
    vi.spyOn(document, 'querySelector').mockImplementation((sel: string) => {
      callCount++;
      if (callCount === 1) {
        // Pre-flight: return a fake element
        return original(sel) ?? document.createElement('textarea');
      }
      // Subsequent calls: element has disappeared
      return null;
    });
    await runDomRelayMainWorld(makeRequest());
    expect(postSpy.messages).toHaveLength(1);
    expect(postSpy.messages[0].type).toBe('WEB_LLM_NEEDS_RELOGIN');
    expect(postSpy.messages[0].message).toContain('disappeared');
  });

  it('emits WEB_LLM_CHUNK + WEB_LLM_DONE when input is present (normal flow)', async () => {
    // Set up a textarea + an assistant message element
    const ta = document.createElement('textarea');
    ta.setAttribute('data-testid', 'chat-input');
    document.body.appendChild(ta);
    const msgEl = document.createElement('div');
    msgEl.className = 'markdown-body';
    msgEl.textContent = 'old reply';
    document.body.appendChild(msgEl);

    // Track that input + change events are fired (React/Lexical reconciler
    // requires change to commit, not just input).
    const events: string[] = [];
    ta.addEventListener('input', () => events.push('input'));
    ta.addEventListener('change', () => events.push('change'));

    // New turn updates the assistant text.
    setTimeout(() => {
      msgEl.textContent = 'AI reply text';
    }, 150);

    await runDomRelayMainWorld(makeRequest());
    // Should NOT emit relogin
    const types = postSpy.messages.map((m: any) => m.type);
    expect(types).not.toContain('WEB_LLM_NEEDS_RELOGIN');
    expect(types).not.toContain('WEB_LLM_ERROR');
    expect(events).toContain('change');
  });

  it('textarea send path dispatches both input AND change on the element (React-friendly)', async () => {
    const ta = document.createElement('textarea');
    ta.setAttribute('data-testid', 'chat-input');
    document.body.appendChild(ta);
    const msgEl = document.createElement('div');
    msgEl.className = 'markdown-body';
    msgEl.textContent = 'old';
    document.body.appendChild(msgEl);

    const fired: string[] = [];
    ta.addEventListener('input', () => fired.push('input'));
    ta.addEventListener('change', () => fired.push('change'));

    setTimeout(() => {
      msgEl.textContent = 'reply-1';
    }, 100);

    await runDomRelayMainWorld(makeRequest());
    // Change is required for React's onChange to fire after value-setter writes.
    expect(fired).toContain('input');
    expect(fired).toContain('change');
  });

  it('pre-flight check uses the strategy.input.selector (not hardcoded)', async () => {
    // Test that a custom strategy with a non-existent selector triggers relogin
    const customStrategy = {
      ...GLM_DOM_STRATEGY,
      input: { ...GLM_DOM_STRATEGY.input, selector: '.custom-non-existent' },
    };
    await runDomRelayMainWorld(makeRequest({ domStrategy: customStrategy }));
    expect(postSpy.messages).toHaveLength(1);
    expect(postSpy.messages[0].type).toBe('WEB_LLM_NEEDS_RELOGIN');
  });

  it('serialized runDomRelayMainWorld remains self-contained (no outer helper refs)', async () => {
    const ta = document.createElement('textarea');
    ta.setAttribute('data-testid', 'chat-input');
    document.body.appendChild(ta);

    const msgEl = document.createElement('div');
    msgEl.className = 'markdown-body';
    msgEl.textContent = 'old reply';
    document.body.appendChild(msgEl);

    setTimeout(() => {
      msgEl.textContent = 'AI reply text';
    }, 150);

    // Simulate chrome.scripting.executeScript function serialization boundary:
    // only the function body survives, no surrounding module scope helpers.
    const serializedFn = (0, eval)(`(${runDomRelayMainWorld.toString()})`) as typeof runDomRelayMainWorld;
    await serializedFn(makeRequest());

    const types = postSpy.messages.map((m: any) => m.type);
    expect(types).not.toContain('WEB_LLM_ERROR');
    expect(types).toContain('WEB_LLM_CHUNK');
    expect(types).toContain('WEB_LLM_DONE');
  });

  it('ignores pre-existing assistant message and emits only the current turn reply', async () => {
    const ta = document.createElement('textarea');
    ta.setAttribute('data-testid', 'chat-input');
    document.body.appendChild(ta);

    // Old reply already on page before this turn starts.
    const oldEl = document.createElement('div');
    oldEl.className = 'markdown-body';
    oldEl.textContent = 'OLD_REPLY';
    document.body.appendChild(oldEl);

    // Simulate the new turn's assistant message appearing later.
    setTimeout(() => {
      const newEl = document.createElement('div');
      newEl.className = 'markdown-body';
      newEl.textContent = 'NEW_REPLY';
      document.body.appendChild(newEl);
    }, 200);

    await runDomRelayMainWorld(makeRequest());

    const chunks = postSpy.messages
      .filter((m: any) => m.type === 'WEB_LLM_CHUNK')
      .map((m: any) => m.text);

    expect(chunks.length).toBeGreaterThan(0);
    expect(chunks[0]).toBe('NEW_REPLY');
    expect(chunks).not.toContain('OLD_REPLY');
  });

  it('does not treat unchanged pre-existing assistant text as this turn result (times out instead)', async () => {
    const ta = document.createElement('textarea');
    ta.setAttribute('data-testid', 'chat-input');
    document.body.appendChild(ta);

    const oldEl = document.createElement('div');
    oldEl.className = 'markdown-body';
    oldEl.textContent = 'OLD_STATIC_REPLY';
    document.body.appendChild(oldEl);

    const fastTimeoutStrategy = {
      ...GLM_DOM_STRATEGY,
      reader: {
        ...GLM_DOM_STRATEGY.reader,
        pollIntervalMs: 50,
        stableThresholdMs: 100,
        maxTotalMs: 400,
      },
    };

    await runDomRelayMainWorld(makeRequest({ domStrategy: fastTimeoutStrategy }));

    const chunks = postSpy.messages
      .filter((m: any) => m.type === 'WEB_LLM_CHUNK')
      .map((m: any) => m.text);
    const types = postSpy.messages.map((m: any) => m.type);

    expect(chunks).not.toContain('OLD_STATIC_REPLY');
    expect(types).toContain('WEB_LLM_ERROR');
    expect(types).not.toContain('WEB_LLM_DONE');
  });

  it('sends Enter to the input element that was set (not a later activeElement)', async () => {
    const ta = document.createElement('textarea');
    ta.setAttribute('data-testid', 'chat-input');
    document.body.appendChild(ta);

    const distractor = document.createElement('input');
    document.body.appendChild(distractor);

    // Simulate provider behavior: only the real chat input handles Enter and
    // produces a new assistant message.
    ta.addEventListener('keydown', (ev) => {
      const kev = ev as KeyboardEvent;
      if (kev.key === 'Enter') {
        const out = document.createElement('div');
        out.className = 'markdown-body';
        out.textContent = 'SENT_OK';
        document.body.appendChild(out);
      }
    });

    const strategy = {
      ...GLM_DOM_STRATEGY,
      input: {
        ...GLM_DOM_STRATEGY.input,
        settleDelayMs: 80,
      },
      reader: {
        ...GLM_DOM_STRATEGY.reader,
        pollIntervalMs: 50,
        stableThresholdMs: 100,
        maxTotalMs: 1000,
      },
    };

    // Focus shifts away before send executes.
    setTimeout(() => {
      distractor.focus();
    }, 20);

    await runDomRelayMainWorld(makeRequest({ domStrategy: strategy }));

    const chunks = postSpy.messages
      .filter((m: any) => m.type === 'WEB_LLM_CHUNK')
      .map((m: any) => m.text);
    const types = postSpy.messages.map((m: any) => m.type);

    expect(chunks).toContain('SENT_OK');
    expect(types).toContain('WEB_LLM_DONE');
    expect(types).not.toContain('WEB_LLM_ERROR');
  });
});

