    const live = makeProvider({ presetId: 'glm', modelId: 'GLM-4.6' });
    const models = getAvailableWebModels([stale, live]);
    expect(models).toHaveLength(1);
    expect(models[0].id).toBe('web:glm:GLM-4.6');
  });
});

