      // Use it again before timeout
      setTimeout(() => reg.markUsed('glm' as WebProvider['presetId']), 50);
      // Wait past original timeout
      await new Promise(r => setTimeout(r, 150));
      expect(reg.getTab('glm' as WebProvider['presetId'])).toBe(1000);
    });
  });
});

describe('injectDomRelay (T7: 鈶?ISOLATED then MAIN injection + message contract)', () => {
  beforeEach(() => {
    if (!(chrome as any).scripting) {
      (chrome as any).scripting = { executeScript: vi.fn() };
    }
    (chrome.scripting.executeScript as any) = vi.fn((_opts: any) => {
      // Mock the bridge registration: ISOLATED injection returns immediately
      return Promise.resolve([{ result: { ok: true } }]);
    });
  });

  function makeRequest(overrides: Partial<DomRelayRequest> = {}): DomRelayRequest {
    return {
      providerId: 'glm',
      modelId: 'glm-4.6',
      message: 'hello',
      domStrategy: GLM_DOM_STRATEGY,
      ...overrides,
    };
  }

  it('injects ISOLATED world first, then MAIN world (order matters for bridge availability)', async () => {
    const callOrder: string[] = [];
    (chrome.scripting.executeScript as any) = vi.fn((opts: any) => {
      callOrder.push(opts.world);
      return Promise.resolve([{ result: { ok: true } }]);
    });
    await injectDomRelay(42, makeRequest());
    expect(callOrder).toEqual(['ISOLATED', 'MAIN']);
  });

  it('ISOLATED injection has correct target + world', async () => {
    const calls: any[] = [];
    (chrome.scripting.executeScript as any) = vi.fn((opts: any) => {
      calls.push(opts);
      return Promise.resolve([{ result: { ok: true } }]);
    });
    await injectDomRelay(42, makeRequest());
    const isolated = calls.find(c => c.world === 'ISOLATED');
    expect(isolated).toBeDefined();
    expect(isolated.target).toEqual({ tabId: 42 });
    expect(typeof isolated.func).toBe('function');
  });

  it('MAIN injection receives the dom relay request as args (providerId, modelId, message, domStrategy)', async () => {
    const calls: any[] = [];
    (chrome.scripting.executeScript as any) = vi.fn((opts: any) => {
      calls.push(opts);
      return Promise.resolve([{ result: { ok: true } }]);
    });
    await injectDomRelay(42, makeRequest({
      providerId: 'kimi',
      modelId: 'kimi-k2',
      message: 'hi from kimi',
    }));
    const main = calls.find(c => c.world === 'MAIN');
    expect(main).toBeDefined();
    expect(main.target).toEqual({ tabId: 42 });
    // Args is the request object (the MAIN-world orchestrator)
    expect(main.args).toEqual([expect.objectContaining({
      providerId: 'kimi',
      modelId: 'kimi-k2',
      message: 'hi from kimi',
      domStrategy: expect.objectContaining({
        input: expect.objectContaining({ selector: expect.any(String) }),
        reader: expect.objectContaining({ assistantMessageSelector: expect.any(String) }),
      }),
    })]);
  });

  it('throws if MAIN injection fails (e.g., page not ready, CSP blocks)', async () => {
    let call = 0;
    (chrome.scripting.executeScript as any) = vi.fn((_opts: any) => {
      call++;
      // 1st call (ISOLATED) ok, 2nd call (MAIN) fails
      if (call === 1) return Promise.resolve([{ result: { ok: true } }]);
      return Promise.reject(new Error('Cannot inject script'));
    });
    await expect(injectDomRelay(42, makeRequest())).rejects.toThrow('Cannot inject script');
  });
});

