// 鈹€鈹€鈹€ 娴嬭瘯杈呭姪 鈹€鈹€鈹€

let reqIdSeq = 0;

function nextReqId(): string {
  return `req-${++reqIdSeq}`;
}

/** 鏋勯€犱竴鏉?CapturedRequest锛岄粯璁?200 + JSON */
function makeRequest(overrides: Partial<CapturedRequest> = {}): CapturedRequest {
  return {
    requestId: nextReqId(),
    url: 'https://api.example.com/api/users',
    method: 'GET',
    requestHeaders: {},
    timestamp: Date.now(),
    responseStatus: 200,
    responseMimeType: 'application/json',
    responseBody: '{"ok":true}',
    ...overrides,
  };
}

/** 浠庣鐐瑰垪琛ㄤ腑鎸?method+pathname 鏌ユ壘 */
function findEndpoint(
  endpoints: EndpointMeta[],
  method: string,
  pathname: string,
): EndpointMeta | undefined {
  return endpoints.find(
    (e) => e.method === method.toUpperCase() && e.pathname === pathname,
  );
}

