    };
  }

  it('sampleCount >= 2 涓旀湁 2xx 鐘舵€佺爜 鈫?true', () => {
    expect(shouldGenerateSkill(makeEndpoint({ sampleCount: 2, statusCodes: [200] }))).toBe(true);
  });

  it('sampleCount = 1 鈫?false锛堜笉瓒虫渶灏戞牱鏈暟锛?, () => {
