/**
 * Native Messaging Host 娴嬭瘯
 *
 * 娴嬭瘯鑼冨洿锛歕n * - Native Messaging I/O锛?瀛楄妭鍓嶇紑缂栫爜/瑙ｇ爜锛塡n * - stdin 缂撳啿鍖鸿В鏋愶紙鍒嗗潡銆佽法鍧楁秷鎭級
 * - HTTP Server锛?mcp 绔偣璇锋眰-鍝嶅簲銆?health 绔偣锛塡n * - 璇锋眰-鍝嶅簲璺敱锛坮equestId 閰嶅锛塡n * - 瓒呮椂澶勭悊
 * - 浼橀泤鍏抽棴锛坰tdin EOF锛塡n */
// @vitest-environment node

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { PassThrough } from 'node:stream';
import { createServer, type Server } from 'node:http';
import {
  encodeNativeMessage,
  sendToChrome,
  StdinParser,
  RequestRouter,
  createHttpHandler,
  startNativeHost,
