  // 鈹€鈹€鈹€ action='click' 鏃剁洿鎺ヨ蛋 DOM 鈹€鈹€鈹€

  describe("action='click' 鏃剁洿鎺ヨ蛋 DOM", () => {
    it('涓嶈皟鐢?executeApiFirst锛岀洿鎺ヨ皟鐢?interactTool', async () => {
      mockInteractExecute.mockResolvedValue(makeInteractResult('Clicked: #btn'));

      const result = await smartInteractTool.execute('call-1', {
        tabId: 42,
        action: 'click',
        selector: '#btn',
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      expect(mockInteractExecute).toHaveBeenCalledWith('call-1', {
        tabId: 42,
        action: 'click',
        selector: '#btn',
        text: undefined,
      });
      expect(result.content[0]).toMatchObject({ type: 'text', text: 'Clicked: #btn' });
    });

    it('鍗充娇鏈?url 涔熶笉璧?API锛坅ction 闈?api_*锛?, async () => {
      mockInteractExecute.mockResolvedValue(makeInteractResult());

      await smartInteractTool.execute('call-1', {
        tabId: 42,
        action: 'click',
        url: 'https://api.example.com/users',
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      expect(mockInteractExecute).toHaveBeenCalledWith('call-1', expect.objectContaining({
        action: 'click',
      }));
    });

    it('action=type 鏃剁洿鎺ヨ蛋 DOM', async () => {
      mockInteractExecute.mockResolvedValue(makeInteractResult('Typed "hi" into: #input'));

      await smartInteractTool.execute('call-1', {
        tabId: 42,
        action: 'type',
        selector: '#input',
        text: 'hi',
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      expect(mockInteractExecute).toHaveBeenCalledWith('call-1', {
        tabId: 42,
        action: 'type',
        selector: '#input',
        text: 'hi',
      });
    });
  });

  // 鈹€鈹€鈹€ 鏃?url 鏃剁洿鎺ヨ蛋 DOM 鈹€鈹€鈹€

  describe('鏃?url 鏃剁洿鎺ヨ蛋 DOM', () => {
    it('action=api_submit 浣嗘棤 url 鏃惰蛋 DOM', async () => {
      mockInteractExecute.mockResolvedValue(makeInteractResult('Clicked: #btn'));

      const result = await smartInteractTool.execute('call-1', {
        tabId: 42,
        action: 'api_submit',
        selector: '#btn',
        // 鏃?url
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      // 璧?DOM 鏃?action 鐩存帴閫忎紶
      expect(mockInteractExecute).toHaveBeenCalledWith('call-1', {
        tabId: 42,
        action: 'api_submit',
        selector: '#btn',
        text: undefined,
      });
      expect(result.content[0]).toMatchObject({ type: 'text', text: 'Clicked: #btn' });
    });

    it('action=api_fill_form 浣嗘棤 url 鏃惰蛋 DOM', async () => {
      mockInteractExecute.mockResolvedValue(makeInteractResult());

      await smartInteractTool.execute('call-1', {
        tabId: 42,
        action: 'api_fill_form',
        selector: '#input',
        text: 'data',
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      expect(mockInteractExecute).toHaveBeenCalledWith('call-1', {
        tabId: 42,
        action: 'api_fill_form',
        selector: '#input',
        text: 'data',
      });
    });
  });
});

