/**
 * lib/tools/smart-read-page.ts 娴嬭瘯
 *
 * 瑕嗙洊鑼冨洿锛歕n * - mode='json' + url 鏃惰蛋 API 璺緞锛堟垚鍔燂級
 * - NoMatchError 鏃跺洖閫€鍒?readPageTool锛坢arkdown 妯″紡锛塡n * - 闈?NoMatchError 寮傚父鏃?re-throw
 * - mode='markdown' 鏃剁洿鎺ヨ蛋 DOM
 * - mode='text' 鏃剁洿鎺ヨ蛋 DOM
 * - 鏃?url 鏃剁洿鎺ヨ蛋 DOM
 *
 * mock 绛栫暐锛歕n * - vi.mock '@/lib/capture/api-executor' 鐨?executeApiFirst 鍜?NoMatchError
 * - vi.mock './read-page' 鐨?readPageTool
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';

// 鈹€鈹€鈹€ mock 澶栭儴渚濊禆 鈹€鈹€鈹€

// NoMatchError 蹇呴』鏄竴涓湡瀹炵殑 class锛岃繖鏍?`err instanceof NoMatchError` 鎵嶈兘宸ヤ綔
// 浣跨敤 vi.hoisted 纭繚 class 瀹氫箟鍦?vi.mock 宸ュ巶鎵ц鍓嶅氨宸插氨缁猏nconst { NoMatchError } = vi.hoisted(() => {
  class NoMatchError extends Error {
    constructor(message: string) {
      super(message);
      this.name = 'NoMatchError';
    }
  }
  return { NoMatchError };
});

vi.mock('@/lib/capture/api-executor', () => ({
  executeApiFirst: vi.fn(),
  NoMatchError,
}));

vi.mock('@/lib/tools/read-page', () => ({
  readPageTool: {
    name: 'read_page',
    execute: vi.fn(),
  },
}));

// 鈹€鈹€鈹€ 瀵煎叆锛堝湪 mock 涔嬪悗锛?鈹€鈹€鈹€

import { smartReadPageTool } from '@/lib/tools/smart-read-page';
import { executeApiFirst, NoMatchError as MockNoMatchError } from '@/lib/capture/api-executor';
import { readPageTool } from '@/lib/tools/read-page';

// 鈹€鈹€鈹€ mock 寮曠敤 鈹€鈹€鈹€

const mockExecuteApiFirst = vi.mocked(executeApiFirst);
const mockReadPageExecute = vi.mocked(readPageTool.execute);

// 鈹€鈹€鈹€ 娴嬭瘯杈呭姪 鈹€鈹€鈹€

/** 鏋勯€犱竴涓垚鍔熺殑 executeApiFirst 杩斿洖鍊?*/
function makeApiResult(overrides: Partial<{
  success: boolean;
  data: unknown;
  status: number;
  latencyMs: number;
  skillName: string;
  confidence: number;
  path: 'api' | 'fallback';
}> = {}) {
  return {
    success: true,
    data: { id: 1, name: 'alice' },
    status: 200,
    latencyMs: 42,
    skillName: 'auto-api-example-com-get-api-users',
    confidence: 0.85,
    path: 'api' as const,
    ...overrides,
  };
}

/** 鏋勯€犱竴涓?readPageTool 鐨勬垚鍔熻繑鍥炲€?*/
function makeReadPageResult(text: string = '# Page content') {
  return {
    content: [{ type: 'text' as const, text }],
    details: {},
  };
}

beforeEach(() => {
  vi.clearAllMocks();
});

// 鈹€鈹€鈹€ 娴嬭瘯濂椾欢 鈹€鈹€鈹€

describe('smart-read-page', () => {
  // 鈹€鈹€鈹€ mode='json' + url锛氳蛋 API 璺緞 鈹€鈹€鈹€

  describe("mode='json' + url锛氳蛋 API 璺緞", () => {
    it('鎴愬姛鏃惰繑鍥?API 缁撴灉锛圝SON 瀛楃涓诧級', async () => {
      mockExecuteApiFirst.mockResolvedValue(makeApiResult({
        data: { id: 1, name: 'alice' },
        latencyMs: 42,
        skillName: 'auto-skill-1',
        confidence: 0.85,
      }));

      const result = await smartReadPageTool.execute('call-1', {
        tabId: 42,
        mode: 'json',
        url: 'https://api.example.com/users/1',
        intent: 'get user',
      });

      // 搴旇璋冪敤 executeApiFirst
      expect(mockExecuteApiFirst).toHaveBeenCalledWith(
        'https://api.example.com/users/1',
        'GET',
        'get user',
      );
      // 涓嶅簲璇ヨ皟鐢?readPageTool
      expect(mockReadPageExecute).not.toHaveBeenCalled();

      // 杩斿洖鍊兼槸 JSON 瀛楃涓瞈n      expect(result.content).toHaveLength(1);
      expect(result.content[0].type).toBe('text');
      const parsed = JSON.parse((result.content[0] as { text: string }).text);
      expect(parsed).toEqual({
        path: 'api',
        data: { id: 1, name: 'alice' },
        latency_ms: 42,
        skill_id: 'auto-skill-1',
        confidence: 0.85,
      });
    });

    it('鏃?intent 鏃朵篃璧?API 璺緞', async () => {
      mockExecuteApiFirst.mockResolvedValue(makeApiResult());

      await smartReadPageTool.execute('call-1', {
        tabId: 42,
        mode: 'json',
        url: 'https://api.example.com/users/1',
      });

      expect(mockExecuteApiFirst).toHaveBeenCalledWith(
        'https://api.example.com/users/1',
        'GET',
        undefined,
      );
    });
  });

  // 鈹€鈹€鈹€ NoMatchError 鏃跺洖閫€鍒?readPageTool锛坢arkdown 妯″紡锛?鈹€鈹€鈹€

  describe('NoMatchError 鏃跺洖閫€鍒?readPageTool', () => {
    it('鍥為€€鏃惰皟鐢?readPageTool 骞朵互 markdown 妯″紡', async () => {
      const noMatch = new MockNoMatchError('No matching API skill for GET https://api.example.com/users/1');
      mockExecuteApiFirst.mockRejectedValue(noMatch);
      mockReadPageExecute.mockResolvedValue(makeReadPageResult('# Hello'));

      const result = await smartReadPageTool.execute('call-1', {
        tabId: 42,
        mode: 'json',
        url: 'https://api.example.com/users/1',
      });

      // 搴旇璋冪敤 readPageTool锛屼娇鐢?markdown 妯″紡
      expect(mockReadPageExecute).toHaveBeenCalledWith('call-1', { tabId: 42, mode: 'markdown' });

      // 杩斿洖鍊煎墠闈㈠姞涓?[fallback: ...]
      expect(result.content).toHaveLength(1);
      expect(result.content[0].type).toBe('text');
      const text = (result.content[0] as { text: string }).text;
      expect(text).toContain('[fallback: No matching API skill');
      expect(text).toContain('# Hello');
    });

    it('鍥為€€鏃朵娇鐢?_toolCallId 鑰岄潪鏂扮殑 id', async () => {
      mockExecuteApiFirst.mockRejectedValue(new MockNoMatchError('no match'));
      mockReadPageExecute.mockResolvedValue(makeReadPageResult());

      await smartReadPageTool.execute('my-tool-call-id', {
        tabId: 42,
        mode: 'json',
        url: 'https://api.example.com/users/1',
      });

      expect(mockReadPageExecute).toHaveBeenCalledWith('my-tool-call-id', expect.anything());
    });

    it('鍥為€€鏃?readPageTool 杩斿洖闈?text content 鏃剁洿鎺ヨ繑鍥?fallback', async () => {
      mockExecuteApiFirst.mockRejectedValue(new MockNoMatchError('no match'));
      // 鍋囪杩斿洖闈?text content锛堣櫧鐒跺疄闄呬笉浼氬彂鐢燂紝浣嗘祴璇曡鐩栬鍒嗘敮锛塡n      mockReadPageExecute.mockResolvedValue({
        content: [{ type: 'image' as const, data: 'base64...' }],
        details: {},
      } as any);

      const result = await smartReadPageTool.execute('call-1', {
        tabId: 42,
        mode: 'json',
        url: 'https://api.example.com/users/1',
      });

      // 鐩存帴杩斿洖 fallback 缁撴灉锛堜笉淇敼 content锛塡n      expect(result.content).toHaveLength(1);
      expect(result.content[0].type).toBe('image');
    });
  });

  // 鈹€鈹€鈹€ 闈?NoMatchError 寮傚父鏃?re-throw 鈹€鈹€鈹€

  describe('闈?NoMatchError 寮傚父鏃?re-throw', () => {
    it('鏅€?Error 琚噸鏂版姏鍑?, async () => {
      const err = new Error('Network timeout');
      mockExecuteApiFirst.mockRejectedValue(err);

      await expect(
        smartReadPageTool.execute('call-1', {
          tabId: 42,
          mode: 'json',
          url: 'https://api.example.com/users/1',
        }),
      ).rejects.toThrow('Network timeout');

      // 涓嶅簲璇ヨ皟鐢?readPageTool
      expect(mockReadPageExecute).not.toHaveBeenCalled();
    });

    it('瀛楃涓查敊璇閲嶆柊鎶涘嚭', async () => {
      mockExecuteApiFirst.mockRejectedValue('some string error');

      await expect(
        smartReadPageTool.execute('call-1', {
          tabId: 42,
          mode: 'json',
          url: 'https://api.example.com/users/1',
        }),
      ).rejects.toBe('some string error');

      expect(mockReadPageExecute).not.toHaveBeenCalled();
    });
  });

  // 鈹€鈹€鈹€ mode='markdown' 鏃剁洿鎺ヨ蛋 DOM 鈹€鈹€鈹€

  describe("mode='markdown' 鏃剁洿鎺ヨ蛋 DOM", () => {
    it('涓嶈皟鐢?executeApiFirst锛岀洿鎺ヨ皟鐢?readPageTool', async () => {
      mockReadPageExecute.mockResolvedValue(makeReadPageResult('# Markdown'));

      const result = await smartReadPageTool.execute('call-1', {
        tabId: 42,
        mode: 'markdown',
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      expect(mockReadPageExecute).toHaveBeenCalledWith('call-1', { tabId: 42, mode: 'markdown' });
      expect(result.content[0]).toMatchObject({ type: 'text', text: '# Markdown' });
    });

    it('鍗充娇鏈?url 涔熶笉璧?API锛坢ode 闈?json锛?, async () => {
      mockReadPageExecute.mockResolvedValue(makeReadPageResult());

      await smartReadPageTool.execute('call-1', {
        tabId: 42,
        mode: 'markdown',
        url: 'https://api.example.com/users/1',
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      expect(mockReadPageExecute).toHaveBeenCalledWith('call-1', { tabId: 42, mode: 'markdown' });
    });
  });

  // 鈹€鈹€鈹€ mode='text' 鏃剁洿鎺ヨ蛋 DOM 鈹€鈹€鈹€

  describe("mode='text' 鏃剁洿鎺ヨ蛋 DOM", () => {
    it('涓嶈皟鐢?executeApiFirst锛岀洿鎺ヨ皟鐢?readPageTool锛坱ext 妯″紡锛?, async () => {
      mockReadPageExecute.mockResolvedValue(makeReadPageResult('plain text'));

      const result = await smartReadPageTool.execute('call-1', {
        tabId: 42,
        mode: 'text',
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      expect(mockReadPageExecute).toHaveBeenCalledWith('call-1', { tabId: 42, mode: 'text' });
      expect(result.content[0]).toMatchObject({ type: 'text', text: 'plain text' });
    });

    it('鍗充娇鏈?url 涔熶笉璧?API锛坢ode=text锛?, async () => {
      mockReadPageExecute.mockResolvedValue(makeReadPageResult());

      await smartReadPageTool.execute('call-1', {
        tabId: 42,
        mode: 'text',
        url: 'https://api.example.com/users/1',
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      expect(mockReadPageExecute).toHaveBeenCalledWith('call-1', { tabId: 42, mode: 'text' });
    });
  });

  // 鈹€鈹€鈹€ 鏃?url 鏃剁洿鎺ヨ蛋 DOM 鈹€鈹€鈹€

  describe('鏃?url 鏃剁洿鎺ヨ蛋 DOM', () => {
    it('mode=json 浣嗘棤 url 鏃惰蛋 DOM锛堥粯璁?markdown锛?, async () => {
      mockReadPageExecute.mockResolvedValue(makeReadPageResult('# Default'));

      const result = await smartReadPageTool.execute('call-1', {
        tabId: 42,
        mode: 'json',
        // 鏃?url
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      // mode=json 浣嗘棤 url 鈫?璧?DOM锛宒omMode 涓?'markdown'锛堝洜涓?mode !== 'text'锛塡n      expect(mockReadPageExecute).toHaveBeenCalledWith('call-1', { tabId: 42, mode: 'markdown' });
      expect(result.content[0]).toMatchObject({ type: 'text', text: '# Default' });
    });

    it('鏃?mode 鏃?url 鏃惰蛋 DOM锛堥粯璁?markdown锛?, async () => {
      mockReadPageExecute.mockResolvedValue(makeReadPageResult());

      await smartReadPageTool.execute('call-1', {
        tabId: 42,
      });

      expect(mockExecuteApiFirst).not.toHaveBeenCalled();
      expect(mockReadPageExecute).toHaveBeenCalledWith('call-1', { tabId: 42, mode: 'markdown' });
    });
  });
});

import { describe, expect, it } from 'vitest';
import { uiToolRegistry } from '@/lib/tools/ui-registry';

// Create a fresh registry for each test to avoid singleton pollution
function createRegistry() {
  // Use the class directly if we could import it; since it's not exported,
  // we test the singleton but clean it up between tests.
  return uiToolRegistry;
}

describe('UIToolRegistry', () => {
  it('returns undefined for unregistered tools', () => {
    expect(uiToolRegistry.get('nonexistent')).toBeUndefined();
  });

  it('registers and retrieves a tool', () => {
    const name = 'test-tool-' + Date.now();
    const Component = () => null;
    uiToolRegistry.register({ name, Component });
    const got = uiToolRegistry.get(name);
    expect(got).toBeDefined();
    expect(got!.name).toBe(name);
    expect(got!.Component).toBe(Component);
  });

  it('overwrites on duplicate registration', () => {
    const name = 'dup-tool-' + Date.now();
    const C1 = () => null;
    const C2 = () => null;
    uiToolRegistry.register({ name, Component: C1 });
    uiToolRegistry.register({ name, Component: C2 });
    expect(uiToolRegistry.get(name)!.Component).toBe(C2);
  });

  it('getAll returns registered tools', () => {
    const before = uiToolRegistry.getAll().length;
    const name = 'all-tool-' + Date.now();
    uiToolRegistry.register({ name, Component: () => null });
    const after = uiToolRegistry.getAll().length;
    expect(after).toBe(before + 1);
    expect(uiToolRegistry.getAll().some(t => t.name === name)).toBe(true);
  });
});

import { describe, expect, it } from 'vitest';
import {
  parseMatchPattern,
  formatMatchPattern,
  matchUrl,
  parseBgFetchPatterns,
  type MatchPattern,
} from '@/lib/tools/url-pattern';

describe('parseMatchPattern', () => {
  it('parses <all_urls>', () => {
    const p = parseMatchPattern('<all_urls>');
    expect(p.isAllUrls).toBe(true);
    expect(p.scheme).toBe('*');
    expect(p.host).toBe('*');
    expect(p.pathGlob).toBe('/*');
    expect(p.pathRe.test('/anything')).toBe(true);
  });

  it('parses *://*/*', () => {
    const p = parseMatchPattern('*://*/*');
    expect(p.scheme).toBe('*');
    expect(p.host).toBe('*');
    expect(p.pathGlob).toBe('/*');
  });

  it('parses https://example.com/*', () => {
    const p = parseMatchPattern('https://example.com/*');
    expect(p.scheme).toBe('https');
    expect(p.host).toBe('example.com');
    expect(p.pathGlob).toBe('/*');
  });

  it('parses http://*.foo.com/path/*', () => {
    const p = parseMatchPattern('http://*.foo.com/path/*');
    expect(p.scheme).toBe('http');
    expect(p.host).toBe('*.foo.com');
    expect(p.pathGlob).toBe('/path/*');
  });

  it('normalizes scheme to lowercase', () => {
    const p = parseMatchPattern('HTTPS://EXAMPLE.COM/*');
    expect(p.scheme).toBe('https');
    expect(p.host).toBe('example.com');
  });

  it('throws on malformed pattern', () => {
    expect(() => parseMatchPattern('bad')).toThrow(/malformed pattern/);
    expect(() => parseMatchPattern('ftp://example.com/*')).toThrow(/unsupported scheme/);
  });

  it('throws on invalid host', () => {
    expect(() => parseMatchPattern('https://exa@mple.com/*')).toThrow(/invalid host/);
  });
});

describe('formatMatchPattern', () => {
  it('round-trips all_urls', () => {
    const p = parseMatchPattern('<all_urls>');
    expect(formatMatchPattern(p)).toBe('<all_urls>');
  });

  it('round-trips normal pattern', () => {
    const p = parseMatchPattern('https://example.com/*');
    expect(formatMatchPattern(p)).toBe('https://example.com/*');
  });
});

describe('matchUrl', () => {
  it('matches exact host and path', () => {
    const p = parseMatchPattern('https://example.com/*');
    expect(matchUrl(new URL('https://example.com/'), p)).toBe(true);
    expect(matchUrl(new URL('https://example.com/foo'), p)).toBe(true);
  });

  it('rejects wrong scheme', () => {
    const p = parseMatchPattern('https://example.com/*');
    expect(matchUrl(new URL('http://example.com/'), p)).toBe(false);
  });

  it('rejects wrong host', () => {
    const p = parseMatchPattern('https://example.com/*');
    expect(matchUrl(new URL('https://other.com/'), p)).toBe(false);
  });

  it('matches wildcard scheme for http and https', () => {
    const p = parseMatchPattern('*://example.com/*');
    expect(matchUrl(new URL('http://example.com/'), p)).toBe(true);
    expect(matchUrl(new URL('https://example.com/'), p)).toBe(true);
    expect(matchUrl(new URL('ftp://example.com/'), p)).toBe(false);
  });

  it('matches subdomain wildcard', () => {
    const p = parseMatchPattern('https://*.foo.com/*');
    expect(matchUrl(new URL('https://foo.com/'), p)).toBe(true);
    expect(matchUrl(new URL('https://bar.foo.com/'), p)).toBe(true);
    expect(matchUrl(new URL('https://baz.bar.foo.com/'), p)).toBe(true);
    expect(matchUrl(new URL('https://notfoo.com/'), p)).toBe(false);
  });

  it('matches exact path', () => {
    const p = parseMatchPattern('https://example.com/api/*');
    expect(matchUrl(new URL('https://example.com/api/v1'), p)).toBe(true);
    expect(matchUrl(new URL('https://example.com/other'), p)).toBe(false);
  });

  it('matches all_urls against any http(s)', () => {
    const p = parseMatchPattern('<all_urls>');
    expect(matchUrl(new URL('https://any.host/path'), p)).toBe(true);
  });
});

describe('parseBgFetchPatterns', () => {
  it('returns null when no bgFetch permissions', () => {
    expect(parseBgFetchPatterns(['read_page', 'interact'])).toBeNull();
  });

  it('parses bare bgFetch as wildcard', () => {
    const ps = parseBgFetchPatterns(['bgFetch']);
    expect(ps).toHaveLength(1);
    expect(ps![0].scheme).toBe('*');
    expect(ps![0].host).toBe('*');
  });

  it('parses bgFetch:pattern', () => {
    const ps = parseBgFetchPatterns(['bgFetch:https://api.example.com/*']);
    expect(ps).toHaveLength(1);
