    for (let i = 0; i < 3; i++) {
      const state = await getRunState(`run-batch-${i}`);
      expect(state?.status).toBe('success');
      expect(state?.endedAt).toBeGreaterThan(0);
    }
  });

  // 鈹€鈹€鈹€ 6. 鎭㈠鎸佺画澶辫触鐨?run 琚爣璁颁负 failure 鈹€鈹€鈹€

  it('鎭㈠鏃舵寔缁姏鍑哄紓甯哥殑 run 琚爣璁颁负 failure锛岄槻姝㈡棤闄愰噸璇?, async () => {
    mockExecuteWorkflow.mockImplementation(async () => {
      throw new Error('Persistent SW crash');
    });

    const steps = [{ type: 'click' as const, selector: '#btn' }];
    const wf = makeWorkflow({ id: 'wf-fail', steps });
    await createWorkflow(wf);
    await createRunState({
      workflowId: wf.id,
      runId: 'run-fail-1',
      status: 'running',
      currentStepIndex: 0,
      variables: {},
      startedAt: Date.now(),
    });

    await recoverRunningWorkflows();

    const state = await getRunState('run-fail-1');
    expect(state?.status).toBe('failure');
    expect(state?.error).toContain('Persistent SW crash');
    expect(state?.endedAt).toBeGreaterThan(0);
  });

  // 鈹€鈹€鈹€ 7. 闀?Workflow锛?0 姝ワ級鐘舵€佷竴鑷存€?鈹€鈹€鈹€

  it('50 姝ラ暱 workflow 鐨勭姸鎬佹洿鏂颁繚鎸佹纭笖鏈€缁堟垚鍔?, async () => {
    mockNormalExecution();

    const steps = Array.from({ length: 50 }, (_, i) => ({
      type: 'click' as const,
      selector: `#item-${i}`,
    }));
    const workflow = makeWorkflow({ id: 'wf-long', steps });
    await createWorkflow(workflow);

    const result = await startWorkflowRun(workflow);

    expect(result.success).toBe(true);
    expect(result.stepResults).toHaveLength(50);

    const finalState = await getRunState(result.runId);
    expect(finalState?.status).toBe('success');
    expect(finalState?.currentStepIndex).toBe(50);

    // 楠岃瘉鎵€鏈変腑闂寸姸鎬侀兘琚纭洿鏂帮紙鏈€缁?currentStepIndex 搴斾负 50锛塡n    expect(mockExecuteWorkflow).toHaveBeenCalledTimes(1);
    const callArgs = mockExecuteWorkflow.mock.calls[0][1] as any;
    expect(callArgs.startStepIndex).toBeUndefined();
  });

  // 鈹€鈹€鈹€ 8. if/宓屽姝ラ涓殑涓柇鎭㈠琛屼负 鈹€鈹€鈹€

  it('if 姝ラ鍐呴儴瀛愭楠ゆ墽琛屾椂涓柇锛屾仮澶嶅悗閲嶆柊鎵ц鏁翠釜 if 姝ラ', async () => {
    // if 姝ラ鍦?executor 涓槸鍘熷瓙鎿嶄綔锛氬瓙姝ラ涓嶅崟鐙Е鍙?onStepStart/onStepEnd
    // 鍥犳 engine 鐨?currentStepIndex 鎸囧悜 if 姝ラ鏈韩
    mockExecuteWorkflow.mockImplementationOnce(async (workflow, options = {}) => {
      const start = options.startStepIndex ?? 0;
      for (let i = start; i < workflow.steps.length; i++) {
        options.onStepStart?.(workflow.steps[i], i);
        if (i === 1) {
          // 妯℃嫙 if 姝ラ鎵ц涓穿婧僜n          throw new Error('SW terminated inside if-step');
        }
        const result = {
          step: workflow.steps[i],
          index: i,
          success: true,
          output: `step-${i}-ok`,
          durationMs: 10,
          variables: { ...options.variables },
        };
        options.onStepEnd?.(workflow.steps[i], i, result);
      }
      return { success: true, stepResults: [], variables: options.variables ?? {} };
    });

    mockNormalExecution();

    const steps: any[] = [
      { type: 'navigate', url: 'https://example.com' },
      {
        type: 'if',
        condition: { variable: 'x', operator: 'eq', value: '1' },
        thenSteps: [
          { type: 'click', selector: '#a' },
          { type: 'click', selector: '#b' },
        ],
      },
      { type: 'click', selector: '#c' },
    ];
    const workflow = makeWorkflow({ id: 'wf-if', steps });
    await createWorkflow(workflow);

    await expect(startWorkflowRun(workflow)).rejects.toThrow('SW terminated inside if-step');

    const state = await getRunState('run-1');
    expect(state?.status).toBe('running');
    // if 姝ラ鐨?onStepStart 琚皟鐢ㄥ悗宕╂簝锛宑urrentStepIndex 搴斾负 1
    expect(state?.currentStepIndex).toBe(1);

    const result = await resumeWorkflowRun(state!);
    expect(result.success).toBe(true);

    // 鎭㈠鍚庝粠绱㈠紩 1锛坕f 姝ラ锛夊紑濮嬫墽琛孿n    expect(result.stepResults[0].index).toBe(1);
    expect(result.stepResults[1].index).toBe(2);

    const finalState = await getRunState('run-1');
    expect(finalState?.status).toBe('success');
  });

  // 鈹€鈹€鈹€ 9. startStepIndex 杈圭晫锛氫粠鏈€鍚庝竴姝ユ仮澶嶅悗鎴愬姛 鈹€鈹€鈹€

  it('浠庢渶鍚庝竴姝ワ紙绱㈠紩绛変簬 steps.length - 1锛夋仮澶嶅悗鎵ц鏈€鍚庝竴姝ュ苟鎴愬姛', async () => {
    mockNormalExecution();

    const steps = [
      { type: 'click' as const, selector: '#a' },
      { type: 'click' as const, selector: '#b' },
    ];
    const wf = makeWorkflow({ id: 'wf-last', steps });
    await createWorkflow(wf);
    await createRunState({
      workflowId: wf.id,
      runId: 'run-last',
      status: 'running',
      currentStepIndex: 1,
      variables: {},
      startedAt: Date.now(),
    });

    const result = await resumeWorkflowRun({
      workflowId: wf.id,
      runId: 'run-last',
      status: 'running',
      currentStepIndex: 1,
      variables: {},
      startedAt: Date.now(),
    });

    expect(result.success).toBe(true);
    expect(result.stepResults).toHaveLength(1);
    expect(result.stepResults[0].index).toBe(1);

    const finalState = await getRunState('run-last');
    expect(finalState?.status).toBe('success');
    expect(finalState?.currentStepIndex).toBe(2);
  });

  // 鈹€鈹€鈹€ 10. 绌?workflow 绔嬪嵆鎴愬姛 鈹€鈹€鈹€

  it('0 姝?workflow 绔嬪嵆杩斿洖鎴愬姛', async () => {
    mockNormalExecution();

    const workflow = makeWorkflow({ id: 'wf-empty', steps: [] });
    await createWorkflow(workflow);

    const result = await startWorkflowRun(workflow);
    expect(result.success).toBe(true);
    expect(result.stepResults).toHaveLength(0);

    const finalState = await getRunState(result.runId);
    expect(finalState?.status).toBe('success');
    expect(finalState?.currentStepIndex).toBe(0);
  });
});

/**
 * Workflow Executor 閲嶈瘯鏈哄埗娴嬭瘯
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

// 妯℃嫙 chrome.tabs
const mockChromeTabs = {
  query: vi.fn(),
  update: vi.fn(),
};

// 妯℃嫙 tab-helpers
const mockExecuteInTabWithArgs = vi.fn();
const mockWaitForNavigation = vi.fn();

vi.mock('@/lib/tab-helpers', () => ({
  executeInTabWithArgs: (...args: unknown[]) => mockExecuteInTabWithArgs(...args),
  waitForNavigation: (...args: unknown[]) => mockWaitForNavigation(...args),
}));

vi.mock('@/lib/tools/interact', () => ({
  performInteraction: vi.fn(),
}));

import { executeWorkflow } from '@/lib/workflow/executor';
import type { Workflow } from '@/lib/workflow/types';

describe('executeWorkflow retry behavior', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockChromeTabs.query.mockResolvedValue([{ id: 123 }]);
    mockWaitForNavigation.mockResolvedValue('Navigation complete');
    global.chrome = { tabs: mockChromeTabs } as unknown as typeof chrome;
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('retries click step on element-not-found error and succeeds on second attempt', async () => {
    mockExecuteInTabWithArgs
      .mockRejectedValueOnce(new Error('Element not found: #btn'))
      .mockResolvedValueOnce('Clicked #btn');

    const workflow: Workflow = {
      id: 'wf-1',
      name: 'Retry Test',
      steps: [{ type: 'click', selector: '#btn' }],
      createdAt: 1,
      updatedAt: 1,
      runCount: 0,
    };

    const result = await executeWorkflow(workflow, { tabId: 123 });
    expect(result.success).toBe(true);
    expect(mockExecuteInTabWithArgs).toHaveBeenCalledTimes(2);
  });

  it('retries extract step up to 3 times then fails', async () => {
    mockExecuteInTabWithArgs.mockResolvedValue(null);

    const workflow: Workflow = {
      id: 'wf-1',
      name: 'Retry Fail Test',
      steps: [{ type: 'extract', selector: '#missing', toVariable: 'x' }],
      createdAt: 1,
      updatedAt: 1,
      runCount: 0,
    };

    const result = await executeWorkflow(workflow, { tabId: 123 });
    expect(result.success).toBe(false);
    // extract: 鍒濆灏濊瘯 + 3娆￠噸璇?= 4娆¤皟鐢╘n    expect(mockExecuteInTabWithArgs).toHaveBeenCalledTimes(4);
  });

  it('does not retry non-retryable errors immediately', async () => {
    mockExecuteInTabWithArgs.mockRejectedValue(new Error('Permission denied'));

    const workflow: Workflow = {
      id: 'wf-1',
      name: 'No Retry Test',
      steps: [{ type: 'click', selector: '#btn' }],
      createdAt: 1,
      updatedAt: 1,
      runCount: 0,
    };

    const result = await executeWorkflow(workflow, { tabId: 123 });
    expect(result.success).toBe(false);
    // 闈炲彲閲嶈瘯閿欒鍙皾璇?娆n    expect(mockExecuteInTabWithArgs).toHaveBeenCalledTimes(1);
  });

  it('retries type step with exponential backoff delay', async () => {
    mockExecuteInTabWithArgs
      .mockRejectedValueOnce(new Error('No element matches selector'))
      .mockRejectedValueOnce(new Error('No element matches selector'))
      .mockResolvedValueOnce('Typed into #input');

    const workflow: Workflow = {
      id: 'wf-1',
      name: 'Type Retry Test',
      steps: [{ type: 'type', selector: '#input', text: 'hello' }],
      createdAt: 1,
      updatedAt: 1,
      runCount: 0,
    };

    const start = Date.now();
    const result = await executeWorkflow(workflow, { tabId: 123 });
    const elapsed = Date.now() - start;

    expect(result.success).toBe(true);
    expect(mockExecuteInTabWithArgs).toHaveBeenCalledTimes(3);
    // 鎸囨暟閫€閬? 绗竴娆￠噸璇?500ms锛岀浜屾 1000ms锛屾€昏鑷冲皯 1400ms
    expect(elapsed).toBeGreaterThanOrEqual(1400);
  });

  it('does not retry scroll or wait steps', async () => {
    mockExecuteInTabWithArgs.mockRejectedValue(new Error('Element not found'));

    const workflow: Workflow = {
      id: 'wf-1',
      name: 'No Retry Scroll',
      steps: [{ type: 'scroll', deltaY: 100 }],
      createdAt: 1,
      updatedAt: 1,
      runCount: 0,
    };

    const result = await executeWorkflow(workflow, { tabId: 123 });
    expect(result.success).toBe(false);
    // scroll 涓嶅湪 RETRYABLE_STEP_TYPES 涓紝鍙皾璇?娆n    expect(mockExecuteInTabWithArgs).toHaveBeenCalledTimes(1);
  });

  it('includes retry info in step result output when successful after retry', async () => {
    mockExecuteInTabWithArgs
      .mockRejectedValueOnce(new Error('Timed out waiting for element'))
      .mockResolvedValueOnce('Clicked #btn');

    const stepResults: { success: boolean; output?: string; error?: string }[] = [];
    const workflow: Workflow = {
      id: 'wf-1',
      name: 'Retry Success',
      steps: [{ type: 'click', selector: '#btn' }],
      createdAt: 1,
      updatedAt: 1,
      runCount: 0,
    };

    await executeWorkflow(workflow, {
      tabId: 123,
      onStepEnd: (_step, _index, result) => stepResults.push(result),
    });

    expect(stepResults[0].success).toBe(true);
    expect(stepResults[0].output).toBe('Clicked #btn');
  });

  it('logs retry attempts via console.warn', async () => {
    const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
    mockExecuteInTabWithArgs
      .mockRejectedValueOnce(new Error('Element not found'))
      .mockResolvedValueOnce('Clicked #btn');

    const workflow: Workflow = {
      id: 'wf-1',
      name: 'Retry Logging Test',
      steps: [{ type: 'click', selector: '#btn' }],
      createdAt: 1,
      updatedAt: 1,
      runCount: 0,
    };

    await executeWorkflow(workflow, { tabId: 123 });
    expect(warnSpy).toHaveBeenCalledTimes(1);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('[Workflow] Step "click" failed (attempt 1/4), retrying in 500ms: Element not found'),
    );
    warnSpy.mockRestore();
  });

  it('respects maxDelayMs cap for exponential backoff', async () => {
    const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
    // 杩炵画澶辫触3娆★紝瑙﹀彂绗?銆?銆?娆￠噸璇曪紝寤惰繜搴旇涓婇檺鎴柇
    mockExecuteInTabWithArgs
      .mockRejectedValueOnce(new Error('Element not found'))
      .mockRejectedValueOnce(new Error('Element not found'))
      .mockRejectedValueOnce(new Error('Element not found'))
      .mockResolvedValueOnce('Clicked #btn');

    const workflow: Workflow = {
      id: 'wf-1',
      name: 'Max Delay Test',
      steps: [{ type: 'click', selector: '#btn' }],
      createdAt: 1,
      updatedAt: 1,
      runCount: 0,
    };

    const start = Date.now();
    await executeWorkflow(workflow, { tabId: 123 });
    const elapsed = Date.now() - start;

    // 寤惰繜: 500 + 1000 + 2000 = 3500ms (鍧囨湭瓒呰繃 5000ms 涓婇檺)
    expect(elapsed).toBeGreaterThanOrEqual(3300);

    // 楠岃瘉绗?娆￠噸璇曠殑寤惰繜涓?2000ms锛屼笉鏄?4000ms
    const calls = warnSpy.mock.calls;
    expect(calls[2][0]).toContain('retrying in 2000ms');
    warnSpy.mockRestore();
  });

  it('aborts retry delay when signal is triggered', async () => {
    mockExecuteInTabWithArgs.mockRejectedValue(new Error('Element not found'));

    const workflow: Workflow = {
      id: 'wf-1',
      name: 'Abort Retry Test',
      steps: [{ type: 'click', selector: '#btn' }],
      createdAt: 1,
      updatedAt: 1,
      runCount: 0,
    };

    const controller = new AbortController();
    const promise = executeWorkflow(workflow, { tabId: 123, signal: controller.signal });

    // 鍦?100ms 鍚庤Е鍙?abort锛岀‘淇濆湪閲嶈瘯寤惰繜鏈熼棿鍙栨秷
    setTimeout(() => controller.abort(), 100);

    const result = await promise;
    expect(result.success).toBe(false);
    expect(result.error).toContain('aborted');
  });

  it('retries all retryable step types on element-not-found errors', async () => {
    const retryableTypes = ['click', 'type', 'select', 'focus', 'hover', 'dblclick', 'rightclick'];

    for (const stepType of retryableTypes) {
      vi.clearAllMocks();
      mockExecuteInTabWithArgs
        .mockRejectedValueOnce(new Error('Element not found'))
        .mockResolvedValueOnce('OK');

      const step: any = { type: stepType, selector: '#target' };
      if (stepType === 'type') step.text = 'hello';
      if (stepType === 'select') step.text = 'option1';

      const workflow: Workflow = {
        id: 'wf-1',
        name: `Retry ${stepType}`,
        steps: [step],
        createdAt: 1,
        updatedAt: 1,
        runCount: 0,
      };

      const result = await executeWorkflow(workflow, { tabId: 123 });
      expect(result.success).toBe(true);
      expect(mockExecuteInTabWithArgs).toHaveBeenCalledTimes(2);
    }
  });
});

