import 'fake-indexeddb/auto';
import { beforeEach, describe, expect, it } from 'vitest';
import { getDb } from '@/lib/db';
import type { Workflow } from '@/lib/workflow/types';
import {
  createWorkflow,
  getWorkflow,
  listWorkflows,
  updateWorkflow,
  deleteWorkflow,
  recordWorkflowRun,
  searchWorkflows,
  getMostUsedWorkflows,
  validateWorkflow,
} from '@/lib/workflow/repository';

// 鈹€鈹€鈹€ 娴嬭瘯杈呭姪 鈹€鈹€鈹€

function makeWorkflow(overrides: Partial<Workflow> = {}): Workflow {
  const now = Date.now();
  return {
    id: `wf-${now}-${Math.random().toString(36).slice(2, 7)}`,
    name: 'Test Workflow',
    description: 'For unit testing',
    steps: [
      { type: 'navigate', url: 'https://example.com' },
      { type: 'click', selector: '#btn' },
    ],
    trigger: { type: 'manual' },
    variables: { q: 'test' },
    createdAt: now,
    updatedAt: now,
    runCount: 0,
    ...overrides,
  };
}

// 鈹€鈹€鈹€ validateWorkflow 鈹€鈹€鈹€

describe('validateWorkflow', () => {
  it('閫氳繃鍚堟硶鐨?Workflow', () => {
    const wf = makeWorkflow();
    expect(() => validateWorkflow(wf)).not.toThrow();
  });

  it('rejects null', () => {
    expect(() => validateWorkflow(null)).toThrow('Workflow must be an object');
  });

  it('rejects empty object', () => {
    expect(() => validateWorkflow({})).toThrow('id must be a non-empty string');
  });

  it('rejects empty id', () => {
    const wf = makeWorkflow({ id: '' });
    expect(() => validateWorkflow(wf)).toThrow('id must be a non-empty string');
  });

