// 鈹€鈹€鈹€ Form state 鈹€鈹€鈹€

type TransportType = MCPTransportConfig['type'];
type AuthType = MCPAuthConfig['type'];

export interface MCPFormValues {
  name: string;
  transportType: TransportType;
  url: string;
  authType: AuthType;
  bearerToken: string;
  /**
   * Headers as an editable array; rows may temporarily have empty keys/values
   * while the user is typing. `formToInput` aggregates them into the storage
   * `Record<string, string>` shape (case-insensitive, last-write-wins) and
   * silently drops rows with empty keys.
   */
  headers: Array<{ key: string; value: string }>;
}

const makeEmpty = (): MCPFormValues => ({
  name: '',
  transportType: 'streamable-http',
  url: '',
  authType: 'none',
  bearerToken: '',
  headers: [],
});

/**
 * Build a store-shaped input from form values. Throws on missing required
 * fields. The store layer (`validateAndNormalize`) does final URL/auth checks.
 */
export function formToInput(values: MCPFormValues): {
  name: string;
  transport: MCPTransportConfig;
  auth: MCPAuthConfig;
} {
  const auth: MCPAuthConfig = values.authType === 'bearer'
    ? { type: 'bearer', token: values.bearerToken.trim() }
    : { type: 'none' };

  // Aggregate header rows: skip empty keys, normalize via Headers (case-
  // insensitive, last write wins). Only attach `headers` when non-empty so
  // the stored record stays minimal.
  let headers: Record<string, string> | undefined;
  if (values.headers.length > 0) {
    const h = new Headers();
    for (const row of values.headers) {
      const k = row.key.trim();
      if (!k) continue;
      h.set(k, row.value);
    }
    const out: Record<string, string> = {};
    h.forEach((v, k) => { out[k] = v; });
    if (Object.keys(out).length > 0) headers = out;
  }

  const transport: MCPTransportConfig = {
    type: values.transportType,
    url: values.url.trim(),
    ...(headers ? { headers } : {}),
  };
  return { name: values.name.trim(), transport, auth };
}

// 鈹€鈹€鈹€ Shared form body 鈹€鈹€鈹€

interface FormBodyProps {
  values: MCPFormValues;
  onChange: (patch: Partial<MCPFormValues>) => void;
  onSubmit: () => void;
  onCancel: () => void;
  submitLabel: string;
  submitDisabled: boolean;
}

export function MCPFormBody({
  values,
  onChange,
  onSubmit,
  onCancel,
  submitLabel,
  submitDisabled,
}: FormBodyProps) {
  const onEnter = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !submitDisabled) {
      e.preventDefault();
      onSubmit();
    }
  };
  // Header rows: Enter must NOT submit (user is mid-edit, multi-row).
  const onHeaderKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') e.preventDefault();
  };
  return (
    <div className="space-y-3 border border-border rounded-lg p-3">
      <div className="space-y-2">
        <Label className="text-xs">{t('settings.mcp.form.name')}</Label>
        <Input
          value={values.name}
          onChange={(e) => onChange({ name: e.target.value })}
          onKeyDown={onEnter}
          placeholder={t('settings.mcp.form.namePlaceholder')}
          className="h-8 text-sm"
        />
      </div>

      <div className="space-y-2">
        <Label className="text-xs">{t('settings.mcp.form.transport')}</Label>
        <div className="flex gap-1">
          {(['streamable-http', 'sse'] as const).map((tt) => {
            const active = values.transportType === tt;
            return (
              <Button
                key={tt}
                type="button"
                variant={active ? 'default' : 'outline'}
                size="sm"
                className={active ? 'border border-transparent' : undefined}
                onClick={() => onChange({ transportType: tt })}
              >
                {tt}
              </Button>
            );
          })}
        </div>
      </div>

      <div className="space-y-2">
        <Label className="text-xs">{t('settings.mcp.form.url')}</Label>
        <Input
          value={values.url}
          onChange={(e) => onChange({ url: e.target.value })}
          onKeyDown={onEnter}
          placeholder={t('settings.mcp.form.urlPlaceholder')}
          className="h-8 text-sm font-mono"
        />
      </div>

      <Separator />

      <div className="space-y-2">
        <Label className="text-xs">{t('settings.mcp.form.authType')}</Label>
        <div className="flex gap-1">
          <Button
            type="button"
            variant={values.authType === 'none' ? 'default' : 'outline'}
            size="sm"
            className={values.authType === 'none' ? 'border border-transparent' : undefined}
            onClick={() => onChange({ authType: 'none' })}
          >
            {t('settings.mcp.form.authNone')}
          </Button>
          <Button
            type="button"
            variant={values.authType === 'bearer' ? 'default' : 'outline'}
            size="sm"
            className={values.authType === 'bearer' ? 'border border-transparent' : undefined}
            onClick={() => onChange({ authType: 'bearer' })}
          >
            {t('settings.mcp.form.authBearer')}
          </Button>
        </div>
      </div>

      {values.authType === 'bearer' && (
        <div className="space-y-2">
          <Label className="text-xs">{t('settings.mcp.form.bearerToken')}</Label>
          <Input
            type="password"
            value={values.bearerToken}
            onChange={(e) => onChange({ bearerToken: e.target.value })}
            onKeyDown={onEnter}
            placeholder={t('settings.mcp.form.bearerTokenPlaceholder')}
            className="h-8 text-sm font-mono"
          />
        </div>
      )}

      <Separator />

      <div className="space-y-2">
        <Label className="text-xs">{t('settings.mcp.form.headers')}</Label>
        {values.headers.length > 0 && (
          <div className="space-y-1">
            {values.headers.map((row, idx) => (
              <div key={idx} className="flex items-center gap-1">
                <Input
                  value={row.key}
                  onChange={(e) => {
                    const next = values.headers.map((r, i) => (i === idx ? { ...r, key: e.target.value } : r));
                    onChange({ headers: next });
                  }}
                  onKeyDown={onHeaderKeyDown}
                  placeholder={t('settings.mcp.form.headerKeyPlaceholder')}
                  className="h-8 text-sm font-mono flex-1"
                />
                <Input
                  value={row.value}
                  onChange={(e) => {
                    const next = values.headers.map((r, i) => (i === idx ? { ...r, value: e.target.value } : r));
                    onChange({ headers: next });
                  }}
                  onKeyDown={onHeaderKeyDown}
                  placeholder={t('settings.mcp.form.headerValuePlaceholder')}
                  className="h-8 text-sm font-mono flex-1"
                />
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="size-7 shrink-0 text-muted-foreground hover:text-destructive"
                  onClick={() => onChange({ headers: values.headers.filter((_, i) => i !== idx) })}
                  aria-label={t('settings.mcp.form.removeHeader')}
                >
                  <Trash2 className="size-3.5" />
                </Button>
              </div>
            ))}
          </div>
        )}
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="w-full"
          onClick={() => onChange({ headers: [...values.headers, { key: '', value: '' }] })}
        >
          <Plus className="size-3.5" />
          {t('settings.mcp.form.addHeader')}
        </Button>
      </div>

      <div className="flex justify-end gap-2 pt-1">
        <Button type="button" variant="ghost" size="sm" onClick={onCancel}>{t('common.cancel')}</Button>
        <Button type="button" size="sm" onClick={onSubmit} disabled={submitDisabled}>{submitLabel}</Button>
      </div>
    </div>
  );
}

// 鈹€鈹€鈹€ Add server: collapsed button 鈫?expanded form 鈹€鈹€鈹€

export function MCPServerAddForm() {
  const [expanded, setExpanded] = useState(false);
  const [values, setValues] = useState<MCPFormValues>(makeEmpty);
  const [busy, setBusy] = useState(false);

  const reset = () => {
    setValues(makeEmpty());
    setExpanded(false);
  };

  const handleSubmit = async () => {
    if (busy) return;
    setBusy(true);
    try {
      await addMCPServer(formToInput(values));
      reset();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  if (!expanded) {
    return (
      <Button variant="outline" size="sm" className="w-full" onClick={() => setExpanded(true)}>
        <Plus className="size-3.5" />
        {t('settings.mcp.actions.add')}
      </Button>
    );
  }

  const submitDisabled = busy
    || !values.name.trim()
    || !values.url.trim()
    || (values.authType === 'bearer' && !values.bearerToken.trim());

  return (
    <MCPFormBody
      values={values}
      onChange={(patch) => setValues((v) => ({ ...v, ...patch }))}
      onSubmit={handleSubmit}
      onCancel={reset}
      submitLabel={t('common.add')}
      submitDisabled={submitDisabled}
    />
  );
}

// 鈹€鈹€鈹€ Edit existing server 鈹€鈹€鈹€

function configToValues(server: MCPServerConfig): MCPFormValues {
  const headerRows = server.transport.headers
    ? Object.entries(server.transport.headers).map(([key, value]) => ({ key, value }))
    : [];
  return {
    name: server.name,
    transportType: server.transport.type,
    url: server.transport.url,
    authType: server.auth.type,
    bearerToken: server.auth.type === 'bearer' ? server.auth.token : '',
    headers: headerRows,
  };
}

interface MCPServerEditFormProps {
  server: MCPServerConfig;
  onDone: () => void;
}

export function MCPServerEditForm({ server, onDone }: MCPServerEditFormProps) {
  const [values, setValues] = useState<MCPFormValues>(() => configToValues(server));
  const [busy, setBusy] = useState(false);

  const handleSubmit = async () => {
    if (busy) return;
    setBusy(true);
    try {
      const input = formToInput(values);
      await updateMCPServer(server.id, {
        name: input.name,
        transport: input.transport,
        auth: input.auth,
      });
      onDone();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const submitDisabled = busy
    || !values.name.trim()
    || !values.url.trim()
    || (values.authType === 'bearer' && !values.bearerToken.trim());

  return (
    <MCPFormBody
      values={values}
      onChange={(patch) => setValues((v) => ({ ...v, ...patch }))}
      onSubmit={handleSubmit}
      onCancel={onDone}
      submitLabel={t('common.save')}
      submitDisabled={submitDisabled}
    />
  );
}

import { useState, useMemo, useEffect } from "react";
import { Eye, EyeOff, Unplug, Save } from "lucide-react";
import {
  getModels,
  complete,
  type KnownProvider,
  type Api,
  type Model,
} from "@earendil-works/pi-ai";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import { Badge } from "@/components/ui/badge";
import { isCustomProvider } from "@/lib/custom-models";
import { t } from "@/lib/i18n";
import type { ApiKeyCredential } from "@/lib/storage";

interface ProviderApiKeyItemProps {
  provider: string;
  label: string;
  models?: Model<Api>[];
  credential?: ApiKeyCredential;
  onSave: (credential: ApiKeyCredential) => void;
  onRemove?: () => void;
}

export function ProviderApiKeyItem({
  provider,
  label,
  models: modelsProp,
  credential,
  onSave,
  onRemove,
}: ProviderApiKeyItemProps) {
  const [key, setKey] = useState(credential?.apiKey ?? "");
  const [showKey, setShowKey] = useState(false);
  const [saving, setSaving] = useState(false);

  // 鍑嵁鐢?storage 寮傛鍔犺浇锛岄娆℃寕杞芥椂 credential 寰€寰€杩樻槸 undefined锛坲seStorageItem
  // 鍏堣繑鍥?fallback锛夈€傜瓑鐪熷疄鍑嵁鍒拌揪鍚庢妸瀹冨悓姝ヨ繘鏈湴杈撳叆妗嗭紝鍚﹀垯淇濆瓨杩囩殑 key 閲嶈繘
  // 璁剧疆椤典細鏄剧ず涓虹┖銆備粎鍦?credential.apiKey 鍙樺寲鏃惰Е鍙戯細鍑嵁鍔犺浇瀹屾垚鍚庯紝鏈繚瀛樼殑
  // 鏅€氳緭鍏ヤ笉浼氳瑕嗙洊锛堟鏃?credential.apiKey 涓嶅彉锛夈€俓n  useEffect(() => {
    setKey(credential?.apiKey ?? "");
  }, [credential?.apiKey]);

  const [status, setStatus] = useState<
    | { type: "success"; message: string }
    | { type: "error"; message: string }
    | null
  >(null);

  const { cheapestModel, modelCount } = useMemo(() => {
    try {
      const models = modelsProp ?? (isCustomProvider(provider) ? [] : (getModels(provider as KnownProvider) as Model<Api>[]));
      if (models.length === 0) return { cheapestModel: undefined, modelCount: 0 };

      const cheapest = models.reduce((min, m) =>
        m.cost.input + m.cost.output < min.cost.input + min.cost.output ? m : min,
      );

      return { cheapestModel: cheapest, modelCount: models.length };
    } catch {
      return { cheapestModel: undefined, modelCount: 0 };
    }
  }, [provider, modelsProp]);

  const handleSave = async () => {
    if (!cheapestModel || !key.trim()) return;

    setSaving(true);
    setStatus(null);

    try {
      const result = await complete(
        cheapestModel,
        {
          messages: [
            { role: "user", content: "Reply only: ok", timestamp: Date.now() },
          ],
        },
        { apiKey: key, maxTokens: 5 },
      );

      // complete() resolves (not rejects) with an Error on failure
      if (result instanceof Error) {
        throw result;
      }

      const text = result.content
        .filter((b) => b.type === "text")
        .map((b) => ("text" in b ? b.text : ""))
        .join("");

      if (!text.toLowerCase().includes("ok")) {
        throw new Error(t('provider.apiKey.verifyNoResponse'));
      }

      onSave({ authType: "apiKey", apiKey: key, verified: true });
      setStatus({ type: "success", message: t('provider.apiKey.connectedWithCount', [modelCount]) });
    } catch (err) {
      console.error(`[ApiKey Verify] ${provider}:`, err);
      setStatus({
        type: "error",
        message: err instanceof Error && err.message ? err.message : t('provider.status.connectFailed'),
      });
    } finally {
      setSaving(false);
    }
  };

  const statusBadge = () => {
    if (saving) {
      return (
        <Badge
          role="status"
          variant="outline"
          className="text-blue-500 border-blue-500/20 bg-blue-500/5 text-[0.65rem] h-4 px-1.5"
        >
          {t('provider.status.verifying')}
        </Badge>
      );
    }
    if (status?.type === "error") {
      return (
        <Badge
          role="status"
          variant="outline"
          className="text-destructive border-destructive/20 bg-destructive/5 text-[0.65rem] h-4 px-1.5"
        >
          {t('provider.status.connectFailed')}
        </Badge>
      );
    }
    if (status?.type === "success" || credential?.verified) {
      return (
        <Badge
          role="status"
          variant="outline"
          className="text-success border-success/20 bg-success/5 text-[0.65rem] h-4 px-1.5"
        >
          {t('provider.status.connected')}
        </Badge>
      );
    }
    if (credential && !credential.verified) {
      return (
        <Badge
          role="status"
          variant="outline"
          className="text-yellow-500 border-yellow-500/20 bg-yellow-500/5 text-[0.65rem] h-4 px-1.5"
        >
          {t('provider.status.unverified')}
        </Badge>
      );
    }
    return (
      <Badge
        role="status"
        variant="outline"
        className="text-muted-foreground border-border text-[0.65rem] h-4 px-1.5"
      >
        {t('provider.status.notConfigured')}
      </Badge>
    );
  };

  if (!cheapestModel) {
    return (
      <div className="flex items-center gap-2">
        <p className="text-sm font-medium">{label}</p>
        <Badge
          variant="outline"
          className="text-muted-foreground border-border text-[0.65rem] h-4 px-1.5"
        >
          {t('provider.apiKey.noModels')}
        </Badge>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2">
        <p className="text-sm font-medium">{label}</p>
        {statusBadge()}
      </div>

      <div className="flex items-center gap-2">
        <div className="relative flex-1">
          <Input
            type={showKey ? "text" : "password"}
            value={key}
            onChange={(e) => setKey(e.target.value)}
            placeholder={t('provider.apiKey.placeholder')}
            className="pr-8"
          />
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            className="absolute right-1 top-1/2 -translate-y-1/2"
            onClick={() => setShowKey(!showKey)}
            tabIndex={-1}
          >
            {showKey ? (
              <EyeOff className="size-3.5" />
            ) : (
              <Eye className="size-3.5" />
            )}
          </Button>
        </div>

        <Button
          size="icon"
          variant="ghost"
          disabled={saving || !key.trim()}
          onClick={handleSave}
          title={t('common.save')}
        >
          {saving ? (
            <Spinner className="size-3.5" />
          ) : (
            <Save className="size-3.5" />
          )}
        </Button>

        <Button
          size="icon"
          variant="ghost"
          className="text-destructive hover:text-destructive hover:bg-destructive/10"
          disabled={saving || !credential}
          onClick={() => {
            onRemove?.();
            setKey("");
            setStatus(null);
          }}
          title={t('provider.apiKey.disconnect')}
        >
          <Unplug className="size-3.5" />
        </Button>
      </div>
    </div>
  );
}

import { LogIn, LogOut, X, Copy, Check } from 'lucide-react';
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Spinner } from '@/components/ui/spinner';
import { copyText } from '@/lib/clipboard';
import { t } from '@/lib/i18n';
import type { OAuthCredential } from '@/lib/storage';

export type OAuthPhase =
  | { phase: 'idle' }
  | { phase: 'authorizing'; deviceCode?: string; message?: string }
  | { phase: 'success' }
  | { phase: 'error'; message: string };

interface ProviderOAuthItemProps {
  provider: string;
  label: string;
  description: string;
  flow: 'device-code' | 'auth-code';
  credential?: OAuthCredential;
  oauthState: OAuthPhase;
  onLogin: () => void;
  onLogout: () => void;
  onCancel: () => void;
}

export function ProviderOAuthItem({
  provider,
  label,
  description,
  flow,
  credential,
  oauthState,
  onLogin,
  onLogout,
  onCancel,
}: ProviderOAuthItemProps) {
  const isLoggedIn = credential?.verified;
  const isAuthorizing = oauthState.phase === 'authorizing';
  const [copied, setCopied] = useState(false);

  const handleCopyCode = (code: string) => {
    void copyText(code, { silent: true });
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const statusBadge = () => {
    if (isAuthorizing) {
      return <Badge variant="outline" className="text-blue-500 border-blue-500/20 bg-blue-500/5 text-[0.65rem] h-4 px-1.5">{t('provider.oauth.authorizing')}</Badge>;
    }
    if (oauthState.phase === 'error') {
      return <Badge variant="outline" className="text-destructive border-destructive/20 bg-destructive/5 text-[0.65rem] h-4 px-1.5">{t('provider.status.failed')}</Badge>;
    }
    if (isLoggedIn) {
      return <Badge variant="outline" className="text-success border-success/20 bg-success/5 text-[0.65rem] h-4 px-1.5">{t('provider.oauth.loggedIn')}</Badge>;
    }
    return <Badge variant="outline" className="text-muted-foreground border-border text-[0.65rem] h-4 px-1.5">{t('provider.oauth.notLoggedIn')}</Badge>;
  };

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <p className="text-sm font-medium">{label}</p>
            {statusBadge()}
          </div>
          <p className="text-xs text-muted-foreground">{description}</p>
        </div>

        <div className="flex items-center gap-1 shrink-0 ml-2">
          {isAuthorizing ? (
            <Button variant="ghost" size="sm" onClick={onCancel}>
              <X className="size-3.5" />
              {t('common.cancel')}
            </Button>
          ) : isLoggedIn ? (
            <Button variant="outline" size="sm" onClick={onLogout}>
              <LogOut className="size-3.5" />
              {t('provider.oauth.signOut')}
            </Button>
          ) : (
            <Button size="sm" onClick={onLogin} disabled={isAuthorizing}>
              <LogIn className="size-3.5" />
              {t('provider.oauth.signIn')}
            </Button>
          )}
        </div>
      </div>

      {/* Device code display (GitHub Copilot) */}
      {isAuthorizing && oauthState.deviceCode && (
        <div className="flex items-center gap-2 rounded-md bg-accent/50 border border-border px-3 py-2">
          <Spinner className="size-3.5 shrink-0" />
          <p className="text-xs text-muted-foreground flex-1">
            {t('provider.oauth.enterCode')}
          </p>
          <code className="text-sm font-mono font-bold tracking-wider">{oauthState.deviceCode}</code>
          <Button
            variant="ghost"
            size="icon-xs"
            onClick={() => handleCopyCode(oauthState.deviceCode!)}
            title={t('common.copy')}
          >
            {copied ? <Check className="size-3" /> : <Copy className="size-3" />}
          </Button>
        </div>
      )}

      {/* Auth-code flow: waiting message */}
      {isAuthorizing && flow === 'auth-code' && !oauthState.deviceCode && (
        <div className="flex items-center gap-2 rounded-md bg-accent/50 border border-border px-3 py-2">
          <Spinner className="size-3.5 shrink-0" />
          <p className="text-xs text-muted-foreground">
            {t('provider.oauth.completeInBrowser')}
          </p>
        </div>
      )}

      {/* Error message */}
      {oauthState.phase === 'error' && (
        <p className="text-xs text-destructive">{oauthState.message}</p>
      )}
    </div>
  );
}

import { ExternalLink, LogIn, LogOut, RotateCw } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import type { WebProviderPreset, resolveEffectiveConfig as ResolveEffectiveConfigType } from '@/lib/ai-config/web-provider-presets';
import type { WebProvider, WebProviderUserOverrides } from '@/lib/types';
import { resolveEffectiveConfig } from '@/lib/ai-config/web-provider-presets';
import { t } from '@/lib/i18n';

export interface WebProviderCardProps {
  provider: WebProvider;
  preset: WebProviderPreset;
  isChecking: boolean;

  /**
   * 2026-06-08: Enabled toggle was temporarily removed, then re-added
   * on user request. The toggle hides the provider from the model
   * selector without unlogging.
   */
  onEnabledChange: (enabled: boolean) => void;
  onModelIdChange: (modelId: string) => void;
  /**
   * 2026-06-08: 'supportsReasoning' is no longer exposed in the UI
   * (GLM doesn't surface reasoning to the user). The prop is still
   * accepted for forward-compat with future providers that DO expose
   * reasoning; the implementation is now no-op for glm.
   */
  onCapabilityChange: (
    capability: 'supportsToolCalls' | 'supportsReasoning',
    value: boolean,
  ) => void;
  /**
   * Kept for SubSection wiring compat. Login button already re-verifies
   * the session, so this is unused in the UI.
   */
  onRecheck: () => void;

  /** 猸?鈶? Login callback for the new "Login" button (opens tab + polls). */
  onLogin?: () => void;

  /** 猸?鈶?3: Logout callback 鈥?parent should clear the bundle + set loggedOut. */
  onLogout?: () => void;

  /** 猸?鈶? whether the login flow is currently running. */
  isLoginLoading?: boolean;

  /** 猸?鈶?A1: last capture metadata for transparency display. */
  lastCaptureInfo?: {
    cookieNames: string[];
    capturedAt: string;
  } | null;

  /** 猸?鈶?A2: precomputed effective config (preset merged with user overrides). */
  effectiveConfig?: ReturnType<typeof ResolveEffectiveConfigType>;

  /** 猸?鈶?A2: update a single user override field. */
  onUserOverrideChange?: (
    field: keyof WebProviderUserOverrides,
    value: string | string[] | boolean | undefined,
  ) => void;

  /** 猸?鈶?A2: clear all overrides and revert to preset defaults. */
  onResetOverrides?: () => void;
}

/**
 * 2026-06-08: Redesigned to align with cebian's neutral compact style
 * (see `components/settings/provider/ProviderOAuthItem.tsx`):
 *   - Removed controls that have no useful effect: Enabled toggle
 *     (only 1 built-in provider, login/logout already gates model
 *     selector visibility), Reasoning toggle (GLM doesn't expose
 *     reasoning to users), Recheck button (Login already verifies
 *     session as part of its flow).
 *   - Layout: header row with status badge + actions, then compact
 *     rows for Model ID / Capabilities / last-attempt footer. Matches
 *     the `space-y-2` + `flex items-center justify-between` pattern
 *     used by ProviderOAuthItem.
 *   - Buttons use lucide icons (LogIn/LogOut/ExternalLink/RotateCw)
 *     sized at 3.5 to match cebian's icon button convention.
 *   - All visible strings route through t() 鈥?Chinese is now the
 *     primary language, English is the fallback.
 */
export function WebProviderCard({
  provider,
  preset,
  // Kept for SubSection wiring compat but currently unused in the UI:
  onEnabledChange,
  onModelIdChange,
  onCapabilityChange,
  onRecheck,
  onLogin,
  onLogout,
  isLoginLoading = false,
  lastCaptureInfo = null,
  effectiveConfig: providedEffectiveConfig,
  onUserOverrideChange,
  onResetOverrides,
}: WebProviderCardProps) {
  // A2: compute effective config if not provided (for tests that don't pass it)
  const effective = providedEffectiveConfig ?? resolveEffectiveConfig(provider, preset);

  // Suppress unused-param lint without breaking the contract.
  void onEnabledChange;
  void onRecheck;

  const isLoggedIn = provider.loginStatus === 'loggedIn';
  const isLoggedOut = provider.loginStatus === 'loggedOut';
  const isUnknown = provider.loginStatus === 'unknown';

  // A4: most recent audit entry
  const latestAudit = provider.loginAuditLog[0];

  return (
    <div
      data-testid={`web-provider-card-${provider.presetId}`}
      className="space-y-2"
    >
      {/* Header row: status badge + name + description / actions */}
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <p className="text-sm font-medium" data-testid="provider-name">
              {/* preset.displayNameKey is dynamic per-preset, so the WXT
                  i18n literal-type doesn't accept it. Cast is required. */}
              {t(preset.displayNameKey as any)}
            </p>
            {isLoggedIn && (
              <Badge
                variant="outline"
                className="text-success border-success/20 bg-success/5 text-[0.65rem] h-4 px-1.5"
                data-testid="status-logged-in"
              >
                {t('webProviders.status.loggedIn')}
              </Badge>
            )}
            {isLoggedOut && (
              <Badge
                variant="outline"
                className="text-muted-foreground border-border text-[0.65rem] h-4 px-1.5"
                data-testid="status-logged-out"
              >
                {t('webProviders.status.loggedOut')}
              </Badge>
            )}
            {isUnknown && (
              <Badge
                variant="outline"
                className="text-muted-foreground border-border text-[0.65rem] h-4 px-1.5"
                data-testid="status-unknown"
              >
                {t('webProviders.status.neverChecked')}
              </Badge>
            )}
          </div>
          {preset.descriptionKey ? (
            <p className="text-xs text-muted-foreground mt-0.5">
              {t(preset.descriptionKey as any)}
            </p>
          ) : null}
        </div>

        <div className="flex items-center gap-2 shrink-0">
          {/* 2026-06-08: re-added Enabled toggle (kept on user request).
              Renamed from "Enabled" to "鍚敤" to match cebian's zh-CN
              convention. The toggle hides the provider from the model
              selector without unlogging 鈥?useful when you have the
              session but don't want this model selectable right now. */}
          <label className="flex items-center gap-1.5 cursor-pointer">
            <Switch
              checked={provider.enabled}
              onCheckedChange={onEnabledChange}
              aria-label={t('webProviders.fields.enabled')}
            />
            <span className="text-xs text-muted-foreground">
              {t('webProviders.fields.enabled')}
            </span>
          </label>
          <Button
            variant="ghost"
            size="icon"
            asChild
            className="h-7 w-7"
            aria-label={t('webProviders.fields.openWebsite')}
          >
            <a href={preset.loginUrl} target="_blank" rel="noreferrer">
              <ExternalLink className="size-3.5" />
            </a>
          </Button>
          {isLoggedIn ? (
            <Button
              variant="outline"
              size="sm"
              onClick={onLogout}
              data-testid="logout-button"
            >
              <LogOut className="size-3.5" />
              {t('webProviders.fields.logout')}
            </Button>
          ) : (
            <Button
              size="sm"
              onClick={onLogin}
              disabled={isLoginLoading}
              data-testid="login-button"
            >
              {isLoginLoading ? (
                <RotateCw className="size-3.5 animate-spin" />
              ) : (
                <LogIn className="size-3.5" />
              )}
              {isLoginLoading
                ? t('webProviders.fields.loggingIn')
                : t('webProviders.fields.login')}
            </Button>
          )}
        </div>
      </div>

      {/* Model selector row with reset (only show reset when user has overridden) */}
      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <label
            htmlFor={`model-${provider.presetId}`}
            className="text-xs font-medium"
          >
            {t('webProviders.fields.modelIdLabel')}
          </label>
          {provider.modelId !== preset.defaultModelId && onResetOverrides && (
            <button
              type="button"
              onClick={onResetOverrides}
              className="text-xs text-muted-foreground hover:text-foreground"
              data-testid="reset-model-button"
            >
              {t('webProviders.fields.resetOverrides')}
            </button>
          )}
        </div>
        <select
          id={`model-${provider.presetId}`}
          value={provider.modelId}
          onChange={(e) => onModelIdChange(e.target.value)}
          className="flex h-8 w-full rounded-md border border-input bg-background px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50"
          data-testid={`model-select-${provider.presetId}`}
        >
          {preset.models.map((m) => (
            <option key={m.id} value={m.id}>
              {m.label}
            </option>
          ))}
        </select>
      </div>

      {/* Capabilities row 鈥?Tool calls only (Reasoning removed 2026-06-08) */}
      <div className="flex items-center gap-6">
        <span className="text-xs font-medium">
          {t('webProviders.fields.capabilities')}
        </span>
        <label className="flex items-center gap-2">
          <Switch
            checked={provider.supportsToolCalls}
            onCheckedChange={(v) => onCapabilityChange('supportsToolCalls', v)}
            aria-label={t('webProviders.fields.toolCalls')}
          />
          <span className="text-sm">{t('webProviders.fields.toolCalls')}</span>
        </label>
      </div>

      {/* Footer: last attempt + captured (A1) 鈥?muted, single line each */}
      {(latestAudit || lastCaptureInfo) && (
        <div className="flex flex-col gap-1 text-xs text-muted-foreground pt-1">
          {latestAudit && (
            <p data-testid="audit-info" className="flex items-center gap-1.5">
              <span>{t('webProviders.fields.lastAttempt')}:</span>
              <span>{new Date(latestAudit.timestamp).toLocaleString()}</span>
              <Badge
                variant={latestAudit.result === 'success' ? 'outline' : 'destructive'}
                className="text-[0.65rem] h-4 px-1.5"
              >
                {latestAudit.result}
              </Badge>
            </p>
          )}
          {lastCaptureInfo && lastCaptureInfo.cookieNames.length > 0 && (
            <p data-testid="capture-info">
              {t('webProviders.fields.captured', [
                String(lastCaptureInfo.cookieNames.length),
              ])}
              : {lastCaptureInfo.cookieNames.slice(0, 3).join(', ')}
              {lastCaptureInfo.cookieNames.length > 3
                ? `, +${lastCaptureInfo.cookieNames.length - 3} more`
                : ''}
            </p>
          )}
        </div>
      )}

      {/* A2: Advanced collapsible 鈥?per-provider config overrides */}
      {onUserOverrideChange && (
        <details className="text-sm pt-1" data-testid="advanced-section">
          <summary className="cursor-pointer text-muted-foreground hover:text-foreground text-xs">
            {t('webProviders.fields.advancedTitle')}
          </summary>
          <div className="mt-2 space-y-2 pl-3 border-l-2 border-border">
            <FieldRow label="Cookie domain" source={effective.source.cookieDomain}>
              <Input
                value={effective.cookieDomain}
                onChange={(e) => onUserOverrideChange('cookieDomain', e.target.value)}
                className="h-8 text-sm"
              />
            </FieldRow>
            <FieldRow
              label="Session indicators (comma-separated)"
              source={effective.source.sessionIndicators}
            >
              <Input
                value={effective.sessionIndicators.join(',')}
                onChange={(e) =>
                  onUserOverrideChange(
                    'sessionIndicators',
                    e.target.value
                      .split(',')
                      .map((s) => s.trim())
                      .filter(Boolean),
                  )
                }
                className="h-8 text-sm"
              />
            </FieldRow>
            {/* 2026-06-08: removed "Use localStorage fallback" 鈥?was for
                providers that store tokens in localStorage (Kimi, DeepSeek).
                Both are removed. GLM uses cookies exclusively. Leaving
                the toggle would just confuse the user. */}
            <FieldRow label="Refresh URL (GLM only)" source={effective.source.refreshUrl}>
              <Input
                value={effective.refreshUrl ?? ''}
                onChange={(e) =>
                  onUserOverrideChange('refreshUrl', e.target.value || undefined)
                }
                className="h-8 text-sm"
              />
            </FieldRow>
            {onResetOverrides && (
              <Button
                variant="ghost"
                size="sm"
                onClick={onResetOverrides}
                data-testid="reset-overrides-button"
              >
                {t('webProviders.fields.resetOverrides')}
              </Button>
            )}
          </div>
        </details>
      )}
    </div>
  );
}

function FieldRow({
  label,
  source,
  children,
}: {
  label: string;
  source: 'preset' | 'user';
  children: React.ReactNode;
}) {
  return (
    <div className="flex flex-col gap-1">
      <div className="flex items-center gap-2">
        <span className="text-xs font-medium">{label}</span>
        {source === 'user' && (
          <Badge variant="secondary" className="text-xs">
            user override
          </Badge>
        )}
      </div>
      {children}
    </div>
  );
}

