message.source:
/**
 * EditorPanel 鈥?VFS file editor with auto-save.
 *
 * Save strategy:
 * - Debounced write 500ms after content stops changing.
 * - Immediate flush on Ctrl/Cmd+S, file switch, unmount, or page unload.
 * - Subtle footer status (settings.editor.{saved,saving,unsaved}) 鈥?no buttons.
 * - Write errors surface via `sonner` toast but don't block further edits.
 */
import { useState, useEffect, useCallback, useRef } from 'react';
import { toast } from 'sonner';
import { CodeMirrorEditor } from '@/components/editor/CodeMirrorEditor';
import { vfs } from '@/lib/vfs';
import { cn } from '@/lib/utils';
import { t } from '@/lib/i18n';

const AUTOSAVE_DEBOUNCE_MS = 500;

type SaveStatus = 'idle' | 'saving' | 'saved' | 'error';

interface EditorPanelProps {
  /** Full VFS path to edit. */
  filePath?: string;
  /** Root path for computing relative breadcrumb. */
  rootPath?: string;
  /** Theme for CodeMirror. */
  isDark: boolean;
  /** Enable {{variable}} template highlighting + autocomplete. */
  enableTemplateVars?: boolean;
  /** Called after a successful save. */
  onSave?: () => void;
}

function detectLanguage(filePath: string): 'markdown' | 'yaml' | 'javascript' {
  if (filePath.endsWith('.js') || filePath.endsWith('.ts')) return 'javascript';
  if (filePath.endsWith('.yaml') || filePath.endsWith('.yml')) return 'yaml';
  return 'markdown';
}

export function EditorPanel({ filePath, rootPath, isDark, enableTemplateVars = false, onSave }: EditorPanelProps) {
  const [body, setBody] = useState('');
  const [savedContent, setSavedContent] = useState('');
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<SaveStatus>('idle');

  // 鈹€鈹€鈹€ Refs (kept fresh for effects / handlers) 鈹€鈹€鈹€
  const filePathRef = useRef(filePath);
  const bodyRef = useRef(body);
  const savedRef = useRef(savedContent);
  const onSaveRef = useRef(onSave);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  // Path of the file whose content is currently loaded into `body`/`savedContent`.
  // Only set at the end of a successful load; the auto-save flush refuses to write
  // until this matches the current `filePath`, which prevents the previous file's
  // body from being written to a newly-selected file while its load is in flight.
  const loadedPathRef = useRef<string | undefined>(undefined);
  filePathRef.current = filePath;
  bodyRef.current = body;
  savedRef.current = savedContent;
  onSaveRef.current = onSave;

  const language = filePath ? detectLanguage(filePath) : 'markdown';
  const dirty = !!filePath && body !== savedContent;

  // 鈹€鈹€鈹€ Core flush: write current body to `targetPath` (or the current file). 鈹€鈹€鈹€
  const flush = useCallback(async (targetPath?: string): Promise<void> => {
    const path = targetPath ?? filePathRef.current;
    if (!path) return;
    const content = bodyRef.current;
    // Refuse to write until the body actually belongs to `path`. Without this
    // guard, a pending debounce scheduled while loading a new file would write
    // the previous file's body to the new file. `loadedPathRef` is only set
    // after a successful read.
    if (path !== loadedPathRef.current) return;
    if (path !== filePathRef.current) return;
    if (content === savedRef.current) return;
    setStatus('saving');
    try {
      await vfs.writeFile(path, content);
      // Only commit UI state if the file is still current.
      if (path === filePathRef.current) {
        setSavedContent(content);
        setStatus('saved');
      }
      onSaveRef.current?.();
    } catch (err) {
      console.error('[EditorPanel] autosave failed', err);
      setStatus('error');
      toast.error(t('settings.editor.saveFailed'), {
        description: err instanceof Error ? err.message : String(err),
      });
    }
  }, []);

  // 鈹€鈹€鈹€ Load file whenever filePath changes. Flush previous on switch. 鈹€鈹€鈹€
  useEffect(() => {
    // Flush any pending debounce for the previous file before loading the new one.
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = null;
    }

    if (!filePath) {
      loadedPathRef.current = undefined;
      setBody('');
      setSavedContent('');
      setStatus('idle');
      return;
    }

    let cancelled = false;
    setLoading(true);
    setStatus('idle');
    // Mark the loaded path as stale until the new read completes; this blocks
    // the auto-save effect from writing during the load window.
    loadedPathRef.current = undefined;
    (async () => {
      try {
        const raw = await vfs.readFile(filePath, 'utf8');
        const content = typeof raw === 'string' ? raw : new TextDecoder().decode(raw as Uint8Array);
        if (cancelled || filePath !== filePathRef.current) return;
        setSavedContent(content);
        setBody(content);
        loadedPathRef.current = filePath;
      } catch {
        if (cancelled) return;
        setBody('');
        setSavedContent('');
        loadedPathRef.current = filePath;
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, [filePath]);

  // 鈹€鈹€鈹€ Debounced auto-save on body change. 鈹€鈹€鈹€
  useEffect(() => {
    if (!filePath) return;
    if (body === savedContent) return;
    setStatus('idle');
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    const pathAtSchedule = filePath;
    debounceTimerRef.current = setTimeout(() => {
      debounceTimerRef.current = null;
      void flush(pathAtSchedule);
    }, AUTOSAVE_DEBOUNCE_MS);
    return () => {
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
        debounceTimerRef.current = null;
      }
    };
  }, [body, filePath, savedContent, flush]);

  // 鈹€鈹€鈹€ Ctrl/Cmd+S: immediate flush. 鈹€鈹€鈹€
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 's') {
        e.preventDefault();
        if (debounceTimerRef.current) {
          clearTimeout(debounceTimerRef.current);
          debounceTimerRef.current = null;
        }
        void flush();
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [flush]);

  // 鈹€鈹€鈹€ Flush on visibility change / page unload. 鈹€鈹€鈹€
  // `visibilitychange 鈫?hidden` fires on tab switch, minimise, and the normal
  // lifecycle leading up to close 鈥?this is the reliable persistence hook for
  // IndexedDB. `beforeunload` is kept as a last-ditch best-effort queue.
  useEffect(() => {
    const maybeFlush = () => {
      if (bodyRef.current !== savedRef.current && filePathRef.current) {
        void flush();
      }
    };
    const onVisibility = () => {
      if (document.visibilityState === 'hidden') maybeFlush();
    };
    document.addEventListener('visibilitychange', onVisibility);
    window.addEventListener('beforeunload', maybeFlush);
    return () => {
      document.removeEventListener('visibilitychange', onVisibility);
      window.removeEventListener('beforeunload', maybeFlush);
    };
  }, [flush]);

  // 鈹€鈹€鈹€ On unmount, flush any pending changes. 鈹€鈹€鈹€
  useEffect(() => {
    return () => {
      if (bodyRef.current !== savedRef.current && filePathRef.current) {
        void flush(filePathRef.current);
      }
    };
  }, [flush]);

  // 鈹€鈹€鈹€ Auto-fade "settings.editor.saved" to "idle" after a moment for calm UI. 鈹€鈹€鈹€
  useEffect(() => {
    if (status !== 'saved') return;
    const t = setTimeout(() => setStatus('idle'), 2000);
    return () => clearTimeout(t);
  }, [status]);

  // 鈹€鈹€鈹€ Render 鈹€鈹€鈹€

  if (!filePath) {
    return (
      <div className="h-full flex items-center justify-center text-muted-foreground text-sm">
        {t('settings.editor.selectFile')}
      </div>
    );
  }

  if (loading) {
    return (
      <div className="h-full flex items-center justify-center text-muted-foreground text-sm">
        {t('common.loading')}
      </div>
    );
  }

  // Compute breadcrumb segments relative to rootPath
  const breadcrumb = (() => {
    const base = rootPath ?? '';
    const rel = base && filePath.startsWith(base + '/') ? filePath.substring(base.length + 1) : filePath;
    return rel.split('/');
  })();

  const statusLabel =
    status === 'saving' ? t('settings.editor.saving')
    : status === 'error' ? t('settings.editor.saveFailed')
    : dirty ? t('settings.editor.unsaved')
    : status === 'saved' ? t('settings.editor.saved')
    : '';

  const statusClass =
    status === 'error' ? 'text-destructive'
    : status === 'saved' ? 'text-muted-foreground'
    : 'text-muted-foreground/70';

  return (
    <div className="flex flex-col h-full">
      {/* Breadcrumb + save status */}
      <div className="flex items-center gap-2 px-3 py-1.5 text-xs border-b border-border shrink-0 overflow-hidden">
        <div className="flex items-center gap-1 min-w-0 flex-1 text-muted-foreground">
          {breadcrumb.map((seg, i) => (
            <span key={i} className="flex items-center gap-1 min-w-0">
              {i > 0 && <span className="text-muted-foreground/50">/</span>}
              <span className={i === breadcrumb.length - 1 ? 'text-foreground font-medium truncate' : 'truncate'}>{seg}</span>
            </span>
          ))}
        </div>
        {statusLabel && (
          <span className={cn('shrink-0 text-[11px] transition-opacity', statusClass)}>
            {statusLabel}
          </span>
        )}
      </div>

      <div className="flex-1 min-h-0">
        <CodeMirrorEditor
          value={body}
          onChange={setBody}
          language={language}
          isDark={isDark}
          enableTemplateVars={enableTemplateVars}
          className="h-full"
        />
      </div>
    </div>
  );
}

import { useCallback, useMemo, useRef } from 'react';
import { useNavigate, useOutletContext, useParams } from 'react-router-dom';
import { Blocks, Download, FolderDown, Upload } from 'lucide-react';
import { toast } from 'sonner';
import {
  FileWorkspace,
  type FileWorkspaceAction, type FileWorkspaceHandle,
} from './FileWorkspace';
import { encodeRelPath } from '@/lib/vfs';
import { CEBIAN_SKILLS_DIR } from '@/lib/constants';
import { settingsFilePanelWidth } from '@/lib/storage';
import { createSkillTemplate } from '@/lib/ai-config/skill-creator';
import {
  exportSkillPackage,
  exportAllSkillsPackage,
  inspectSkillPackage,
  SkillPackageError,
  type SkillImportResult,
} from '@/lib/ai-config/skill-transfer';
import { showDialog } from '@/lib/dialog';
import { vfs, normalizePath } from '@/lib/vfs';
import type { SettingsOutletContext } from '@/components/settings/SettingsLayout';
import { t } from '@/lib/i18n';

/**
 * SkillsSection 鈥?multi-file agent skill manager under /settings/skills[/*].
 *
 * Supports nested paths (e.g. `my-skill/scripts/foo.js`). Edits and imports
 * go through `vfs.writeFile`, which broadcasts change events across
 * extension contexts so the background scanner's cached skill index is
 * invalidated automatically 鈥?no manual notification needed.
 *
 * Contributes four toolbar actions: create, import, export current, export
 * all. The domain scaffolding lives in `lib/ai-config/skill-creator.ts` and
 * `lib/ai-config/skill-transfer.ts` so `FileWorkspace` stays free of any
 * business concepts.
 */
export function SkillsSection() {
  const { basePath, breakpoint } = useOutletContext<SettingsOutletContext>();
  const params = useParams();
  const navigate = useNavigate();
  const workspaceRef = useRef<FileWorkspaceHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const splat = params['*'] ?? '';
  const relativePath = splat || undefined;
  // The first path segment of the currently-selected file IS the skill
  // directory name (skills are flat under CEBIAN_SKILLS_DIR). Used to
  // enable / target the "Export current" action.
  const currentSkillName = relativePath ? relativePath.split('/')[0] : undefined;

  const handleSelect = useCallback((rel: string | null) => {
    if (rel) {
      navigate(`${basePath}/skills/${encodeRelPath(rel)}`, { replace: true });
    } else {
      navigate(`${basePath}/skills`, { replace: true });
    }
  }, [basePath, navigate]);

  const handleCreateSkill = useCallback(async () => {
    const { entryFile } = await createSkillTemplate(CEBIAN_SKILLS_DIR);
    workspaceRef.current?.refresh();
    workspaceRef.current?.selectAbs(entryFile);
  }, []);

  // 鈹€鈹€鈹€ Import / Export 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /** Localized message for a SkillPackageError, falling back to the raw
   *  message for non-domain errors. WXT generates separate overloads for
   *  keys with vs without `$N` placeholders, so we dispatch by the code's
   *  shape rather than passing one variable to a single `t()` call. */
  const formatError = useCallback((err: unknown): string => {
    if (err instanceof SkillPackageError) {
      const arg = err.arg ?? '';
      switch (err.code) {
        case 'invalid':           return t('errors.skillPackage.invalid');
        case 'tooLarge':          return t('errors.skillPackage.tooLarge');
        case 'tooManyFiles':      return t('errors.skillPackage.tooManyFiles');
        case 'missingEntry':      return t('errors.skillPackage.missingEntry');
        case 'parseFrontmatter':  return t('errors.skillPackage.parseFrontmatter');
        case 'unsafePath':            return t('errors.skillPackage.unsafePath', [arg]);
        case 'unsupportedPermission': return t('errors.skillPackage.unsupportedPermission', [arg]);
        case 'invalidName':           return t('errors.skillPackage.invalidName', [arg]);
        case 'reservedName':          return t('errors.skillPackage.reservedName', [arg]);
      }
    }
    return err instanceof Error ? err.message : String(err);
  }, []);

  /** Trigger a browser download for the given blob. Uses an ephemeral
   *  anchor + object URL since the project has no existing download
   *  helper and chrome.downloads requires the optional `downloads`
   *  permission. */
  const triggerDownload = useCallback((blob: Blob, filename: string) => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    // Defer revoke so the click has a chance to start the download.
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }, []);

  const handleExportCurrent = useCallback(async () => {
    if (!currentSkillName) return;
    try {
      const skillsRoot = normalizePath(CEBIAN_SKILLS_DIR);
      const blob = await exportSkillPackage(`${skillsRoot}/${currentSkillName}`);
      triggerDownload(blob, `${currentSkillName}.cebian-skill.zip`);
      toast.success(t('settings.skills.exportSuccess', [currentSkillName]));
    } catch (err) {
      toast.error(formatError(err));
    }
  }, [currentSkillName, formatError, triggerDownload]);

  const handleExportAll = useCallback(async () => {
    try {
      const { blob, count } = await exportAllSkillsPackage();
      const date = new Date().toISOString().slice(0, 10);
      triggerDownload(blob, `cebian-skills-backup-${date}.zip`);
      toast.success(t('settings.skills.exportAllSuccess', count));
    } catch (err) {
      if (err instanceof SkillPackageError && err.code === 'missingEntry') {
        // No exportable skills 鈥?surface as a neutral info, not an error.
        toast(t('settings.skills.exportEmpty'));
        return;
      }
      toast.error(formatError(err));
    }
  }, [formatError, triggerDownload]);

  /** Caller for the import preview dialog. Refreshes the file tree and
   *  shows a localized success toast based on package type. The scanner's
   *  cached skill index is invalidated automatically via the vfs change
   *  events emitted by the underlying writes 鈥?no manual notification
   *  needed. */
  const handleImported = useCallback((result: SkillImportResult) => {
    workspaceRef.current?.refresh();
    if (result.installed.length === 1) {
      toast.success(t('settings.skills.importSuccess', [result.installed[0].targetDirName]));
    } else {
      toast.success(t('settings.skills.importSuccessBackup', result.installed.length));
    }
  }, []);

  const handleImportFile = useCallback(async (file: File) => {
    try {
      const preview = await inspectSkillPackage(file);
      showDialog('skill-import-preview', {
        blob: file,
        preview,
        onImported: handleImported,
        onError: (err) => toast.error(formatError(err)),
      });
    } catch (err) {
      toast.error(formatError(err));
    }
  }, [formatError, handleImported]);

  const handleImportClick = useCallback(() => {
    // Reset the input so re-picking the same file still fires onChange.
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
      fileInputRef.current.click();
    }
  }, []);

  const handleFileInputChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) void handleImportFile(file);
  }, [handleImportFile]);

  const toolbarActions = useMemo<FileWorkspaceAction[]>(() => [
    {
      id: 'new-skill',
      icon: Blocks,
      label: t('settings.skills.create'),
      separatorBefore: true,
      onSelect: handleCreateSkill,
    },
    {
      id: 'import-skill',
      icon: Upload,
      label: t('settings.skills.import'),
      onSelect: handleImportClick,
    },
    {
      id: 'export-current-skill',
      icon: Download,
      label: t('settings.skills.exportCurrent'),
      disabled: !currentSkillName,
      onSelect: handleExportCurrent,
    },
    {
      id: 'export-all-skills',
      icon: FolderDown,
      label: t('settings.skills.exportAll'),
      onSelect: handleExportAll,
    },
  ], [handleCreateSkill, handleImportClick, handleExportCurrent, handleExportAll, currentSkillName]);

  return (
    <div className="flex flex-col flex-1 min-h-0">
      <div className="px-6 pt-6 pb-4 shrink-0 border-b border-border">
        <h2 className="text-base font-semibold">{t('settings.skills.title')}</h2>
        <p className="text-xs text-muted-foreground mt-0.5">
          {t('settings.skills.hint')}
        </p>
      </div>
      <input
        ref={fileInputRef}
        type="file"
        accept=".zip,application/zip"
        onChange={handleFileInputChange}
        className="hidden"
        aria-hidden
      />
      <FileWorkspace
        ref={workspaceRef}
        root={CEBIAN_SKILLS_DIR}
        relativePath={relativePath}
        onSelectRelative={handleSelect}
        allowNewFolder
        panelWidthStorage={settingsFilePanelWidth}
        compactMode={breakpoint === 'compact'}
        className="flex-1"
        toolbarActions={toolbarActions}
      />
    </div>
  );
}

