      type: 'agent_end',
      sessionId,
      messages: finalMessages,
    });
  }

  /** Resolve an interactive tool's pending request */
  resolveTool(sessionId: string, toolName: string, response: unknown): void {
    const managed = this.sessions.get(sessionId);
    // ctx subscription handles broadcasting tool_resolved
    managed?.toolCtx.resolve(toolName, response);
  }

  /** Cancel a specific interactive tool */
  cancelTool(sessionId: string, toolName: string): void {
    const managed = this.sessions.get(sessionId);
    // ctx subscription handles broadcasting tool_resolved
    managed?.toolCtx.cancel(toolName);
  }

  /** Get current state for a session (for reconnecting clients).
   *
   *  `isRunning` is the sidepanel's "busy" signal: true while the session
   *  cannot accept a normal prompt yet. That includes both active streaming
   *  and rebuild windows (retry / model switch), so a reconnecting or second
   *  window keeps the composer blocked instead of dispatching a prompt the
   *  manager would ignore while `phase === 'rebuilding'`. */
  getSessionState(sessionId: string): {
    messages: AgentMessage[];
    isRunning: boolean;
    pendingTools: { toolName: string; toolCallId: string; args: unknown }[];
  } | null {
    const managed = this.sessions.get(sessionId);
    if (!managed) return null;
    return {
      messages: [...managed.agent.state.messages],
      isRunning: managed.phase !== 'idle',
      pendingTools: this.getPendingToolSnapshot(managed),
    };
  }

  /** Delete a message and all subsequent messages from a session.
   *
   *  Removing a message from the middle of a transcript breaks the
   *  conversation context (an assistant reply may reference the deleted
   *  user message, or vice-versa). Therefore we truncate *from* the
   *  deleted index to the end, preserving the prefix up to (but not
   *  including) the target message.
   *
   *  No-op if the session is not found or the index is out of range.
   *  Rejects if the agent is currently running 鈥?the caller must cancel
   *  or wait for completion first. */
  async deleteMessage(sessionId: string, messageIndex: number): Promise<void> {
    const managed = this.sessions.get(sessionId);
    if (!managed) {
      // Session not in memory 鈥?load from DB, mutate, persist, and return.
      const session = await sessionStore.load(sessionId);
      if (!session) return;
      if (messageIndex < 0 || messageIndex >= session.messages.length) return;
      const truncated = session.messages.slice(0, messageIndex);
      await sessionStore.scheduleWrite(sessionId, truncated);
      await sessionStore.flush(sessionId);
      this.broadcast(sessionId, {
        type: 'session_loaded',
        sessionId,
        session: { ...session, messages: truncated },
      });
      return;
    }

    if (managed.phase !== 'idle') {
      throw new Error('Cannot delete messages while the agent is running');
    }

    const messages = managed.agent.state.messages;
    if (messageIndex < 0 || messageIndex >= messages.length) return;

    const truncated = messages.slice(0, messageIndex);
    // pi-agent-core's Agent state.messages is mutable 鈥?replace it directly.
    managed.agent.state.messages = truncated;

    // Persist and broadcast so all subscribers refresh.
    sessionStore.scheduleWrite(sessionId, truncated);
    try {
      await sessionStore.flush(sessionId);
    } catch (err) {
      console.warn(`[agent-manager] flush after delete failed for ${sessionId}:`, err);
    }
    this.broadcast(sessionId, {
      type: 'session_state',
      sessionId,
      messages: truncated,
      isRunning: false,
      pendingTools: this.getPendingToolSnapshot(managed),
    });
  }

  /** Destroy a managed session entirely */
  destroySession(sessionId: string): void {
    const managed = this.sessions.get(sessionId);
    if (managed) {
      managed.unsubscribeAgent();
      managed.toolCtx.dispose();
      managed.agent.abort();
      this.sessions.delete(sessionId);
      this.updateKeepAlive();
    }
  }
}

export const agentManager = new AgentManager();

import { customProviders, providerCredentials, activeModel } from '@/lib/storage';
import { customProviderKey } from '@/lib/custom-models';

// 鈹€鈹€鈹€ Dev-only storage seed 鈹€鈹€鈹€
//
// On background startup in dev mode (`pnpm dev`), if the user has filled
// `WXT_DEV_API_KEY` (and the required companions) in `.env.local`, this
// auto-creates a custom OpenAI-compatible provider with the fixed id `dev`
// so devs can skip the manual setup wizard on a fresh install.
//
// Production builds short-circuit immediately 鈥?none of this code path runs.
//
// Semantics: never overwrite user data.
//   - If a provider with id `dev` already exists, the entire seed is
//     skipped (the user may have edited it; we don't know).
//   - `activeModel` is only set when nothing is currently active.
//
// The provider id is intentionally fixed (`dev`) rather than configurable:
// keeping it stable means re-running `pnpm dev` doesn't accumulate stale
// providers, and the "already exists" check has a single source of truth.
//
// Write order is also intentional: credentials 鈫?activeModel 鈫?provider.
// The provider entry doubles as our "already seeded" flag, so we write it
// LAST. Any crash mid-seed leaves the guard "unseeded" and the next launch
// retries cleanly from scratch instead of leaving orphan state.

const PROVIDER_ID = 'dev';
const CREDENTIALS_KEY = customProviderKey(PROVIDER_ID);

function parseBool(raw: string | undefined): boolean {
  return ['true', '1', 'yes'].includes((raw ?? '').trim().toLowerCase());
}

export async function seedDevStorage(): Promise<void> {
  if (!import.meta.env.DEV) return;

  const apiKey = import.meta.env.WXT_DEV_API_KEY?.trim();
  const baseUrl = import.meta.env.WXT_DEV_BASE_URL?.trim();
  const modelId = import.meta.env.WXT_DEV_MODEL_ID?.trim();

  // API key is the gate. Without it, the user hasn't opted in.
  if (!apiKey) return;

  if (!baseUrl || !modelId) {
    console.warn(
      '[dev-seed] WXT_DEV_API_KEY is set but WXT_DEV_BASE_URL or WXT_DEV_MODEL_ID is missing; skipping seed.',
    );
    return;
  }

  const existing = await customProviders.getValue();
  if (existing.some(p => p.id === PROVIDER_ID)) {
    // Already seeded (or user created their own with the same id). Don't touch.
    return;
  }

  const providerName = import.meta.env.WXT_DEV_PROVIDER_NAME?.trim() || 'Dev Provider';
  const modelName = import.meta.env.WXT_DEV_MODEL_NAME?.trim() || modelId;
  const reasoning = parseBool(import.meta.env.WXT_DEV_MODEL_REASONING);

  // Write credentials first (idempotent 鈥?same key overwrites cleanly on retry).
  const credentials = await providerCredentials.getValue();
  await providerCredentials.setValue({
    ...credentials,
    [CREDENTIALS_KEY]: {
      authType: 'apiKey',
      apiKey,
      verified: true,
    },
  });

  // Only auto-select if the user hasn't picked anything yet.
  const currentActive = await activeModel.getValue();
  if (!currentActive) {
    await activeModel.setValue({ provider: CREDENTIALS_KEY, modelId });
  }

  // Provider entry is written LAST: it's the "seeded" flag the guard above checks.
  await customProviders.setValue([
    ...existing,
    {
      id: PROVIDER_ID,
      name: providerName,
      baseUrl,
      models: [{ modelId, name: modelName, reasoning }],
    },
  ]);

  console.log(`[dev-seed] Seeded provider "${providerName}" (id=${PROVIDER_ID}) from .env.local`);
}

