  });

  // 瀹夎宸ヤ綔娴佽Е鍙戝櫒鐩戝惉鍣╘n  installUrlTriggerListener();
  installCronTriggerListener();
  installDomTriggerListener();
  void reloadCronAlarms();
  void reloadDomTriggers();

  // 鎭㈠鍥?MV3 SW 缁堟鑰屼腑鏂殑宸ヤ綔娴佽繍琛孿n  void recoverRunningWorkflows();

  // 瀹夎 MCP Server 澶栭儴娑堟伅鐩戝惉鍣╘n  installMcpServerListener();
  // 瀹夎 Native Messaging 鐩戝惉鍣紙Hermes 鈫?Native Host 鈫?鎵╁睍锛塡n  installNativeMessagingListener();

  // 娉ㄥ唽 API Discovery handler
  registerApiDiscoveryHandlers();
  void initApiDiscovery();

  // 鈹€鈹€鈹€ Port management 鈹€鈹€鈹€

  /** All connected ports and the session each is subscribed to. */
  const ports = new Map<chrome.runtime.Port, { subscribedSession: string | null; instanceId: string | null }>();

  /**
   * Pending grace cancels keyed by sessionId. When the last subscriber
   * disconnects we don't cancel the agent immediately 鈥?we schedule a
   * cancel `AGENT_GRACE_PERIOD_MS` later so a quick reconnect (user closes
   * then reopens the sidepanel) keeps the stream alive.
   */
  const graceTimers = new Map<string, ReturnType<typeof setTimeout>>();

  function scheduleGraceCancel(sessionId: string): void {
    // Replace any existing timer so the most recent disconnect wins.
    const existing = graceTimers.get(sessionId);
    if (existing) clearTimeout(existing);
    const timer = setTimeout(() => {
      graceTimers.delete(sessionId);
      // Defensive: ports map is the source of truth. In a single-threaded
      // SW runtime `clearTimeout` reliably cancels a pending timer, so this
      // check normally always passes 鈥?but it costs nothing to verify.
      const stillNoSubscriber = ![...ports.values()].some(s => s.subscribedSession === sessionId);
      if (stillNoSubscriber) {
        agentManager.cancel(sessionId).catch(err =>
          console.warn(`[grace-cancel] agent cancel failed for ${sessionId}:`, err),
        );
      }
    }, AGENT_GRACE_PERIOD_MS);
    graceTimers.set(sessionId, timer);
  }

  function cancelGrace(sessionId: string): void {
    const t = graceTimers.get(sessionId);
    if (t) {
      clearTimeout(t);
      graceTimers.delete(sessionId);
    }
  }

  /**
   * Post to one port, swallowing the "disconnected port" error.
   *
   * Chrome throws when you `postMessage` to a port whose other side has
   * closed (sidepanel closed mid-flight, tab navigated away, SW idle
   * suspension on the far end). For our use 鈥?sending status updates and
   * RPC replies 鈥?the right behaviour is "best effort, don't escalate".
   * Every BG 鈫?sidepanel post in this file goes through here so the
   * behaviour is uniform and one inline `try/catch` doesn't drift away
   * from another over time.
   */
  function safePost(port: chrome.runtime.Port, msg: ServerMessage): void {
    try { port.postMessage(msg); } catch { /* port disconnected */ }
  }

  /** Send a message to all ports subscribed to a given session. */
  function broadcast(sessionId: string, msg: ServerMessage): void {
    for (const [port, state] of ports) {
      if (state.subscribedSession === sessionId) {
        safePost(port, msg);
      }
    }
  }

  agentManager.setBroadcast(broadcast);

  // 妯″瀷鐩稿叧 storage 鍙樻洿鏃舵竻闄ょ紦瀛榎n  activeModelStorage.watch(() => agentManager.clearModelCache());
  providerCredentials.watch(() => agentManager.clearModelCache());
  customProviders.watch(() => agentManager.clearModelCache());

  // 鈹€鈹€鈹€ Recorder broadcast 鈹€鈹€鈹€

  /** Send recorder_status to every connected port (recorder is a global,
   *  per-instance concept, not session-scoped). */
  function broadcastRecorderStatus(): void {
    const status = recorder.getStatus();
    const msg: ServerMessage = {
      type: 'recorder_status',
      isRecording: status.isRecording,
      startedAt: status.startedAt,
      eventCount: status.eventCount,
      truncated: status.truncated,
      initiatorInstanceId: status.initiatorInstanceId,
      activeWindowId: status.activeWindowId,
    };
    for (const [port] of ports) {
      safePost(port, msg);
    }
  }
  recorder.onStatusChange(broadcastRecorderStatus);

  // Forward finalized recordings to whichever port owned the recording.
  // Both manual `stop()` and the cap-trigger `autoStop()` fan out through
  // this single hook, so we never need to special-case auto-stop on the
  // delivery side. We snapshot the initiator port BEFORE recorder.stop()
  // clears it; by the time this fires, recorder state is already idle, so
  // we capture the port via a closure on the start path instead.
  let lastInitiatorPort: chrome.runtime.Port | null = null;
  recorder.onStatusChange(() => {
    // Track the current initiator while it exists so the session listener
    // (which fires AFTER recorder clears it) still knows where to send.
    const ip = recorder.getInitiatorPort();
    if (ip) lastInitiatorPort = ip;
  });
  recorder.onRecordingFinished(session => {
    const target = lastInitiatorPort;
    lastInitiatorPort = null;
    if (!target) {
      console.warn('[recorder] session finalized but no initiator port to deliver to');
      return;
    }
    try {
      target.postMessage({
        type: 'recorder_session',
        session,
      } satisfies ServerMessage);
    } catch (err) {
      // Port disconnected between recorder clear and our send. The session
      // is lost 鈥?acceptable, the user closed the surface.
      console.warn('[recorder] failed to deliver session:', err);
    }
  });

  // 鈹€鈹€鈹€ Recorder attach/detach hooks 鈹€鈹€鈹€
  //
  // The recorder singleton is content-script-agnostic; this is where the
  // background wires the actual injection. `attach`:
  //   1. Skips restricted pages (chrome://, web store, etc.) silently 鈥擻n  //      tab/navigation events still reach the timeline via the recorder's
  //      own chrome.tabs listeners; only interactions/mutations are missed.
  //   2. Programmatically injects the WXT-built content script bundle.
  //   3. Sends an `init` message carrying `startedAt` (so `t` is computed
  //      against a single clock) and `tabId` (content scripts can't
  //      discover their own tab id).
  //
  // `detach`:
  //   1. Sends `final_flush` so any pending mutation buffer is drained.
  //   2. Calls the script's `__cebianRecorderStop()` global to remove all
  //      listeners, the MutationObserver, and the global itself.
  //   3. Both messages are best-effort 鈥?if the script is gone (page
  //      navigated, tab closed) we swallow the error.
  recorder.setAttachHooks({
    async attach(tabId, startedAt) {
      let tab: chrome.tabs.Tab;
      try {
        tab = await chrome.tabs.get(tabId);
      } catch {
        return; // tab vanished between activated event and attach
      }
      if (!isInjectablePage(tab.url)) {
        // Restricted page (chrome://, web store, view-source:, file://, etc.).
        // Throw so the recorder marks the attach as failed and will retry
        // on the next `complete` navigation if the user moves to a normal page.
        throw new Error(`page not injectable: ${tab.url ?? '<no url>'}`);
      }
      // executeScript can fail if the page navigates between our tab.get
      // and this call, or if the page CSP blocks ISOLATED-world scripts.
      // Re-thrown errors land in the recorder's switchObservedTab catch
      // which marks attach failed and retries on the next `complete`.
      await chrome.scripting.executeScript({
        target: { tabId, allFrames: false },
        files: ['/content-scripts/recorder.js'],
        world: 'ISOLATED',
      });
      // Send init. If the script is somehow gone already, swallow 鈥?the
      // recorder will see no events and the user will notice; better than
      // throwing and triggering an immediate retry storm.
      try {
        await chrome.tabs.sendMessage(tabId, {
          kind: RECORDER_MSG_KIND,
          type: 'init',
          startedAt,
          tabId,
        } satisfies RecorderControlMessage);
      } catch (err) {
        console.warn('[recorder] init send failed for tab', tabId, err);
      }
    },
    async detach(tabId) {
      // Best-effort final flush + stop. Errors here are normal (tab closed,
      // navigated to chrome://, content script never landed).
      try {
        await chrome.tabs.sendMessage(tabId, {
          kind: RECORDER_MSG_KIND,
          type: 'final_flush',
        } satisfies RecorderControlMessage);
      } catch { /* ignore */ }
      try {
        await chrome.scripting.executeScript({
          target: { tabId, allFrames: false },
          world: 'ISOLATED',
          func: () => {
            // Idempotent; the content script removes its own global on stop.
            const fn = (window as unknown as { __cebianRecorderStop?: () => void }).__cebianRecorderStop;
            if (typeof fn === 'function') fn();
          },
        });
      } catch { /* ignore */ }
    },
  });

  /** Recorder events from the content script. */
  chrome.runtime.onMessage.addListener((msg, sender) => {
    if (!isRecorderRuntimeMessage(msg)) return false;
    if (msg.type === 'event') {
      // Defense in depth: only accept events from extension scripts running
      // in the currently observed tab. Without this, the picker / agent
      // content scripts on OTHER tabs could push events into the active
      // recording.
      if (sender.id !== chrome.runtime.id) return false;
      const expected = recorder.getObservedTabId();
      if (expected == null || sender.tab?.id !== expected) return false;
      recorder.pushEvent(msg.event);
    }
    return false;
  });

  chrome.runtime.onConnect.addListener((port) => {
    if (port.name !== AGENT_PORT_NAME) return;

    ports.set(port, { subscribedSession: null, instanceId: null });
    safePost(port, { type: 'connected' });

    // Sync recorder state to the new port. Without this, a sidepanel that
    // opens during an active recording (or reconnects after a brief SW
    // suspension) would display "idle" until the next event triggers a
    // broadcast.
    const recStatus = recorder.getStatus();
    safePost(port, {
      type: 'recorder_status',
      isRecording: recStatus.isRecording,
      startedAt: recStatus.startedAt,
      eventCount: recStatus.eventCount,
      truncated: recStatus.truncated,
      initiatorInstanceId: recStatus.initiatorInstanceId,
      activeWindowId: recStatus.activeWindowId,
    });

    port.onMessage.addListener(async (msg: ClientMessage) => {
      try {
        await handleClientMessage(port, msg);
      } catch (err: unknown) {
        const sessionId = 'sessionId' in msg ? msg.sessionId : null;
        safePost(port, {
          type: 'error',
          sessionId,
          error: err instanceof Error ? err.message : String(err),
        });
      }
    });

    port.onDisconnect.addListener(() => {
      const disconnectedState = ports.get(port);
      const sessionId = disconnectedState?.subscribedSession;
      ports.delete(port);

      // If no other port is subscribed to this session, schedule a grace
      // cancel instead of killing the agent immediately. This lets the user
      // briefly close the sidepanel without aborting an in-flight response.
      if (sessionId) {
        const hasOtherSubscriber = [...ports.values()].some(s => s.subscribedSession === sessionId);
        if (!hasOtherSubscriber) {
          scheduleGraceCancel(sessionId);
        }
      }

      // Recording is owned by a single sidepanel/tab instance (identified
      // by its port). When that exact port disconnects 鈥?sidepanel closed,
      // standalone tab closed 鈥?drop the in-flight recording immediately.
      // The recorder's keep-alive prevents SW suspension from triggering
      // a false-positive disconnect, so this branch only fires on a real
      // user action. Also drains any pending auto-stopped session so it
      // doesn't leak.
      if (recorder.getInitiatorPort() === port) {
        void recorder.stop({ discard: true })
          .catch(err => console.warn('[recorder] discard-on-disconnect failed:', err));
      }
    });
  });

  async function handleClientMessage(port: chrome.runtime.Port, msg: ClientMessage): Promise<void> {
    const state = ports.get(port);
    if (!state) return;

    switch (msg.type) {
      case 'subscribe': {
        state.subscribedSession = msg.sessionId;
        // A new subscriber arrived 鈥?cancel any pending grace timer for this
        // session so we don't kill an agent that's about to be observed again.
        cancelGrace(msg.sessionId);
        // Send current agent state if the agent is running for this session
        if (agentManager.getSessionState(msg.sessionId)) {
          // Title isn't part of the in-memory agent state 鈥?load it from DB
          // so the subscriber's header can show the session title even when
          // (re)subscribing mid-stream.
          const session = await sessionStore.load(msg.sessionId);
          // Re-snapshot AFTER the await: during the DB load the agent could
          // have emitted message_update / agent_end and broadcast() already
          // forwarded those to this port (we set subscribedSession above).
          // Posting an older snapshot here would regress the hook's
          // `messages` state.
          const fresh = agentManager.getSessionState(msg.sessionId);
          if (fresh) {
            safePost(port, {
              type: 'session_state',
              sessionId: msg.sessionId,
              title: session?.title ?? '',
              messages: fresh.messages,
              isRunning: fresh.isRunning,
              pendingTools: fresh.pendingTools,
            });
          } else {
            // Agent finished during the await 鈥?fall through to DB-based
            // session_loaded using the row we already loaded.
            safePost(port, {
              type: 'session_loaded',
              sessionId: msg.sessionId,
              session: session ?? null,
            });
          }
        } else {
          // Agent not running 鈥?load from DB
          const session = await sessionStore.load(msg.sessionId);
          if (session) {
            safePost(port, {
              type: 'session_loaded',
              sessionId: msg.sessionId,
              session,
            });
          } else {
            // Session not found in DB
            safePost(port, {
              type: 'session_loaded',
              sessionId: msg.sessionId,
              session: null,
            });
          }
        }
        break;
      }

      case 'unsubscribe':
        state.subscribedSession = null;
        break;

      case 'prompt': {
        const sessionId = msg.sessionId ?? crypto.randomUUID();
        state.subscribedSession = sessionId;
        // Start the agent (async 鈥?events will be broadcast).
        // For new sessions, agentManager.prompt() persists the session and
        // broadcasts 'session_created' before starting, so the client can
        // navigate to /chat/<id> immediately.
        agentManager.prompt(sessionId, msg.text, msg.attachments).catch((err) => {
          safePost(port, {
            type: 'error',
            sessionId,
            error: err.message ?? String(err),
          });
        });
        break;
      }

      case 'cancel':
        // User-initiated cancel 鈥?immediate, no grace period.
        cancelGrace(msg.sessionId);
        agentManager.cancel(msg.sessionId).catch(err =>
          console.warn(`[cancel] agent cancel failed for ${msg.sessionId}:`, err),
        );
        break;

      case 'retry': {
        // Re-run the last user turn. Errors propagate via the `error`
        // ServerMessage just like `prompt` so the sidepanel can surface
        // "no user message found" / "agent already running" / model setup
        // failures consistently.
        state.subscribedSession = msg.sessionId;
        agentManager.retry(msg.sessionId).catch((err) => {
          safePost(port, {
            type: 'error',
            sessionId: msg.sessionId,
            error: err.message ?? String(err),
          });
        });
        break;
      }

      case 'resolve_tool':
        agentManager.resolveTool(msg.sessionId, msg.toolName, msg.response);
        break;

      case 'cancel_tool':
        agentManager.cancelTool(msg.sessionId, msg.toolName);
        break;

      case 'session_list': {
        const sessions = await sessionStore.list();
        // Annotate with live running state so the UI can show an indicator
        // for sessions whose agent is currently mid-stream in the background.
        const annotated = sessions.map(s => ({
          ...s,
          isRunning: agentManager.getSessionState(s.id)?.isRunning === true,
        }));
        safePost(port, {
          type: 'session_list_result',
          sessions: annotated,
        });
        break;
      }

      case 'delete_message': {
        const dmSessionId = msg.sessionId;
        const dmIndex = msg.messageIndex;
        if (!dmSessionId || typeof dmIndex !== 'number') break;
        try {
          await agentManager.deleteMessage(dmSessionId, dmIndex);
        } catch (err: unknown) {
          safePost(port, {
            type: 'error',
            sessionId: dmSessionId,
            error: err instanceof Error ? err.message : String(err),
          });
        }
        break;
      }

      case 'session_delete': {
        // Validate sessionId before any path construction. The handler is a
        // message boundary that must not trust client input 鈥?interpolating
        // a malicious value (empty, `..`, `/etc`, `a/../b`) into the path
        // would let `vfs.rm({recursive:true})` escape `/workspaces/` and
        // wipe `/`, `/home`, or `~/.cebian/` (skills + prompts).
        // Lock to the shape of `crypto.randomUUID()`.
        const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
        if (!UUID_RE.test(msg.sessionId)) {
          console.warn('[session_delete] rejecting non-UUID sessionId:', msg.sessionId);
          break;
        }
        // Cancel any pending grace timer 鈥?the session is going away.
        cancelGrace(msg.sessionId);
        // Best-effort workspace cleanup. `vfs.rm({force:true})` already
        // tolerates ENOENT, so no exists pre-check is needed. Tolerate any
        // other VFS error and continue with DB deletion 鈥?a leaked workspace
        // is recoverable via the VFS browser; an orphan session row would
        // be more confusing.
        const workspacePath = `/workspaces/${msg.sessionId}`;
        try {
          await vfs.rm(workspacePath, { recursive: true, force: true });
        } catch (err) {
          console.warn(`[session_delete] failed to remove workspace ${workspacePath}:`, err);
        }
        await sessionStore.delete(msg.sessionId);
        agentManager.destroySession(msg.sessionId);
        // Broadcast deletion to all connected ports
        for (const [p] of ports) {
          safePost(p, {
            type: 'session_deleted',
            sessionId: msg.sessionId,
          });
        }
        break;
      }

      case 'recorder_start': {
        const instanceId = state.instanceId;
        if (instanceId == null) {
          // Sidepanel never sent its instanceId 鈥?reject so we never start
          // a recording we couldn't gate stop() on later.
          safePost(port, {
            type: 'recorder_start_rejected',
            reason: 'before_hello',
          });
          break;
        }
        const currentOwner = recorder.getInitiatorPort();
        if (currentOwner != null && currentOwner !== port) {
          // Another instance already owns the recording. Tell the
          // requesting client so it can toast "another window is
          // recording" instead of silently doing nothing.
          safePost(port, {
            type: 'recorder_start_rejected',
            reason: 'busy',
          });
          break;
        }
        // Resolve the requesting port's window so the recording starts
        // focused on the right tab. Prefer the last-focused normal window;
        // fall back to any normal window if the desktop currently has
        // focus (WINDOW_ID_NONE / unknown). This await yields, so we MUST
        // re-check ownership afterwards in case a concurrent recorder_start
        // from another port commits first.
        let initialWindowId: number = chrome.windows.WINDOW_ID_NONE;
        try {
          const focused = await chrome.windows.getLastFocused({ windowTypes: ['normal'] });
          if (focused.id != null) initialWindowId = focused.id;
        } catch { /* ignore 鈥?will try getAll below */ }
        if (initialWindowId === chrome.windows.WINDOW_ID_NONE) {
          try {
            const all = await chrome.windows.getAll({ windowTypes: ['normal'] });
            const first = all.find(w => w.id != null);
            if (first?.id != null) initialWindowId = first.id;
          } catch { /* leave as WINDOW_ID_NONE */ }
        }
        // Re-check ownership: another port may have grabbed the recorder
        // while we were awaiting window resolution. Without this, both
        // ports' pre-await guards pass, only one wins inside recorder.start
        // (which silently re-broadcasts), and the loser's UI gets no
        // rejection toast.
        const ownerNow = recorder.getInitiatorPort();
        if (ownerNow != null && ownerNow !== port) {
          safePost(port, {
            type: 'recorder_start_rejected',
            reason: 'busy',
          });
          break;
        }
        await recorder.start({ port, instanceId, initialWindowId });
        break;
      }

      case 'recorder_stop': {
        if (recorder.getInitiatorPort() !== port) {
          // Only the initiator instance's port may stop. Ignore from
          // other instances so a stale UI can't kill a sibling's recording.
          break;
        }
        // Don't send `recorder_session` from here 鈥?the `onRecordingFinished`
        // listener wired above does that uniformly for manual stop and
        // cap-trigger auto-stop alike.
        await recorder.stop({ discard: false });
        break;
      }

      case 'hello': {
        // First message after connect: the sidepanel tells us its unique
        // per-instance id. Used to gate recorder_start/stop and to
        // distinguish 'owned' vs 'foreign' on the client.
        state.instanceId = msg.instanceId;
        break;
      }

      case 'mcp_read_resource': {
        // Fetch a `ui://...` UI resource for an MCP App iframe. Reply goes
        // back to the requesting port only (not broadcast) 鈥?each iframe
        // owns its own pending read keyed by `requestId`. Errors are
        // classified into two coarse buckets so the sidepanel can render
        // an appropriate fallback without parsing strings.
        const { requestId, serverId, uri } = msg;
        const manager = getMCPManager();
        try {
          // Pre-check disambiguates "server gone" from "fetch failed".
          // Without it, the same `Error("MCP server disabled: ...")` from
          // MCPManager would mask both cases.
          const enabled = await manager.getEnabledServers();
          if (!enabled.some(s => s.id === serverId)) {
            safePost(port, {
              type: 'mcp_resource_result',
              requestId,
              error: {
                code: 'server_unavailable',
                message: `MCP server is not enabled or no longer registered`,
              },
            });
            break;
          }
          const result = await manager.readResource(serverId, uri);
          safePost(port, { type: 'mcp_resource_result', requestId, result });
        } catch (err: unknown) {
          const message = err instanceof Error ? err.message : String(err);
          // Re-map the narrow race where the user disables / removes the
          // server between the pre-check and `readResource`. The MCPManager
          // throws `MCP server disabled: ...` / `MCP server not registered: ...`
          // for these 鈥?string-match is brittle but matches the rest of this
          // file's error-classification style.
          const isServerGone =
            message.startsWith('MCP server disabled:') ||
            message.startsWith('MCP server not registered:');
          safePost(port, {
            type: 'mcp_resource_result',
            requestId,
            error: {
              code: isServerGone ? 'server_unavailable' : 'fetch_failed',
              message,
            },
          });
        }
        break;
      }
    }
  }

  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    // 渚ц竟鏍忔姌鍙狅細sidepanel 鑷繁 window.close()锛宐ackground 鍙渶娉ㄥ叆灞曞紑鎸夐挳
    if (msg?.type === 'collapse-sidebar') {
      (async () => {
        await sidebarCollapsedFlag.setValue(true);
        const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
        if (tab?.id != null) {
          await injectToggleScript(tab.id);
          chrome.tabs.sendMessage(tab.id, { type: 'cebianx:show-toggle' }).catch(() => {});
        }
      })();
      return false;
    }

    // 椤甸潰灞曞紑鎸夐挳鐐瑰嚮锛氭墦寮€ sidepanel + 闅愯棌鎸夐挳
    if (msg?.type === 'expand-sidebar') {
      (async () => {
        await sidebarCollapsedFlag.setValue(false);
        const currentWindow = await chrome.windows.getCurrent();
        if (currentWindow.id != null) {
          chrome.sidePanel.open({ windowId: currentWindow.id }).catch((err) => console.warn('[expand] open sidePanel failed:', err));
        }
        notifyAllTabsToggle(false);
      })();
      return false;
    }

    if (msg?.type === 'mcp_status') {
      // One-shot status query for the Settings UI. Returns a map keyed by
      // server id, only for currently-enabled servers (disabled ones never
      // connect, so the UI handles them via `!server.enabled` first).
      void (async () => {
        try {
          const mgr = getMCPManager();
          const servers = await mgr.getEnabledServers();
          const out: Record<string, { connected: boolean; breaker: string }> = {};
          for (const s of servers) {
            const st = await mgr.getStatus(s.id);
            if (st) out[s.id] = { connected: st.connected, breaker: st.breaker };
          }
          sendResponse(out);
        } catch (err) {
          console.warn('[background] mcp_status query failed:', err);
          sendResponse({});
        }
      })();
      return true; // async response
    }
    return false;
  });
});

import { providerCredentials, type OAuthCredential, type ProviderCredentials } from '@/lib/storage';
import { refreshOAuthCredential } from '@/lib/oauth';

const ALARM_NAME = 'oauth-refresh';
const REFRESH_INTERVAL_MINUTES = 10;
const EXPIRY_BUFFER_MS = 5 * 60 * 1000;

export function setupOAuthRefresh() {
  chrome.alarms.create(ALARM_NAME, { periodInMinutes: REFRESH_INTERVAL_MINUTES });

  chrome.alarms.onAlarm.addListener(async (alarm) => {
    if (alarm.name !== ALARM_NAME) return;

    const creds = await providerCredentials.getValue();
    let updated = false;
    const next: ProviderCredentials = { ...creds };

    for (const [provider, cred] of Object.entries(creds)) {
      if (cred.authType !== 'oauth' || !cred.refreshToken || !cred.expiresAt) continue;
      if (Date.now() < cred.expiresAt - EXPIRY_BUFFER_MS) continue;

      try {
        const refreshed = await refreshOAuthCredential(provider, cred as OAuthCredential);
        next[provider] = refreshed;
        updated = true;
        console.log(`[OAuth Refresh] ${provider}: token refreshed`);
      } catch (err) {
        console.error(`[OAuth Refresh] ${provider}:`, err);
        next[provider] = { ...(cred as OAuthCredential), verified: false };
        updated = true;
      }
    }

    if (updated) {
      await providerCredentials.setValue(next);
    }
  });
}

// Background-side recorder singleton.
//
// Owns the in-memory recording session, tab/window event listeners, the
// content-script attach/detach lifecycle (delegated to `attach()` / `detach()`
// hooks set by Task 4), and the cap watcher that auto-stops on overflow.
//
// State machine:
//   idle 鈫?recording 鈫?idle
// Transitions:
//   start()                  : idle    鈫?recording
//   stop({discard:true})     : recording 鈫?idle, returns null
//   stop({discard:false})    : recording 鈫?idle, returns RecordedSession
//   internal cap-trigger     : recording 鈫?idle (via autoStop, which pushes
//                              the finalized session through the
//                              `onRecordingFinished` hook to whoever wired it)
//
// Sidepanel disconnect handling lives in `entrypoints/background/index.ts`:
// when the initiator port disconnects (sidepanel/tab closed), the background
// calls `recorder.stop({ discard: true })` immediately. There is no
// auto-resume on reconnect 鈥?the user explicitly chose this behaviour
// (closing the surface = ending the recording session).
//
// While `status === 'recording'` the recorder holds a SW keep-alive token
// (see `sw-keepalive.ts`) so a long quiet recording doesn't get terminated
// by Chrome's 30 s service-worker idle timeout 鈥?which would otherwise
// look like a spurious port disconnect and discard the in-flight session.

import {
  RECORDER_MAX_DURATION_MS,
  RECORDER_MAX_EVENTS,
} from '@/lib/recorder/constants';
import type {
  RecordedEvent,
  RecordedEventWithoutBase,
  RecordedSession,
  TabEvent,
} from '@/lib/recorder/types';
import { acquireKeepAlive, releaseKeepAlive } from './sw-keepalive';
import { randomId } from '@/lib/utils';

// 鈹€鈹€鈹€ Types 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export type RecorderStatus = {
  isRecording: boolean;
  startedAt: number | null;
  eventCount: number;
  truncated?: 'event_limit' | 'time_limit';
  /** Unique id of the sidepanel/tab instance that started the recording.
   *  Sidepanels compare this against their own per-instance id to decide
   *  whether to render the button in the owned (red, stoppable) state.
   *  `null` when idle. */
  initiatorInstanceId: string | null;
  /** The window currently being recorded. Tracks the user's focused window
   *  while recording (recording follows focus). `null` when idle. */
  activeWindowId: number | null;
};

export type RecorderStatusListener = (status: RecorderStatus) => void;

/** Called whenever a recording finishes with a deliverable session
 *  (either via `stop({discard:false})`, or the internal cap-trigger
 *  `autoStop()`). NOT fired for `stop({discard:true})` 鈥?discard means
 *  there is no session to deliver. Wired by the BG entrypoint to push
 *  the session to the initiator port as a `recorder_session` server
 *  message. Recorder doesn't know about ports or the wire protocol 鈥擻n *  it just hands off the sealed session. */
export type RecordingFinishedListener = (session: RecordedSession) => void;

/** Hooks that Task 4 (content-script orchestration) plugs in. Kept as an
 *  injectable interface so this module can be unit-tested in isolation and
 *  so the recorder can be exercised end-to-end before Task 4 lands by
 *  supplying no-op hooks. */
export type RecorderAttachHooks = {
  /** Inject the content script into the given tab and arm it with `startedAt`.
   *  May reject; caller logs and continues (the tab is then unobserved). */
  attach(tabId: number, startedAt: number): Promise<void>;
  /** Send a final-flush message to the content script and disconnect it.
   *  Must be tolerant of a missing/dead script. */
  detach(tabId: number): Promise<void>;
};

const noopHooks: RecorderAttachHooks = {
  async attach() { /* will be replaced by Task 4 */ },
  async detach() { /* will be replaced by Task 4 */ },
};

/** Shallow equality for the keypress modifier array. The content script
 *  emits modifiers in a stable order (ctrl, shift, alt, meta) via
 *  `modifiersFromEvent`, so simple length + index comparison is sufficient 鈥擻n *  we don't need set semantics. Both `undefined` is treated as equal. */
function sameModifiers(
  a: readonly string[] | undefined,
  b: readonly string[] | undefined,
): boolean {
  const al = a?.length ?? 0;
  const bl = b?.length ?? 0;
  if (al !== bl) return false;
  for (let i = 0; i < al; i++) {
    if (a![i] !== b![i]) return false;
  }
  return true;
}

// 鈹€鈹€鈹€ Singleton state 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

class Recorder {
  private status: 'idle' | 'recording' = 'idle';
  private startedAt: number | null = null;
  /** The port owned by the sidepanel/tab instance that started this
   *  recording. Used to gate stop() permissions (only this exact port can
   *  stop) and to decide on disconnect whether to discard the session
   *  (initiator port disconnects 鈫?instance is gone 鈫?discard). */
  private initiatorPort: chrome.runtime.Port | null = null;
  /** The instance id that the initiator port declared via `hello`. Mirrors
   *  `initiatorPort` but is JSON-serialisable so it can ride in the
   *  `recorder_status` broadcast for the client-side `isOwner` check. */
  private initiatorInstanceId: string | null = null;
  /** The window currently being recorded. Updated as the user focuses
   *  different windows during a recording. `chrome.tabs.*` events from
   *  other windows are silently ignored. */
  private activeWindowId: number | null = null;
  /** Tab that currently has the content script attached. */
  private observedTabId: number | null = null;
  /** Sticky flag: once attach failed for the current observedTabId, the next
   *  `tabs.onUpdated` with `status === 'complete'` will retry. Cleared on
   *  successful attach. */
  private observedAttachFailed = false;
  /** Generation counter for switchObservedTab. Each call bumps this; if a
   *  pending attach finds the generation has changed by the time it resolves,
   *  it discards its result rather than overwriting fresher state (e.g. user
   *  rapidly toggles between window A and B). */
  private switchGeneration = 0;
  private events: RecordedEvent[] = [];
  private truncated: 'event_limit' | 'time_limit' | undefined;
  private capTimer: ReturnType<typeof setInterval> | null = null;
  private statusBroadcastTimer: ReturnType<typeof setTimeout> | null = null;
  /** True iff we're currently holding a SW keep-alive token. Tracked so
   *  start/stop pairing remains balanced even across error paths. */
  private keepAliveHeld = false;
  private listeners = new Set<RecorderStatusListener>();
  private recordingFinishedListeners = new Set<RecordingFinishedListener>();
  private hooks: RecorderAttachHooks = noopHooks;
  /** Wrapped chrome.* listeners we attach on start and remove on stop, so
   *  there is no leak between sessions. */
  private chromeListeners: Array<() => void> = [];

  /** Task 4 calls this from the background entrypoint to wire injection. */
  setAttachHooks(hooks: RecorderAttachHooks): void {
    this.hooks = hooks;
  }

  // 鈹€鈹€鈹€ Status subscription 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  onStatusChange(listener: RecorderStatusListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  /** Subscribe to recording-finished events. Fires once per recording on
   *  the transition recording 鈫?idle whenever a deliverable session was
   *  produced (manual `stop({discard:false})` or the internal cap-trigger
   *  `autoStop()`). NOT fired for `stop({discard:true})`. The BG entrypoint
   *  wires this to push the session to the initiator port. */
  onRecordingFinished(listener: RecordingFinishedListener): () => void {
    this.recordingFinishedListeners.add(listener);
    return () => this.recordingFinishedListeners.delete(listener);
  }

  getStatus(): RecorderStatus {
    return {
      isRecording: this.status === 'recording',
      startedAt: this.startedAt,
      eventCount: this.events.length,
      truncated: this.truncated,
      initiatorInstanceId: this.initiatorInstanceId,
      activeWindowId: this.activeWindowId,
    };
  }

  /** The port that started the active recording. The BG entrypoint compares
   *  this against the disconnecting port to decide whether to discard. */
  getInitiatorPort(): chrome.runtime.Port | null {
    return this.initiatorPort;
  }

  /** The tab whose content script is currently authorized to push events.
   *  Used by the runtime-message listener to reject events from other tabs
   *  (defense in depth 鈥?our own picker/agent scripts on other tabs would
   *  otherwise be able to inject events into the active recording). */
  getObservedTabId(): number | null {
    return this.observedTabId;
  }

  /** Coalesce status broadcasts to ~5/sec so the sidepanel's badge updates
   *  without hammering postMessage during high-rate event windows. */
  private scheduleBroadcast(immediate = false): void {
    if (immediate) {
      if (this.statusBroadcastTimer) {
        clearTimeout(this.statusBroadcastTimer);
        this.statusBroadcastTimer = null;
      }
      this.flushBroadcast();
      return;
    }
    if (this.statusBroadcastTimer) return;
    this.statusBroadcastTimer = setTimeout(() => {
      this.statusBroadcastTimer = null;
      this.flushBroadcast();
    }, 200);
  }

  private flushBroadcast(): void {
    const snap = this.getStatus();
    for (const l of this.listeners) {
      try { l(snap); } catch (err) { console.warn('[recorder] listener threw:', err); }
    }
  }

  // 鈹€鈹€鈹€ Lifecycle 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /** Begin a recording owned by the given sidepanel instance. Only that
   *  exact port can stop it (BG checks `port === recorder.getInitiatorPort()`),
   *  and the recording is discarded immediately when that port disconnects.
   *  `initialWindowId` seeds `activeWindowId` so the recording starts in
   *  the window the user clicked from; recording-follows-focus moves it
   *  later via `handleWindowFocusChanged`. */
  async start(initiator: {
    port: chrome.runtime.Port;
    instanceId: string;
    initialWindowId: number;
  }): Promise<void> {
    // Flip status synchronously BEFORE any await so concurrent recorder_start
    // messages can't both pass the guard and double-install listeners.
    if (this.status === 'recording') {
      // Re-broadcast so a reconnecting client gets a fresh status.
      this.scheduleBroadcast(true);
      return;
    }
    this.status = 'recording';
    this.startedAt = Date.now();
    this.events = [];
    this.truncated = undefined;
    this.observedTabId = null;
    this.observedAttachFailed = false;
    this.switchGeneration = 0;
    this.initiatorPort = initiator.port;
    this.initiatorInstanceId = initiator.instanceId;
    // Recording starts focused on the initiator window;
    // handleWindowFocusChanged moves it as the user alt-tabs.
    this.activeWindowId = initiator.initialWindowId;

    this.installChromeListeners();
    this.startCapTimer();
    this.acquireKeepAliveOnce();

    // Snapshot generation BEFORE any await: a focus-change event arriving
    // while we resolve the initial active tab will bump switchGeneration
    // and we'll skip the trailing switchObservedTab so we don't clobber
    // fresher state. (Review issue #6.)
    const startGen = this.switchGeneration;

    // Resolve the active tab in the initiator window AFTER state is
    // initialized so any concurrent listener callbacks see consistent state.
    let activeTab: chrome.tabs.Tab | undefined;
    try {
      const win = await chrome.windows.get(initiator.initialWindowId, { populate: true });
      activeTab = win.tabs?.find(t => t.active);
    } catch (err) {
      console.warn('[recorder] failed to populate initiator window:', err);
    }

    // Bail out if a focus change has already moved us elsewhere.
    if (this.status !== 'recording' || startGen !== this.switchGeneration) {
      this.scheduleBroadcast(true);
      return;
    }

    // Push an initial focus_changed marker for the starting tab so the
    // timeline always begins with a navigation context 鈥?this is the
    // sole page-context signal the agent will see at t鈮?.
    if (activeTab?.id != null && activeTab.url) {
      this.pushEvent({
        kind: 'tab',
        event: 'focus_changed',
        tabId: activeTab.id,
        url: activeTab.url,
        title: activeTab.title,
        openerTabId: activeTab.openerTabId,
      });
    }

    if (activeTab?.id != null) {
      await this.switchObservedTab(activeTab.id);
    }

    this.scheduleBroadcast(true);
  }

  /** Stop recording. Returns the sealed session unless `discard` is true,
   *  in which case all in-memory state is dropped and `null` is returned.
   *  Returns `null` if not currently recording 鈥?there is no separate
   *  pending-session state any more; cap-triggered auto-stops push their
   *  session through `onRecordingFinished` synchronously and clean up
   *  exactly like a manual stop. */
  async stop(opts: { discard?: boolean } = {}): Promise<RecordedSession | null> {
    return this.finalize(opts.discard === true);
  }

  // 鈹€鈹€鈹€ Event ingestion 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  /** Called by the runtime-message handler in `index.ts` when the content
   *  script forwards a captured event. Caller already verified the message
   *  envelope; we just need to assign id/t and check caps.
   *
   *  We use a distributive helper instead of `Omit<RecordedEvent, 'id'|'t'>`
   *  because Omit on a discriminated union collapses the variants 鈥?TS would
   *  refuse the discriminator field (`event` / `kind` / `action`) on object
   *  literals. */
  pushEvent(event: RecordedEventWithoutBase): void {
    if (this.status !== 'recording' || this.startedAt == null) return;
    if (this.truncated) return; // already capped, drop further events

    // Coalesce repeated Backspace/Delete presses on the same target into a
    // `repeat` count on the previous event. Holding the key is already
    // dropped at the source (`ke.repeat` guard in the content script), so
    // this only catches rapid *independent* presses 鈥?the common case when
    // a user deletes a few characters to fix a typo. Other whitelisted
    // keys (Enter/Escape/Tab/arrows) stay individual: each press is
    // semantically distinct.
    if (
      event.kind === 'interaction'
      && event.action === 'keypress'
      && (event.key === 'Backspace' || event.key === 'Delete')
    ) {
      const last = this.events[this.events.length - 1];
      if (
        last
        && last.kind === 'interaction'
        && last.action === 'keypress'
        && last.key === event.key
        && last.target.selector === event.target.selector
        && sameModifiers(last.modifiers, event.modifiers)
        && (Date.now() - this.startedAt) - last.t < 1000
      ) {
        last.repeat = (last.repeat ?? 1) + 1;
        this.scheduleBroadcast();
        return;
      }
    }

    // Coalesce consecutive navigated events on the same tab to the same
    // URL. Chrome fires multiple `tabs.onUpdated` ticks during SPA route
    // changes and doc loads (loading/title-update/complete phases), each
    // producing a `navigated` with the same URL but progressively richer
    // title/openerTabId. Keep just the latest snapshot 鈥?title changes
    // mid-load are not user-meaningful. We only collapse when the LAST
    // event is the same navigated (no interaction/mutation in between),
    // so causality between user actions and navigations is preserved.
    //
    // No time-window guard: a single navigation can take seconds during
    // a slow load, and the user cannot trigger a second navigation on
    // the same tab while waiting for the first to complete. `last.t` is
    // intentionally NOT updated, mirroring the Backspace `repeat` rule 鈥擻n    // keeping `t` at the FIRST navigated of the run preserves the timeline
    // ordering against the click/interaction that caused the navigation.
    if (event.kind === 'tab' && event.event === 'navigated') {
      const last = this.events[this.events.length - 1];
      if (
        last
        && last.kind === 'tab'
        && last.event === 'navigated'
        && last.tabId === event.tabId
        && last.url === event.url
      ) {
        // Update last in place. Prefer the newer non-empty title /
        // openerTabId so a richer late update wins over an earlier sparse
        // one; never overwrite a populated field with an empty one.
        if (event.title) last.title = event.title;
        if (event.openerTabId != null) last.openerTabId = event.openerTabId;
        this.scheduleBroadcast();
        return;
      }
    }

    const enriched = {
      ...event,
      id: randomId(8),
      t: Date.now() - this.startedAt,
    } as RecordedEvent;
    this.events.push(enriched);

    if (this.events.length >= RECORDER_MAX_EVENTS) {
      this.truncated = 'event_limit';
      void this.autoStop();
      return;
    }

    this.scheduleBroadcast();
  }

  /** Cap-triggered finalization (event-count or duration limit). Just a
   *  thin fire-and-forget wrapper around the shared `finalize()` path so
   *  manual stop and cap-stop are guaranteed identical. There is no
   *  "pending" state 鈥?a recording either is active or has been finalized
   *  + handed off. */
  private async autoStop(): Promise<void> {
    await this.finalize(false);
  }

  /** Single sealed-session finalization path. Used by both manual `stop()`
   *  (with caller-supplied `discard`) and the internal cap-trigger
   *  `autoStop()` (always `discard=false`). Returns the session that was
   *  fanned out, or `null` on discard / when not recording. */
  private async finalize(discard: boolean): Promise<RecordedSession | null> {
    if (this.status !== 'recording' || this.startedAt == null) return null;

    const startedAt = this.startedAt;
    // The session's windowId carries the window the recording was last
    // focused on; the active window may have moved during recording (visible
    // via tab events of kind 'focus_changed' in the event stream).
    const sessionWindowId = this.activeWindowId ?? -1;
    const observed = this.observedTabId;
    const sealedTruncated = this.truncated;
    const sealedEvents = this.events;

    // Synchronous teardown FIRST so subsequent messages see idle state.
    this.status = 'idle';
    this.removeChromeListeners();
    this.stopCapTimer();
    this.releaseKeepAliveOnce();
    this.startedAt = null;
    this.initiatorPort = null;
    this.initiatorInstanceId = null;
    this.activeWindowId = null;
    this.observedTabId = null;
    this.observedAttachFailed = false;
    this.switchGeneration = 0;
    this.events = [];
    this.truncated = undefined;

    if (observed != null) {
      try { await this.hooks.detach(observed); }
      catch (err) { console.warn('[recorder] detach failed:', err); }
    }

    const endedAt = Date.now();
    const session: RecordedSession | null = discard ? null : {
      version: 1,
      startedAt,
      endedAt,
      durationMs: endedAt - startedAt,
      windowId: sessionWindowId,
      events: sealedEvents,
      truncated: sealedTruncated,
    };

    // Fan the finalized session out to subscribers (the BG entrypoint
    // forwards it to the initiator port). Skipped on `discard` because
    // there's no session to deliver. Listener errors are swallowed so one
    // bad subscriber doesn't break others.
    if (session) {
      for (const l of this.recordingFinishedListeners) {
        try { l(session); } catch (err) { console.warn('[recorder] recordingFinished listener threw:', err); }
      }
    }

    this.scheduleBroadcast(true);
    return session;
  }

  // 鈹€鈹€鈹€ Tab/window listeners 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private installChromeListeners(): void {
    const onActivated = (info: { tabId: number; windowId: number }) => {
      void this.handleTabActivated(info.tabId, info.windowId);
    };
    const onUpdated = (
      tabId: number,
      change: chrome.tabs.OnUpdatedInfo,
      tab: chrome.tabs.Tab,
    ) => {
      void this.handleTabUpdated(tabId, change, tab);
    };
    const onRemoved = (tabId: number, info: { windowId: number; isWindowClosing: boolean }) => {
      void this.handleTabRemoved(tabId, info);
    };
    const onCreated = (tab: chrome.tabs.Tab) => {
      void this.handleTabCreated(tab);
    };
    const onWindowFocus = (windowId: number) => {
      void this.handleWindowFocusChanged(windowId);
    };

    chrome.tabs.onActivated.addListener(onActivated);
    chrome.tabs.onUpdated.addListener(onUpdated);
    chrome.tabs.onRemoved.addListener(onRemoved);
    chrome.tabs.onCreated.addListener(onCreated);
    chrome.windows.onFocusChanged.addListener(onWindowFocus);

    this.chromeListeners.push(
      () => chrome.tabs.onActivated.removeListener(onActivated),
      () => chrome.tabs.onUpdated.removeListener(onUpdated),
      () => chrome.tabs.onRemoved.removeListener(onRemoved),
      () => chrome.tabs.onCreated.removeListener(onCreated),
      () => chrome.windows.onFocusChanged.removeListener(onWindowFocus),
    );
  }

  private removeChromeListeners(): void {
    for (const undo of this.chromeListeners) {
      try { undo(); } catch { /* ignore */ }
    }
    this.chromeListeners = [];
  }

  private async handleTabActivated(tabId: number, windowId: number): Promise<void> {
    if (windowId !== this.activeWindowId) return; // only the currently-focused window
    const tab = await safeGetTab(tabId);
    this.pushTabEvent('focus_changed', tabId, tab);
    await this.switchObservedTab(tabId);
  }

  private async handleTabUpdated(
    tabId: number,
    change: chrome.tabs.OnUpdatedInfo,
    tab: chrome.tabs.Tab,
  ): Promise<void> {
    if (tab.windowId !== this.activeWindowId) return;
    if (tabId !== this.observedTabId) return; // only care about the observed tab
    if (change.url || (change.status === 'loading' && tab.url)) {
      this.pushTabEvent('navigated', tabId, tab);
      // Re-attach: the previous content script was destroyed by navigation.
      // Detach is implicit (script is gone); just attach again once loaded.
      this.observedAttachFailed = true; // force a retry on `complete`
    } else if (change.status === 'complete' && this.observedAttachFailed) {
      // No new url in this update, but a previous attach failed (or a
      // navigation just completed in a separate update). Try again.
      await this.switchObservedTab(tabId);
    }
  }

  private async handleTabRemoved(
    tabId: number,
    info: { windowId: number; isWindowClosing: boolean },
  ): Promise<void> {
    if (info.windowId !== this.activeWindowId) return;
    this.pushEvent({
      kind: 'tab',
      event: 'closed',
      tabId,
      url: '',
    });
    if (tabId === this.observedTabId) {
      this.observedTabId = null;
      // Don't proactively pick a new tab here 鈥?chrome.tabs.onActivated will
      // fire for whichever tab Chrome focuses next, and that path handles attach.
    }
  }

  private async handleTabCreated(tab: chrome.tabs.Tab): Promise<void> {
    if (tab.windowId !== this.activeWindowId) return;
    if (tab.id == null) return; // skip rather than emit a -1 sentinel
    this.pushTabEvent('created', tab.id, tab);
  }

  /** Recording follows the user's focused window. When focus moves to a
   *  different normal window, detach from the previous tab, switch the
   *  active scope, and attach to the new window's active tab. Focus loss
   *  (`WINDOW_ID_NONE`) and devtools/popup windows are ignored 鈥?we keep
   *  the previous active tab observed so brief excursions don't churn
   *  attach/detach. */
  private async handleWindowFocusChanged(windowId: number): Promise<void> {
    if (this.status !== 'recording') return;
    if (windowId === chrome.windows.WINDOW_ID_NONE) return;
    if (windowId === this.activeWindowId) return;

    // Bump generation FIRST so any in-flight switchObservedTab from the
    // previous focus bails out. Capture our own gen so we can detect a
    // newer focus event clobbering us mid-await. (Review issue #1.)
    const gen = ++this.switchGeneration;

    let win: chrome.windows.Window;
    try {
      win = await chrome.windows.get(windowId, { populate: true });
    } catch {
      return; // window vanished
    }
    if (gen !== this.switchGeneration) return;
    if (this.status !== 'recording') return;
    // Ignore devtools / popup / panel windows 鈥?recording stays on the last
    // normal window the user was using.
    if (win.type !== 'normal') return;

    const prev = this.observedTabId;
    if (prev != null) {
      try { await this.hooks.detach(prev); }
      catch (err) { console.warn('[recorder] detach failed on focus change:', err); }
      // Re-check after detach await: another focus event may have moved
      // us again. Don't mutate state if so.
      if (gen !== this.switchGeneration) return;
      if (this.status !== 'recording') return;
    }
    this.observedTabId = null;
    this.observedAttachFailed = false;
    this.activeWindowId = windowId;

    const activeTab = win.tabs?.find(t => t.active);
    if (activeTab?.id != null) {
      this.pushTabEvent('focus_changed', activeTab.id, activeTab);
      await this.switchObservedTab(activeTab.id);
    }
  }

  /** Detach old observed tab (if any) and attach to the new one. Guarded
   *  by `switchGeneration`: if focus moves to another window mid-attach,
   *  the resolved attach is discarded so we don't overwrite the newer
   *  observed-tab state. */
  private async switchObservedTab(tabId: number): Promise<void> {
    const gen = this.switchGeneration;
    const prev = this.observedTabId;
    if (prev === tabId && !this.observedAttachFailed) return;
    if (prev != null && prev !== tabId) {
      try { await this.hooks.detach(prev); }
      catch (err) { console.warn('[recorder] detach failed:', err); }
      // Generation may have been bumped while detach awaited.
      if (gen !== this.switchGeneration) return;
    }
    this.observedTabId = tabId;
    this.observedAttachFailed = false;
    if (this.startedAt == null) return;
    let attached = false;
    try {
      await this.hooks.attach(tabId, this.startedAt);
      attached = true;
    } catch (err) {
      if (gen !== this.switchGeneration) return;
      // Restricted page or injection error. Keep observedTabId set so the
      // tab event filters in handleTab* still treat it as "the tab we care
      // about", but mark attach as failed so a subsequent navigation
      // (`change.status === 'complete'`) gets a retry.
      console.debug('[recorder] attach failed for tab', tabId, err);
      this.observedAttachFailed = true;
      return;
    }
    // Attach succeeded. If a newer focus change has happened, the script
    // is now leaked w.r.t. our state 鈥?always detach it before returning,
    // regardless of whether observedTabId still equals tabId. Otherwise
    // we'd leave a content script attached that we no longer track.
    // (Review issue #3.)
    if (gen !== this.switchGeneration) {
      if (this.observedTabId === tabId) this.observedTabId = null;
      try { await this.hooks.detach(tabId); }
      catch (err) { console.warn('[recorder] stale-attach detach failed:', err); }
      return;
    }
    void attached;
  }

  private pushTabEvent(
    eventKind: TabEvent['event'],
    tabId: number,
    tab: chrome.tabs.Tab | undefined,
  ): void {
    this.pushEvent({
      kind: 'tab',
      event: eventKind,
      tabId,
      url: tab?.url ?? '',
      title: tab?.title,
      openerTabId: tab?.openerTabId,
    });
  }

  // 鈹€鈹€鈹€ Cap watcher 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  private startCapTimer(): void {
    this.stopCapTimer();
    this.capTimer = setInterval(() => {
      if (this.status !== 'recording' || this.startedAt == null) return;
      if (this.truncated) return;
      const elapsed = Date.now() - this.startedAt;
      if (elapsed >= RECORDER_MAX_DURATION_MS) {
        this.truncated = 'time_limit';
        void this.autoStop();
      }
    }, 1000);
