/**
 * 妫€鏌ュ苟閮ㄧ讲鎵€鏈夊唴缃?skill銆俓n *
 * @returns 閮ㄧ讲缁撴灉鎽樿锛岀敤浜庢棩蹇楀拰璋冭瘯銆俓n */
export async function seedBuiltinSkills(): Promise<{
  installed: string[];
  skipped: string[];
  errors: Array<{ skill: string; message: string }>;
}> {
  const installed: string[] = [];
  const skipped: string[] = [];
  const errors: Array<{ skill: string; message: string }> = [];

  for (const skill of BUILTIN_SKILLS) {
    const skillRoot = `${CEBIAN_SKILLS_DIR}/${skill.dirName}`;
    const skillMdPath = `${skillRoot}/${SKILL_ENTRY_FILE}`;

    try {
      // 骞傜瓑妫€鏌ワ細鑻?SKILL.md 宸插瓨鍦ㄥ垯璺宠繃锛屼繚鎶ょ敤鎴疯嚜瀹氫箟鍐呭
      const exists = await vfs.exists(skillMdPath);
      if (exists) {
        skipped.push(skill.dirName);
        continue;
      }

      // 鍒涘缓鐩綍
      await vfs.mkdir(skillRoot, { recursive: true });

      // 鍐欏叆鎵€鏈夋枃浠禱n      for (const file of skill.files) {
        const filePath = `${skillRoot}/${file.relPath}`;
        // 纭繚瀛愮洰褰曞瓨鍦紙濡?scripts/锛塡n        const lastSlash = file.relPath.lastIndexOf('/');
        if (lastSlash > 0) {
          const subDir = `${skillRoot}/${file.relPath.slice(0, lastSlash)}`;
          try {
            await vfs.mkdir(subDir, { recursive: true });
          } catch { /* ignore if already exists */ }
        }
        await vfs.writeFile(filePath, file.content);
      }

      installed.push(skill.dirName);
      console.log(`[seedBuiltinSkills] installed built-in skill: ${skill.dirName} (v${skill.version})`);
    } catch (err) {
      const message = (err as Error).message || String(err);
      errors.push({ skill: skill.dirName, message });
      console.warn(`[seedBuiltinSkills] failed to install ${skill.dirName}:`, message);
    }
  }

  return { installed, skipped, errors };
}

// Background-only session store.
// Sole writer to Dexie DB 鈥?eliminates write conflicts from multiple sidepanels.

import {
  createSession,
  getSession,
  listSessions,
  deleteSession,
  ThrottledSessionWriter,
  type SessionRecord,
} from '@/lib/db';
import type { AgentMessage } from '@earendil-works/pi-agent-core';

class SessionStore {
  private writers = new Map<string, ThrottledSessionWriter>();

  async create(session: SessionRecord): Promise<void> {
    await createSession(session);
  }

  async load(id: string): Promise<SessionRecord | undefined> {
    return getSession(id);
  }

  async list(): Promise<Omit<SessionRecord, 'messages'>[]> {
    const all = await listSessions();
    return all.map(({ messages, ...rest }) => rest);
  }

  async delete(id: string): Promise<void> {
    await deleteSession(id);
    this.disposeWriter(id);
  }

  scheduleWrite(id: string, messages: AgentMessage[]): void {
    let writer = this.writers.get(id);
    if (!writer) {
      writer = new ThrottledSessionWriter();
      this.writers.set(id, writer);
    }
    writer.schedule(id, messages);
  }

  async flush(id: string): Promise<void> {
    const writer = this.writers.get(id);
    if (writer) await writer.flush();
  }

  private disposeWriter(id: string): void {
    const writer = this.writers.get(id);
    if (writer) {
      writer.dispose();
      this.writers.delete(id);
    }
  }
}

export const sessionStore = new SessionStore();

/**
 * 鈶?T鈶?鈥?SW-side orchestration for WEB_LLM_NEEDS_RELOGIN.
 *
 * When the relay's MAIN-world fetcher gets a 401/403, it posts
 * WEB_LLM_NEEDS_RELOGIN to the SW. This handler:
 *   1. Invalidates the bundle cache for that provider (so the next
 *      resolveBundle() returns null 鈫?user sees "please log in" error
 *      instead of stale 401)
 *   2. Broadcasts a 'web_provider_needs_relogin' ServerMessage to all
 *      connected sidepanel ports (so the UI can open Settings +
 *      highlight the failed provider + show a toast)
 *
 * Testability: handleWebProviderRelogin() is a pure function that
 * takes injected deps. registerWebProviderReloginHandler() wires the
 * chrome.runtime.onMessage listener and is called once at SW startup.
 */

import { WEB_LLM_NEEDS_RELOGIN, type WebProviderRelayMessage } from '@/lib/ai-config/web-provider-relay';
import { invalidateBundle } from '@/lib/ai-config/web-provider-bundle';
import type { WebProvider } from '@/lib/types';

/**
 * ServerMessage variant broadcast to sidepanel ports when a provider
 * needs re-login. The sidepanel handler (鈶?4) opens Settings, scrolls
 * to the failed provider card, and shows a toast.
 */
export interface WebProviderNeedsReloginMessage {
  type: 'web_provider_needs_relogin';
  providerId: WebProvider['presetId'];
  status: 401 | 403;
  message: string;
}

/** Dependencies injected for testability. */
export interface WebProviderReloginDeps {
  /** Broadcast a server message to all connected sidepanel ports. */
  broadcast: (msg: WebProviderNeedsReloginMessage) => void;
  /** Invalidate the bundle cache for a provider. */
  invalidateBundle: (providerId: WebProvider['presetId']) => void;
}

/**
 * Pure handler: inspects the relay message, invalidates the bundle,
 * broadcasts to the UI. Returns true if handled, false to let other
 * listeners process the message.
 */
export function handleWebProviderRelogin(
  msg: WebProviderRelayMessage,
  deps: WebProviderReloginDeps,
): boolean {
  if (msg.type !== WEB_LLM_NEEDS_RELOGIN) return false;

  // 1. Invalidate bundle cache FIRST so the next resolveBundle() returns
  //    null 鈫?chat will show "please log in" instead of looping on 401.
  //    Order matters: the broadcast may trigger UI that reads bundle state.
  deps.invalidateBundle(msg.providerId);

  // 2. Broadcast to sidepanel ports to open Settings + highlight.
  deps.broadcast({
    type: 'web_provider_needs_relogin',
    providerId: msg.providerId,
    status: msg.status,
    message: msg.message,
  });

  return true;
}

let _chromeListenerInstalled = false;
let _currentDeps: WebProviderReloginDeps | null = null;

/**
 * Register a chrome.runtime.onMessage listener for WEB_LLM_NEEDS_RELOGIN.
 * Idempotent: safe to call multiple times (only installs the listener once).
 * Call this ONCE at SW startup (entrypoints/background/index.ts).
 */
export function registerWebProviderReloginHandler(deps: WebProviderReloginDeps): void {
  _currentDeps = deps;
  if (_chromeListenerInstalled) return;
  chrome.runtime.onMessage.addListener((msg: unknown) => {
    if (!_currentDeps) return false;
    if (!msg || typeof msg !== 'object') return false;
    return handleWebProviderRelogin(msg as WebProviderRelayMessage, _currentDeps);
  });
  _chromeListenerInstalled = true;
}

/** Test-only: reset module-level state. Use in vitest beforeEach. */
export function _resetReloginHandlerForTesting(): void {
  _currentDeps = null;
  _chromeListenerInstalled = false;
}

/**
 * BG wiring for the session watcher (Issue 2: 401/session-expired
 * proactive detection, KNOWN_ISSUES.md).
 *
 * The watcher itself lives in `lib/ai-config/web-provider-session-watcher.ts`
 * and is fully testable in isolation (pure predicates + dep-injected
 * watcher). This module is the *thin* BG-side glue that:
 *
 *   1. Reads `WEB_PROVIDER_PRESETS` and the Dexie `webProviders` table
 *   2. For each preset whose `loginStatus === 'loggedIn'`, starts a
 *      `SessionWatcher` and stores the handle in a module-level map
 *   3. Installs a single global `chrome.cookies.onChanged` listener
 *      that dispatches to the right preset's `runProbe` (filtered by
 *      the preset's `cookieDomain` 鈥?leading-dot normalized)
 *   4. Listens for `{type:'relogin_success'}` messages (emitted by
 *      `web-provider-relogin.ts` after a successful re-login) and
 *      restarts the watcher for that provider (re-reads cookies)
 *
 * Idempotency: `installSessionWatcher()` is safe to call multiple
 * times 鈥?only the first call installs listeners. This matches the
 * pattern used by `registerWebProviderReloginHandler`.
 *
 * The watcher reuses the existing `WEB_LLM_NEEDS_RELOGIN` plumbing 鈥擻n * when a probe detects session loss, it broadcasts the same
 * `web_provider_needs_relogin` ServerMessage that the HTTP-replay
 * 401 path already produces. The sidepanel toast + openSettings
 * flow is untouched.
 */

import type { WebProviderPreset } from '@/lib/ai-config/web-provider-presets';
import { WEB_PROVIDER_PRESETS } from '@/lib/ai-config/web-provider-presets';
import type { WebProvider } from '@/lib/types';
import {
  startSessionWatcher as defaultStartSessionWatcher,
  shouldFireOnCookieChange,
  type SessionWatcherHandle,
} from '@/lib/ai-config/web-provider-session-watcher';
import { listCookiesForDomain as defaultListCookies } from '@/lib/ai-config/web-provider-cookie-service';
import { invalidateBundle as defaultInvalidateBundle } from '@/lib/ai-config/web-provider-bundle';
import { getWebProviderRepository } from '@/lib/ai-config/web-provider-store';

const PROBE_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes
const DEFAULT_BROADCAST_DEDUP_MS = 5_000; // 5 seconds

export interface InstallDeps {
  /**
   * Presets to watch. In production this defaults to `WEB_PROVIDER_PRESETS`;
   * tests pass a custom (possibly empty) array. Only presets whose Dexie
   * `loginStatus === 'loggedIn'` actually get a watcher started.
   */
  presets?: readonly WebProviderPreset[];
  /** startSessionWatcher injection 鈥?production uses the real one. */
  startSessionWatcher: typeof defaultStartSessionWatcher;
  /** addListener injection. Production: chrome.cookies.onChanged.addListener. */
  addCookieListener: (cb: (event: unknown) => void) => void;
  /** addListener injection. Production: chrome.runtime.onMessage.addListener. */
  addMessageListener: (cb: (msg: any) => void) => void;
  /**
   * Per-providerId broadcast dedup window in ms. Default 5000. When the
   * session watcher detects session loss and fires the relogin broadcast,
   * a second detection within this window for the same providerId is
   * suppressed. This prevents the sidepanel from showing 2-3 stacked
   * toasts when a single user action (e.g. deleting 2 session cookies)
   * fires `chrome.cookies.onChanged` multiple times in quick succession.
   * Set to 0 to disable dedup (useful in tests).
   */
  dedupWindowMs?: number;
  /**
   * `Date.now` injection. Defaults to globalThis.Date.now. Tests can pass
   * a controllable clock to fast-forward time and verify the dedup window
   * elapses correctly.
   */
  now?: () => number;
}

let _installed = false;
const _handles = new Map<WebProvider['presetId'], SessionWatcherHandle>();
let _domainToPresetId = new Map<string, WebProvider['presetId']>();
/** Last broadcast time per providerId, used for dedup. */
const _lastBroadcastAt = new Map<WebProvider['presetId'], number>();

/**
 * Install the session watcher. Idempotent 鈥?only the first call has
 * any effect. Production callers (entrypoints/background/index.ts)
 * invoke this once on SW boot.
 */
export function installSessionWatcher(deps: InstallDeps): void {
  if (_installed) return;
  _installed = true;

  const presets = deps.presets ?? WEB_PROVIDER_PRESETS;
  const startW = deps.startSessionWatcher;
  const dedupWindowMs = deps.dedupWindowMs ?? DEFAULT_BROADCAST_DEDUP_MS;
  const now = deps.now ?? Date.now;

  // Build a normalized domain 鈫?presetId map so the global cookie
  // listener can dispatch quickly without scanning all presets per
  // event. Both bare ('chatglm.cn') and leading-dot ('.chatglm.cn')
  // shapes are registered.
  _domainToPresetId = new Map();
  for (const p of presets) {
    if (!p.cookieDomain) continue;
    _domainToPresetId.set(p.cookieDomain, p.id);
    _domainToPresetId.set(`.${p.cookieDomain}`, p.id);
  }

  // Start a watcher for each preset whose Dexie loginStatus is loggedIn.
  // Async because Dexie reads are async; we don't block SW boot on this.
  void (async () => {
    const repo = getWebProviderRepository();
    for (const p of presets) {
      try {
        const row = await repo.get(p.id);
        if (row?.loginStatus === 'loggedIn') {
          _startForPreset(p, startW, dedupWindowMs, now);
        }
      } catch (err) {
        console.warn(`[session-watcher] failed to start for ${p.id}:`, err);
      }
    }
  })();

  // Global cookie listener. The watcher itself only knows about a
  // single domain; the BG layer dispatches the right watcher's probe
  // by looking up the presetId from the event's cookie domain.
  deps.addCookieListener((event: unknown) => {
    const e = event as { cookie?: { domain?: string } } | undefined;
    const domain = e?.cookie?.domain ?? '';
    if (!domain) return;
    if (!shouldFireOnCookieChange({
      cause: 'unknown',
      domain,
      watchedDomains: Array.from(_domainToPresetId.keys()),
    })) {
      return;
    }
    // Map the (possibly dot-prefixed) domain back to its presetId.
    const normalized = domain.replace(/^\./, '');
    const presetId =
      _domainToPresetId.get(domain) ??
      _domainToPresetId.get(normalized) ??
      _domainToPresetId.get(`.${normalized}`);
    if (!presetId) return;
    const handle = _handles.get(presetId);
    if (!handle) return;
    // Short-circuit the 500ms debounce: the change already fired for
    // the right domain, so probe immediately.
    void handle.runProbe();
  });

  // Re-login handler: restart the watcher for that provider so the
  // new (post-relogin) cookies are picked up and the next periodic
  // probe doesn't immediately re-fire NEEDS_RELOGIN.
  deps.addMessageListener((msg: any) => {
    if (msg?.type !== 'relogin_success') return;
    const providerId = msg.providerId;
    if (typeof providerId !== 'string') return;
    const preset = presets.find((p) => p.id === providerId);
    if (!preset) return;
    _startForPreset(preset, startW, dedupWindowMs, now);
  });
}

function _startForPreset(
  preset: WebProviderPreset,
  startW: typeof defaultStartSessionWatcher,
  dedupWindowMs: number,
  now: () => number,
): void {
  // Stop the old handle if any (idempotent: a no-op if not running).
  _handles.get(preset.id)?.stop();
  // Also reset the dedup clock for this providerId 鈥?a relogin means a
  // fresh start, so the user should get a fresh broadcast if cookies
  // are lost again later.
  _lastBroadcastAt.delete(preset.id);

  const handle = startW(preset.id, {
    chromeApi: {
      cookies: {
        onChanged: {
          // The watcher only needs a stub here 鈥?the global listener
          // installed in installSessionWatcher() does the actual
          // dispatch. The stub satisfies the type contract without
          // double-registering listeners.
          addListener: () => { /* global listener owns dispatch */ },
        },
      },
    },
    broadcast: (msg) => {
      // Dedup: skip the broadcast if we already broadcast for this
      // providerId within the dedup window. The 2026-06-07 real-E2E
      // confirmed 2-3 stacked toasts when a single user action (e.g.
      // deleting 2 session cookies) fires `chrome.cookies.onChanged`
      // multiple times in quick succession. After a successful re-login,
      // _startForPreset() is called again, which deletes the dedup
      // entry 鈥?so the user gets a fresh broadcast if the session is
      // lost again later.
      if (dedupWindowMs > 0) {
        const last = _lastBroadcastAt.get(preset.id);
        if (last !== undefined && (now() - last) < dedupWindowMs) {
          return; // within dedup window 鈥?skip
        }
        _lastBroadcastAt.set(preset.id, now());
      }
      // The handle's broadcast must be the one that reaches the
      // sidepanel. We delegate to the existing WEB_LLM_NEEDS_RELOGIN
      // re-login flow which already wires the sidepanel port.
      defaultBroadcast(msg);
    },
    listCookies: (domain) => defaultListCookies(domain),
    invalidateBundle: (providerId) => defaultInvalidateBundle(providerId as WebProvider['presetId']),
    sessionIndicators: preset.sessionIndicators,
    watchedDomains: preset.cookieDomain ? [preset.cookieDomain] : [],
    intervalMs: PROBE_INTERVAL_MS,
  });
  _handles.set(preset.id, handle);
}

/**
 * Default broadcast: post the watcher-detected `web_provider_needs_relogin`
 * message through the same path as the HTTP-replay 401 path. We import
 * `chrome.runtime` lazily to avoid loading chrome.* at module-eval time
 * in unit tests.
 */
function defaultBroadcast(msg: {
  type: 'web_provider_needs_relogin';
  providerId: string;
  status: 401;
  message: string;
}): void {
  try {
    // Lazy import to keep this module side-effect-free at unit-test
    // load time (no chrome.* references at module top level).
    // The BG's registerWebProviderReloginHandler already owns a
    // chrome.runtime.onMessage listener that routes
    // WEB_LLM_NEEDS_RELOGIN-shaped messages back to the sidepanel.
    // We re-use that path by posting a synthetic relay message:
    void chrome.runtime.sendMessage({
      type: 'WEB_LLM_NEEDS_RELOGIN',
      providerId: msg.providerId,
      status: msg.status,
      message: msg.message,
    });
  } catch (err) {
    console.warn('[session-watcher] broadcast failed:', err);
  }
}

/** Test-only: reset module-level state. Use in vitest beforeEach. */
export function _resetSessionWatcherBgForTesting(): void {
  for (const h of _handles.values()) h.stop();
  _handles.clear();
  _domainToPresetId = new Map();
  _installed = false;
}

// Offscreen document: provides DOM APIs (DOMParser, document) for
// HTML鈫抦arkdown conversion that can't run in the background service worker.

import { Readability } from '@mozilla/readability';
import TurndownService from 'turndown';
import { gfm } from 'turndown-plugin-gfm';
import {
  handlePdfInfo,
  handlePdfText,
  handlePdfSearch,
  type PdfInfo,
  type PdfTextResult,
  type PdfSearchResult,
} from './pdf';

// 鈹€鈹€鈹€ Message types 鈹€鈹€鈹€

export type OffscreenRequest =
  | { type: 'html-to-markdown'; html: string; readability?: { url: string } }
  | { type: 'crop-image'; imageData: string; crop: { x: number; y: number; width: number; height: number } }
  | { type: 'pdf-info'; url: string }
  | { type: 'pdf-text'; url: string; pageRange?: string; maxChars?: number }
  | {
      type: 'pdf-search';
      url: string;
      query: string;
      pageRange?: string;
      regex?: boolean;
      caseInsensitive?: boolean;
      maxHits?: number;
    };

/** Response shape for the original handlers (html-to-markdown, crop-image)
 *  whose `result` is always a string. New PDF handlers use the typed
 *  variants below to keep their structured payloads strongly typed at the
 *  call site without breaking existing callers. */
export interface OffscreenResponse {
  result?: string;
  error?: string;
}

export interface OffscreenPdfInfoResponse {
  result?: PdfInfo;
  error?: string;
}
export interface OffscreenPdfTextResponse {
  result?: PdfTextResult;
  error?: string;
}
export interface OffscreenPdfSearchResponse {
  result?: PdfSearchResult;
  error?: string;
}

// 鈹€鈹€鈹€ PDF error normalization 鈹€鈹€鈹€
// pdf.js v5 doesn't export `PasswordException` as a public symbol but
// still throws errors whose `name` is `'PasswordException'`. Detect by
// name so users get a useful message instead of pdf.js's internal text.
function formatPdfError(err: unknown): string {
  if (err instanceof Error) {
    if (err.name === 'PasswordException') {
      return 'PDF is password-protected (unsupported).';
    }
    if (err.name === 'InvalidPDFException') {
      return `Invalid PDF: ${err.message}`;
    }
    return err.message || String(err);
  }
  return String(err);
}

// 鈹€鈹€鈹€ Processing functions 鈹€鈹€鈹€

function parseWithReadability(html: string, url: string): string | null {
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const base = doc.createElement('base');
  base.href = url;
  doc.head.prepend(base);
  const article = new Readability(doc).parse();
  return article?.content ?? null;
}

function htmlToMarkdown(html: string): string {
  const turndown = new TurndownService({
    headingStyle: 'atx',
    codeBlockStyle: 'fenced',
    bulletListMarker: '-',
  });
  turndown.use(gfm);
  turndown.remove(['style', 'script', 'noscript']);
  return turndown.turndown(html);
}

// 鈹€鈹€鈹€ Image cropping 鈹€鈹€鈹€

async function cropImage(
  base64: string,
  crop: { x: number; y: number; width: number; height: number },
): Promise<string> {
  const img = new Image();
  await new Promise<void>((resolve, reject) => {
    img.onload = () => resolve();
    img.onerror = () => reject(new Error('Failed to load image for cropping'));
    img.src = `data:image/jpeg;base64,${base64}`;
  });

  const clampedX = Math.max(0, Math.min(crop.x, img.width));
  const clampedY = Math.max(0, Math.min(crop.y, img.height));
  const clampedW = Math.min(crop.width, img.width - clampedX);
  const clampedH = Math.min(crop.height, img.height - clampedY);

  if (clampedW <= 0 || clampedH <= 0) {
    throw new Error('Crop region is outside image bounds or has zero dimensions');
  }

  const canvas = document.createElement('canvas');
  canvas.width = clampedW;
  canvas.height = clampedH;
  const ctx = canvas.getContext('2d')!;
  ctx.drawImage(img, clampedX, clampedY, clampedW, clampedH, 0, 0, clampedW, clampedH);

  const dataUrl = canvas.toDataURL('image/jpeg', 0.9);
  return dataUrl.replace(/^data:image\/jpeg;base64,/, '');
}

// 鈹€鈹€鈹€ Message listener 鈹€鈹€鈹€

chrome.runtime.onMessage.addListener(
  (message: OffscreenRequest | SandboxRelayMessage, _sender, sendResponse) => {
    // 鈹€鈹€鈹€ Sandbox relay: forward messages to/from sandbox iframe 鈹€鈹€鈹€
    if ('type' in message && typeof message.type === 'string' && message.type.startsWith('sandbox:')) {
      const sandboxMsg = message as SandboxRelayMessage;

      // Messages TO sandbox (run, chrome_result, page_exec_result, vfs_result, bg_fetch_result)
      if (sandboxMsg.type === 'sandbox:run' ||
          sandboxMsg.type === 'sandbox:chrome_result' ||
          sandboxMsg.type === 'sandbox:page_exec_result' ||
          sandboxMsg.type === 'sandbox:vfs_result' ||
          sandboxMsg.type === 'sandbox:bg_fetch_result') {
        ensureSandboxFrame();
        if (sandboxReady) {
          sandboxFrame!.contentWindow?.postMessage(sandboxMsg, '*');
        } else {
          pendingSandboxMessages.push(sandboxMsg);
        }
        sendResponse({ ok: true });
        return false;
      }

      return false;
    }

    // 鈹€鈹€鈹€ Original offscreen handlers 鈹€鈹€鈹€
    const req = message as OffscreenRequest;
    if (req.type === 'crop-image') {
      cropImage(req.imageData, req.crop)
        .then(result => sendResponse({ result } satisfies OffscreenResponse))
        .catch(err => sendResponse({ error: (err as Error).message } satisfies OffscreenResponse));
      return true;
    }

    // 鈹€鈹€鈹€ PDF handlers 鈹€鈹€鈹€
    // 閫氱敤鏀跺熬锛氭妸 PDF handler 鎶涘嚭鐨?Error 鏀舵垚 `OffscreenResponse.error`銆俓n    // password-protected 绛夊満鏅湪 pdf.js 閲屾姏 PasswordException锛屾垜浠妸瀹僜n    // 鏍囪瘑鍖栦竴涓嬭涓婂眰 UI 鏂囨鑳借瘑鍒€俓n    if (req.type === 'pdf-info') {
      handlePdfInfo(req.url)
        .then(result => sendResponse({ result } satisfies OffscreenPdfInfoResponse))
        .catch(err => sendResponse({ error: formatPdfError(err) } satisfies OffscreenPdfInfoResponse));
      return true;
    }
    if (req.type === 'pdf-text') {
      handlePdfText(req.url, req.pageRange, req.maxChars)
        .then(result => sendResponse({ result } satisfies OffscreenPdfTextResponse))
        .catch(err => sendResponse({ error: formatPdfError(err) } satisfies OffscreenPdfTextResponse));
      return true;
    }
    if (req.type === 'pdf-search') {
      handlePdfSearch(req.url, req.query, req.pageRange, {
        regex: req.regex,
        caseInsensitive: req.caseInsensitive,
        maxHits: req.maxHits,
      })
        .then(result => sendResponse({ result } satisfies OffscreenPdfSearchResponse))
        .catch(err => sendResponse({ error: formatPdfError(err) } satisfies OffscreenPdfSearchResponse));
      return true;
    }

    if (req.type !== 'html-to-markdown') return;

    try {
      let html = req.html;

      // Optionally run Readability first
      if (req.readability) {
        const articleHtml = parseWithReadability(html, req.readability.url);
        if (!articleHtml) {
          sendResponse({ error: 'readability-failed' } satisfies OffscreenResponse);
          return true;
        }
        html = articleHtml;
      }

      const markdown = htmlToMarkdown(html);
      sendResponse({ result: markdown } satisfies OffscreenResponse);
    } catch (err: any) {
      sendResponse({ error: err.message ?? String(err) } satisfies OffscreenResponse);
    }

    return true; // keep sendResponse channel open
  },
);

// 鈹€鈹€鈹€ Sandbox iframe host 鈹€鈹€鈹€
// The sandbox page cannot be embedded directly by the background SW.
// Offscreen document acts as host: embeds sandbox iframe and relays
// messages between background (chrome.runtime.onMessage) and sandbox (postMessage).

type SandboxRelayMessage = { type: string; [key: string]: unknown };

let sandboxFrame: HTMLIFrameElement | null = null;
let sandboxReady = false;
const pendingSandboxMessages: SandboxRelayMessage[] = [];

function ensureSandboxFrame(): void {
  if (sandboxFrame) return;
  sandboxFrame = document.createElement('iframe');
  sandboxFrame.src = chrome.runtime.getURL('/sandbox.html');
  sandboxFrame.style.display = 'none';
  document.body.appendChild(sandboxFrame);
}

// Relay messages from sandbox iframe 鈫?background
window.addEventListener('message', (event) => {
  const msg = event.data;
  if (!msg || typeof msg.type !== 'string') return;

  if (msg.type === 'sandbox:ready') {
    sandboxReady = true;
    // Flush any messages that arrived before sandbox was ready
    for (const queued of pendingSandboxMessages) {
      sandboxFrame?.contentWindow?.postMessage(queued, '*');
    }
    pendingSandboxMessages.length = 0;
    return;
  }

  // Forward sandbox responses to background (chrome_call, page_exec, run_result)
  if (msg.type.startsWith('sandbox:')) {
    chrome.runtime.sendMessage(msg).catch(() => {});
  }
});

// PDF service for the offscreen document.
//
// All pdf.js usage lives here so the file stays cohesive (the offscreen
// `main.ts` only dispatches messages). Handlers are intentionally
// straightforward functions returning the response payload; `main.ts`
// wraps them with the `sendResponse` plumbing.
//
// 娉ㄦ剰锛歱df.js 蹇呴』鍦?offscreen 杩欑甯?DOM 鐨勪笂涓嬫枃閲岃窇锛堥渶瑕乗n// DOMMatrix / OffscreenCanvas 绛夛級锛涗粠 Service Worker 璋?`loadPdfJs()` 浼氬け璐ャ€俓n
import type { PDFDocumentProxy } from 'pdfjs-dist';
import { loadPdfJs } from '@/lib/pdf-loader';
import { escapeRegExp } from '@/lib/utils';

/** Structural slice of pdf.js's `TextItem` covering only the fields we
 *  actually read. Avoids importing from the package's internal subpath
 *  (`pdfjs-dist/types/src/display/api`) which isn't part of the public
 *  surface and can move on minor bumps. `getTextContent().items` also
 *  contains `TextMarkedContent` entries that lack `str` 鈥?we discriminate
 *  with `'str' in item` at the use site. */
interface PdfTextItemLike {
  str: string;
  hasEOL: boolean;
}

// 鈹€鈹€鈹€ Types exposed to callers (background / agent tool) 鈹€鈹€鈹€

/** Result of `pdf-info`. */
export interface PdfInfo {
  pageCount: number;
  title?: string;
  author?: string;
  subject?: string;
  keywords?: string;
  creationDate?: string;
  /** Flattened outline entries (鈮?2 levels deep, 鈮?50 entries). Empty when
   *  the document has no outline. `truncated` is true when entries were
   *  dropped to honor the cap. */
  outline: PdfOutlineEntry[];
  outlineTruncated: boolean;
}

export interface PdfOutlineEntry {
  title: string;
  /** 1-based target page; missing when the destination cannot be resolved
   *  to a numbered page (rare for normal documents). */
  page?: number;
  /** Indent level (0 for top-level, 1 for one level deep). */
  level: number;
}

/** Result of `pdf-text`. */
export interface PdfTextResult {
  /** Joined text for the resolved page range. Page boundaries are marked
   *  by a `\f\n=== Page N ===\n` separator so downstream consumers can
   *  re-split if needed. */
  text: string;
  /** Pages actually included (in iteration order, after page-range
   *  resolution and any early stop from `maxChars`). */
  pages: number[];
  /** Total resolved pages requested (before truncation). */
  requestedPages: number;
  /** True if the response was cut short by `maxChars`. The character
   *  count of what was actually returned is just `text.length`; we don't
   *  separately compute the would-be total 鈥?callers can re-request
   *  remaining pages by page range if they need more. */
  truncated: boolean;
}

/** Result of `pdf-search`. */
export interface PdfSearchResult {
  hits: PdfSearchHit[];
  /** True when the hit cap was reached and more matches exist. */
  truncated: boolean;
  /** Number of pages actually scanned (matches the resolved page range,
   *  even if a hit-cap-induced early stop occurred 鈥?for transparency). */
  pagesScanned: number;
}

export interface PdfSearchHit {
  /** 1-based page number. */
  page: number;
  /** Character offset inside the joined page text. */
  index: number;
  /** Length of the match in characters. */
  length: number;
  /** Surrounding text, with the match in the middle. Truncated to roughly
   *  卤80 chars on each side. Leading/trailing `鈥 marks indicate the
   *  snippet was cut at that end. */
  snippet: string;
}

// 鈹€鈹€鈹€ Document cache (URL 鈫?loaded PDF) 鈹€鈹€鈹€

/** Bounded LRU cache. Stores promises so concurrent requests for the same
 *  URL share one fetch + parse. Cap chosen small because each entry can
 *  retain tens of MB of decoded structures. */
const MAX_CACHE = 3;
const documentCache = new Map<string, Promise<PDFDocumentProxy>>();

function touchCache(url: string, promise: Promise<PDFDocumentProxy>): void {
  // Re-insert moves the key to the end of insertion order, marking it MRU.
  documentCache.delete(url);
  documentCache.set(url, promise);

  while (documentCache.size > MAX_CACHE) {
    // First key by insertion order = least recently used.
    const oldest = documentCache.keys().next().value;
    if (oldest === undefined) break;
    documentCache.delete(oldest);
    // 涓嶄富鍔ㄨ皟 doc.destroy()锛氭矇鐫?listener 鍙兘鍚屾椂杩樻嬁鐫€琚窐姹伴」鐨刓n    // `PDFDocumentProxy` 鍦ㄨ法 page 杩唬锛屾彁鍓?destroy 浼氳璇ヨ皟鐢ㄨ剼涓嬫姤閿欍€俓n    // 鐜板湪鏄?LRU 琛ㄤ笂鍙栦笉鍒颁簡锛屼笂涓嬫枃閲婃斁鍚?GC 浼氬洖鏀讹紱cap 鏄?3锛屽嵎涓嶈捣鏉ャ€俓n  }
}

async function getOrLoadDocument(url: string): Promise<PDFDocumentProxy> {
  const cached = documentCache.get(url);
  if (cached) {
    // Move to MRU position on hit.
    touchCache(url, cached);
    return cached;
  }

  const loadingPromise = (async () => {
    const pdfjs = await loadPdfJs();
    const bytes = await fetchPdf(url);
    const task = pdfjs.getDocument({
      data: bytes,
      // Disable pdf.js's built-in font fetching attempts (no network access
      // for sub-resources needed for text extraction).
      disableFontFace: true,
      // Keep the worker chatter quiet 鈥?we don't need stream progress.
      verbosity: 0,
    });
    return task.promise;
  })();

  touchCache(url, loadingPromise);

  // If the load fails, evict so subsequent calls can retry from scratch
  // instead of replaying the cached rejection.
  loadingPromise.catch(() => {
    if (documentCache.get(url) === loadingPromise) {
      documentCache.delete(url);
    }
  });

  return loadingPromise;
}

// 鈹€鈹€鈹€ Fetch 鈹€鈹€鈹€

/** Hard cap on a single PDF's bytes. Anything larger likely chokes the
 *  offscreen document anyway (pdf.js holds the full ArrayBuffer plus
 *  decoded structures in memory); failing fast with a clear message is
 *  better than the page silently going OOM. */
const PDF_MAX_BYTES = 100 * 1024 * 1024;

async function fetchPdf(url: string): Promise<ArrayBuffer> {
  // URL 浠呭仛鍙?parse 鏍￠獙銆備笉鍐嶅仛鍗忚鐧藉悕鍗?鈥斺€?Chrome 娌欑瀵?file://銆乥lob: 绛塡n  // 鍗忚鏈潵灏辨湁瀹冭嚜宸辩殑绛栫暐锛岃 fetch 鐩存帴璇磋瘽姣斿伐鍏峰眰鍘荤寽鏇磋瘹瀹炪€俓n  try {
    new URL(url);
  } catch {
    throw new Error(`Invalid URL: ${url}`);
  }

  // Extension fetches with `<all_urls>` host_permissions are privileged for
  // http(s) 鈥?bypassing CORS and attaching cookies. For file:// the request
  // only succeeds when the user has toggled "Allow access to file URLs"
  // for Cebian at chrome://extensions; otherwise fetch throws naturally and
  // we surface that. For blob: URLs scoped to a page, fetch also fails
  // naturally because the blob is not in this context's URL store.
  const response = await fetch(url, { credentials: 'include' });
  if (!response.ok) {
    throw new Error(`Failed to fetch PDF: HTTP ${response.status} ${response.statusText}`);
  }

  // 澶у皬棰勬锛氳嫢 Content-Length 宸茬煡涓旇秴闄愶紝鎻愬墠鎷掔粷锛涙湭鐭ュ氨闈?arrayBuffer
  // 涔嬪悗鍐嶈ˉ涓€娆℃牎楠岋紝閬垮厤缂撳啿鏁翠釜瓒呭ぇ鏂囦欢銆俓n  const declaredLength = Number(response.headers.get('content-length') ?? '');
  if (Number.isFinite(declaredLength) && declaredLength > PDF_MAX_BYTES) {
    throw new Error(
      `PDF is too large to process (${(declaredLength / 1024 / 1024).toFixed(1)} MB; ` +
      `cap is ${PDF_MAX_BYTES / 1024 / 1024} MB). Open a smaller range or download the file ` +
      `to disk first.`,
    );
  }

  // 鍐呭绫诲瀷鏍￠獙锛氭斁杩?application/pdf / application/x-pdf 锛堣€佹湇鍔″櫒锛夊拰
  // 甯歌鐨?octet-stream 鍏滃簳锛涚┖ Content-Type 涔熸斁杩囷紙閮ㄥ垎绉佹湁閮ㄧ讲鏈嶅姟鍣╘n  // 涓嶄笅鍙戣澶达級銆俓n  const rawCt = response.headers.get('content-type') ?? '';
  const contentType = rawCt.split(';')[0]!.trim().toLowerCase();
  if (
    contentType
    && !contentType.startsWith('application/pdf')
    && contentType !== 'application/x-pdf'
    && contentType !== 'application/octet-stream'
    && contentType !== 'binary/octet-stream'
  ) {
    throw new Error(`URL did not return a PDF (Content-Type: ${contentType}).`);
  }

  const buf = await response.arrayBuffer();
  if (buf.byteLength > PDF_MAX_BYTES) {
    throw new Error(
      `PDF is too large to process (${(buf.byteLength / 1024 / 1024).toFixed(1)} MB; ` +
      `cap is ${PDF_MAX_BYTES / 1024 / 1024} MB).`,
    );
  }
  return buf;
}

// 鈹€鈹€鈹€ Page range parsing 鈹€鈹€鈹€

/** Resolve a `pageRange` spec ("1-3,7,10-12" / "5" / undefined) into a
 *  sorted, unique, 1-based page-number list clamped to `[1, pageCount]`.
 *  `undefined` / empty input returns all pages. Throws on syntactic
 *  garbage; returns `[]` if the spec is well-formed but matches no pages. */
export function parsePageRange(spec: string | undefined, pageCount: number): number[] {
  if (!spec || !spec.trim()) {
    return Array.from({ length: pageCount }, (_, i) => i + 1);
  }
  const out = new Set<number>();
  const parts = spec.split(',').map(s => s.trim()).filter(Boolean);
  for (const part of parts) {
    const m = part.match(/^(\d+)\s*-\s*(\d+)$/);
    if (m) {
      // 姝ｅ垯宸蹭繚璇?m[1] / m[2] 鏄函鏁板瓧锛屼笉闇€ isFinite 璞″緛鎬ф鏌ャ€俓n      let a = parseInt(m[1], 10);
      let b = parseInt(m[2], 10);
      if (a > b) [a, b] = [b, a];
      a = Math.max(1, a);
      b = Math.min(pageCount, b);
      for (let i = a; i <= b; i++) out.add(i);
      continue;
    }
    if (/^\d+$/.test(part)) {
      const n = parseInt(part, 10);
      if (n >= 1 && n <= pageCount) out.add(n);
      continue;
    }
    throw new Error(`Invalid page range part: "${part}"`);
  }
  return Array.from(out).sort((a, b) => a - b);
}

// 鈹€鈹€鈹€ Page text extraction 鈹€鈹€鈹€

/** Join a page's text items into a single string. `hasEOL` items end the
 *  current line; other items are separated by a single space. Marked-
 *  content items (no `str` field) are skipped. Final string is trimmed
 *  and whitespace-normalized. */
async function extractPageText(doc: PDFDocumentProxy, pageNumber: number): Promise<string> {
  const page = await doc.getPage(pageNumber);
  try {
    const content = await page.getTextContent();
    let out = '';
    for (const item of content.items) {
      if (!('str' in item)) continue;
      const textItem = item as PdfTextItemLike;
      out += textItem.str;
      out += textItem.hasEOL ? '\n' : ' ';
    }
    // Normalize: collapse internal runs of spaces/tabs, tidy line breaks.
    return out
      .replace(/[ \t]+/g, ' ')
      .replace(/[ \t]*\n[ \t]*/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  } finally {
    // `cleanup()` releases page-level decoded resources without destroying
    // the document. Helps keep memory bounded across long extractions.
    page.cleanup();
  }
}

// 鈹€鈹€鈹€ Outline (table of contents) 鈹€鈹€鈹€

const OUTLINE_MAX_ENTRIES = 50;
const OUTLINE_MAX_DEPTH = 2;

interface RawOutlineNode {
  title: string;
  dest?: unknown;
  items?: RawOutlineNode[];
}

async function extractOutline(doc: PDFDocumentProxy): Promise<{
  entries: PdfOutlineEntry[];
  truncated: boolean;
}> {
  let raw: RawOutlineNode[] | null = null;
  try {
    raw = (await doc.getOutline()) as RawOutlineNode[] | null;
  } catch {
    raw = null;
  }
  if (!raw || raw.length === 0) return { entries: [], truncated: false };

  const out: PdfOutlineEntry[] = [];
  let truncated = false;

  const walk = async (nodes: RawOutlineNode[], level: number): Promise<void> => {
    for (const node of nodes) {
      if (out.length >= OUTLINE_MAX_ENTRIES) {
        truncated = true;
        return;
      }
      const page = await resolveOutlineDestination(doc, node.dest);
      out.push({
        title: (node.title ?? '').trim().slice(0, 200),
        page,
        level,
      });
      if (node.items && node.items.length > 0 && level + 1 < OUTLINE_MAX_DEPTH) {
        await walk(node.items, level + 1);
        if (out.length >= OUTLINE_MAX_ENTRIES) {
          truncated = true;
          return;
        }
      } else if (node.items && node.items.length > 0) {
        // Deeper levels exist but are dropped per cap; mark truncated.
        truncated = true;
      }
    }
  };

  await walk(raw, 0);
  return { entries: out, truncated };
}

/** Best-effort outline destination 鈫?1-based page number resolution.
 *  pdf.js outline entries carry either a named destination (string) or an
 *  explicit destination array; we try both and return undefined on any
 *  failure so the caller can still show the title. */
async function resolveOutlineDestination(
  doc: PDFDocumentProxy,
  dest: unknown,
): Promise<number | undefined> {
  try {
    let explicit: unknown[] | null = null;
    if (Array.isArray(dest)) {
      explicit = dest;
    } else if (typeof dest === 'string') {
      const resolved = await doc.getDestination(dest);
      if (Array.isArray(resolved)) explicit = resolved;
    }
    if (!explicit || explicit.length === 0) return undefined;
    const ref = explicit[0];
    const pageIndex = await doc.getPageIndex(ref as any);
    if (typeof pageIndex === 'number') return pageIndex + 1; // 0-based 鈫?1-based
    return undefined;
  } catch {
    return undefined;
  }
}

// 鈹€鈹€鈹€ Handlers (invoked from main.ts dispatcher) 鈹€鈹€鈹€

export async function handlePdfInfo(url: string): Promise<PdfInfo> {
  const doc = await getOrLoadDocument(url);
  const meta = await doc.getMetadata().catch(() => null);
  const info = (meta?.info ?? {}) as Record<string, string | undefined>;
  const { entries, truncated } = await extractOutline(doc);

  return {
    pageCount: doc.numPages,
    title: info.Title,
    author: info.Author,
    subject: info.Subject,
    keywords: info.Keywords,
    creationDate: info.CreationDate,
    outline: entries,
    outlineTruncated: truncated,
  };
}

export async function handlePdfText(
  url: string,
  pageRangeSpec: string | undefined,
  maxChars: number | undefined,
): Promise<PdfTextResult> {
  const doc = await getOrLoadDocument(url);
  const pages = parsePageRange(pageRangeSpec, doc.numPages);
  if (pages.length === 0) {
    throw new Error(
      `Page range "${pageRangeSpec}" matched no pages (document has ${doc.numPages} page(s)).`,
    );
  }

  const segments: string[] = [];
  const includedPages: number[] = [];
  let totalChars = 0;
  let truncated = false;

  for (const pageNumber of pages) {
    const pageText = await extractPageText(doc, pageNumber);
    // Page boundary marker: form-feed + heading so it's both human- and
    // regex-friendly. Doesn't count against `maxChars` budget tracking
    // (kept simple 鈥?caller sees a coherent break either way).
    const segment = (segments.length > 0 ? '\n\f\n' : '')
      + `=== Page ${pageNumber} ===\n`
      + pageText;

    if (maxChars !== undefined && totalChars + segment.length > maxChars) {
      // Slice the current segment to fit, then stop.
      const remaining = Math.max(0, maxChars - totalChars);
      if (remaining > 0) {
        segments.push(segment.slice(0, remaining));
        includedPages.push(pageNumber);
        totalChars += remaining;
      }
      truncated = true;
      break;
    }

    segments.push(segment);
    includedPages.push(pageNumber);
    totalChars += segment.length;
  }

  const result: PdfTextResult = {
    text: segments.join(''),
    pages: includedPages,
    requestedPages: pages.length,
    truncated,
  };
  return result;
}

const SEARCH_SNIPPET_CONTEXT = 80;
const SEARCH_DEFAULT_MAX_HITS = 50;
const SEARCH_HARD_MAX_HITS = 500;

export async function handlePdfSearch(
  url: string,
  query: string,
  pageRangeSpec: string | undefined,
  options: { regex?: boolean; caseInsensitive?: boolean; maxHits?: number } = {},
): Promise<PdfSearchResult> {
  if (!query || !query.trim()) {
    throw new Error('Search query is empty.');
  }
  const doc = await getOrLoadDocument(url);
  const pages = parsePageRange(pageRangeSpec, doc.numPages);
  if (pages.length === 0) {
    throw new Error(
      `Page range "${pageRangeSpec}" matched no pages (document has ${doc.numPages} page(s)).`,
    );
  }

  const flags = (options.caseInsensitive ?? true) ? 'gi' : 'g';
  let matcher: RegExp;
  try {
    matcher = options.regex
      ? new RegExp(query, flags)
      : new RegExp(escapeRegExp(query), flags);
  } catch (err) {
    throw new Error(`Invalid regex query: ${(err as Error).message}`);
  }

  const maxHits = Math.min(
    SEARCH_HARD_MAX_HITS,
    Math.max(1, options.maxHits ?? SEARCH_DEFAULT_MAX_HITS),
  );

  const hits: PdfSearchHit[] = [];
  let truncated = false;
  let pagesScanned = 0;

  outer: for (const pageNumber of pages) {
    pagesScanned++;
    const pageText = await extractPageText(doc, pageNumber);
    matcher.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = matcher.exec(pageText)) !== null) {
      const index = m.index;
      const length = m[0].length;
      const start = Math.max(0, index - SEARCH_SNIPPET_CONTEXT);
      const end = Math.min(pageText.length, index + length + SEARCH_SNIPPET_CONTEXT);
      const prefix = start > 0 ? '鈥? : '';
      const suffix = end < pageText.length ? '鈥? : '';
      hits.push({
        page: pageNumber,
        index,
        length,
        snippet: prefix + pageText.slice(start, end) + suffix,
      });
      if (hits.length >= maxHits) {
        truncated = true;
        break outer;
      }
      // Defensive guard against zero-width regex matches infinite-looping.
      if (length === 0) matcher.lastIndex++;
    }
  }

  return { hits, truncated, pagesScanned };
}

