// 鈹€鈹€鈹€ ChatPage 鈹€鈹€鈹€

export function ChatPage({ onOpenSettings, onTitleChange }: {
  onOpenSettings?: () => void;
  onTitleChange?: (title: string) => void;
}) {
  const { sessionId: routeSessionId } = useParams<{ sessionId?: string }>();
  const isNewChat = !routeSessionId || routeSessionId === 'new';
  const navigate = useNavigate();

  // Only read activeModel for UI display (is a model selected?)
  const [currentModel] = useStorageItem(activeModel, null);

  // 椤甸潰鐩戞帶鐘舵€乗n  const [isWatching, setIsWatching] = useState(false);
  const [pageChangeAlert, setPageChangeAlert] = useState<{ count: number } | null>(null);

  // 鈹€鈹€鈹€ Agent port (all agent/session logic via background) 鈹€鈹€鈹€
  const {
    state,
    pendingTools,
    send,
    cancel,
    retry,
    subscribe: portSubscribe,
    unsubscribe: portUnsubscribe,
    deleteMessage,
    resolveTool,
  } = useBackgroundAgent({
    onSessionCreated: useCallback((sessionId: string, title: string) => {
      onTitleChange?.(title);
      navigate(`/chat/${sessionId}`, { replace: true });
    }, [navigate, onTitleChange]),
    onSessionLoaded: useCallback((session: SessionRecord | null) => {
      if (!session) {
        navigate('/chat/new', { replace: true });
      }
    }, [navigate]),
    // 2026-06-07: forward onOpenSettings so the web_provider_needs_relogin
    // flow (handleWebProviderNeedsRelogin 鈫?callbacks.onOpenSettings) can
    // actually navigate to /settings. Without this the optional-chaining
    // in useBackgroundAgent.ts:255 silently no-ops, and the user just sees
    // a toast without any visible navigation.
    onOpenSettings,
  });

  const { messages, isAgentRunning, sessionId: activeSessionId, sessionTitle, lastError } = state;

  // Mirror activeSessionId into a ref so the subscribe-effect can read the
  // latest value WITHOUT re-running when activeSessionId changes. Putting
  // activeSessionId in the effect's deps would cause an extra run between
  // session_created (which sets state.sessionId) and navigate (which sets
  // routeSessionId) 鈥?at that point isNewChat is still true, so the effect
  // would hit portUnsubscribe() and wipe the optimistic user message.
  const activeSessionIdRef = useRef<string | null>(null);
  activeSessionIdRef.current = activeSessionId;

  // When an interactive tool (e.g. ask_user) is pending, the agent is blocked
  // waiting for user input 鈥?treat as "not running" so the input is usable.
  // Sending a message during this state triggers steer + cancelAll in the
  // background agent manager automatically.
  const effectiveRunning = isAgentRunning && pendingTools.size === 0;

  // Subscribe to existing session or unsubscribe for new chat.
  //
  // Skip the subscribe IPC when the hook already considers this id active
  // (`activeSessionId === routeSessionId`). That's the case right after
  // sending the first message in a new chat: session_created set
  // state.sessionId to the new id, and the BG port's subscribedSession was
  // already pinned by the 'prompt' handler 鈥?we're implicitly subscribed.
  // A redundant 'subscribe' here would race with the in-flight
  // getOrCreateAgent: BG would fall through to a DB load of the just-written
  // empty row and reply with session_loaded{messages:[]}, clobbering the
  // optimistic user message and briefly flashing the welcome screen.
  useEffect(() => {
    if (isNewChat) {
      portUnsubscribe();
      return;
    }
    if (routeSessionId && routeSessionId !== activeSessionIdRef.current) {
      portSubscribe(routeSessionId);
    }
  }, [routeSessionId, isNewChat, portSubscribe, portUnsubscribe]);

  // Sync session title to parent
  useEffect(() => {
    onTitleChange?.(sessionTitle);
  }, [sessionTitle, onTitleChange]);

  // 鎸佷箙鍖?lastSessionId锛氬綋 activeSessionId 鍙樺寲鏃跺啓鍏ュ瓨鍌╘n  useEffect(() => {
    if (activeSessionId) {
      lastSessionId.setValue(activeSessionId);
    }
  }, [activeSessionId]);

  // 鐩戝惉鍙抽敭涓婁笅鏂囪彍鍗曡Е鍙戠殑 prompt
  useEffect(() => {
    if (typeof chrome === 'undefined' || !chrome.runtime?.onMessage) return;
    const listener = (msg: unknown) => {
      const m = msg as { type?: string; text?: string };
      if (m?.type === 'context_menu_prompt' && m?.text) {
        const text = m.text;
        // 濡傛灉褰撳墠鍦ㄨ缃〉鎴栧叾浠栭〉闈紝鍏堝鑸埌鏂拌亰澶‐n        if (isNewChat) {
          send(text, undefined, null);
        } else {
          // 宸叉湁浼氳瘽锛屽湪鏂拌亰澶╀腑鍙戦€乗n          navigate('/chat/new');
          // 绛夊緟瀵艰埅瀹屾垚鍚庡啀鍙戦€乗n          setTimeout(() => send(text, undefined, null), 100);
        }
      }
    };
    chrome.runtime.onMessage.addListener(listener);
    return () => chrome.runtime.onMessage.removeListener(listener);
  }, [send, isNewChat, navigate]);

  // Auto-scroll: stick to bottom while content streams, but stop following
  // as soon as the user scrolls up. Resumes when the user scrolls back near
  // the bottom. Driven internally by ResizeObserver, so no `messages`-dep
  // effect needed here.
  const { scrollRef, isAtBottom, scrollToBottom } = useStickToBottom();

  // Force-pin to bottom when switching sessions, opening a fresh chat, or when new messages arrive.
  useEffect(() => {
    scrollToBottom({ force: true });
  }, [activeSessionId, isNewChat, scrollToBottom]);

  // Also force-pin when the message list grows (e.g. first message in new chat, restored session).
  // Use rAF to ensure DOM has updated before scrolling.
  const messageCount = messages.length;
  useEffect(() => {
    if (messageCount > 0) {
      requestAnimationFrame(() => {
        scrollToBottom({ force: true });
      });
    }
  }, [messageCount, scrollToBottom]);

  // Force-pin when the user sends a new message 鈥?sending is an explicit
  // intent to see the latest output.
  const handleSend = useCallback(
    async (text: string, attachments: Attachment[] | undefined, expectedSessionId: string | null) => {
      const result = await send(text, attachments, expectedSessionId);
      if (result.status === 'dispatched') {
        scrollToBottom({ force: true });
      }
      return result;
    },
    [scrollToBottom, send],
  );

  // Quick tool actions 鈥?one-click prompt + optional screenshot
  const handleQuickTool = useCallback(async (toolId: QuickToolId) => {
    if (effectiveRunning && toolId !== 'watch-page') return;
    switch (toolId) {
      case 'read-page':
        await send(t('chat.quickTool.prompts.readPage'));
        break;
      case 'screenshot-analyze': {
        try {
          const dataUrl = await chrome.tabs.captureVisibleTab({ format: 'jpeg', quality: 85 });
          const base64 = dataUrl.split(',', 2)[1] ?? '';
          await send(
            t('chat.quickTool.prompts.screenshotAnalyze'),
            [{ type: 'image', source: 'screenshot', data: base64, mimeType: 'image/jpeg' }],
          );
        } catch {
          // 鎴浘澶辫触鏃堕€€鍥炵函鏂囨湰 prompt
          await send(t('chat.quickTool.prompts.screenshotFallback'));
        }
        break;
      }
      case 'operate-page':
        await send(t('chat.quickTool.prompts.operatePage'));
        break;
      case 'fill-form':
        await send(t('chat.quickTool.prompts.fillForm'));
        break;
      case 'watch-page': {
        try {
          const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
          if (!tab?.id) break;
          if (isWatching) {
            await chrome.scripting.executeScript({ target: { tabId: tab.id }, func: stopPageWatcher });
            setIsWatching(false);
            toast.info(t('chat.quickActions.watchStopped'));
          } else {
            const results = await chrome.scripting.executeScript({ target: { tabId: tab.id }, func: startPageWatcher });
            const status = results?.[0]?.result as string;
            if (status === 'already_watching') {
              toast.info(t('chat.quickActions.watchAlreadyActive'));
            } else {
              toast.success(t('chat.quickActions.watchStarted'));
            }
            setIsWatching(true);
          }
        } catch {
          toast.error(t('chat.quickActions.watchFailed'));
        }
        break;
      }
    }
    if (toolId !== 'watch-page') scrollToBottom({ force: true });
  }, [send, scrollToBottom, effectiveRunning, isWatching]);

  // 鐩戝惉椤甸潰鍙樺寲閫氱煡
  useEffect(() => {
    if (typeof chrome === 'undefined' || !chrome.runtime?.onMessage) return;
    const listener = (msg: unknown) => {
      const m = msg as { type?: string; changeCount?: number };
      if (m?.type === 'page_change_detected') {
        const count = m.changeCount ?? 0;
        setPageChangeAlert({ count });
        toast.info(t('chat.quickActions.pageChanged', [String(count)]), { duration: 8000 });
      }
    };
    chrome.runtime.onMessage.addListener(listener);
    return () => chrome.runtime.onMessage.removeListener(listener);
  }, []);

  const lastMsg = messages.length > 0 ? messages[messages.length - 1] : null;
  const showWaitingPlaceholder = effectiveRunning && lastMsg && 'role' in lastMsg && lastMsg.role === 'user';

  // History of user-typed prompts in this session, oldest first; consumed by
  // ChatInput's 鈫?鈫?navigation. Strips the <user-request> wrapper added by
  // buildStructuredMessage so what comes back is exactly what the user typed.
  const userHistory = useMemo(
    () => messages
      .filter((m): m is UserMessage => 'role' in m && m.role === 'user')
      .map(extractUserText)
      .filter((s) => s.length > 0),
    [messages],
  );

  // Session loading state: any route/state mismatch means the current
  // message array belongs to a different chat and must not be rendered.
  const sessionLoading = !isNewChat && routeSessionId !== activeSessionId;

  // Ref into ChatInput so QuickActionsBar can drive the same composer state
  // (value, focus, slash-menu close) without mirroring it up here. Forwarded
  // by ChatInput via `forwardRef<ChatInputHandle>`.
  const chatInputRef = useRef<ChatInputHandle>(null);

  // Pre-computed indexes for O(1) lookups inside message rendering
  const toolResultIndex = useMemo(() => buildToolResultIndex(messages as Message[]), [messages]);
  const turnMetaMap = useMemo(() => buildTurnMetaMap(messages as Message[]), [messages]);

  return (
    <>
      <div className="flex-1 min-h-0 relative flex flex-col">
        <ScrollArea className="flex-1 min-h-0" ref={scrollRef}>
          <div className="flex flex-col gap-4 p-5">
            {sessionLoading && (
              <div className="text-center text-sm text-muted-foreground py-12">
                {t('chat.session.loading')}
            </div>
          )}

          {!sessionLoading && messages.map((msg, idx) => {
            if (!('role' in msg)) return null;

            const handleDelete = () => {
              const sid = activeSessionId ?? routeSessionId;
              if (sid && sid !== 'new') deleteMessage(sid, idx);
            };

            const handleEdit = async (newText: string) => {
              const sid = activeSessionId ?? routeSessionId;
              if (!sid || sid === 'new') return;
              // Truncate from this message onward, then re-send with new text.
              deleteMessage(sid, idx);
              // Small delay so the BG processes delete before the prompt.
              await new Promise(r => setTimeout(r, 80));
              await send(newText);
            };

            if (msg.role === 'user') {
              return (
                <UserMessageBubble key={`user-${idx}`} msg={msg} onDelete={handleDelete} onEdit={handleEdit} />
              );
            }

            if (msg.role === 'assistant') {
              const assistantMsg = msg as import('@earendil-works/pi-ai').AssistantMessage;
              const isLast = idx === messages.length - 1;

              // Show header only for the first assistant message in a consecutive group
              let showHeader = true;
              for (let i = idx - 1; i >= 0; i--) {
                const prev = messages[i];
                if (!('role' in prev)) continue;
                if (prev.role === 'toolResult') {
                  const tr = prev as ToolResultMessage;
                  const info = uiToolRegistry.get(tr.toolName);
                  if (info?.renderResultAsUserBubble && !tr.details?.cancelled) break;
                  continue;
                }
                if (prev.role === 'assistant') showHeader = false;
                break;
              }

              // Meta row: show only on the assistant message that *closes*
              // the turn (stopReason !== 'toolUse'), so multi-tool-round
              // turns get one consolidated meta at the very end instead of
              // one per intermediate model call.
              const turnEnded = !isLast || !isAgentRunning;
              const isTurnClosing =
                turnEnded && assistantMsg.stopReason !== 'toolUse';
              const plainText = getAssistantText(assistantMsg).trim();
              const copyText = isTurnClosing && plainText.length > 0 ? plainText : undefined;
              const meta = isTurnClosing ? turnMetaMap.get(idx) : undefined;

              // Retry button: only on the very last message in the timeline,
              // only when the turn has actually closed (no pending tool round),
              // and only when the agent is idle (no overlapping run).
              const canRetry = isLast && isTurnClosing && !isAgentRunning;
              const onRetry = canRetry ? retry : undefined;

              return (
                <AssistantMessageItem
                  key={`asst-${idx}`}
                  idx={idx}
                  msg={assistantMsg}
                  isLast={isLast}
                  isAgentRunning={isAgentRunning}
                  effectiveRunning={effectiveRunning}
                  showHeader={showHeader}
                  meta={meta}
                  copyText={copyText}
                  canRetry={canRetry}
                  onRetry={onRetry}
                  onDelete={handleDelete}
                  toolResultIndex={toolResultIndex}
                  pendingTools={pendingTools}
                  resolveTool={resolveTool}
                />
              );
            }

            // Generic: render interactive tool results as user bubbles
            if (msg.role === 'toolResult') {
              return (
                <ToolResultBubble
                  key={`tr-${idx}`}
                  msg={msg as ToolResultMessage}
                  idx={idx}
                />
              );
            }

            return null;
          })}

          {/* Waiting placeholder */}
          {showWaitingPlaceholder && (
            <AgentMessage isStreaming />
          )}

          {/* Error display */}
          {lastError && !isAgentRunning && (
            <div className="text-sm text-destructive bg-destructive/15 border border-destructive/30 rounded-lg px-3 py-2">
              {lastError}
            </div>
          )}

          {!sessionLoading && messages.length === 0 && !isAgentRunning && (
            <div className="flex flex-col items-center gap-4 pt-20 pb-12 text-center">
              <div className="w-10 h-10 rounded-xl bg-primary/10 grid place-items-center">
                <SquarePen className="size-5 text-primary" />
              </div>
              {!currentModel ? (
                <p className="text-sm text-muted-foreground">{t('chat.composer.needModel')}</p>
              ) : (
                <div className="space-y-2">
                  <p className="text-2xl text-foreground/80 leading-relaxed" style={{ fontFamily: "var(--font-serif)" }}>
                    {t('chat.emptyState.slogan')}
                  </p>
                  <p className="text-sm text-muted-foreground tracking-wide" style={{ fontFamily: "var(--font-serif)" }}>
                    As Thought Reaches, So Action Arrives.
                  </p>
                  <div className="flex flex-wrap items-center justify-center gap-1.5 pt-3 text-xs text-muted-foreground/70">
                    <kbd className="px-1.5 py-0.5 rounded bg-muted border border-border/50 text-[10px]">/</kbd>
                    <span>{t('chat.emptyState.viewCommands')}</span>
                    <span className="text-border">路</span>
                    <span>{t('chat.emptyState.startChat')}</span>
                    <span className="text-border">路</span>
                    <kbd className="px-1.5 py-0.5 rounded bg-muted border border-border/50 text-[10px]">鈫戔啌</kbd>
                    <span>{t('chat.emptyState.historyInput')}</span>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </ScrollArea>

        {!isAtBottom && (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="secondary"
                size="icon"
                aria-label={t('chat.session.scrollToBottom')}
                onClick={() => scrollToBottom({ force: true })}
                className="absolute bottom-3 right-3 size-8 rounded-full shadow-md border border-border/60 bg-background/90 backdrop-blur hover:bg-background"
              >
                <ArrowDown className="size-4" />
              </Button>
            </TooltipTrigger>
            <TooltipContent>{t('chat.session.scrollToBottom')}</TooltipContent>
          </Tooltip>
        )}
      </div>

      <QuickActionsBar
        onTrigger={(prompt) => chatInputRef.current?.handleQuickAction(prompt.fileName)}
      />

      {/* 椤甸潰鍙樺寲鎻愰啋妯箙 */}
      {pageChangeAlert && (
        <button
          type="button"
          onClick={() => setPageChangeAlert(null)}
          className="mx-4 mb-1.5 px-3 py-1.5 rounded-md bg-amber-50 border border-amber-200 text-amber-800 text-xs flex items-center justify-between hover:bg-amber-100 transition-colors"
        >
          <span className="flex items-center gap-1.5">
            <span className="size-1.5 rounded-full bg-amber-500 animate-pulse" />
            {t('chat.quickActions.pageChanged', [String(pageChangeAlert.count)])}
          </span>
          <span className="text-amber-600/70">{t('chat.dismiss')}</span>
        </button>
      )}

      <ChatInput
        ref={chatInputRef}
        onSend={handleSend}
        onCancel={cancel}
        isAgentRunning={effectiveRunning}
        onOpenSettings={onOpenSettings}
        userHistory={userHistory}
        sessionId={isNewChat ? activeSessionId : routeSessionId ?? null}
        onQuickTool={handleQuickTool}
        isWatching={isWatching}
      />
    </>
  );
}

import { useEffect, type ReactNode } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useStorageItem } from '@/hooks/useStorageItem';
import { SettingsLayout } from '@/components/settings/SettingsLayout';
import { ProvidersSection } from '@/components/settings/sections/ProvidersSection';
import { InstructionsSection } from '@/components/settings/sections/InstructionsSection';
import { PromptsSection } from '@/components/settings/sections/PromptsSection';
import { SkillsSection } from '@/components/settings/sections/SkillsSection';
import { MCPSection } from '@/components/settings/sections/MCPSection';
import { ApiDiscoverySection } from '@/components/settings/sections/ApiDiscoverySection';
import { WorkflowsSection } from '@/components/settings/sections/WorkflowsSection';
import { AdvancedSection } from '@/components/settings/sections/AdvancedSection';
import { AboutSection } from '@/components/settings/sections/AboutSection';
import { lastSettingsSection } from '@/lib/storage';

interface SettingsRoutesProps {
  /** Absolute base path where SettingsRoutes is mounted (e.g. '/settings'). */
  basePath: string;
  /** Show back button in the top bar. True in sidepanel, false in standalone tab page. */
  showBackButton?: boolean;
  /** Show "open in new tab" button. True in sidepanel only. */
  showOpenInTab?: boolean;
}

/**
 * SettingsRoutes 鈥?top-level route tree for the Settings hub.
 *
 * Mounted at `/settings/*` in sidepanel (MemoryRouter) and at `/*` in the
 * standalone tab page (HashRouter). Only relative paths are used internally
 * so the same tree works under both routers. `basePath` is forwarded to
 * `SettingsLayout`/`SectionNav` so they can build absolute NavLinks.
 */
export function SettingsRoutes({ basePath, showBackButton = false, showOpenInTab = false }: SettingsRoutesProps) {
  return (
    <Routes>
      <Route element={<SettingsLayout basePath={basePath} showBackButton={showBackButton} showOpenInTab={showOpenInTab} />}>
        <Route index element={<SettingsIndexRedirect />} />
        <Route path="providers" element={<ProvidersSection />} />
        <Route path="instructions" element={<InstructionsSection />} />
        <Route path="prompts/*" element={<PromptsSection />} />
        <Route path="skills/*" element={<SkillsSection />} />
        <Route path="workflows" element={<WorkflowsSection />} />
        <Route path="mcp" element={<MCPSection />} />
        <Route path="api-discovery" element={<ApiDiscoverySection />} />
        <Route path="advanced" element={<AdvancedSection />} />
        <Route path="about" element={<AboutSection />} />
        <Route path="*" element={<Navigate to="." replace />} />
      </Route>
    </Routes>
  );
}

/** Redirects /settings to the last-visited section (fallback handled by storage item). */
function SettingsIndexRedirect(): ReactNode {
  const [target] = useStorageItem(lastSettingsSection, 'providers');
  return <Navigate to={target} replace />;
}

import { useState, useEffect, useRef } from 'react';
import { toast } from 'sonner';
import { Download, Loader2 } from 'lucide-react';
import { vfs } from '@/lib/vfs';
import { useStorageItem } from '@/hooks/useStorageItem';
import { themePreference } from '@/lib/storage';
import { downloadFile } from '@/lib/utils';
import { TooltipProvider } from '@/components/ui/tooltip';
import { Toaster } from '@/components/ui/sonner';
import { t } from '@/lib/i18n';
import { applyTheme, resolveTheme } from './lib/theme';
import { MAX_PREVIEW_BYTES, classifyFile, fileExtension, getHashPath, navigateTo } from './lib/path-utils';
import { mimeFor } from '@/lib/mime';
import { zipDirectory, zipNameFor } from './lib/download';
import { Breadcrumbs } from './ui/Breadcrumbs';
import { DirView } from './ui/DirView';
import { FileView } from './ui/FileView';
import type { FileMedia, ViewState } from './types';

export default function App() {
  const [theme] = useStorageItem(themePreference, 'system');
  const [themeReady, setThemeReady] = useState(false);
  const [view, setView] = useState<ViewState>({ kind: 'loading' });
  // Global busy flag for the download button. Kept outside `view` because a
  // download started on `/prompts` MUST keep running even if the user
  // navigates away mid-zip (decision A: don't interrupt explicit downloads).
  // The handler captures its target path from the closure at click time, so
  // the in-flight task is independent of subsequent view changes.
  const [isDownloading, setIsDownloading] = useState(false);

  // 鈹€鈹€ Theme sync 鈹€鈹€
  useEffect(() => {
    themePreference.getValue().then((val) => {
      applyTheme(resolveTheme(val ?? 'system'));
      setThemeReady(true);
    });
  }, []);

  useEffect(() => {
    if (!themeReady) return;
    applyTheme(resolveTheme(theme));
  }, [theme, themeReady]);

  useEffect(() => {
    if (theme !== 'system') return;
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const handler = (e: MediaQueryListEvent) => applyTheme(e.matches ? 'dark' : 'light');
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, [theme]);

  // 鈹€鈹€ Load path from hash 鈹€鈹€
  //
  // Two pieces of cross-call state live in refs:
  //
  // 1. `loadIdRef` 鈥?every call to loadPath() captures a monotonically
  //    increasing id at entry and re-checks it after each await. A rapid
  //    sequence of hashchange events (or a hashchange that fires while a
  //    previous load is still resolving) would otherwise let a stale
  //    setView win the race. The old `let stale` flag only flipped on
  //    effect unmount, so it could not protect against this.
  //
  // 2. `blobUrlRef` 鈥?image/video/audio media is exposed as `URL.createObjectURL`.
  //    We revoke the previous URL before issuing a new one (and on unmount)
  //    to keep memory bounded across many navigations.
  const loadIdRef = useRef(0);
  const blobUrlRef = useRef<string | null>(null);

  useEffect(() => {
    if (!themeReady) return;

    function revokeBlobUrl() {
      if (blobUrlRef.current) {
        URL.revokeObjectURL(blobUrlRef.current);
        blobUrlRef.current = null;
      }
    }

    async function loadPath() {
      const myId = ++loadIdRef.current;
      const p = getHashPath();
      revokeBlobUrl();
      setView({ kind: 'loading' });

      try {
        const st = await vfs.stat(p);
        if (myId !== loadIdRef.current) return;

        if (st.isDirectory()) {
          const names = await vfs.readdir(p);
          if (myId !== loadIdRef.current) return;
          const entries = await Promise.all(
            names.map(async (name) => {
              const childPath = p === '/' ? `/${name}` : `${p}/${name}`;
              try {
                const childStat = await vfs.stat(childPath);
                return { name, isDir: childStat.isDirectory(), size: childStat.size };
              } catch {
                return { name, isDir: false, size: 0 };
              }
            }),
          );
          if (myId !== loadIdRef.current) return;
          setView({ kind: 'dir', path: p, entries });
          return;
        }

        // File branch. One blanket size guard for every type 鈥?a 50 MB
        // markdown file is just as painful to render as a 50 MB image,
        // and the placeholder still lets the user fall back to Download.
        if (st.size > MAX_PREVIEW_BYTES) {
          setView({ kind: 'file', path: p, media: { type: 'tooLarge', size: st.size } });
          return;
        }

        const name = p.split('/').pop() ?? '';
        const ext = fileExtension(name);
        const klass = classifyFile(name);
        let media: FileMedia;

        if (klass === 'text' || klass === 'markdown') {
          const raw = (await vfs.readFile(p, 'utf8')) as unknown as string;
          if (myId !== loadIdRef.current) return;
          media = { type: klass, content: raw, size: st.size };
        } else if (klass === 'image' || klass === 'video' || klass === 'audio') {
          const data = (await vfs.readFile(p)) as unknown as Uint8Array;
          if (myId !== loadIdRef.current) return;
          const mime = mimeFor(ext);
          // `as BlobPart` for the same reason as the download path: the TS
          // DOM lib types Uint8Array<ArrayBufferLike> which BlobPart's
          // ArrayBufferView constraint won't accept directly, but the vfs
          // always hands us a plain ArrayBuffer-backed view.
          const url = URL.createObjectURL(new Blob([data as BlobPart], { type: mime }));
          blobUrlRef.current = url;
          media = { type: klass, mime, size: st.size, url };
        } else if (klass === 'binary') {
          // No read 鈥?just surface size. Download still works independently.
          media = { type: 'binary', size: st.size };
        } else {
          // Exhaustiveness guard 鈥?matches FileView's pattern. If
          // classifyFile's return union ever grows, TS will flag this.
          const _exhaustive: never = klass;
          throw new Error(`unreachable file class: ${_exhaustive}`);
        }

        setView({ kind: 'file', path: p, media });
      } catch (err: any) {
        if (myId !== loadIdRef.current) return;
        const message =
          err?.code === 'ENOENT'
            ? t('vfs.pathNotFound', [p])
            : err?.message ?? t('vfs.unknownError');
        setView({ kind: 'error', path: p, message });
      }
    }

    loadPath();
    window.addEventListener('hashchange', loadPath);
    return () => {
      // Invalidate any in-flight load and revoke the last blob URL so we
      // don't leak object URLs across remounts.
      loadIdRef.current++;
      revokeBlobUrl();
      window.removeEventListener('hashchange', loadPath);
    };
  }, [themeReady]);

  // 鈹€鈹€ Download (file or zipped folder) 鈹€鈹€
  //
  // Snapshots `view` into a const before the first await so a concurrent
  // hashchange that flips us to a different path can't redirect the
  // download to the wrong content. We intentionally do NOT abort on
  // navigation 鈥?see the `isDownloading` declaration comment.
  async function handleDownload() {
    if (isDownloading) return;
    const snapshot = view;
    if (snapshot.kind !== 'file' && snapshot.kind !== 'dir') return;

    setIsDownloading(true);
    try {
      if (snapshot.kind === 'file') {
        const data = (await vfs.readFile(snapshot.path)) as unknown as Uint8Array;
        const name = snapshot.path.split('/').pop() || 'file';
        // Wrap in Blob 鈥?`downloadFile` accepts ArrayBuffer/Blob/string but
        // not Uint8Array directly. The `as BlobPart` cast is required: the
        // current TS DOM lib types `Uint8Array<ArrayBufferLike>` which
        // includes SharedArrayBuffer, but BlobPart only accepts plain
        // ArrayBuffer-backed views. The vfs always hands us regular
        // ArrayBuffer, so the cast is sound. Generic octet-stream mime
        // keeps the browser from rewriting the extension (e.g. .md 鈫?.txt).
        downloadFile(name, new Blob([data as BlobPart], { type: 'application/octet-stream' }), 'application/octet-stream');
      } else {
        const data = await zipDirectory(snapshot.path);
        downloadFile(zipNameFor(snapshot.path), new Blob([data as BlobPart], { type: 'application/zip' }), 'application/zip');
      }
    } catch (err) {
      console.error('[vfs.download]', err);
      toast.error(t('common.downloadFailed'));
    } finally {
      setIsDownloading(false);
    }
  }

  // 鈹€鈹€ Render 鈹€鈹€

  if (!themeReady) return null;

  const currentPath = view.kind !== 'loading' ? view.path : getHashPath();

  return (
    <TooltipProvider delayDuration={300}>
      <div className="flex flex-col h-screen bg-background text-foreground">
        {/* Header */}
        <header className="flex items-center gap-4 px-5 py-3 border-b border-border shrink-0">
          <div className="flex items-center gap-2 shrink-0">
            <span className="text-base font-semibold tracking-tight">VFS</span>
            <span className="text-xs text-muted-foreground/50 font-mono">cebian</span>
          </div>
          <div className="h-4 w-px bg-border shrink-0" />
          <div className="flex-1 min-w-0">
            <Breadcrumbs path={currentPath} />
          </div>
          {/* Keep the button mounted while a download is in flight, even if
           *  `view` has flipped to `loading` because the user navigated
           *  away 鈥?otherwise the spinner unmounts and the user loses the
           *  busy indicator until the download finishes. Hidden only on
           *  `error` (nothing to download) and on a clean `loading` state
           *  with no active download. */}
          {(view.kind === 'file' || view.kind === 'dir' || isDownloading) && (
            <button
              onClick={handleDownload}
              disabled={isDownloading}
              title={isDownloading ? t('vfs.zipping') : t('common.download')}
              aria-label={isDownloading ? t('vfs.zipping') : t('common.download')}
              className="shrink-0 size-7 inline-flex items-center justify-center rounded-md text-muted-foreground hover:text-foreground hover:bg-accent transition-colors disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:hover:text-muted-foreground"
            >
              {isDownloading ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <Download className="size-4" />
              )}
            </button>
          )}
        </header>

        {/* Main content */}
        <main className="flex-1 min-h-0 overflow-y-auto">
          <div className="max-w-3xl mx-auto px-5 py-5">
            {view.kind === 'loading' && (
              <div className="flex items-center justify-center py-20">
                <div className="h-5 w-5 border-2 border-primary/30 border-t-primary rounded-full animate-spin" />
              </div>
            )}

            {view.kind === 'dir' && <DirView path={view.path} entries={view.entries} />}

            {view.kind === 'file' && <FileView path={view.path} media={view.media} />}

            {view.kind === 'error' && (
              <div className="flex flex-col items-center justify-center py-20 gap-3">
                <div className="h-12 w-12 rounded-full bg-destructive/10 flex items-center justify-center">
                  <span className="text-destructive text-lg">!</span>
                </div>
                <p className="text-sm text-muted-foreground">{view.message}</p>
                <button
                  onClick={() => navigateTo('/')}
                  className="mt-2 text-xs text-primary hover:underline"
                >
                  {t('vfs.backToRoot')}
                </button>
              </div>
            )}
          </div>
        </main>
        <Toaster theme={resolveTheme(theme)} />
      </div>
    </TooltipProvider>
  );
}

// Hook: connects sidepanel to background agent manager via chrome.runtime Port.
// Replaces useAgentLifecycle + useSessionManager.

import { useState, useRef, useEffect, useCallback } from 'react';
import type { AgentMessage } from '@earendil-works/pi-agent-core';
import type { TextContent, ImageContent } from '@earendil-works/pi-ai';
import { AGENT_PORT_NAME, type ClientMessage, type ServerMessage, type SessionMeta } from '@/lib/protocol';
import type { SessionRecord } from '@/lib/db';
import type { Attachment } from '@/lib/attachments';
import { truncateForRetry } from '@/lib/message-helpers';
import { t } from '@/lib/i18n';
import { recorderChannel } from '@/lib/recorder/sidepanel-channel';
import { mcpAppResourceChannel } from '@/lib/mcp/sidepanel-channel';
import { myInstanceId } from '@/lib/instance-id';
import { toast } from 'sonner';
import { handleWebProviderNeedsRelogin } from '@/hooks/handle-web-provider-needs-relogin';

// 鈹€鈹€鈹€ State 鈹€鈹€鈹€

export interface AgentPortState {
  messages: AgentMessage[];
  isAgentRunning: boolean;
  sessionId: string | null;
  sessionTitle: string;
  connected: boolean;
  /** Last error message from the agent, cleared on next prompt. */
  lastError: string | null;
}

// 鈹€鈹€鈹€ Pending interactive tool info (for UI rendering) 鈹€鈹€鈹€

export interface PendingToolInfo {
  toolCallId: string;
  args: unknown;
}

export type PromptDispatchResult =
  | { status: 'dispatched' }
  | { status: 'notDispatched'; reason: 'empty' | 'unavailable' };

const PROMPT_RECONNECT_TIMEOUT_MS = 1_500;

// 鈹€鈹€鈹€ Callbacks 鈹€鈹€鈹€

export interface AgentPortCallbacks {
  onSessionCreated?: (sessionId: string, title: string) => void;
  onSessionLoaded?: (session: SessionRecord | null) => void;
  onSessionList?: (sessions: SessionMeta[]) => void;
  onSessionDeleted?: (sessionId: string) => void;
  /** 鈶?4.followup: open Settings view (e.g. navigate to /settings).
   *  Used by the web_provider_needs_relogin flow to take the user to the
   *  re-login surface after a 401/403 from a web provider. */
  onOpenSettings?: () => void;
}

// 鈹€鈹€鈹€ Hook 鈹€鈹€鈹€

export function useBackgroundAgent(callbacks: AgentPortCallbacks) {
  const [state, setState] = useState<AgentPortState>({
    messages: [],
    isAgentRunning: false,
    sessionId: null,
    sessionTitle: '',
    connected: false,
    lastError: null,
  });

  const [pendingTools, setPendingTools] = useState<Map<string, PendingToolInfo>>(new Map());

  const portRef = useRef<chrome.runtime.Port | null>(null);
  const sessionIdRef = useRef<string | null>(null);
  const connectedWaitersRef = useRef<Set<(connected: boolean) => void>>(new Set());
  const scheduleRetryRef = useRef<(() => void) | null>(null);
  // Stable callback refs to avoid re-creating the port listener
  const callbacksRef = useRef(callbacks);
  callbacksRef.current = callbacks;

  // Connect to background on mount, with auto-reconnect on disconnect.
  useEffect(() => {
    let unmounted = false;
    let retryTimer: ReturnType<typeof setTimeout> | null = null;
    let retryCount = 0;
    const MAX_RETRY_DELAY = 30_000;
    const BASE_DELAY = 500;

    const handleMessage = (msg: ServerMessage) => {
      if (unmounted) return;
      try {
        handleMessageInner(msg);
      } catch (err) {
        console.error('[AgentPort] Unhandled error in message handler:', err);
        // Don't let a single bad message crash the entire sidepanel.
        // Report it as a non-fatal error so the user can continue.
        if (err instanceof Error) {
          setState(prev => ({ ...prev, lastError: err.message }));
        }
      }
    };

    function handleMessageInner(msg: ServerMessage) {
      const isCurrentSession = (sessionId: string | null | undefined) =>
        sessionId != null && sessionId === sessionIdRef.current;
      switch (msg.type) {
        case 'connected': {
          retryCount = 0;
          setState(prev => ({ ...prev, connected: true, lastError: null }));
          const waiters = Array.from(connectedWaitersRef.current);
          connectedWaitersRef.current.clear();
          for (const resolve of waiters) resolve(true);
          break;
        }

        case 'session_state':
          if (!isCurrentSession(msg.sessionId)) break;
          if (msg.pendingTools) {
            const next = new Map<string, PendingToolInfo>();
            for (const pending of msg.pendingTools) {
              next.set(pending.toolName, {
                toolCallId: pending.toolCallId,
                args: pending.args,
              });
            }
            setPendingTools(next);
          }
          setState(prev => ({
            ...prev,
            sessionId: msg.sessionId,
            // Title is only included on initial subscribe (loaded from DB);
            // mid-stream rebuild broadcasts omit it, so preserve the existing
            // value rather than wiping the header.
            ...(msg.title !== undefined ? { sessionTitle: msg.title } : {}),
            messages: msg.messages,
            isAgentRunning: msg.isRunning,
          }));
          break;

        case 'agent_start':
          if (!isCurrentSession(msg.sessionId)) break;
          setState(prev => ({ ...prev, isAgentRunning: true }));
          break;

        case 'message_update':
          if (!isCurrentSession(msg.sessionId)) break;
          setState(prev => {
            const msgs = [...prev.messages];
            const last = msgs[msgs.length - 1];
            if (last && 'role' in last && last.role === 'assistant') {
              msgs[msgs.length - 1] = msg.message;
            } else {
              msgs.push(msg.message);
            }
            return { ...prev, messages: msgs };
          });
          break;

        case 'message_end':
          if (!isCurrentSession(msg.sessionId)) break;
          setState(prev => ({ ...prev, messages: msg.messages }));
          break;

        case 'agent_end':
          if (!isCurrentSession(msg.sessionId)) break;
          setState(prev => ({
            ...prev,
            messages: msg.messages,
            isAgentRunning: false,
          }));
          setPendingTools(new Map());
          break;

        case 'tool_pending':
          if (!isCurrentSession(msg.sessionId)) break;
          setPendingTools(prev => {
            const next = new Map(prev);
            next.set(msg.toolName, { toolCallId: msg.toolCallId, args: msg.args });
            return next;
          });
          break;

        case 'tool_resolved':
          if (!isCurrentSession(msg.sessionId)) break;
          setPendingTools(prev => {
            const next = new Map(prev);
            next.delete(msg.toolName);
            return next;
          });
          break;

        case 'session_created':
          if (!isCurrentSession(msg.sessionId)) break;
          setPendingTools(new Map());
          setState(prev => ({
            ...prev,
            sessionId: msg.sessionId,
            sessionTitle: msg.title,
          }));
          callbacksRef.current.onSessionCreated?.(msg.sessionId, msg.title);
          break;

        case 'session_loaded':
          if (!isCurrentSession(msg.sessionId)) break;
          setPendingTools(new Map());
          if (msg.session) {
            setState(prev => ({
              ...prev,
              sessionId: msg.session!.id,
              sessionTitle: msg.session!.title,
              messages: msg.session!.messages,
              isAgentRunning: false,
            }));
          }
          callbacksRef.current.onSessionLoaded?.(msg.session);
          break;

        case 'session_list_result':
          callbacksRef.current.onSessionList?.(msg.sessions);
          break;

        case 'session_deleted':
          callbacksRef.current.onSessionDeleted?.(msg.sessionId);
          break;

        case 'error':
          if (msg.sessionId && !isCurrentSession(msg.sessionId)) break;
          console.error('[AgentPort] Error:', msg.error);
          setState(prev => ({ ...prev, isAgentRunning: false, lastError: msg.error }));
          break;

        case 'recorder_status':
          recorderChannel.publishStatus({
            isRecording: msg.isRecording,
            startedAt: msg.startedAt,
            eventCount: msg.eventCount,
            truncated: msg.truncated,
            initiatorInstanceId: msg.initiatorInstanceId,
            activeWindowId: msg.activeWindowId,
          });
          break;

        case 'recorder_session':
          recorderChannel.publishSession(msg.session);
          break;

        case 'recorder_start_rejected':
          recorderChannel.publishRejection({ reason: msg.reason });
          break;

        case 'mcp_resource_result':
          mcpAppResourceChannel.handleResult(msg);
          break;

        case 'web_provider_needs_relogin':
          // 鈶?4 + 鈶?4.followup: surface the 401/403 from a web provider.
          // 1) Show a destructive toast (user immediately sees the cause)
          // 2) Call onOpenSettings (navigate to /settings where the user
          //    can re-login). The providerId is intentionally not threaded
          //    into the callback yet 鈥?once we plumb a "scroll to provider"
          //    affordance in the settings page, we can extend this signature.
          handleWebProviderNeedsRelogin(msg, {
            showToast: ({ variant, title, description }) => {
              // Map shadcn/ui-style variants to sonner's API.
              // 'destructive' 鈫?toast.error; 'default' 鈫?toast (regular).
              if (variant === 'destructive') {
                toast.error(title, { description });
              } else {
                toast(title, { description });
              }
            },
            openSettings: () => callbacks.onOpenSettings?.(),
          });
          break;
      }
    };

    function scheduleRetry() {
      if (unmounted) return;
      const delay = Math.min(BASE_DELAY * 2 ** retryCount, MAX_RETRY_DELAY);
      retryCount++;
      if (retryCount === 5) {
        setState(prev => ({
          ...prev,
          lastError: t('chat.session.reconnecting'),
        }));
      }
      if (retryTimer) clearTimeout(retryTimer);
      retryTimer = setTimeout(() => {
        retryTimer = null;
        connect();
      }, delay);
    }

    scheduleRetryRef.current = scheduleRetry;

    function connect() {
      if (unmounted) return;
      const sessionToRestore = sessionIdRef.current;

      let port: chrome.runtime.Port;
      try {
        port = chrome.runtime.connect({ name: AGENT_PORT_NAME });
      } catch {
        scheduleRetry();
        return;
      }
      portRef.current = port;
      // Expose to the recorder channel so useRecorder can post start/stop.
      recorderChannel.setPort(port);
      // Expose to the MCP App resource channel so useMCPAppResource can
      // fetch `ui://` HTML for inline iframe rendering.
      mcpAppResourceChannel.setPort(port);

      port.onMessage.addListener(handleMessage);

      let disconnected = false;
      const handleDisconnect = () => {
        if (unmounted) return;
        if (disconnected) return;
        disconnected = true;
        if (portRef.current === port) {
          portRef.current = null;
          recorderChannel.setPort(null);
          mcpAppResourceChannel.setPort(null);
          setState(prev => ({ ...prev, connected: false }));
        }
        scheduleRetry();
      };
      port.onDisconnect.addListener(handleDisconnect);

      // Tell the background which sidepanel/tab instance this port belongs
      // to so the recorder can gate stop() and detect initiator-disconnect.
      // Sent synchronously 鈥?the instance id is generated at module load
      // and doesn't require an async Chrome API 鈥?so the BG sees the hello
      // before any other message we might post on this port.
      try {
        port.postMessage({
          type: 'hello',
          instanceId: myInstanceId,
        } satisfies ClientMessage);
        if (sessionToRestore) {
          port.postMessage({ type: 'subscribe', sessionId: sessionToRestore } satisfies ClientMessage);
        }
      } catch {
        handleDisconnect();
      }
    }

    connect();

    return () => {
      unmounted = true;
      if (retryTimer) clearTimeout(retryTimer);
      scheduleRetryRef.current = null;
      const waiters = Array.from(connectedWaitersRef.current);
      connectedWaitersRef.current.clear();
      for (const resolve of waiters) resolve(false);
      portRef.current?.disconnect();
      portRef.current = null;
      recorderChannel.setPort(null);
      mcpAppResourceChannel.setPort(null);
    };
  }, []);

  // 鈹€鈹€鈹€ Actions 鈹€鈹€鈹€

  const postMessage = useCallback((msg: ClientMessage) => {
    portRef.current?.postMessage(msg);
  }, []);

  const waitForConnected = useCallback((timeoutMs: number): Promise<boolean> => {
    if (portRef.current) return Promise.resolve(true);

    return new Promise((resolve) => {
      let settled = false;
      const finish = (connected: boolean) => {
        if (settled) return;
        settled = true;
        clearTimeout(timeout);
        connectedWaitersRef.current.delete(finish);
        resolve(connected && !!portRef.current);
      };
      const timeout = setTimeout(() => finish(false), timeoutMs);
      connectedWaitersRef.current.add(finish);
    });
  }, []);

  const dispatchPrompt = useCallback((
    text: string,
    attachments: Attachment[] | undefined,
    expectedSessionId: string | null,
  ): boolean => {
    if (sessionIdRef.current !== expectedSessionId) return false;

    const port = portRef.current;
    if (!port) return false;

    const existingSessionId = sessionIdRef.current;
    const sessionId = existingSessionId ?? crypto.randomUUID();

    try {
      port.postMessage({ type: 'prompt', sessionId, text, attachments });
    } catch {
      if (portRef.current === port) {
        portRef.current = null;
        recorderChannel.setPort(null);
        mcpAppResourceChannel.setPort(null);
        setState(prev => ({ ...prev, connected: false }));
        scheduleRetryRef.current?.();
      }
      return false;
    }

    // 鐪熸鎶曢€掓垚鍔熷悗鍐嶅啓鍏ユ柊 sessionId锛岄伩鍏嶉噸杩炵瓑寰呮湡闂磋闃呬竴涓皻鏈垱寤虹殑浼氳瘽銆俓n    if (!existingSessionId) {
      sessionIdRef.current = sessionId;
    }

    // Optimistically add user message to local state for immediate UI feedback
    setState(prev => {
      const content: Array<TextContent | ImageContent> = [{ type: 'text' as const, text: text.trim() }];
      // Include image attachments in optimistic message for preview
      if (attachments) {
        for (const att of attachments) {
          if (att.type === 'image') {
            content.push({ type: 'image', data: att.data, mimeType: att.mimeType });
          }
        }
      }
      const userMsg = { role: 'user' as const, content, timestamp: Date.now() };
      return {
        ...prev,
        messages: [...prev.messages, userMsg],
        isAgentRunning: true,
        lastError: null,
      };
    });
    return true;
  }, []);

  const send = useCallback(async (
    text: string,
    attachments?: Attachment[],
    expectedSessionId: string | null = sessionIdRef.current,
  ): Promise<PromptDispatchResult> => {
    const trimmed = text.trim();
    if (!trimmed) return { status: 'notDispatched', reason: 'empty' };

    const startedSessionId = expectedSessionId;
    if (dispatchPrompt(trimmed, attachments, startedSessionId)) return { status: 'dispatched' };

    const connected = await waitForConnected(PROMPT_RECONNECT_TIMEOUT_MS);
    if (!connected || sessionIdRef.current !== startedSessionId) {
      if (sessionIdRef.current === startedSessionId) {
        setState(prev => ({ ...prev, lastError: t('chat.session.notConnected') }));
      }
      return { status: 'notDispatched', reason: 'unavailable' };
    }

    if (dispatchPrompt(trimmed, attachments, startedSessionId)) return { status: 'dispatched' };

    setState(prev => ({ ...prev, lastError: t('chat.session.notConnected') }));
    return { status: 'notDispatched', reason: 'unavailable' };
  }, [dispatchPrompt, waitForConnected]);

  const cancel = useCallback(() => {
    const sessionId = sessionIdRef.current;
    if (sessionId) postMessage({ type: 'cancel', sessionId });
  }, [postMessage]);

  const retry = useCallback(() => {
    const sessionId = sessionIdRef.current;
    if (!sessionId) return;
    if (!portRef.current) {
      setState(prev => ({ ...prev, lastError: t('chat.session.notConnected') }));
      return;
    }
    // Optimistic update: locally apply the SAME truncation the background
    // will perform (drop everything after the last user message) and flip
    // `isAgentRunning` to true. Three effects, all immediate:
    //
    //   1. The errored / unwanted assistant bubble disappears right away 鈥擻n    //      no waiting for the BG round-trip's `session_state` broadcast,
    //      which used to leave the streaming cursor stranded at the end
    //      of the old bubble for ~100鈥?00ms.
    //   2. Retry button hides instantly so a double-click in this window
    //      can't fire a second IPC.
    //   3. Prior `lastError` clears.
    //
    // Multi-window safety: every subscribed window receives the BG's
    // authoritative `session_state` later; this window's local state
    // converges to that broadcast without flicker because the shared
    // `truncateForRetry` helper guarantees we computed the same array.
    // Defensive bail: if there's somehow no user message to retry from,
    // skip the optimistic step and let the background's own no-op path
    // surface the issue (matches BG's defensive throw).
    setState(prev => {
      const truncated = truncateForRetry(prev.messages);
      return {
        ...prev,
        messages: truncated ?? prev.messages,
        isAgentRunning: true,
        lastError: null,
      };
    });
    postMessage({ type: 'retry', sessionId });
  }, [postMessage]);

  const subscribe = useCallback((sessionId: string) => {
    const isSessionChange = sessionIdRef.current !== sessionId;
    if (isSessionChange) {
      setPendingTools(new Map());
    }
    sessionIdRef.current = sessionId;
    setState(prev => isSessionChange
      ? {
          ...prev,
          messages: [],
          isAgentRunning: false,
          sessionTitle: '',
          lastError: null,
        }
      : { ...prev, sessionId });
    postMessage({ type: 'subscribe', sessionId });
  }, [postMessage]);

  const unsubscribe = useCallback(() => {
    sessionIdRef.current = null;
    setState({
      messages: [],
      isAgentRunning: false,
      sessionId: null,
      sessionTitle: '',
      connected: true,
      lastError: null,
    });
    setPendingTools(new Map());
    postMessage({ type: 'unsubscribe' });
  }, [postMessage]);

  const listSessions = useCallback(() => {
    postMessage({ type: 'session_list' });
  }, [postMessage]);

  const deleteMessage = useCallback((sessionId: string, messageIndex: number) => {
    postMessage({ type: 'delete_message', sessionId, messageIndex });
  }, [postMessage]);

  const deleteSession = useCallback((sessionId: string) => {
    postMessage({ type: 'session_delete', sessionId });
  }, [postMessage]);

  const resolveTool = useCallback((toolName: string, response: unknown) => {
    const sessionId = sessionIdRef.current;
    if (sessionId) {
      postMessage({ type: 'resolve_tool', sessionId, toolName, response });
      setPendingTools(prev => {
        const next = new Map(prev);
        next.delete(toolName);
        return next;
      });
    }
  }, [postMessage]);

  const cancelTool = useCallback((toolName: string) => {
    const sessionId = sessionIdRef.current;
    if (sessionId) {
      postMessage({ type: 'cancel_tool', sessionId, toolName });
      setPendingTools(prev => {
        const next = new Map(prev);
        next.delete(toolName);
        return next;
      });
    }
  }, [postMessage]);

  return {
    state,
    pendingTools,
    send,
    cancel,
    retry,
    subscribe,
    unsubscribe,
    listSessions,
    deleteSession,
    deleteMessage,
    resolveTool,
    cancelTool,
  };
}

