/**
 * useUpdateCheck 鈥?fetches the latest Cebian release from the fork's GitHub
 * Releases atom feed and compares against the currently installed extension
 * version.
 *
 * Why atom feed and not api.github.com:
 * - The unauthenticated api.github.com endpoint is rate-limited to 60 req/h per
 *   IP. The user's IP exhausted this and the check silently 403'd, leaving
 *   the "Check for updates" button perpetually clickable (error state).
 * - The GitHub Pages atom feed (releases.atom) is served from a separate
 *   rate-limit pool and is not subject to the 60/h cap.
 * - The atom feed for a repo with zero releases returns HTTP 200 with an
 *   empty <feed>, which is a deterministic "noRelease" signal.
 *
 * Result is cached in localStorage for 6 hours to avoid hitting the feed on
 * every About-page mount. Call `recheck()` to force-refresh.
 */
import { useCallback, useEffect, useRef, useState } from 'react';

const CACHE_KEY = 'cebian:updateCheck';
const CACHE_VERSION = 3;
const CACHE_TTL_MS = 6 * 60 * 60 * 1000; // 6h
const RELEASES_URL = 'https://github.com/zhixingt/Cebian/releases.atom';

export type UpdateStatus =
  | { kind: 'idle' }
  | { kind: 'checking' }
  | { kind: 'noRelease' }
  | { kind: 'upToDate'; current: string; latest: string }
  | { kind: 'updateAvailable'; current: string; latest: string }
  | { kind: 'error' };

interface CacheEntry {
  version: number;
  checkedAt: number;
  latest: string;
}

function readCache(): CacheEntry | null {
  try {
    const raw = localStorage.getItem(CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as CacheEntry;
    if (parsed.version !== CACHE_VERSION) return null;
    if (typeof parsed.checkedAt !== 'number' || typeof parsed.latest !== 'string') return null;
    return parsed;
  } catch {
    return null;
  }
}

function writeCache(entry: Omit<CacheEntry, 'version'>): void {
  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify({ version: CACHE_VERSION, ...entry }));
  } catch {
    // ignore quota / disabled storage
  }
}

/**
 * Compare two semver-like strings. Strips any prerelease/build suffix
 * (anything after `-` or `+`) before numeric `a.b.c` comparison.
 * Returns 1, 0, -1.
 */
function compareVersions(a: string, b: string): number {
  const stripSuffix = (s: string) => s.split(/[-+]/)[0];
  const pa = stripSuffix(a).split('.').map((n) => parseInt(n, 10) || 0);
  const pb = stripSuffix(b).split('.').map((n) => parseInt(n, 10) || 0);
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const da = pa[i] ?? 0;
    const db = pb[i] ?? 0;
    if (da > db) return 1;
    if (da < db) return -1;
  }
  return 0;
}

function stripV(tag: string): string {
  return tag.replace(/^v/i, '').trim();
}

function isPrerelease(tag: string): boolean {
  // semver: anything after '-' is a prerelease; anything after '+' is build metadata.
  // Per the test contract, +build is treated as a prerelease.
  return /[-+]/.test(tag);
}

function buildStatus(current: string, latest: string): UpdateStatus {
  return compareVersions(latest, current) > 0
    ? { kind: 'updateAvailable', current, latest }
    : { kind: 'upToDate', current, latest };
}

function initialStatus(current: string): UpdateStatus {
  const cached = readCache();
  if (cached && Date.now() - cached.checkedAt < CACHE_TTL_MS) {
    return buildStatus(current, cached.latest);
  }
  return { kind: 'idle' };
}

/**
 * Parse a GitHub Releases atom feed and return the first stable release tag
 * (without leading `v`), or `null` when no stable release is present.
 *
 * An entry is treated as a prerelease when its `<title>` contains `-` or `+`
 * (semver prerelease / build-metadata marker).
 */
export function findFirstStableRelease(xml: string): string | null {
  if (!xml || typeof xml !== 'string') return null;
  let doc: Document;
  try {
    doc = new DOMParser().parseFromString(xml, 'application/xml');
  } catch {
    return null;
  }
  // DOMParser surfaces parse errors as a <parsererror> child of the document.
  if (doc.getElementsByTagName('parsererror').length > 0) return null;

  const entries = Array.from(doc.getElementsByTagName('entry'));
  for (const entry of entries) {
    const title = entry.getElementsByTagName('title')[0]?.textContent?.trim();
    if (!title) continue;
    if (isPrerelease(title)) continue;
    return stripV(title);
  }
  return null;
}

export function useUpdateCheck() {
  const current = chrome.runtime.getManifest().version;
  const [status, setStatus] = useState<UpdateStatus>(() => initialStatus(current));
  const inflightRef = useRef(false);
  const mountedRef = useRef(true);
  const abortRef = useRef<AbortController | null>(null);

  const runCheck = useCallback(
    async (force: boolean) => {
      if (inflightRef.current) return;
      if (!force) {
        const cached = readCache();
        if (cached && Date.now() - cached.checkedAt < CACHE_TTL_MS) {
          if (mountedRef.current) setStatus(buildStatus(current, cached.latest));
          return;
        }
      }

      inflightRef.current = true;
      const controller = new AbortController();
      abortRef.current = controller;
      if (mountedRef.current) setStatus({ kind: 'checking' });
      try {
        const res = await fetch(RELEASES_URL, {
          headers: { Accept: 'application/atom+xml' },
          signal: controller.signal,
        });
        if (!res.ok) {
          // 404 / 410 on a releases.atom endpoint is a deterministic "this
          // repo has no releases" signal (the URL is correct, the feed just
          // doesn't exist). Map to noRelease so the UI can show a stable
          // "no release" state instead of a perpetual error.
          if (res.status === 404 || res.status === 410) {
            if (mountedRef.current) setStatus({ kind: 'noRelease' });
            return;
          }
          throw new Error(`HTTP ${res.status}`);
        }
        const xml = await res.text();
        const latest = findFirstStableRelease(xml);
        if (!latest) {
          // No stable release on the feed (fork with 0 releases, or every
          // entry is a prerelease). Treat as a deterministic terminal state
          // so the caller can show "your fork has no releases" instead of
          // a perpetual spinner / error.
          if (mountedRef.current) setStatus({ kind: 'noRelease' });
          return;
        }
        writeCache({ checkedAt: Date.now(), latest });
        if (mountedRef.current) setStatus(buildStatus(current, latest));
      } catch (err) {
        if ((err as Error)?.name === 'AbortError') return;
        console.warn('[useUpdateCheck] update check failed:', err);
        if (mountedRef.current) setStatus({ kind: 'error' });
      } finally {
        inflightRef.current = false;
        if (abortRef.current === controller) abortRef.current = null;
      }
    },
    [current],
  );

  useEffect(() => {
    mountedRef.current = true;
    void runCheck(false);
    return () => {
      mountedRef.current = false;
    };
  }, [runCheck]);

  const recheck = useCallback(() => runCheck(true), [runCheck]);

  return { status, current, recheck };
}

/**
 * Resolves the install-guide URL on cebian.catcat.work based on the current
 * UI language. Chinese locales (zh, zh_CN, zh_TW, zh_HK) all map to /zh;
 * everything else falls back to /en.
 *
 * TODO: add a /zh-tw path once the install guide site ships a Traditional
 * Chinese variant 鈥?currently zh_TW users get the Simplified guide.
 */
export function getInstallGuideUrl(): string {
  const lang = chrome.i18n.getUILanguage().toLowerCase();
  const path = lang.startsWith('zh') ? '/zh/install-guide' : '/en/install-guide';
  return `https://cebian.catcat.work${path}`;
}

import { Agent, type AgentOptions, type AgentMessage, type AgentTool } from '@earendil-works/pi-agent-core';
import type { Api, Model, Message } from '@earendil-works/pi-ai';
import { providerCredentials, type OAuthCredential } from './storage';
import { getValidOAuthToken } from './oauth';
import { DEFAULT_SYSTEM_PROMPT } from './constants';
import { buildMemoryPrompt } from './memory/prompt-builder';

// 鈹€鈹€鈹€ Agent factory 鈹€鈹€鈹€

export interface CreateAgentOptions {
  model: Model<Api>;
  /** Session id 鈥?substituted into the system prompt as the agent's working directory. */
  sessionId: string;
  /**
   * Optional user-provided instructions appended to the built-in system prompt.
   * Intended for style/language/role tweaks; cannot override tool protocol or safety rules.
   */
  userInstructions: string;
  thinkingLevel: 'off' | 'minimal' | 'low' | 'medium' | 'high';
  maxRounds: number;
  messages?: AgentMessage[];
  /** Session-specific tools array (includes per-session ask_user). */
  tools: AgentTool<any>[];
}

export async function createCebianAgent(options: CreateAgentOptions): Promise<Agent> {
  const {
    model,
    sessionId,
    userInstructions,
    thinkingLevel,
    maxRounds,
    messages = [],
    tools: agentTools,
  } = options;

  const basePrompt = DEFAULT_SYSTEM_PROMPT
    .replaceAll('{{SESSION_ID}}', sessionId);
  const trimmedInstructions = userInstructions.trim();
  const effectivePrompt = trimmedInstructions
    ? `${basePrompt}\n\n<user-instructions>\n${trimmedInstructions}\n</user-instructions>`
    : basePrompt;

  // 鍒嗗眰璁板繂娉ㄥ叆锛氭绱㈢敤鎴风敾鍍?+ 浼氳瘽鎽樿 + Agent 璁板繂锛岃拷鍔犲埌 system prompt銆俓n  // 澶辫触鏃朵笉闃诲 Agent 鍒涘缓锛堣繑鍥炵┖瀛楃涓诧紝浣跨敤 effectivePrompt 鍏滃簳锛夈€俓n  // 鐢ㄦ渶杩戠敤鎴锋秷鎭綔涓烘绱㈡煡璇紝鑰岄潪 sessionId锛圲UID 浼氬鑷村叧閿瘝鍖归厤澶辨晥锛夈€俓n  const lastUserMessage = [...messages].reverse().find(
    (m): m is AgentMessage => 'role' in m && (m as { role?: string }).role === 'user',
  );
  const queryText = lastUserMessage
    ? (typeof (lastUserMessage as { content?: unknown }).content === 'string'
        ? ((lastUserMessage as { content: string }).content)
        : JSON.stringify((lastUserMessage as { content?: unknown }).content ?? ''))
    : '';

  let memoryPrompt = '';
  try {
    memoryPrompt = await buildMemoryPrompt(queryText);
  } catch (err) {
    console.warn('[Agent] Failed to build memory prompt:', err);
  }
  const finalPrompt = memoryPrompt
    ? `${effectivePrompt}\n\n${memoryPrompt}`
    : effectivePrompt;

  const agentOptions: AgentOptions = {
    initialState: {
      systemPrompt: finalPrompt,
      model,
      thinkingLevel,
      tools: agentTools,
      messages,
    },

    // Convert AgentMessages to LLM messages (filter out any custom types)
    convertToLlm: (msgs: AgentMessage[]): Message[] => {
      return msgs.filter((m): m is Message =>
        'role' in m && ['user', 'assistant', 'toolResult'].includes((m as Message).role),
      );
    },

    // Context window management: sliding window based on maxRounds
    transformContext: async (msgs: AgentMessage[]): Promise<AgentMessage[]> => {
      const limit = maxRounds * 3; // ~3 messages per round (user + assistant + potential toolResult)
      if (msgs.length <= limit) return msgs;
      return msgs.slice(-limit);
    },

    // Dynamic API key resolution (handles OAuth token refresh)
    getApiKey: async (provider: string): Promise<string | undefined> => {
      try {
        const creds = await providerCredentials.getValue();
        const cred = creds[provider];
        if (!cred) return undefined;

        if (cred.authType === 'apiKey') {
          return cred.apiKey;
        }

        if (cred.authType === 'oauth') {
          return getValidOAuthToken(provider, cred as OAuthCredential);
        }
      } catch (err) {
        console.error(`[Agent] Failed to get API key for ${provider}:`, err);
      }
      return undefined;
    },
  };

  return new Agent(agentOptions);
}

/**
 * skill-creator 鈥?VFS scaffolding for new Skills following agentskills.io spec.
 *
 * Creates a new skill directory with a SKILL.md template, plus empty `scripts/`
 * and `references/` subdirs. Naming collides are resolved by appending `-N`.
 */
import { vfs } from '@/lib/vfs';
import { t } from '@/lib/i18n';

async function uniqueName(dir: string, base: string): Promise<string> {
  if (!(await vfs.exists(`${dir}/${base}`))) return base;
  let n = 1;
  // eslint-disable-next-line no-constant-condition
  while (true) {
    const candidate = `${base}-${n}`;
    if (!(await vfs.exists(`${dir}/${candidate}`))) return candidate;
    n++;
  }
}

export interface CreatedSkill {
  /** Absolute path to the new skill directory. */
  dirPath: string;
  /** Absolute path to the SKILL.md entry file (good target for auto-select). */
  entryFile: string;
}

/**
 * Scaffold a new skill under `root` and return its paths. The caller is
 * expected to refresh the file tree and optionally select `entryFile`.
 */
export async function createSkillTemplate(root: string): Promise<CreatedSkill> {
  const name = await uniqueName(root, 'new-skill');
  const dirPath = `${root}/${name}`;
  const entryFile = `${dirPath}/SKILL.md`;

  const skillMd = `---
name: ${name}
description: "TODO - describe what this skill does and when to use it."
metadata:
  author: ""
  version: "0.1.0"
  # Optional Cebian extensions 鈥?uncomment as needed:
  # matched-url: "https://example.com/**"
  # permissions:
  #   - chrome.bookmarks
  #   - page.executeJs
---

## Instructions

${t('settings.skills.newBody')}
`;

  await vfs.mkdir(dirPath, { recursive: true });
  await vfs.mkdir(`${dirPath}/scripts`, { recursive: true });
  await vfs.mkdir(`${dirPath}/references`, { recursive: true });
  await vfs.writeFile(entryFile, skillMd);

  return { dirPath, entryFile };
}

/**
 * 鈶?4 GLM (chatglm.cn) MAIN-world content-script adapter 鈥?鈶?6 rewrite.
 *
 * Every helper, constant, and dependency is inlined into the exported
 * function body. This is REQUIRED because chrome.scripting.executeScript
 * serializes only the function body 鈥?any reference to module-scope
 * symbols (constants, helpers) would become undefined at runtime
 * (the "ryt is not defined" bug from the 鈶?selector-fix round).
 *
 * What this adapter does:
 *   1. Read chatglm_token + chatglm_refresh_token from document.cookie
 *   2. If no auth token but refresh token exists, call the refresh
 *      endpoint inline (best-effort, 1 try)
 *   3. Build a real GLM request:
 *        - URL: /chatglm/backend-api/assistant/stream
 *        - Body: { assistant_id, conversation_id, project_id,
 *                  chat_type: 'user_chat', meta_data, messages: [...] }
 *        - Headers: Authorization + 10+ X-* headers including
 *                   X-Sign = MD5(timestamp-nonce-secret) where
 *                   timestamp has a checksum digit
 *   4. Read SSE response, dedupe cumulative text deltas
 *      (parts[0].content[0].text contains the FULL accumulated text
 *      every event, so we must subtract prevText to get the delta)
 *   5. Forward deltas to the bridge via window.postMessage
 *
 * Reference: chromeclaw-research/.../providers/{glm-shared,glm-signing}.ts
 */
import type { ContentFetchRequest } from './web-provider-content-fetch-main';

export const glmMainWorldFetch = async (request: ContentFetchRequest): Promise<void> => {
  const requestId = request.requestId;
  const origin = window.location.origin;

  // 鈶? Max wall-clock for the entire adapter call. If the GLM SSE
  // stream stalls (server side hang, network drop, etc.) the reader
  // never resolves and the sidepanel stays in a loading state
  // forever. We cap the call at this duration so the spinner
  // disappears and the user sees a clear error.
  //
  // CRITICAL: this MUST be declared inside the function body. The function
  // is serialized via `chrome.scripting.executeScript({func})` which uses
  // `Function.prototype.toString()` 鈥?module-scope identifiers are NOT
  // captured, so the function would reference an undefined symbol in MAIN
  // world 鈫?runtime `ReferenceError` (e.g. "qyt is not defined" after minify).
  const ADAPTER_TIMEOUT_MS = 90_000;

  // 鈶?FIX: cross-world messaging via document CustomEvent
  // (window.postMessage doesn't cross the MAIN鈫擨SOLATED world boundary)
  // 鈶?providerId must be in the event detail 鈥?the ISOLATED bridge
  // filters by data.providerId === installed-providerId, and drops
  // anything that doesn't match. We capture it from the request so
  // every postToBridge call automatically includes it.
  const postToBridge = (data: Record<string, unknown>, _origin?: string): void => {
    document.dispatchEvent(new CustomEvent('ceb-web-provider-message', {
      detail: { ...data, providerId: request.providerId },
    }));
  };

  // 鈶? Port-based abort channel. The SW opens a port named
  // `abort-${requestId}` and posts `{type:'abort'}` when the user clicks
  // Stop. The ISOLATED bridge forwards this as a `ceb-web-provider-message`
  // CustomEvent with `{type:'WEB_LLM_ABORT'}`. We listen for it here and
  // set `window.__webProviderAbortFlag = true` so the SSE reading loop
  // below can break early instead of continuing to push chunks after the
  // user cancelled. Without this, the SW-side stream is cancelled but
  // the MAIN-world IIFE keeps running and eventually pushes
  // WEB_LLM_DONE with full accumulated text 鈥?leaving residual text in
  // the assistant message bubble.
  // MVP assumption: one active web-provider session per tab at a time.
  // If concurrent sessions are ever supported, this flag must be keyed
  // by session/request id instead of being a singleton.
  (window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag = false;
  const abortListener = (event: Event) => {
    const data = (event as CustomEvent<Record<string, unknown>>).detail;
    if (data && data.type === 'WEB_LLM_ABORT') {
      (window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag = true;
    }
  };
  document.addEventListener('ceb-web-provider-message', abortListener);

  // 鈶? Adapter-level wall-clock timeout. Race the body against a
  // timer so a hung stream can't pin the sidepanel. Inner async +
  // Promise.race + finally ensures the timer is cleared exactly once
  // on every exit path.
  let timeoutHandle: ReturnType<typeof setTimeout> | null = null;
  const work = (async () => {

      const init = request.init;

      // 鈹€鈹€ Inlined constants (cannot be module-scope 鈥?would be undefined
      //    when this function is serialized via chrome.scripting.executeScript) 鈹€鈹€
      const GLM_SIGN_SECRET = '8a1317a7468aa3ad86e997d08f3f31cb';
      const GLM_DEVICE_ID_KEY = '__cebGlmDeviceId__';
      const GLM_REFRESH_URL_SUFFIX = '/chatglm/user-api/user/refresh';
      const GLM_STREAM_URL_SUFFIX = '/chatglm/backend-api/assistant/stream';

      // MD5 K constants (64 脳 floor(2^32 * abs(sin(i+1))))
      const MD5_K = [
        0xd76aa478, 0xe8c7b756, 0x242070db, 0xc1bdceee, 0xf57c0faf, 0x4787c62a,
        0xa8304613, 0xfd469501, 0x698098d8, 0x8b44f7af, 0xffff5bb1, 0x895cd7be,
        0x6b901122, 0xfd987193, 0xa679438e, 0x49b40821, 0xf61e2562, 0xc040b340,
        0x265e5a51, 0xe9b6c7aa, 0xd62f105d, 0x02441453, 0xd8a1e681, 0xe7d3fbc8,
        0x21e1cde6, 0xc33707d6, 0xf4d50d87, 0x455a14ed, 0xa9e3e905, 0xfcefa3f8,
        0x676f02d9, 0x8d2a4c8a, 0xfffa3942, 0x8771f681, 0x6d9d6122, 0xfde5380c,
        0xa4beea44, 0x4bdecfa9, 0xf6bb4b60, 0xbebfbc70, 0x289b7ec6, 0xeaa127fa,
        0xd4ef3085, 0x04881d05, 0xd9d4d039, 0xe6db99e5, 0x1fa27cf8, 0xc4ac5665,
        0xf4292244, 0x432aff97, 0xab9423a7, 0xfc93a039, 0x655b59c3, 0x8f0ccc92,
        0xffeff47d, 0x85845dd1, 0x6fa87e4f, 0xfe2ce6e0, 0xa3014314, 0x4e0811a1,
        0xf7537e82, 0xbd3af235, 0x2ad7d2bb, 0xeb86d391,
      ];
      const MD5_S = [
        7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
        5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
        4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
        6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
      ];

      // 鈹€鈹€ Inlined helpers (cannot be module-scope) 鈹€鈹€
      const md5Hex = (input: string): string => {
        const bytes: number[] = [];
        for (let i = 0; i < input.length; i++) {
          const c = input.charCodeAt(i);
          if (c < 0x80) bytes.push(c);
          else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
          else bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
        }
        const bitLen = bytes.length * 8;
        bytes.push(0x80);
        while (bytes.length % 64 !== 56) bytes.push(0);
        for (let i = 0; i < 4; i++) bytes.push((bitLen >>> (i * 8)) & 0xff);
        for (let i = 0; i < 4; i++) bytes.push(0);
        let a0 = 0x67452301;
        let b0 = 0xefcdab89;
        let c0 = 0x98badcfe;
        let d0 = 0x10325476;
        const toHex = (n: number) => {
          const u = n >>> 0;
          return (
            ((u & 0xff).toString(16).padStart(2, '0')) +
            (((u >>> 8) & 0xff).toString(16).padStart(2, '0')) +
            (((u >>> 16) & 0xff).toString(16).padStart(2, '0')) +
            (((u >>> 24) & 0xff).toString(16).padStart(2, '0'))
          );
        };
        for (let offset = 0; offset < bytes.length; offset += 64) {
          const w = new Int32Array(16);
          for (let j = 0; j < 16; j++) {
            w[j] =
              bytes[offset + j * 4] |
              (bytes[offset + j * 4 + 1] << 8) |
              (bytes[offset + j * 4 + 2] << 16) |
              (bytes[offset + j * 4 + 3] << 24);
          }
          let a = a0, b = b0, c = c0, d = d0;
          for (let i = 0; i < 64; i++) {
            let f: number, g: number;
            if (i < 16) { f = (b & c) | (~b & d); g = i; }
            else if (i < 32) { f = (d & b) | (~d & c); g = (5 * i + 1) % 16; }
            else if (i < 48) { f = b ^ c ^ d; g = (3 * i + 5) % 16; }
            else { f = c ^ (b | ~d); g = (7 * i) % 16; }
            const temp = d; d = c; c = b;
            const sum = ((a + f) | 0) + ((MD5_K[i] + w[g]) | 0);
            const rot = MD5_S[i];
            b = (b + ((sum << rot) | (sum >>> (32 - rot)))) | 0;
            a = temp;
          }
          a0 = (a0 + a) | 0; b0 = (b0 + b) | 0; c0 = (c0 + c) | 0; d0 = (d0 + d) | 0;
        }
        return toHex(a0) + toHex(b0) + toHex(c0) + toHex(d0);
      };

      const generateGlmSign = (): { timestamp: string; nonce: string; sign: string } => {
        const now = Date.now();
        const digits = now.toString();
        const len = digits.length;
        const digitArr = digits.split('').map(Number);
        const sum = digitArr.reduce((acc, v) => acc + v, 0) - digitArr[len - 2];
        const checkDigit = sum % 10;
        const timestamp = digits.substring(0, len - 2) + checkDigit + digits.substring(len - 1);
        const nonce = crypto.randomUUID().replace(/-/g, '');
        const sign = md5Hex(`${timestamp}-${nonce}-${GLM_SIGN_SECRET}`);
        return { timestamp, nonce, sign };
      };

      const readCookie = (name: string): string => {
        try {
          const m = document.cookie.match(
            new RegExp(`(?:^|;\\s*)${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}=([^;]*)`),
          );
          if (!m) return '';
          try { return decodeURIComponent(m[1]); } catch { return m[1]; }
        } catch { return ''; }
      };

      const getOrCreateDeviceId = (): string => {
        try {
          const cached = localStorage.getItem(GLM_DEVICE_ID_KEY);
          if (cached && /^[0-9a-f-]{36}$/i.test(cached)) return cached;
        } catch { /* ignore */ }
        const fresh = crypto.randomUUID();
        try { localStorage.setItem(GLM_DEVICE_ID_KEY, fresh); } catch { /* ignore */ }
        return fresh;
      };

      const refreshGlmToken = async (refreshUrl: string, refreshToken: string): Promise<string | null> => {
        const { timestamp, nonce, sign } = generateGlmSign();
        try {
          const resp = await fetch(refreshUrl, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              Authorization: `Bearer ${refreshToken}`,
              'App-Name': 'chatglm',
              'X-App-Platform': 'pc',
              'X-App-Version': '0.0.1',
              'X-Device-Id': getOrCreateDeviceId(),
              'X-Request-Id': crypto.randomUUID(),
              'X-Sign': sign,
              'X-Nonce': nonce,
              'X-Timestamp': timestamp,
            },
            body: JSON.stringify({}),
            credentials: 'include',
          });
          if (!resp.ok) return null;
          const data = (await resp.json()) as Record<string, unknown>;
          const result = data?.result as Record<string, unknown> | undefined;
          return (
            (result?.access_token as string | undefined) ??
            (result?.accessToken as string | undefined) ??
            (data?.accessToken as string | undefined) ??
            null
          );
        } catch { return null; }
      };

      // 鈹€鈹€ Main logic 鈹€鈹€
      // (requestId, init, origin come from the runGlmBody parameters
      //  declared above.)
      if (!origin.includes('chatglm.cn')) {
        postToBridge(
          { type: 'WEB_LLM_ERROR', requestId, error: `GLM adapter requires chatglm.cn origin, got ${origin}` },
          origin,
        );
        return;
      }

      let glmPrompt = '';
      let existingChatId = '';
      let assistantId = '65940acff94777010aa6b796'; // 鈶?4: fallback to GLM-4.6
      try {
        const bodyObj = JSON.parse(typeof init.body === 'string' ? init.body : '{}') as Record<string, string>;
        glmPrompt = bodyObj.prompt ?? '';
        existingChatId = bodyObj.chatId ?? '';
        // 鈶?4: assistantId is now resolved from preset.models by the SW
        // and passed through the request body. Falls back to GLM-4.6.
        if (bodyObj.assistantId) assistantId = bodyObj.assistantId;
      } catch { /* defaults */ }

      let authToken = readCookie('chatglm_token');
      const refreshToken = readCookie('chatglm_refresh_token');

      if (!authToken && refreshToken) {
        const refreshed = await refreshGlmToken(`${origin}${GLM_REFRESH_URL_SUFFIX}`, refreshToken);
        if (refreshed) authToken = refreshed;
      }

      if (!authToken) {
        postToBridge(
          {
            type: 'WEB_LLM_ERROR',
            requestId,
            error: `No chatglm_token (and refresh failed) for GLM. Please visit chatglm.cn to log in, then reconnect via Settings 鈫?Web Providers.`,
          },
          origin,
        );
        return;
      }

      const deviceId = getOrCreateDeviceId();
      const { timestamp, nonce, sign } = generateGlmSign();
      const glmHeaders: Record<string, string> = {
        'Content-Type': 'application/json',
        Accept: 'text/event-stream',
        Authorization: `Bearer ${authToken}`,
        'App-Name': 'chatglm',
        'X-App-Platform': 'pc',
        'X-App-Version': '0.0.1',
        'X-App-fr': 'default',
        'X-Device-Brand': '',
        'X-Device-Id': deviceId,
        'X-Device-Model': '',
        'X-Lang': 'zh',
        'X-Request-Id': crypto.randomUUID(),
        'X-Sign': sign,
        'X-Nonce': nonce,
        'X-Timestamp': timestamp,
      };

      const glmBody = JSON.stringify({
        assistant_id: assistantId,
        conversation_id: existingChatId,
        project_id: '',
        chat_type: 'user_chat',
        meta_data: {
          cogview: { rm_label_watermark: false },
          is_test: false,
          input_question_type: 'xxxx',
          channel: '',
          draft_id: '',
          chat_mode: '',
          is_networking: false,
          quote_log_id: '',
          platform: 'pc',
        },
        messages: [{ role: 'user', content: [{ type: 'text', text: glmPrompt }] }],
      });

      // 鈶?DIAG: log the full request so we can see exactly what's sent
      console.log('[GLM-DIAG] request body:', glmBody);
      console.log('[GLM-DIAG] assistantId:', assistantId);
      console.log('[GLM-DIAG] modelId from request:', request.modelId);

      const glmResponse = await fetch(`${origin}${GLM_STREAM_URL_SUFFIX}`, {
        method: 'POST',
        headers: glmHeaders,
        body: glmBody,
        credentials: 'include',
      });

      // 鈶?DIAG: log response status immediately
      console.log('[GLM-DIAG] response status:', glmResponse.status, glmResponse.statusText);

      if (!glmResponse.ok) {
        let errorBody = '';
        try {
          errorBody = await glmResponse.text();
          if (errorBody.length > 500) errorBody = errorBody.slice(0, 500);
        } catch { /* ignore */ }
        console.error('[GLM-DIAG] HTTP error body:', errorBody);
        const authHint = glmResponse.status === 401 || glmResponse.status === 403
          ? ' Please visit chatglm.cn to verify your account.' : '';
        postToBridge(
          {
            type: 'WEB_LLM_ERROR',
            requestId,
            error: `GLM HTTP ${glmResponse.status}: ${glmResponse.statusText}${errorBody ? ` 鈥?${errorBody}` : ''}${authHint}`,
          },
          origin,
        );
        return;
      }

      const reader = glmResponse.body?.getReader();
      if (!reader) {
        postToBridge({ type: 'WEB_LLM_ERROR', requestId, error: 'No response body from GLM' }, origin);
        return;
      }

      if (existingChatId) {
        // 鈶?2: tell the SW to persist this session id so a follow-up
        // turn (or a future session) can re-use it. The SW listener calls
        // setConversation() and any Dexie failure is just a console.warn.
        // 鈶? don't leak the raw `data: {glm:chat_id}` envelope to the
        // sidepanel 鈥?that was a UX bug fixed in the same commit family.
        postToBridge(
          {
            type: 'WEB_LLM_CONVERSATION_UPDATE',
            requestId,
            modelId: request.modelId,
            conversationId: existingChatId,
          },
          origin,
        );
      }

      let buffer = '';
      let prevText = '';
      let prevThink = '';
      let prevLogicId = '';
      // 鈶? locally track whether the stream produced any text so the
      // empty-response guard at the end of the function has a real
      // variable to read. The chunks themselves are sent straight to
      // the bridge; this is just a "did we get anything" flag.
      let accumulatedText = '';
      // 鈶?2: GLM's first response carries the new conversation_id at the
      // top level of the JSON. Capture it once and tell the SW to persist
      // it so the next turn can echo it back as conversation_id.
      let seenConversationId: string | null = existingChatId || null;
      const decoder = new TextDecoder();
      const flushSse = (): string | null => {
        const idx = buffer.indexOf('\n\n');
        if (idx < 0) return null;
        const block = buffer.slice(0, idx);
        buffer = buffer.slice(idx + 2);
        const dataLines: string[] = [];
        for (const line of block.split('\n')) {
          if (line.startsWith('data:')) dataLines.push(line.slice(5).trimStart());
        }
        if (dataLines.length === 0) return '';
        const data = dataLines.join('\n');
        if (data === '[DONE]') return '__DONE__';
        let parsed: Record<string, unknown>;
        try { parsed = JSON.parse(data) as Record<string, unknown>; } catch { return ''; }
        // 鈶?2: surface the new conversation_id the first time we see it
        if (!seenConversationId && typeof parsed.conversation_id === 'string' && parsed.conversation_id.length > 0) {
          seenConversationId = parsed.conversation_id;
          postToBridge(
            {
              type: 'WEB_LLM_CONVERSATION_UPDATE',
              requestId,
              modelId: request.modelId,
              conversationId: seenConversationId,
            },
            origin,
          );
        }
        if (parsed.error) {
          const err = parsed.error as Record<string, unknown>;
          throw new Error((err.message as string | undefined) ?? 'GLM error');
        }
        // 鈶? GLM-5.1 may return error payloads that don't use the `error`
        // key 鈥?e.g. `{status:'error', message:'...'}`. Treat any object
        // without `parts` (and not `[DONE]`) as a potential error so the
        // user sees a message instead of an empty retry icon.
        const parts = parsed.parts as Array<{
          logic_id?: string;
          content?: Array<{ type?: string; text?: string; think?: string }>;
        }> | undefined;
        if (!parts || parts.length === 0) {
          const altErr =
            (parsed.message as string | undefined) ??
            (parsed.detail as string | undefined) ??
            (parsed.msg as string | undefined);
          if (altErr) throw new Error(altErr);
          return '';
        }
        const logicId = parts[0]?.logic_id;
        if (logicId && logicId !== prevLogicId) {
          prevLogicId = logicId; prevText = ''; prevThink = '';
        }
        const content = parts[0]?.content?.[0];
        if (!content) return '';
        if (content.type === 'think' && typeof content.think === 'string') {
          const fullThink = content.think;
          if (fullThink.length <= prevThink.length) return '';
          const delta = fullThink.slice(prevThink.length);
          prevThink = fullThink;
          return `<think>${delta}</think>`;
        }
        if (content.type === 'text' && typeof content.text === 'string') {
          const fullText = content.text;
          if (fullText.length <= prevText.length) return '';
          const delta = fullText.slice(prevText.length);
          prevText = fullText;
          return delta;
        }
        return '';
      };

      try {
        while (true) {
          // 鈶? check the abort flag at the top of each polling iteration.
          // The SW posts `{type:'abort'}` on the port when the user clicks
          // Stop; the ISOLATED bridge forwards it as a CustomEvent with
          // `{type:'WEB_LLM_ABORT'}`; our listener sets the flag. Break
          // early so no residual text is pushed after cancel.
          if ((window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag) {
            postToBridge({ type: 'WEB_LLM_DONE', requestId }, origin);
            return;
          }
          const { done, value } = await reader.read();
          if (done) break;
          // 鈶? re-check the abort flag after `reader.read()` returns.
          // The read above can block for a long time (waiting for the
          // next SSE event). If the user clicks Stop while we're blocked
          // here, the flag is set but we wouldn't notice it until the
          // NEXT iteration's top-of-loop check 鈥?by which time we'd have
          // already processed the chunk that just arrived and pushed a
          // residual WEB_LLM_CHUNK. Checking here ensures we drop any
          // chunk that arrives after the abort signal.
          if ((window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag) {
            postToBridge({ type: 'WEB_LLM_DONE', requestId }, origin);
            return;
          }
          buffer += decoder.decode(value, { stream: true });
          let guard = 0;
          while (guard++ < 100) {
            try {
              const out = flushSse();
              if (out === null) break;
              if (out === '__DONE__') {
                postToBridge({ type: 'WEB_LLM_DONE', requestId }, origin);
                return;
              }
              if (out) {
                accumulatedText += out;
                postToBridge(
                  { type: 'WEB_LLM_CHUNK', requestId, chunk: out },
                  origin,
                );
              }
            } catch (err) {
              postToBridge(
                {
                  type: 'WEB_LLM_ERROR',
                  requestId,
                  error: `GLM SSE parse: ${err instanceof Error ? err.message : String(err)}`,
                },
                origin,
              );
              return;
            }
          }
        }
        const tail = decoder.decode();
        if (tail) buffer += tail;
        let guard = 0;
        while (guard++ < 10) {
          const out = flushSse();
          if (out === null) break;
          if (out === '__DONE__') {
            postToBridge({ type: 'WEB_LLM_DONE', requestId }, origin);
            return;
          }
          if (out) {
            accumulatedText += out;
            postToBridge(
              { type: 'WEB_LLM_CHUNK', requestId, chunk: out },
              origin,
            );
          }
        }
        // 鈶? if the entire stream produced zero text, surface it as an
        // error so the user sees a message instead of an empty retry icon.
        if (!accumulatedText) {
          postToBridge(
            {
              type: 'WEB_LLM_ERROR',
              requestId,
              error: `GLM returned empty response (modelId=${request.modelId}, assistantId=${assistantId}). The server accepted the request but produced no content.`,
            },
            origin,
          );
          return;
        }
        postToBridge({ type: 'WEB_LLM_DONE', requestId }, origin);
      } catch (err) {
        postToBridge(
          {
            type: 'WEB_LLM_ERROR',
            requestId,
            error: `GLM stream: ${err instanceof Error ? err.message : String(err)}`,
          },
          origin,
        );
      }

  })();
  const timeout = new Promise<never>((_, reject) => {
    timeoutHandle = setTimeout(
      () =>
        reject(
          new Error(
            `GLM adapter timed out after ${Math.round(
              ADAPTER_TIMEOUT_MS / 1000,
            )}s. The streaming endpoint may be unreachable.`,
          ),
        ),
      ADAPTER_TIMEOUT_MS,
    );
  });

  try {
    await Promise.race([work, timeout]);
  } catch (err) {
    postToBridge(
      {
        type: 'WEB_LLM_ERROR',
        requestId,
        error: err instanceof Error ? err.message : String(err),
      },
      origin,
    );
    postToBridge({ type: 'WEB_LLM_DONE', requestId }, origin);
  } finally {
    if (timeoutHandle !== null) clearTimeout(timeoutHandle);
    // 鈶? clean up the abort listener to avoid leaks on tab reuse.
    document.removeEventListener('ceb-web-provider-message', abortListener);
  }
};

/**
 * 鈶? Self-contained MAIN-world content script.
 *
 * Runs inside the provider's chat page. Responsibilities:
 *   1. Inject the user's message into the input element (via InputStrategy)
 *   2. Trigger send (Enter key, Ctrl+Enter, or click)
 *   3. Poll the DOM for the AI's reply (via ReaderStrategy)
 *   4. Report text chunks back to the SW via window.postMessage 鈫?ISOLATED bridge
 *
 * Self-contained because chrome.scripting.executeScript stringifies the function
 * 鈥?no imports are available in the page context.
 *
 * Strategy functions are inlined (vs imported) so the script is one blob.
 * Keep them in sync with lib/ai-config/web-provider-dom-strategy.ts.
 *
 * Stringified and passed to chrome.scripting.executeScript; do not break the
 * "must be self-contained" rule.
 */

import type { WebProviderDomStrategy } from './web-provider-dom-strategy';

export interface DomRelayRequest {
  providerId: string;
  modelId: string;
  /** The user's message text (concat of all content parts) */
  message: string;
  /** The provider's DOM strategy (input + reader) */
  domStrategy: WebProviderDomStrategy;
}

/**
 * MAIN-world orchestrator. Stringified and injected via chrome.scripting.
 * MUST be self-contained 鈥?no closure references, no imports.
 */
export async function runDomRelayMainWorld(request: DomRelayRequest): Promise<void> {
  const postToBridge = (payload: unknown) => {
    window.postMessage({
      source: 'ceb-web-provider-main',
      providerId: request.providerId,
      payload,
    }, '*');
  };

  // Keep helper logic INSIDE this function. chrome.scripting.executeScript
  // serializes only `runDomRelayMainWorld` itself; module-scope helpers are
  // not available in MAIN world.
  const setInput = (root: ParentNode, strategy: WebProviderDomStrategy['input'], message: string): { ok: boolean; error?: string; element?: HTMLElement } => {
    const el = root.querySelector(strategy.selector) as HTMLElement | null;
    if (!el) return { ok: false, error: `Input not found: ${strategy.selector}` };
    if (strategy.scrollIntoView !== false && typeof el.scrollIntoView === 'function') {
      el.scrollIntoView({ block: 'center' });
    }
    el.focus();

    if (strategy.setMethod === 'textarea-setter') {
      const proto = el.tagName === 'TEXTAREA'
        ? window.HTMLTextAreaElement.prototype
        : window.HTMLInputElement.prototype;
      const desc = Object.getOwnPropertyDescriptor(proto, 'value');
      if (!desc?.set) return { ok: false, error: 'No value setter' };
      // Clear first, then write the new value. Two writes ensure React's value
      // tracker observes a "change" rather than a no-op equal-value set.
      desc.set.call(el, '');
      el.dispatchEvent(new Event('input', { bubbles: true }));
      desc.set.call(el, message);
      el.dispatchEvent(new Event('input', { bubbles: true }));
      // React controlled inputs commit on blur/change; dispatch a change so
      // onChange handlers run before the synthetic Enter.
      el.dispatchEvent(new Event('change', { bubbles: true }));
    } else if (strategy.setMethod === 'contenteditable-setter') {
      const desc = Object.getOwnPropertyDescriptor(window.HTMLElement.prototype, 'innerText');
      if (desc?.set) {
        desc.set.call(el, '');
        el.dispatchEvent(new InputEvent('beforeinput', { bubbles: true, inputType: 'deleteContentBackward' }));
        el.dispatchEvent(new Event('input', { bubbles: true }));
        desc.set.call(el, message);
      } else {
        el.textContent = message;
      }
      // Lexical / ProseMirror listen to beforeinput (inputType=insertText)
      // and input. Dispatch both so the editor commits the change.
      el.dispatchEvent(new InputEvent('beforeinput', { bubbles: true, inputType: 'insertText', data: message }));
      el.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: message }));
    } else if (strategy.setMethod === 'execCommand') {
      if (typeof document.execCommand !== 'function') {
        return { ok: false, error: 'document.execCommand is not available' };
      }
      if (!document.execCommand('insertText', false, message)) {
        return { ok: false, error: 'execCommand insertText returned false' };
      }
    } else {
      return { ok: false, error: `Unknown setMethod: ${(strategy as any).setMethod}` };
    }
    return { ok: true, element: el };
  };

  const sendInput = (root: ParentNode, strategy: WebProviderDomStrategy['input'], activeElement: Element | null): { ok: boolean; error?: string; method?: string } => {
    // Try click-send-button FIRST if configured. Real buttons are the most
    // reliable trigger across providers (Lexical/React controlled textareas
    // often ignore synthetic KeyboardEvents that don't bubble through document).
    if (strategy.sendMethod === 'click-send-button' || strategy.sendButtonSelector) {
      const sel = strategy.sendButtonSelector;
      if (!sel) return { ok: false, error: 'sendMethod=click-send-button requires sendButtonSelector' };
      const btn = root.querySelector(sel) as HTMLElement | null;
      if (!btn) return { ok: false, error: `Send button not found: ${sel}` };
      btn.click();
      return { ok: true, method: 'click-send-button' };
    }

    if (strategy.sendMethod === 'enter' || strategy.sendMethod === 'ctrl-enter') {
      if (!activeElement) return { ok: false, error: 'No active element' };
      const ctrlKey = strategy.sendMethod === 'ctrl-enter';
      const init: KeyboardEventInit = {
        key: 'Enter', code: 'Enter', keyCode: 13, which: 13,
        bubbles: true, cancelable: true, ctrlKey,
      };
      // 1) Dispatch on the element first (provider handlers usually bind here).
      activeElement.dispatchEvent(new KeyboardEvent('keydown', init));
      activeElement.dispatchEvent(new KeyboardEvent('keypress', init));
      activeElement.dispatchEvent(new KeyboardEvent('keyup', init));
      // 2) Also bubble through document so React/Lexical delegated listeners
      //    (which often sit on the document) can react to the Enter.
      root.dispatchEvent(new KeyboardEvent('keydown', init));
      root.dispatchEvent(new KeyboardEvent('keypress', init));
      root.dispatchEvent(new KeyboardEvent('keyup', init));
      return { ok: true, method: 'enter-bubbled' };
    }
    return { ok: false, error: `Unknown sendMethod: ${(strategy as any).sendMethod}` };
  };

  /**
   * Best-effort real-button click fallback.
   * The reasoning behind this is empirical: after the standard "set + Enter"
   * sequence, real providers (DeepSeek/GLM) often still ignore the synthetic
   * keyboard event because the React reconciler only listens to the actual
   * send button's onClick. We probe a small set of likely selectors and click
   * the first matching one we find. This is preferred over a configured
   * sendButtonSelector because each provider's button is currently unmodeled.
   */
  const tryRealSendButtonClick = (): { clicked: boolean; selector?: string } => {
    // 1) Constrain candidates to the input's parent container (avoid
    //    clicking unrelated toolbar buttons). 2) Prefer empirically verified
    //    selectors (DeepSeek ds-button, Kimi send-button-container). 3)
    //    Respect the "disabled / aria-disabled" state so we don't click a
    //    stale "stop" button mid-stream.
    const inputEl = document.querySelector(request.domStrategy.input.selector) as HTMLElement | null;
    const root: ParentNode = inputEl?.closest('form, [class*="chat"], [class*="input"], [class*="editor"]') || document;

    const isEnabled = (el: HTMLElement) =>
      !el.hasAttribute('disabled') &&
      el.getAttribute('aria-disabled') !== 'true' &&
      !/\bdisabled\b/.test(el.className || '');

    const candidates: string[] = [
      // DeepSeek: <div role="button" class="ds-button"> - the XL variant is the send button
      'div.ds-button[role="button"].ds-button--xl:not(.disabled)',
      'div[role="button"].ds-button.ds-button--primary:not(.disabled)',
      // Kimi: <div class="send-button-container"> (becomes enabled when text is set)
      '.send-button-container:not(.disabled)',
      // Generic fallbacks
      'button[aria-label*="Send"]',
      'div[role="button"][class*="send"]',
    ];

    for (const sel of candidates) {
      const el = root.querySelector(sel) as HTMLElement | null;
      if (el && isEnabled(el)) {
        el.click();
        return { clicked: true, selector: sel };
      }
    }
    return { clicked: false };
  };

  /**
   * Returns a promise that resolves when the assistant is clearly streaming
   * (stop button or thinking indicator present, or new markdown element added).
   * Used to decide whether the send attempt was actually accepted.
   */
  const waitForStreamingEvidence = (timeoutMs: number): Promise<boolean> => new Promise((resolve) => {
    const start = Date.now();
    const initialCount = document.querySelectorAll('[class*="markdown"]').length;
    const indicatorSelector = request.domStrategy.reader.thinkingIndicatorSelector;
    const tick = () => {
      const stop = !!document.querySelector('button[class*="stop"], [data-testid="stop-generating"]');
      const mdCount = document.querySelectorAll('[class*="markdown"]').length;
      const indicator = indicatorSelector ? !!document.querySelector(indicatorSelector) : false;
      if (stop || indicator || mdCount > initialCount) {
        resolve(true);
        return;
      }
      if (Date.now() - start > timeoutMs) {
        resolve(false);
        return;
      }
      setTimeout(tick, 80);
    };
    tick();
  });

  const readAssistantText = (el: HTMLElement | null): string => {
    if (!el) return '';
    return request.domStrategy.reader.textMode === 'textContent'
      ? (el.textContent ?? '')
      : (el.innerText ?? el.textContent ?? '');
  };

  const normalizeForComparison = (text: string): string =>
    text.replace(/\s+/g, ' ').trim();

  // 鈶? Port-based abort channel. The SW opens a port named
  // `abort-${requestId}` and posts `{type:'abort'}` when the user clicks
  // Stop. The ISOLATED bridge forwards this as a `ceb-web-provider-message`
  // CustomEvent with `{type:'WEB_LLM_ABORT'}`. We listen for it here and
  // set `window.__webProviderAbortFlag = true` so the DOM polling loop
  // below can break early instead of continuing to push chunks after the
  // user cancelled. Without this, the SW-side stream is cancelled but
  // the MAIN-world IIFE keeps polling the DOM and eventually pushes
  // WEB_LLM_DONE with full accumulated text 鈥?leaving residual text in
  // the assistant message bubble.
  // MVP assumption: one active web-provider session per tab at a time.
  // If concurrent sessions are ever supported, this flag must be keyed
  // by session/request id instead of being a singleton.
  (window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag = false;
  const abortListener = (event: Event) => {
    const data = (event as CustomEvent<Record<string, unknown>>).detail;
    if (data && data.type === 'WEB_LLM_ABORT') {
      (window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag = true;
    }
  };
  document.addEventListener('ceb-web-provider-message', abortListener);

  try {
    // 0. 鈶? pre-flight "needs relogin" check.
    //    The most reliable signal that the user's session expired is that the
    //    chat input element is no longer present 鈥?the provider redirected to
    //    a login wall or the page is showing an error. Emit a relogin signal
    //    (not a generic error) so the sidepanel can prompt the user.
    if (!document.querySelector(request.domStrategy.input.selector)) {
      postToBridge({
        type: 'WEB_LLM_NEEDS_RELOGIN',
        providerId: request.providerId,
        status: 401,
        message: `Provider ${request.providerId} is no longer logged in (chat input not found on ${location.href}). Please re-login via Settings 鈫?Web Providers.`,
      });
      return;
    }

    // Snapshot the pre-send assistant text as this turn's baseline.
    // If polling keeps seeing exactly this text, it's stale history from the
    // previous turn and must be ignored.
    const baselineElBeforeSend = document.querySelector(request.domStrategy.reader.assistantMessageSelector) as HTMLElement | null;
    const baselineText = readAssistantText(baselineElBeforeSend);
    const baselineComparable = normalizeForComparison(baselineText);

    // 1. Set the message
    const setResult = setInput(document, request.domStrategy.input, request.message);
    if (!setResult.ok) {
      // 鈶? "set failed" usually means the input element disappeared between
      // our pre-flight check and the set call. Treat as needs-relogin too 鈥擻n      // the page likely redirected to a login wall mid-call.
      const isInputMissing = !document.querySelector(request.domStrategy.input.selector);
      if (isInputMissing) {
        postToBridge({
          type: 'WEB_LLM_NEEDS_RELOGIN',
          providerId: request.providerId,
          status: 401,
          message: `Provider ${request.providerId} is no longer logged in (chat input disappeared mid-call). Please re-login via Settings 鈫?Web Providers.`,
        });
        return;
      }
      postToBridge({ type: 'WEB_LLM_ERROR', providerId: request.providerId, error: 'set: ' + setResult.error });
      return;
    }

    // 2. Wait for the input to settle (some apps debounce)
    const settleMs = request.domStrategy.input.settleDelayMs ?? 100;
    await new Promise((r) => setTimeout(r, settleMs));

    // 3. Trigger send. Real-world evidence: dispatching Enter to a React/Lexical
    //    controlled input alone is unreliable, so we send the key first then
    //    poll briefly to see if streaming actually started; if not, try once
    //    more with a fresh focus + input event.
    const sendTarget = setResult.element ?? document.activeElement;
    const firstSend = sendInput(document, request.domStrategy.input, sendTarget);
    if (!firstSend.ok) {
      postToBridge({ type: 'WEB_LLM_ERROR', providerId: request.providerId, error: 'send: ' + firstSend.error });
      return;
    }

    // Brief poll to detect streaming. If nothing happened, fall back to the
    // real on-page send button. This mirrors the chromeclaw pattern of waiting
    // for the first streaming signal before reporting "sent", and is the
    // empirically reliable path against React/Lexical controlled inputs.
    let streamingStarted = await waitForStreamingEvidence(1500);
    if (!streamingStarted) {
      const clicked = tryRealSendButtonClick();
      if (clicked.clicked) {
        streamingStarted = await waitForStreamingEvidence(1500);
      }
    }

    // 4. Poll the DOM for the AI's reply
    const pollMs = request.domStrategy.reader.pollIntervalMs ?? 100;
    const stableMs = request.domStrategy.reader.stableThresholdMs ?? 800;
    const maxMs = request.domStrategy.reader.maxTotalMs ?? 60_000;
    const startedAt = Date.now();

    let lastText = '';
    let lastChangedAt = Date.now();
    let stableReported = false;
    let hasTurnOutput = false;

    // Helper: check if still streaming (thinking indicator visible)
    const isStillStreaming = (): boolean => {
      if (!request.domStrategy.reader.thinkingIndicatorSelector) return false;
      return !!document.querySelector(request.domStrategy.reader.thinkingIndicatorSelector);
    };

    // 2026-06-07: early-out for known non-chat pages. If the tab is on
    // chatglm.cn but not on a chat surface (e.g. /main/alltoolsdetail
    // tool description, /tools, /model-detail), the DOM reader will
    // never find the right .markdown-body and will burn the full
    // 60s maxTotalMs. Detect this once at reader start and surface an
    // actionable WEB_LLM_ERROR with the current URL. We only check
    // /alltoolsdetail explicitly because that's the page the root
    // loginUrl redirects to; other non-chat paths are rare for the
    // GLM web provider flow and fall through to the normal timeout
    // path.
    if (/\/alltoolsdetail(\?|$|\/)/.test(location.pathname + location.search + location.hash)) {
      postToBridge({
        type: 'WEB_LLM_ERROR',
        providerId: request.providerId,
        error: `GLM is on a tool description page (${location.pathname}), not the chat interface. Please open https://chatglm.cn/main/chat/new in this tab and retry.`,
      });
      return;
    }

    // eslint-disable-next-line no-constant-condition
    while (true) {
      // 鈶? check the abort flag at the top of each polling iteration.
      // The SW posts `{type:'abort'}` on the port when the user clicks
      // Stop; the ISOLATED bridge forwards it as a CustomEvent with
      // `{type:'WEB_LLM_ABORT'}`; our listener sets the flag. Break
      // early so no residual text is pushed after cancel.
      if ((window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag) {
        postToBridge({ type: 'WEB_LLM_DONE', providerId: request.providerId });
        return;
      }
      if (Date.now() - startedAt > maxMs) {
        postToBridge({ type: 'WEB_LLM_ERROR', providerId: request.providerId, error: `Reader timeout after ${maxMs}ms` });
        return;
      }
      await new Promise((r) => setTimeout(r, pollMs));
      // 鈶? re-check the abort flag after the poll delay. The setTimeout
      // above can block for pollMs; if the user clicked Stop while we
      // were waiting, the flag is set but we wouldn't notice it until
      // the NEXT iteration's top-of-loop check 鈥?by which time we'd
      // have already read the DOM and pushed a residual WEB_LLM_CHUNK.
      if ((window as unknown as { __webProviderAbortFlag?: boolean }).__webProviderAbortFlag) {
        postToBridge({ type: 'WEB_LLM_DONE', providerId: request.providerId });
        return;
      }

      const el = document.querySelector(request.domStrategy.reader.assistantMessageSelector) as HTMLElement | null;
      if (!el) continue;  // No message yet, keep polling

      const text = readAssistantText(el);

      // Ignore unchanged baseline from previous turns.
      const isSameBaselineElement = !!baselineElBeforeSend && el === baselineElBeforeSend;
      if (!hasTurnOutput && isSameBaselineElement && normalizeForComparison(text) === baselineComparable) {
        continue;
      }

      if (!hasTurnOutput) {
        hasTurnOutput = true;
      }

      if (text !== lastText) {
        lastText = text;
        lastChangedAt = Date.now();
        postToBridge({ type: 'WEB_LLM_CHUNK', providerId: request.providerId, text });
      }

      // Done conditions:
      //   1. Text is stable for stableThresholdMs AND no thinking indicator
      //   2. (or) text is stable for stableThresholdMs (most apps)
      const stable = Date.now() - lastChangedAt >= stableMs;
      const thinking = isStillStreaming();
      if (stable && !thinking && text.length > 0 && hasTurnOutput && !stableReported) {
        stableReported = true;
        postToBridge({ type: 'WEB_LLM_DONE', providerId: request.providerId });
        return;
      }
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    postToBridge({ type: 'WEB_LLM_ERROR', providerId: request.providerId, error: msg });
  } finally {
    // 鈶? clean up the abort listener to avoid leaks on tab reuse.
    document.removeEventListener('ceb-web-provider-message', abortListener);
  }
}

/**
 * ISOLATED-world bridge. Forwards window.postMessage from MAIN to SW.
 * Stringified and injected; must be self-contained.
 */
export function installIsolatedBridge(providerId: string, debug: boolean = false): void {
  // 鈶?FIX: extension reload survival. When the SW is reloaded (user
  // clicks "Reload" in chrome://extensions, or the extension is
  // updated), the old content script's listener still has a live
  // reference to the (now-defunct) old SW via chrome.runtime. A new
  // injection of this function sees the existing `__cebWebProviderBridge`
  // guard and exits early 鈥?but the OLD listener is the one that's
  // actually attached to the document, holding the dead SW ref.
  // Every event it tries to forward throws "Extension context
  // invalidated", while the new content script's listener never gets
  // a chance to run.
  //
  // Fix: store the listener function on the window so a fresh
  // injection can removeEventListener on the old one before adding
  // the new one. The providerId guard still prevents duplicate
  // listeners within a single page (no extra cost on the happy
  // path 鈥?same providerId, same listener ref).
  const w = window as unknown as {
    __cebWebProviderBridge?: {
      providerId: string;
      listener?: EventListener;
      connectListener?: (port: { name: string; onMessage: { addListener: (fn: (msg: unknown) => void) => void } }) => void;
    };
  };
  const existing = w.__cebWebProviderBridge;
  if (existing?.providerId === providerId && existing.listener) {
    // Same provider, same listener ref: nothing to do.
    return;
  }
  if (existing?.listener) {
    // Stale (different SW generation, different provider, or first
    // call after reload): clean up before installing the new one.
    document.removeEventListener('ceb-web-provider-message', existing.listener);
  }

  // 鈶?FIX: cross-world messaging. window.postMessage doesn't cross the
  // MAIN鈫擨SOLATED world boundary (each world has its own `window`).
  // document.dispatchEvent(CustomEvent) IS shared because both worlds
  // share the same `document`. Adapters dispatch 'ceb-web-provider-message'
  // on document; the bridge listens here.
  const listener = ((event: Event) => {
    const data = (event as CustomEvent<Record<string, unknown>>).detail;
    if (!data || typeof data !== 'object') return;
    // 鈶?DIAG: log every event the bridge sees. We can't use the 鈶?4
    // diag gate here directly because this function is serialized by
    // `chrome.scripting.executeScript` and re-parsed in the ISOLATED
    // world 鈥?module-scope imports would be `undefined` in the target
    // context, throwing "X is not defined" on the first message. The
    // SW reads the flag and passes it as the `debug` arg, so the gate
    // is respected without a module reference.
    const log = (...args: unknown[]): void => {
      if (debug) console.log(...args);
    };
    log('[WS-DIAG-BRIDGE] received CustomEvent', {
      type: data.type,
      providerId: data.providerId,
      keys: Object.keys(data).slice(0, 8),
    });
    if (data.providerId !== providerId) {
      log('[WS-DIAG-BRIDGE] DROPPING (providerId mismatch)');
      return;
    }
    if (typeof data.type !== 'string' || !data.type.startsWith('WEB_LLM_')) {
      log('[WS-DIAG-BRIDGE] DROPPING (not WEB_LLM_ type)');
      return;
    }
    // Abort signals are bridge鈫扢AIN only; never forward back to SW.
    // The connectListener below dispatches WEB_LLM_ABORT on this same
    // CustomEvent channel to reach the MAIN-world IIFE; without this
    // guard the bridge's own listener would re-send it to the SW,
    // forming a feedback loop (SW 鈫?port 鈫?bridge 鈫?SW).
    if (data.type === 'WEB_LLM_ABORT') {
      log('[WS-DIAG-BRIDGE] DROPPING (abort is bridge鈫扢AIN only)');
      return;
    }
    log('[WS-DIAG-BRIDGE] forwarding to SW', data.type);
    chrome.runtime.sendMessage(data).catch((err) => {
      // sendMessage failures are real (no SW receiver, etc.) 鈥?surface
      // them even when diag is off so we don't lose this signal.
      console.warn('[WS-DIAG-BRIDGE] sendMessage failed:', err);
    });
  }) as EventListener;

  document.addEventListener('ceb-web-provider-message', listener);
  w.__cebWebProviderBridge = { providerId, listener };
  chrome.runtime.sendMessage({
    type: 'WEB_LLM_RELAY_READY',
    providerId,
  }).catch(() => { /* SW may not be ready; harmless */ });

  // 鈶? Port-based abort channel. The SW opens a port named
  // `abort-${requestId}` via `chrome.tabs.connect(tabId, {name: ...})`
  // and posts `{type:'abort'}` when the user clicks Stop. We listen
  // for the connection here (in the ISOLATED world) and forward the
  // abort signal to the MAIN world via a `ceb-web-provider-message`
  // CustomEvent with `{type:'WEB_LLM_ABORT'}`. The MAIN-world IIFE
  // has a listener that sets `window.__webProviderAbortFlag = true`,
  // causing its polling/SSE loop to break early.
  //
  // Guard against duplicate onConnect listeners (same reload-survival
  // concern as the message listener above): remove the old connect
  // listener (captured from `existing` BEFORE we overwrote
  // `w.__cebWebProviderBridge` above) before adding a new one.
  if (existing?.connectListener) {
    chrome.runtime.onConnect.removeListener(existing.connectListener);
  }
  const connectListener = (port: { name: string; onMessage: { addListener: (fn: (msg: unknown) => void) => void } }) => {
    // Only handle ports named `abort-*` (other ports are for unrelated
    // features like the agent port in background/index.ts).
    if (!port.name || !port.name.startsWith('abort-')) return;
    port.onMessage.addListener((msg: unknown) => {
      if (msg && typeof msg === 'object' && (msg as { type?: unknown }).type === 'abort') {
        // Forward to MAIN world via the shared document CustomEvent
        // channel. The MAIN-world IIFE listens for this and sets
        // `window.__webProviderAbortFlag = true`.
        document.dispatchEvent(new CustomEvent('ceb-web-provider-message', {
          detail: { type: 'WEB_LLM_ABORT', providerId },
        }));
      }
    });
  };
  chrome.runtime.onConnect.addListener(connectListener);
  (w.__cebWebProviderBridge as { connectListener?: typeof connectListener }).connectListener = connectListener;
}

import { getDb, type WebProviderConversationRecord } from '@/lib/db';

/**
 * Per-(provider, model) server-side conversation memory pointer.
 *
 * Some web chat providers use a stateful protocol where the client must
 * echo back a server-issued id on each new message to keep the server's
 * context (Kimi uses `conversation_id`, GLM uses `conversation_id`,
 * DeepSeek uses `parent_message_id`, etc.). This record stores whichever
 * field the provider actually returns.
 *
 * The actual wire format (which field name to send on the next request,
 * and which field name to extract from each response) is provider-specific
 * and gated on T1 DevTools research. Until then, this storage layer
 * provides the durable foundation; the relay hook that populates it can
 * be added per-provider once the protocol is known.
 */
export interface WebProviderConversationState {
  /** Provider presetId (e.g. 'kimi', 'glm', 'deepseek') */
  providerId: string;
  /** Model id within the provider (e.g. 'kimi-k2-0711-preview') */
  modelId: string;
  /** Provider's conversation/session/thread id (whichever applies) */
  conversationId?: string;
  /**
   * Some providers track the last message id separately from the
   * conversation id (e.g. DeepSeek's parent_message_id). Optional
   * because not all providers use it.
   */
  parentMessageId?: string;
  /** Last write timestamp (ms since epoch). Used for LRU eviction later. */
  lastUpdated: number;
}

const KEY_SEP = '::';

function makeKey(providerId: string, modelId: string): string {
  return `${providerId}${KEY_SEP}${modelId}`;
}

/**
 * Look up a saved conversation state. Returns null if not present.
 * The synthetic `id` field (Dexie primary key) is stripped from the
 * returned record so callers see only the user-facing state shape.
 */
export async function getConversation(
  providerId: string,
  modelId: string,
): Promise<WebProviderConversationState | null> {
  const key = makeKey(providerId, modelId);
  const got = await getDb().webProviderConversations.get(key);
  if (!got) return null;
  const { id: _id, ...state } = got as WebProviderConversationRecord;
  return state as WebProviderConversationState;
}

/**
 * Persist a conversation state. Upserts on (providerId, modelId).
 */
export async function setConversation(
  state: WebProviderConversationState,
): Promise<void> {
  const key = makeKey(state.providerId, state.modelId);
  await getDb().webProviderConversations.put({ ...state, id: key } as any);
}

/**
 * Remove a conversation state. Idempotent: no-op if not present.
 */
export async function clearConversation(
  providerId: string,
  modelId: string,
): Promise<void> {
  const key = makeKey(providerId, modelId);
  await getDb().webProviderConversations.delete(key);
}

/**
 * Background service for web provider cookie extraction & encrypted storage.
 *
 * Handles 2 message types from the React hook:
 *   - WEB_PROVIDER_LOGIN: open tab, poll for cookies, encrypt, persist
 *   - WEB_PROVIDER_RECHECK: verify stored credentials still decrypt
 *
 * Implements 6 production-grade enhancements (A1-A6):
 *   A3: Active tab tracking (background polling throttling)
 *   A4: Login attempt audit log (writes to Dexie on every attempt)
 *   A5: RefreshAuth retry with exponential backoff
 *   A6: Detect already-open tab (reuse instead of open)
 */

import { WEB_PROVIDER_PRESETS, resolveEffectiveConfig } from './web-provider-presets';
import { getWebProviderRepository } from './web-provider-store';
import { encryptCookieBundle, decryptCookieBundle } from './web-provider-crypto';
import type {
  WebProvider,
  LoginAuditEntry,
  LoginStatus,
} from '../types';

const POLL_INTERVAL_MS = 2_000;
const BACKGROUND_POLL_INTERVAL_MS = 5_000;
const LOGIN_TIMEOUT_MS = 5 * 60 * 1_000;
const MIN_WAIT_MS = 5_000;
const REFRESH_AUTH_MAX_ATTEMPTS = 3;
const REFRESH_AUTH_BACKOFFS = [1000, 2000, 4000] as const;

const COMMON_AUTH_COOKIES = ['lastActiveOrg', 'XSRF-TOKEN', 'csrf_token'] as const;

interface LoginResponse {
  success: boolean;
  status?: LoginStatus;
  error?: string;
  capturedCookieNames?: string[];
  capturedTokenSources?: Array<'cookie' | 'localStorage'>;
}

/**
 * Register the message listener. Idempotent: call once from background.ts.
 * The listener dispatches based on msg.type and returns true to keep the
 * message channel open (we use async sendResponse).
 */
export function registerCookieService(): void {
  chrome.runtime.onMessage.addListener((msg: unknown, _sender: chrome.runtime.MessageSender, sendResponse: (response?: unknown) => void) => {
    const m = msg as { type?: string; presetId?: string };
    if (m?.type === 'WEB_PROVIDER_LOGIN') {
      handleLogin(m.presetId!)
        .then(sendResponse)
        .catch(err => {
          sendResponse({ success: false, error: String(err), status: 'loggedOut' as LoginStatus });
        });
      return true;
    }
    if (m?.type === 'WEB_PROVIDER_RECHECK') {
      handleRecheck(m.presetId!)
        .then(sendResponse)
        .catch(err => {
          sendResponse({ success: false, error: String(err), status: 'loggedOut' as LoginStatus });
        });
      return true;
    }
    return false;
  });
}

// ====== Login Flow ======

async function handleLogin(presetId: string): Promise<LoginResponse> {
  const presetIdTyped = presetId as WebProvider['presetId'];
  const preset = WEB_PROVIDER_PRESETS.find(p => p.id === presetIdTyped);
  if (!preset) {
    return { success: false, error: 'Unknown preset', status: 'loggedOut' };
  }
  const repo = getWebProviderRepository();
  const provider = await repo.get(presetIdTyped);
  if (!provider) {
    return { success: false, error: 'Provider not found', status: 'loggedOut' };
  }
  const effective = resolveEffectiveConfig(provider, preset);

  // A6: open or focus existing tab
  const tabId = await openOrFocusLoginTab(effective.loginUrl);

  // A3: track focus state for throttling
  let isTabFocused = true;
  const onActivated = (activeInfo: { tabId: number; windowId: number }) => {
    isTabFocused = activeInfo.tabId === tabId;
  };
  const onFocusChanged = (windowId: number) => {
    if (windowId === chrome.windows.WINDOW_ID_NONE) {
      isTabFocused = false;
    } else {
      chrome.tabs.get(tabId).then(t => {
        chrome.windows.get(t.windowId, (w: chrome.windows.Window) => {
          isTabFocused = w.focused;
        });
      }).catch(() => { /* tab gone */ });
    }
  };
  chrome.tabs.onActivated.addListener(onActivated);
  chrome.windows.onFocusChanged.addListener(onFocusChanged);

  const startTime = Date.now();
  let lastError: string | null = null;

  try {
    const tokens = await pollForSession(
      tabId,
      effective,
      startTime,
      () => isTabFocused,
      (err) => { lastError = err; },
    );
    if (!tokens) {
      const errorStr: string = lastError ?? '';
      const result: 'timeout' | 'tab-closed' = errorStr.includes('closed') ? 'tab-closed' : 'timeout';
      await appendAudit(presetId, {
        timestamp: new Date().toISOString(),
        result,
        errorMessage: lastError ?? undefined,
      });
      // 2026-06-07: do NOT auto-close the tab on failure. The user
      // owns the tab lifecycle; auto-closing a tab the user is
      // actively using (e.g. they navigated to chatglm.cn themselves
      // and the SW focused their existing tab) is hostile UX.
      chrome.tabs.onActivated.removeListener(onActivated);
      chrome.windows.onFocusChanged.removeListener(onFocusChanged);
      return { success: false, error: lastError ?? 'Login failed', status: 'loggedOut' };
    }

    const captured: Record<string, string> = { ...tokens.cookies };

    // A5: refresh auth retry for GLM (only when refreshUrl is set)
    if (effective.refreshUrl) {
      const refreshToken = captured['chatglm_refresh_token'] || captured['refresh_token'];
      if (refreshToken && !captured['chatglm_token']) {
        const accessToken = await tryRefreshAuthWithRetry(
          effective.refreshUrl,
          refreshToken,
          tabId,
        );
        if (accessToken) {
          captured['chatglm_token'] = accessToken;
        } else {
          await appendAudit(presetId, {
            timestamp: new Date().toISOString(),
            result: 'refresh-failed',
            errorMessage: 'RefreshAuth failed after 3 attempts; stored refresh_token only',
          });
        }
      }
    }

    const ciphertext = await encryptCookieBundle(JSON.stringify(captured));
    await repo.setEncryptedCookieBundle(presetId as WebProvider['presetId'], ciphertext);
    await repo.setLoginStatus(presetId as WebProvider['presetId'], 'loggedIn');

    const cookiesCaptured = Object.keys(captured).length;
    const auditEntry: LoginAuditEntry = {
      timestamp: new Date().toISOString(),
      result: 'success',
      source: tokens.source,
      cookiesCaptured,
    };
    await appendAudit(presetId, auditEntry);

    chrome.tabs.onActivated.removeListener(onActivated);
    chrome.windows.onFocusChanged.removeListener(onFocusChanged);
    // 2026-06-07: do NOT auto-close the tab on success. Same reasoning
    // as the failure path 鈥?the user may be actively using the tab.

    return {
      success: true,
      status: 'loggedIn',
      capturedCookieNames: Object.keys(captured),
      capturedTokenSources: [tokens.source],
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    await appendAudit(presetId, {
      timestamp: new Date().toISOString(),
      result: 'no-cookies',
      errorMessage: message,
    });
    chrome.tabs.onActivated.removeListener(onActivated);
    chrome.windows.onFocusChanged.removeListener(onFocusChanged);
    // 2026-06-07: do NOT auto-close the tab on exception either.
    return { success: false, error: message, status: 'loggedOut' };
  }
}

// ====== Recheck Flow ======

async function handleRecheck(presetId: string): Promise<LoginResponse> {
  const presetIdTyped = presetId as WebProvider['presetId'];
  const repo = getWebProviderRepository();
  const provider = await repo.get(presetIdTyped);
  if (!provider?.encryptedCookieBundle) {
    return { success: false, error: 'No stored credentials', status: 'loggedOut' };
  }
  try {
    const plaintext = await decryptCookieBundle(provider.encryptedCookieBundle);
    JSON.parse(plaintext);  // validate it's still parseable JSON
    return { success: true, status: 'loggedIn' };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    await appendAudit(presetId, {
      timestamp: new Date().toISOString(),
      result: 'decryption-failed',
      errorMessage: message,
    });
    return { success: false, error: message, status: 'loggedOut' };
  }
}

// ====== A6: Open or Focus Existing Tab ======

async function openOrFocusLoginTab(loginUrl: string): Promise<number> {
  const url = new URL(loginUrl);
  const urlPattern = `*://${url.hostname}/*`;
  const existingTabs = await chrome.tabs.query({ url: urlPattern });
  if (existingTabs.length > 0) {
    const tab = existingTabs[0];
    await chrome.tabs.update(tab.id!, { active: true });
    if (tab.windowId) {
      await chrome.windows.update(tab.windowId, { focused: true });
    }
    return tab.id!;
  }
  const tab = await chrome.tabs.create({ url: loginUrl, active: true });
  return tab.id!;
}

// ====== A3: Polling with Focus-Aware Throttling ======

async function pollForSession(
  tabId: number,
  preset: ReturnType<typeof resolveEffectiveConfig>,
  startTime: number,
  isTabFocused: () => boolean,
  onError: (err: string) => void,
): Promise<{ cookies: Record<string, string>; source: 'cookie' | 'localStorage' } | null> {
  while (Date.now() - startTime < LOGIN_TIMEOUT_MS) {
    // Check tab still exists
    try {
      await chrome.tabs.get(tabId);
    } catch {
      // Last-chance probe: users may close the tab right after login succeeds.
      // For cookie-based providers (GLM/DeepSeek), we can still detect the
      // session directly from cookie jar even if the tab is gone.
      const cookieSession = await tryCaptureCookieSession(preset);
      if (cookieSession) return cookieSession;

      onError('Login tab was closed before session was detected');
      return null;
    }

    // MIN_WAIT before first check (chromeclaw pattern)
    if (Date.now() - startTime < MIN_WAIT_MS) {
      await sleep(500);
      continue;
    }

    try {
      const cookieSession = await tryCaptureCookieSession(preset);
      if (cookieSession) return cookieSession;

      if (preset.useLocalStorageFallback) {
        const lsTokens = await readLocalStorageFromTab(tabId, preset.sessionIndicators);
        if (Object.keys(lsTokens).length > 0) {
          return { cookies: lsTokens, source: 'localStorage' };
        }
      }
    } catch (err) {
      onError(`Poll error: ${err instanceof Error ? err.message : String(err)}`);
    }

    // A3: focus-aware interval
    const interval = isTabFocused() ? POLL_INTERVAL_MS : BACKGROUND_POLL_INTERVAL_MS;
    await sleep(interval);
  }
  onError(`Login timed out after ${LOGIN_TIMEOUT_MS / 1000}s`);
  return null;
}

async function tryCaptureCookieSession(
  preset: ReturnType<typeof resolveEffectiveConfig>,
): Promise<{ cookies: Record<string, string>; source: 'cookie' } | null> {
  // listCookiesForDomain returns a name鈫抳alue map directly.
  const cookieMap = await listCookiesForDomain(preset.cookieDomain);

  const matched = preset.sessionIndicators.filter((n: string) => cookieMap[n]);
  if (matched.length === 0) return null;

  const captured: Record<string, string> = {};
  for (const n of preset.sessionIndicators) {
    if (cookieMap[n]) captured[n] = cookieMap[n];
  }
  for (const n of COMMON_AUTH_COOKIES) {
    if (cookieMap[n]) captured[n] = cookieMap[n];
  }
  return { cookies: captured, source: 'cookie' };
}

// ====== localStorage Fallback (MAIN world) ======

async function readLocalStorageFromTab(
  tabId: number,
  keys: string[],
): Promise<Record<string, string>> {
  try {
    const results = await chrome.scripting.executeScript({
      target: { tabId },
      world: 'MAIN',  // CRITICAL: page's localStorage, not isolated
      func: (keysToRead: string[]) => {
        const out: Record<string, string> = {};
        for (const k of keysToRead) {
          const v = localStorage.getItem(k);
          if (v !== null) out[k] = v;
        }
        return out;
      },
      args: [keys],
    });
    return (results?.[0]?.result as Record<string, string>) ?? {};
  } catch (err) {
    console.warn('[web-provider] localStorage read failed:', err);
    return {};
  }
}

// ====== A5: RefreshAuth with Retry ======

async function tryRefreshAuthWithRetry(
  refreshUrl: string,
  refreshToken: string,
  tabId: number,
): Promise<string | null> {
  for (let attempt = 1; attempt <= REFRESH_AUTH_MAX_ATTEMPTS; attempt++) {
    const token = await tryRefreshAuth(refreshUrl, refreshToken, tabId);
    if (token) return token;
    if (attempt < REFRESH_AUTH_MAX_ATTEMPTS) {
      await sleep(REFRESH_AUTH_BACKOFFS[attempt - 1]);
    }
  }
  return null;
}

async function tryRefreshAuth(
  refreshUrl: string,
  refreshToken: string,
  tabId: number,
): Promise<string | null> {
  try {
    const results = await chrome.scripting.executeScript({
      target: { tabId },
      world: 'MAIN',
      func: async (url: string, token: string) => {
        try {
          const res = await fetch(url, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${token}`,
            },
            body: JSON.stringify({}),
            credentials: 'include',
          });
          if (!res.ok) return null;
          const data = await res.json();
          return (
            data?.result?.access_token ??
            data?.result?.accessToken ??
            data?.accessToken ??
            null
          );
        } catch {
          return null;
        }
      },
      args: [refreshUrl, refreshToken],
    });
    return (results?.[0]?.result as string | null) ?? null;
  } catch {
    return null;
  }
}

// ====== Helpers ======

async function appendAudit(presetId: string, entry: LoginAuditEntry): Promise<void> {
  try {
    await getWebProviderRepository().appendAuditEntry(presetId as WebProvider['presetId'], entry);
  } catch (err) {
    console.warn('[web-provider] failed to append audit entry:', err);
  }
}

async function safeRemoveTab(tabId: number): Promise<void> {
  try {
    await chrome.tabs.remove(tabId);
  } catch {
    /* tab may already be closed */
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise(r => setTimeout(r, ms));
}

// ====== List cookies for a domain (used by session-watcher) ======

/**
 * Read all cookies for a domain and return them as a name鈫抳alue map.
 * Used by the session watcher to periodically verify the user is
 * still logged in. Exported for the BG wiring layer.
 */
export async function listCookiesForDomain(domain: string): Promise<Record<string, string>> {
  const cookies = await chrome.cookies.getAll({ domain });
  const out: Record<string, string> = {};
  for (const c of cookies) out[c.name] = c.value;
  return out;
}

/**
 * 鈶?4: Diagnostic logging gate.
 *
 * All `[WS-DIAG*]` logs in the web provider code paths are routed
 * through this module. They are SILENT in production unless the
 * user has explicitly enabled debug logging via the chrome.storage
 * flag `web_provider_debug` (e.g. from the Settings 鈫?Web Providers
 * 鈫?"Enable debug logs" toggle in a future PR).
 *
 * Why a gate and not just a build-time `if (DEBUG)`?
 *   - chrome.storage.local is shared across all extension contexts
 *     (SW, ISOLATED content scripts, MAIN world via SW proxy).
 *   - Users (and we) can toggle it live without reloading the
 *     extension to debug a specific failure.
 *   - Production console stays clean 鈥?no spam in DevTools when
 *     running normally.
 *
 * Usage:
 *   import { diag, diagWarn, diagError } from './web-provider-diag';
 *   diag('WS-DIAG-LISTENER', 'received', msg);     // tag + payload
 *   diagWarn('WS-DIAG', 'injection failed', err); // warn level
 *
 * Tag conventions:
 *   - WS-DIAG          : SW orchestration steps (parse, preset, tab, inject)
 *   - WS-DIAG-BRIDGE   : ISOLATED bridge receive/forward
 *   - WS-DIAG-LISTENER : SW listener receive/drop
 *   - GLM-DIAG / DS-DIAG : per-adapter state transitions (not per-chunk)
 *
 * The helper is async because chrome.storage.local.get is async, but
 * the cache (`cached`) means the typical hot-path cost is a single
 * boolean read. `diag()` is fire-and-forget: callers don't need to
 * await it.
 */

const STORAGE_KEY = 'web_provider_debug';
const TRUE = true as const;
const FALSE = false as const;

// In-memory cache so the hot path doesn't re-read chrome.storage
// on every chunk (DS/GLM adapters emit dozens of chunks per second).
let cached: boolean | null = null;

// Subscribers that want live updates when the flag changes
// (e.g. a future Settings UI wants to reflect state).
type Listener = (enabled: boolean) => void;
const listeners = new Set<Listener>();

function getChrome(): typeof chrome | null {
  if (typeof chrome === 'undefined') return null;
  return chrome as unknown as typeof chrome;
}

/**
 * Read the current flag value, hitting chrome.storage on first call
 * (and after a clear). Returns false (production-safe default) if
 * chrome.storage is unavailable (e.g. test env without a mock).
 */
export async function isDiagEnabled(): Promise<boolean> {
  if (cached !== null) return cached;
  const c = getChrome();
  if (!c?.storage?.local) {
    cached = FALSE;
    return FALSE;
  }
  try {
    const got = await c.storage.local.get(STORAGE_KEY);
    cached = got?.[STORAGE_KEY] === TRUE;
  } catch {
    cached = FALSE;
  }
  return cached;
}

/**
 * Subscribe to live changes of the flag. Returns an unsubscribe fn.
 * The callback fires whenever chrome.storage.onChanged reports a
 * change to `web_provider_debug` (whether caused by this process
 * via `setDiagEnabled` or by a different context like the Settings UI).
 */
export function subscribeDiagEnabled(cb: Listener): () => void {
  listeners.add(cb);
  // Lazy-attach the chrome.storage.onChanged listener the first time
  // someone subscribes. Idempotent: re-attaching is a no-op because
  // `installed` is module-scope.
  installOnChangedOnce();
  return () => {
    listeners.delete(cb);
  };
}

let installed = false;
function installOnChangedOnce(): void {
  if (installed) return;
  const c = getChrome();
  if (!c?.storage?.onChanged) return;
  installed = true;
  c.storage.onChanged.addListener((changes, area) => {
    if (area !== 'local') return;
    const change = changes[STORAGE_KEY];
    if (!change) return;
    cached = change.newValue === TRUE;
    for (const l of listeners) {
      try {
        l(cached);
      } catch {
        /* a broken listener shouldn't break the others */
      }
    }
  });
}

/**
 * Set the flag programmatically. Useful for tests and for a future
 * Settings UI. Returns the resolved value (which is always what
 * was passed in, modulo coercion).
 */
export async function setDiagEnabled(value: boolean): Promise<void> {
  const c = getChrome();
  if (!c?.storage?.local) {
    cached = value;
    return;
  }
  await c.storage.local.set({ [STORAGE_KEY]: value });
  // The onChanged listener will update `cached` and notify
  // subscribers; we also set it eagerly so callers that read
  // `isDiagEnabled` immediately after don't see a stale value.
  cached = value;
  for (const l of listeners) {
    try {
      l(cached);
    } catch {
      /* see subscribeDiagEnabled */
    }
  }
}

/**
 * Hot-path diagnostic log. Fire-and-forget: the chrome.storage read
 * is short-circuited by the cache. The `tag` argument is wrapped in
 * `[...]` automatically 鈥?don't include brackets yourself.
 *
 * If the cache is cold (e.g. first call after module load before
 * `isDiagEnabled()` has resolved), we schedule a fire-and-forget
 * warm. The first call after a cold start is always silent 鈥?by the
 * time the next call comes, the cache is populated.
 */
export function diag(tag: string, msg: string, extra?: unknown): void {
  if (cached === null) {
    // Cold start: schedule a warm. Don't block the caller.
    void isDiagEnabled();
    return;
  }
  if (cached !== TRUE) return;
  if (extra === undefined) {
    console.log(`[${tag}] ${msg}`);
  } else {
    console.log(`[${tag}] ${msg}`, extra);
  }
}

/** Like `diag` but uses console.warn. For non-fatal issues that
 *  the user might want to know about (e.g. recoverable fetch errors). */
export function diagWarn(tag: string, msg: string, extra?: unknown): void {
  if (cached === null) {
    void isDiagEnabled();
    return;
  }
  if (cached !== TRUE) return;
  if (extra === undefined) {
    console.warn(`[${tag}] ${msg}`);
  } else {
    console.warn(`[${tag}] ${msg}`, extra);
  }
}

/** Like `diag` but uses console.error. Reserved for actual errors
 *  (failed executeScript, Dexie write rejected, etc.). */
export function diagError(tag: string, msg: string, extra?: unknown): void {
  if (cached === null) {
    void isDiagEnabled();
    return;
  }
  if (cached !== TRUE) return;
  if (extra === undefined) {
    console.error(`[${tag}] ${msg}`);
  } else {
    console.error(`[${tag}] ${msg}`, extra);
  }
}

/**
 * 鈶? Provider-specific DOM strategy.
 *
 * Why a DOM strategy (not HTTP replay):
 *   - T1 DevTools research (2026-06-04) revealed each provider's chat API has
 *     anti-bot mechanisms that make pure HTTP replay infeasible:
 *       - GLM: requires HMAC X-Sign header (reverse-engineer their JS)
 *       - DeepSeek: requires WebAssembly PoW challenge solver
 *       - Kimi: uses gRPC-web binary protocol (custom framing)
 *   - Each has a public OpenAI-compatible API (api.deepseek.com, etc.) that
 *     needs an API key 鈥?defeats the "use my logged-in browser session" value prop.
 *   - Solution: reuse the real browser tab. Inject the user's message into the
 *     chat input, press Enter, read the AI's reply from the DOM.
 *   - This is the same approach used by browser-use, Anthropic Computer Use,
 *     and OpenAI Operator 鈥?bypasses all anti-bot because the browser session
 *     does the actual work.
 *
 * Each provider has two strategies:
 *   - InputStrategy: how to find the input element, set the message, trigger send
 *   - ReaderStrategy: how to poll the DOM for the AI's reply, detect completion
 */

import type { WebProvider } from '../types';

// ===== Input strategy =====

/**
 * How to set the message into the page's input element.
 *
 * Most providers use a controlled <textarea> (GLM, DeepSeek) or a contenteditable
 * <div> (Kimi uses Lexical editor). React-style controlled inputs need the
 * value setter trick to bypass React's value comparison; contenteditable
 * editors need execCommand or InputEvent dispatch.
 */
export interface InputStrategy {
  /** CSS selector for the input element. Must be specific (avoid catching the search box). */
  selector: string;

  /**
   * How to set the message into the element:
   *   - 'textarea-setter': Use HTMLTextAreaElement.prototype.value setter
   *     (required for React-controlled textareas; dispatches synthetic input event)
   *   - 'contenteditable-setter': Use HTMLElement.innerText setter + InputEvent
   *     (required for Lexical editor and similar contenteditable frameworks)
   *   - 'execCommand': Use document.execCommand('insertText') (legacy but works
   *     for some apps; deprecated in modern Chrome but still functional)
   */
  setMethod: 'textarea-setter' | 'contenteditable-setter' | 'execCommand';

  /**
   * How to trigger the send:
   *   - 'enter': dispatch an Enter keydown+keyup (works for most chat UIs)
   *   - 'ctrl-enter': use Ctrl+Enter (some apps use this instead of plain Enter)
   *   - 'click-send-button': click a send button (only when there's a visible
   *     button; some apps don't have one)
   */
  sendMethod: 'enter' | 'ctrl-enter' | 'click-send-button';

  /** CSS selector for the send button (required if sendMethod=click-send-button) */
  sendButtonSelector?: string;

  /**
   * Time to wait after setting the value before triggering send (ms).
   * Some apps debounce the input event; default 100ms.
   */
  settleDelayMs?: number;

  /**
   * Optional: scroll the input into view before interacting.
   * Default true; some pages have multiple inputs and need to focus the right one.
   */
  scrollIntoView?: boolean;
}

// ===== Reader strategy =====

/**
 * How to read the AI's reply from the DOM after sending the message.
 *
 * The reader polls the DOM at regular intervals looking for the most recent
 * assistant message element. When new text appears, onChunk is called.
 * When the text is stable for stableThresholdMs, onDone is called.
 */
export interface ReaderStrategy {
  /**
   * CSS selector for the most recent assistant message element.
   * Strategy: pick a selector that uniquely matches the LAST assistant message,
   * not all of them. E.g., for Kimi, the last `[data-message-role="assistant"]`.
   */
  assistantMessageSelector: string;

  /**
   * Optional: selector for a "thinking/loading" indicator.
   * While present, the message is still streaming.
   * Used to determine completion when stableThresholdMs is ambiguous.
   */
  thinkingIndicatorSelector?: string;

  /**
   * Polling interval in ms. Default 100ms.
   * Lower = more responsive but more CPU. 100ms feels real-time to humans.
   */
  pollIntervalMs?: number;

  /**
   * How long the text must be stable (unchanged) before onDone is called (ms).
   * Default 800ms. Apps typically pause briefly between sentences.
   * Too low = false completion; too high = perceptible lag.
   */
  stableThresholdMs?: number;

  /**
   * Maximum total time to wait for a reply before giving up (ms).
   * Default 60s. Resets on every new chunk.
   */
  maxTotalMs?: number;

  /**
   * How to extract text from the matched element.
   *   - 'textContent': raw text, includes whitespace and hidden elements
   *   - 'innerText': rendered text, respects CSS visibility (recommended)
   */
  textMode?: 'textContent' | 'innerText';

  /**
   * Minimum text length (trimmed) before the reader emits any chunk.
   * Filters out noise from the first poll 鈥?e.g. a "retry" button's
   * tooltip text, the assistantMessageSelector picking up a static
   * .markdown-body from the page chrome (footer, sidebar, etc.) before
   * the real AI reply renders, or transient placeholder text like
   * single characters. The reader still calls onDone when the text
   * stabilizes regardless of length. Default 0 (no filter).
   *
   * For providers using `:last-of-type` selectors on a page that has
   * other .markdown-body elements in the chrome, set to 2 or 3.
   */
  minChunkLength?: number;
}

// ===== Combined strategy =====

/**
 * A provider's complete DOM strategy.
 * One per preset. Stored in WebProviderPreset.domStrategy.
 */
export interface WebProviderDomStrategy {
  input: InputStrategy;
  reader: ReaderStrategy;
}

// ===== Execution helpers (testable, also used by the content script) =====

/** Result of executing an input strategy. */
export interface InputExecutionResult {
  /** Whether the input element was found and the message was set. */
  ok: boolean;
  /** If !ok, why. */
  error?: string;
  /** The element that received the message (useful for debugging). */
  element?: HTMLElement;
}

/**
 * Find the input element and set the message. Pure DOM operation.
 *
 * Does NOT trigger send. Call executeSend separately (so the caller can verify
 * the input was set before sending).
 *
 * @param root - typically `document`, but can be a sub-tree for testing
 * @param strategy - the input strategy to apply
 * @param message - the user's message text
 */
export function executeInputSet(
  root: ParentNode,
  strategy: InputStrategy,
  message: string,
): InputExecutionResult {
  const el = root.querySelector(strategy.selector) as HTMLElement | null;
  if (!el) {
    return { ok: false, error: `Input element not found: ${strategy.selector}` };
  }
  if (strategy.scrollIntoView !== false && typeof el.scrollIntoView === 'function') {
    // jsdom doesn't implement scrollIntoView; real Chrome does. Guard for both.
    el.scrollIntoView({ block: 'center' });
  }
  el.focus();

  if (strategy.setMethod === 'textarea-setter') {
    // React-controlled textarea: use the prototype's value setter
    // to bypass React's value comparison.
    const proto = el.tagName === 'TEXTAREA'
      ? window.HTMLTextAreaElement.prototype
      : window.HTMLInputElement.prototype;
    const desc = Object.getOwnPropertyDescriptor(proto, 'value');
    if (!desc?.set) {
      return { ok: false, error: 'No value setter on element prototype' };
    }
    desc.set.call(el, message);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  } else if (strategy.setMethod === 'contenteditable-setter') {
    // Lexical/ProseMirror/other contenteditable: prefer innerText setter
    // (real Chrome); fall back to textContent for environments that lack it
    // (jsdom tests).
    const desc = Object.getOwnPropertyDescriptor(window.HTMLElement.prototype, 'innerText');
    if (desc?.set) {
      desc.set.call(el, message);
    } else {
      el.textContent = message;
    }
    el.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: message }));
  } else if (strategy.setMethod === 'execCommand') {
    // Legacy fallback. Works for some contenteditable, fails for others.
    if (typeof document.execCommand !== 'function') {
      return { ok: false, error: 'document.execCommand is not available' };
    }
    if (!document.execCommand('insertText', false, message)) {
      return { ok: false, error: 'execCommand insertText returned false' };
    }
  } else {
    return { ok: false, error: `Unknown setMethod: ${strategy.setMethod}` };
  }
  return { ok: true, element: el };
}

/**
 * Trigger the send action (Enter key, Ctrl+Enter, or click).
 *
 * For key-based sends, dispatches keydown + keyup events with the appropriate
 * modifier. This works for both textarea (sends on Enter) and contenteditable
 * (sends on Enter) apps.
 *
 * @param root - typically `document`
 * @param strategy - the input strategy
 * @param activeElement - typically `document.activeElement` (the input we just filled)
 */
export function executeSend(
  root: ParentNode,
  strategy: InputStrategy,
  activeElement: Element | null,
): { ok: boolean; error?: string } {
  if (strategy.sendMethod === 'enter' || strategy.sendMethod === 'ctrl-enter') {
    if (!activeElement) {
      return { ok: false, error: 'No active element to send key to' };
    }
    const ctrlKey = strategy.sendMethod === 'ctrl-enter';
    const keyEventInit: KeyboardEventInit = {
      key: 'Enter',
      code: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true,
      cancelable: true,
      ctrlKey,
    };
    activeElement.dispatchEvent(new KeyboardEvent('keydown', keyEventInit));
    activeElement.dispatchEvent(new KeyboardEvent('keypress', keyEventInit));
    activeElement.dispatchEvent(new KeyboardEvent('keyup', keyEventInit));
    return { ok: true };
  } else if (strategy.sendMethod === 'click-send-button') {
    if (!strategy.sendButtonSelector) {
      return { ok: false, error: 'sendMethod=click-send-button requires sendButtonSelector' };
    }
    const btn = root.querySelector(strategy.sendButtonSelector) as HTMLElement | null;
    if (!btn) {
      return { ok: false, error: `Send button not found: ${strategy.sendButtonSelector}` };
    }
    btn.click();
    return { ok: true };
  }
  return { ok: false, error: `Unknown sendMethod: ${strategy.sendMethod}` };
}

/** Callbacks for the reader. */
export interface ReaderCallbacks {
  /** Called when new text appears (after a poll where textContent changed). */
  onChunk: (text: string, fullText: string) => void;
  /** Called when the message is complete (text stable for stableThresholdMs or thinking indicator gone). */
  onDone: (fullText: string) => void;
  /** Called on unrecoverable error (selector lost, total timeout). */
  onError: (err: Error) => void;
}

/**
 * Handle returned by startReader. Call stop() to cancel polling.
 */
export interface ReaderHandle {
  /** Cancel the polling. Safe to call multiple times. */
  stop: () => void;
  /** Resolves when onDone or onError fires (whichever comes first). */
  done: Promise<void>;
}

/** Scheduler interface for testability. */
export interface Scheduler {
  setInterval: (fn: () => void, ms: number) => unknown;
  clearInterval: (handle: unknown) => void;
}

const defaultScheduler: Scheduler = {
  setInterval: (fn, ms) => setInterval(fn, ms),
  clearInterval: (h) => clearInterval(h as ReturnType<typeof setInterval>),
};

/**
 * Start polling the DOM for the AI's reply. Calls onChunk when text changes
 * and onDone when text is stable for stableThresholdMs.
 *
 * Pure DOM operation; the "scheduler" is injectable for tests.
 *
 * @param root - typically `document`
 * @param strategy - the reader strategy
 * @param callbacks - onChunk, onDone, onError handlers
 * @param scheduler - injectable for tests (default uses real setInterval)
 * @param now - injectable for tests (default uses Date.now)
 */
export function startReader(
  root: ParentNode,
  strategy: ReaderStrategy,
  callbacks: ReaderCallbacks,
  scheduler: Scheduler = defaultScheduler,
  now: () => number = Date.now,
): ReaderHandle {
  const pollMs = strategy.pollIntervalMs ?? 100;
  const stableMs = strategy.stableThresholdMs ?? 800;
  const maxMs = strategy.maxTotalMs ?? 60_000;
  const minLen = strategy.minChunkLength ?? 0;

  let lastText = '';
  let lastChangedAt = now();
  let startedAt = now();
  let stopped = false;

  const tick = () => {
    if (stopped) return;

    // Total timeout check
    if (now() - startedAt > maxMs) {
      stopped = true;
      callbacks.onError(new Error(`Reader timeout after ${maxMs}ms`));
      resolveDone();
      return;
    }

    // Find the assistant message element
    const el = root.querySelector(strategy.assistantMessageSelector) as HTMLElement | null;
    if (!el) {
      // No message yet 鈥?keep polling, but don't error
      return;
    }

    // Read text
    const text = strategy.textMode === 'textContent'
      ? (el.textContent ?? '')
      : (el.innerText ?? '');

    if (text !== lastText) {
      lastText = text;
      // minChunkLength gate: only emit if the new text is at least
      // minLen characters trimmed. Smaller texts are noise (single
      // character from a stray element, retry button tooltip, etc.)
      // and we DON'T update lastChangedAt either 鈥?we want the stable
      // check to keep waiting for the real reply.
      if (text.trim().length >= minLen) {
        lastChangedAt = now();
        callbacks.onChunk(text, text);
      }
    }

    // Stable check (text hasn't changed for stableMs)
    if (text.length > 0 && now() - lastChangedAt >= stableMs) {
      stopped = true;
      callbacks.onDone(text);
      resolveDone();
    }
  };

  const handle = scheduler.setInterval(tick, pollMs);
  // Fire once immediately in case the element already exists
  queueMicrotask(tick);

  let resolveDone!: () => void;
  const donePromise = new Promise<void>((resolve) => { resolveDone = resolve; });

  return {
    stop: () => {
      stopped = true;
      scheduler.clearInterval(handle);
      resolveDone();
    },
    done: donePromise,
  };
}

