// 鈹€鈹€鈹€ Attachment types 鈹€鈹€鈹€

export interface ImageAttachment {
  type: 'image';
  source: 'screenshot' | 'upload' | 'paste';
  data: string;          // base64 without data: prefix
  mimeType: string;
  name?: string;
}

export interface TextFileAttachment {
