  disableSkill,
  deleteSkill,
} from './skill-registry';
import type { ApiDiscoveryControlMessage, ApiDiscoveryStatusMessage } from './types';
import { API_DISCOVERY_MSG } from './types';

/** 鏄惁宸插垵濮嬪寲 */
let initialized = false;

/** 鐘舵€佸箍鎾洖璋冨垪琛?*/
type StatusListener = (msg: ApiDiscoveryStatusMessage) => void;
const statusListeners = new Set<StatusListener>();

/** 骞挎挱鐘舵€佹秷鎭?*/
function broadcast(msg: ApiDiscoveryStatusMessage): void {
  for (const listener of statusListeners) {
    try {
      listener(msg);
    } catch (err) {
      console.error('[api-discovery] broadcast error:', err);
    }
  }
}

/** 娉ㄥ唽鐘舵€佺洃鍚櫒 */
export function onStatus(listener: StatusListener): () => void {
  statusListeners.add(listener);
  return () => statusListeners.delete(listener);
}

/** 鍒濆鍖?API Discovery 妯″潡 */
export async function initApiDiscovery(): Promise<void> {
  if (initialized) return;
  initialized = true;

  await initRegistry();

  // 鐩戝惉鎹曡幏浼氳瘽鐘舵€佸彉鏇碶n  captureSession.onStateChange((state) => {
    broadcast({ type: 'capture_status', state });
    broadcast({
      type: 'capture_progress',
      requestCount: state.requestCount,
      apiCandidateCount: state.apiCandidateCount,
    });
  });

  console.log('[api-discovery] initialized');
}

/**
 * 澶勭悊 API Discovery 鎺у埗娑堟伅銆俓n * 鍦?background 鐨?onMessage 鐩戝惉鍣ㄤ腑璋冪敤銆俓n */
export async function handleApiDiscoveryMessage(
  msg: ApiDiscoveryControlMessage,
): Promise<unknown> {
  await initApiDiscovery();

  switch (msg.type) {
    case 'enable':
    case 'disable':
      // 鍏ㄥ眬寮€鍏筹紙鐩墠浠呮爣璁帮紝瀹為檯鎺у埗閫氳繃 start/stop_capture锛塡n      return { ok: true };

    case 'start_capture': {
      try {
        // 妫€鏌?debugger 鏉冮檺锛坥ptional_permissions锛岄渶鐢ㄦ埛鎺堟潈锛塡n        if (!(await chrome.permissions.contains({ permissions: ['debugger'] }))) {
          const granted = await chrome.permissions.request({ permissions: ['debugger'] });
          if (!granted) {
            throw new Error('Debugger permission is required to capture network traffic');
          }
        }

        // 鑾峰彇鏍囩椤典俊鎭痋n        const tab = await chrome.tabs.get(msg.tabId);
        let hostname: string;
        try {
          hostname = new URL(tab.url ?? '').hostname;
        } catch {
          throw new Error('Unable to resolve tab hostname');
        }

        await captureSession.start(msg.tabId, hostname);
        return { ok: true, state: captureSession.getState() };
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        broadcast({ type: 'error', message });
        return { ok: false, error: message };
      }
    }

    case 'stop_capture': {
      const requests = await captureSession.stop();
      return { ok: true, requestCount: requests.length };
    }

    case 'analyze_capture': {
      try {
        const requests = captureSession.getCapturedRequests();
        const endpoints = analyzeRequests(requests);
        const skills = generateSkillsFromEndpoints(endpoints);

        if (skills.length > 0) {
          await addSkills(skills);
        }

        broadcast({
          type: 'analysis_complete',
          endpointsFound: endpoints.length,
          skillsGenerated: skills.length,
        });

        return {
          ok: true,
          endpointsFound: endpoints.length,
          skillsGenerated: skills.length,
        };
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        broadcast({ type: 'error', message });
        return { ok: false, error: message };
      }
    }

    case 'list_auto_skills': {
      const skills = await getAllSkills();
      broadcast({ type: 'skills_list', skills });
      return { ok: true, skills };
    }

    case 'enable_skill': {
      await enableSkill(msg.skillName);
      return { ok: true };
    }

    case 'disable_skill': {
      await disableSkill(msg.skillName);
      return { ok: true };
    }

    case 'delete_skill': {
      await deleteSkill(msg.skillName);
      return { ok: true };
    }

    default:
      return { ok: false, error: 'Unknown message type' };
  }
}

/**
 * 娉ㄥ唽 chrome.runtime.onMessage 鐩戝惉鍣ㄣ€俓n * 搴斿湪 background index.ts 涓皟鐢ㄣ€俓n */
export function registerApiDiscoveryHandlers(): void {
  chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
    if (message?.type !== API_DISCOVERY_MSG) return false;

    handleApiDiscoveryMessage(message.payload as ApiDiscoveryControlMessage)
      .then((result) => sendResponse(result))
      .catch((err) => {
        sendResponse({ ok: false, error: err instanceof Error ? err.message : String(err) });
      });

    return true; // 寮傛鍝嶅簲
  });
}

/**
 * Skill 娉ㄥ唽琛?鈥?绠＄悊鑷姩鍙戠幇鐨?API Skill 鐨勫唴瀛樼储寮曞拰 IndexedDB 鎸佷箙鍖栥€俓n *
 * 鎸?hostname 闅旂锛屾敮鎸侊細
 * - 鏌ヨ鏌愮珯鐐圭殑鎵€鏈?Skill
 * - 鏌ユ壘鍖归厤 URL + intent 鐨?Skill
 * - 鍚敤/绂佺敤/鍒犻櫎 Skill
 * - 鏇存柊鎵ц缁熻鍜屽姩鎬佺疆淇″害
 */

import type { AutoSkillDefinition, SkillStats } from './types';
import {
  CONFIDENCE_HISTORY_WEIGHT,
  CONFIDENCE_RECENT_WEIGHT,
  CONFIDENCE_MAX,
  SKILL_MIN_CONFIDENCE,
  SKILL_ENABLE_MIN_CALLS,
} from './types';
import { getDb } from '@/lib/db';

// 鈹€鈹€鈹€ 鍐呭瓨绱㈠紩 鈹€鈹€鈹€

/** 鎸?hostname 鍒嗙粍鐨?Skill 鏄犲皠 */
const skillsByHostname = new Map<string, AutoSkillDefinition[]>();

/** 鎸?Skill 鍚嶇О绱㈠紩 */
const skillsByName = new Map<string, AutoSkillDefinition>();

/** 鏄惁宸蹭粠 IndexedDB 鍔犺浇 */
let loaded = false;

// 鈹€鈹€鈹€ 鍔犺浇/鎸佷箙鍖?鈹€鈹€鈹€

/** 浠?IndexedDB 鍔犺浇鎵€鏈?Skill 鍒板唴瀛?*/
async function loadFromDb(): Promise<void> {
  if (loaded) return;
  loaded = true;

  try {
    const db = getDb();
    const all = await db.autoSkills.toArray();
    skillsByHostname.clear();
    skillsByName.clear();

    for (const skill of all) {
      registerInMemory(skill);
    }
  } catch (err) {
    console.error('[skill-registry] failed to load from DB:', err);
  }
}

/** 鎸佷箙鍖?Skill 鍒?IndexedDB */
async function persistSkill(skill: AutoSkillDefinition): Promise<void> {
  try {
    const db = getDb();
    await db.autoSkills.put(skill);
  } catch (err) {
    console.error('[skill-registry] failed to persist skill:', err);
  }
}

/** 鎵归噺鎸佷箙鍖?*/
async function persistSkills(skills: AutoSkillDefinition[]): Promise<void> {
  if (skills.length === 0) return;
  try {
    const db = getDb();
    await db.autoSkills.bulkPut(skills);
  } catch (err) {
    console.error('[skill-registry] failed to bulk persist:', err);
  }
}

/** 浠?IndexedDB 鍒犻櫎 */
async function deleteFromDb(skillName: string): Promise<void> {
  try {
    const db = getDb();
    await db.autoSkills.delete(skillName);
  } catch (err) {
    console.error('[skill-registry] failed to delete from DB:', err);
  }
}

// 鈹€鈹€鈹€ 鍐呭瓨鎿嶄綔 鈹€鈹€鈹€

function registerInMemory(skill: AutoSkillDefinition): void {
  skillsByName.set(skill.name, skill);

  let list = skillsByHostname.get(skill.hostname);
  if (!list) {
    list = [];
    skillsByHostname.set(skill.hostname, list);
  }

  // 鏇挎崲鍚屽悕 Skill
  const idx = list.findIndex(s => s.name === skill.name);
  if (idx >= 0) {
    list[idx] = skill;
  } else {
    list.push(skill);
  }
}

function removeFromMemory(skillName: string): void {
  const skill = skillsByName.get(skillName);
  if (!skill) return;

  skillsByName.delete(skillName);

  const list = skillsByHostname.get(skill.hostname);
  if (list) {
    const idx = list.findIndex(s => s.name === skillName);
    if (idx >= 0) list.splice(idx, 1);
    if (list.length === 0) skillsByHostname.delete(skill.hostname);
  }
}

// 鈹€鈹€鈹€ 鍏紑 API 鈹€鈹€鈹€

/** 鍒濆鍖栨敞鍐岃〃锛堜粠 DB 鍔犺浇锛?*/
export async function initRegistry(): Promise<void> {
  await loadFromDb();
}

/**
 * 娣诲姞鏂扮敓鎴愮殑 Skill锛堟壒閲忥級銆俓n * 宸插瓨鍦ㄧ殑鍚屽悕 Skill 浼氳瑕嗙洊銆俓n */
export async function addSkills(skills: AutoSkillDefinition[]): Promise<void> {
  await loadFromDb();

  for (const skill of skills) {
    registerInMemory(skill);
  }

  await persistSkills(skills);
}

/**
 * 鏌ヨ鎸囧畾 hostname 鐨勬墍鏈?Skill銆俓n */
export async function getSkillsByHostname(hostname: string): Promise<AutoSkillDefinition[]> {
  await loadFromDb();
  return skillsByHostname.get(hostname) ?? [];
}

/**
 * 鏌ヨ鎵€鏈?Skill銆俓n */
export async function getAllSkills(): Promise<AutoSkillDefinition[]> {
  await loadFromDb();
  return Array.from(skillsByName.values());
}

/**
 * 鏌ヨ鎵€鏈夊凡鍚敤鐨?Skill锛堝睍绀虹粰 Agent锛夈€俓n * 浠呰繑鍥炵疆淇″害杈炬爣涓旇皟鐢ㄦ鏁拌冻澶熺殑 Skill銆俓n */
export async function getEnabledSkills(): Promise<AutoSkillDefinition[]> {
  await loadFromDb();
  return Array.from(skillsByName.values()).filter((s) => {
    if (!s.enabled) return false;
    const confidence = getEffectiveConfidence(s);
    return confidence >= SKILL_MIN_CONFIDENCE;
  });
}

/**
 * 鏌ユ壘鍖归厤鎸囧畾 URL 鍜?intent 鐨?Skill銆俓n * @returns 鍖归厤鐨?Skill锛堟寜缃俊搴﹂檷搴忥級锛屾垨 null
 */
export async function findMatchingSkill(url: string, intent?: string): Promise<AutoSkillDefinition | null> {
  await loadFromDb();

  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }

  const hostname = parsed.hostname;
  const candidates = skillsByHostname.get(hostname) ?? [];

  if (candidates.length === 0) return null;

  // pathname 鍖归厤璇勫垎
  const scored = candidates
    .filter(s => s.enabled)
    .map((s) => {
      const score = computeMatchScore(s, parsed, intent);
      return { skill: s, score };
    })
    .filter(({ score }) => score > 0)
    .sort((a, b) => b.score - a.score);

  return scored.length > 0 ? scored[0].skill : null;
}

/**
 * 鍚敤 Skill銆俓n */
export async function enableSkill(skillName: string): Promise<void> {
  const skill = skillsByName.get(skillName);
