// 鈹€鈹€鈹€ Throttled writer 鈹€鈹€鈹€

export class ThrottledSessionWriter {
  private timer: ReturnType<typeof setTimeout> | null = null;
  private pending: { id: string; messages: AgentMessage[] } | null = null;

  constructor(private delayMs = 3000) {}

  schedule(id: string, messages: AgentMessage[]): void {
    this.pending = { id, messages: [...messages] };
    if (this.timer) return; // Already scheduled
    this.timer = setTimeout(() => this.flush(), this.delayMs);
  }

  async flush(): Promise<void> {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    if (this.pending) {
      const { id, messages } = this.pending;
      this.pending = null;
      await updateSessionMessages(id, messages);
      // 寮傛淇濆瓨浼氳瘽鎽樿锛堜笉闃诲 flush锛屽け璐ユ椂闈欓粯锛夈€俓n      // 鍔ㄦ€佸鍏ラ伩鍏嶅惊鐜緷璧栵細session-history.ts 鈫?db.ts
      void import('./memory/session-history')
        .then(({ saveSessionSummary }) =>
          saveSessionSummary(id).catch((err) => {
            console.warn('[DB] Failed to save session summary:', err);
          }),
        )
        .catch(() => {
          /* ignore import errors */
        });
      // 寮傛瀛︿範鐢ㄦ埛鍋忓ソ锛堣瑷€妫€娴嬶紝涓嶉樆濉?flush锛屽け璐ユ椂闈欓粯锛夈€俓n      // 鍔ㄦ€佸鍏ラ伩鍏嶅惊鐜緷璧栵細preference-learner.ts 鈫?user-profile.ts 鈫?db.ts
      void import('./memory/preference-learner')
        .then(({ learnFromMessage }) =>
          learnFromMessage(id, messages).catch((err) => {
            console.warn('[DB] Failed to learn preferences:', err);
          }),
        )
        .catch(() => {
          /* ignore import errors */
        });
    }
  }

  dispose(): void {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    this.pending = null;
  }
}

