// 鈹€鈹€鈹€ Native Messaging 浼犺緭 鈹€鈹€鈹€

/** Native Messaging Port 鍚嶇О锛屼笌 Native Host 绾﹀畾涓€鑷?*/
const NATIVE_HOST_PORT_NAME = 'cebianx-mcp-host';

/** 鍙宸ュ叿闆嗗悎 鈥?hermesMode='readonly' 鏃朵粎鍏佽璋冪敤杩欎簺宸ュ叿 */
const READONLY_TOOLS = new Set([
  'cebian_extract',
  'cebian_read_page',
  'cebian_screenshot',
  'cebian_wait',
]);

/** 瀹¤鏃ュ織鏈€澶т繚鐣欐潯鏁?*/
const AUDIT_LOG_MAX = 200;

/**
 * 瀹夎 Native Messaging 鐩戝惉鍣ㄣ€傚簲鍦?background service worker 鍒濆鍖栨椂璋冪敤涓€娆°€俓n *
 * 涓?`installMcpServerListener`锛坥nMessageExternal锛夊苟鍒楋紝澶嶇敤鍚屼竴涓?`handleRequest`銆俓n * Native Host 閫氳繃 `chrome.runtime.connectNative('cebianx-mcp-host')` 寤虹珛杩炴帴锛孿n * 姣忔潯娑堟伅鏍煎紡锛歚{ requestId: string, mcpRequest: MCPRequest }`锛孿n * 鎵╁睍澶勭悊鍚庡洖浼狅細`{ requestId: string, mcpResponse: MCPResponse }`銆俓n *
 * 瀹夊叏鎺у埗锛歕n * - 鎺堟潈寮€鍏筹細`hermesEnabled` 涓?false 鏃舵嫆缁濇墍鏈夎姹俓n * - 妯″紡杩囨护锛歚hermesMode='readonly'` 鏃朵粎鍏佽鍙宸ュ叿
 * - 瀹¤鏃ュ織锛氭瘡娆¤皟鐢ㄨ褰曞埌 `hermesAuditLog`
 */
export function installNativeMessagingListener(): void {
  chrome.runtime.onConnect.addListener((port) => {
    if (port.name !== NATIVE_HOST_PORT_NAME) return;

    console.log('[MCP Server] Native Messaging host connected');

    port.onMessage.addListener(async (msg) => {
      // 楠岃瘉娑堟伅鏍煎紡锛岄伩鍏?null/undefined 鎴栫己灏戝瓧娈靛鑷村悗缁姏 TypeError
      if (!msg || typeof msg !== 'object' || typeof msg.requestId !== 'string' || !msg.mcpRequest) {
        console.warn('[MCP Server] Invalid Native Messaging message:', msg);
        return;
      }
      const { requestId, mcpRequest } = msg as { requestId: string; mcpRequest: MCPRequest };

      // 鎺堟潈妫€鏌n      const enabled = await hermesEnabled.getValue();
      if (!enabled) {
        const mcpResponse = {
          id: mcpRequest.id,
          error: { code: -32001, message: 'Hermes integration is disabled. Enable it in CebianX settings.' },
        };
        try { port.postMessage({ requestId, mcpResponse }); } catch { /* port closed */ }
        return;
      }

      // 妯″紡杩囨护锛歳eadonly 妯″紡涓嬫嫆缁濊鍐欏伐鍏穃n      const mode = await hermesMode.getValue();
      if (mode === 'readonly' && mcpRequest.method === 'tools/call') {
        const toolName = String(mcpRequest.params?.name ?? '');
        if (toolName && !READONLY_TOOLS.has(toolName)) {
          const mcpResponse = {
            id: mcpRequest.id,
            error: { code: -32602, message: `Tool "${toolName}" is not allowed in readonly mode. Switch to readwrite mode in CebianX settings.` },
          };
          await appendAuditLog({
            id: requestId,
            timestamp: Date.now(),
            tool: toolName,
            args: mcpRequest.params?.arguments,
            success: false,
            error: 'Blocked by readonly mode',
          });
          try { port.postMessage({ requestId, mcpResponse }); } catch { /* port closed */ }
          return;
        }
      }

      // 澶勭悊璇锋眰
      const mcpResponse = await handleRequest(mcpRequest);

      // 璁板綍瀹¤鏃ュ織锛堜粎瀵?tools/call锛塡n      if (mcpRequest.method === 'tools/call') {
        const toolName = String(mcpRequest.params?.name ?? '');
        const success = !mcpResponse.error;
        await appendAuditLog({
          id: requestId,
          timestamp: Date.now(),
          tool: toolName,
          args: mcpRequest.params?.arguments,
          success,
          error: mcpResponse.error?.message,
        });
      }

      try {
        port.postMessage({ requestId, mcpResponse });
      } catch (err) {
        // Port 鍙兘鍦ㄥ紓姝ュ鐞嗘湡闂存柇寮€锛圢ative Host 閫€鍑恒€丆hrome 鍏抽棴锛塡n        console.warn('[MCP Server] postMessage to Native Host failed:', err);
      }
    });

    port.onDisconnect.addListener(() => {
      console.log('[MCP Server] Native Messaging host disconnected');
    });
  });

  console.log('[MCP Server] Native Messaging listener installed');
}

/** 杩藉姞瀹¤鏃ュ織鏉＄洰锛岃嚜鍔ㄨ鍓埌 AUDIT_LOG_MAX 鏉?*/
async function appendAuditLog(entry: HermesAuditEntry): Promise<void> {
  try {
    const log = await hermesAuditLog.getValue();
    log.push(entry);
    // 瑁佸壀锛氫繚鐣欐渶鏂扮殑 AUDIT_LOG_MAX 鏉n    if (log.length > AUDIT_LOG_MAX) {
      log.splice(0, log.length - AUDIT_LOG_MAX);
    }
    await hermesAuditLog.setValue(log);
  } catch (err) {
    console.warn('[MCP Server] Failed to append Hermes audit log:', err);
  }
}

