};

export type SessionToSequenceOptions = {
  /** 鏄惁鍦?type 鍓嶈嚜鍔ㄦ彃鍏?clear 姝ラ锛堥粯璁?true锛?*/
  clearBeforeType?: boolean;
  /** 鏄惁灏?tab/navigated 杞崲涓?wait_navigation 姝ラ锛堥粯璁?true锛?*/
  includeNavigation?: boolean;
  /** 鏄惁灏?mutation/appeared 杞崲涓?wait 姝ラ锛堥粯璁?false锛屽洜涓?selector 涓嶅彲闈狅級 */
  includeMutations?: boolean;
  /** 鏄惁鍚敤鏅鸿兘浼樺寲锛氬悎骞惰繛缁緭鍏?婊氬姩銆佸幓閲嶇偣鍑伙紙榛樿 true锛?*/
  smartOptimize?: boolean;
};

// 鈹€鈹€鈹€ 杞崲閫昏緫 鈹€鈹€鈹€

export function sessionToSequence(
  session: RecordedSession,
  options: SessionToSequenceOptions = {},
): SequenceStep[] {
  const {
    clearBeforeType = true,
    includeNavigation = true,
    includeMutations = false,
    smartOptimize = true,
  } = options;

  const steps: SequenceStep[] = [];

  for (const event of session.events) {
    switch (event.kind) {
      case 'interaction':
        pushInteractionSteps(steps, event, clearBeforeType);
        break;
      case 'tab':
        if (includeNavigation) {
          pushTabStep(steps, event);
        }
        break;
      case 'mutation':
        if (includeMutations) {
          pushMutationSteps(steps, event);
        }
        break;
    }
  }

  return smartOptimize ? optimizeSteps(steps) : steps;
}

// 鈹€鈹€鈹€ 鍐呴儴杈呭姪 鈹€鈹€鈹€

function pushInteractionSteps(
  steps: SequenceStep[],
  event: InteractionEvent,
  clearBeforeType: boolean,
): void {
  switch (event.action) {
    case 'click':
      steps.push({ action: 'click', selector: event.target.selector || undefined });
      break;

    case 'input': {
      const selector = event.target.selector || undefined;
      // type 鍓嶅厛 clear锛岀‘淇濊緭鍏ユ鍐呭姝ｇ‘
      if (clearBeforeType && selector) {
        steps.push({ action: 'clear', selector });
      }
      steps.push({ action: 'type', selector, text: event.value });
      break;
    }

    case 'change':
      steps.push({ action: 'select', selector: event.target.selector || undefined, text: event.value });
      break;

    case 'scroll':
      if (event.scroll) {
        steps.push({
          action: 'scroll',
          selector: event.target.selector || undefined,
          deltaX: event.scroll.deltaX,
          deltaY: event.scroll.deltaY,
        });
      }
      break;

    case 'keypress': {
      const selector = event.target.selector || undefined;
      const key = event.key;
      const modifiers = event.modifiers;
      // repeat: 灞曞紑涓哄娆?keypress
      const count = event.repeat ?? 1;
      for (let i = 0; i < count; i++) {
        steps.push({ action: 'keypress', selector, key, modifiers });
      }
      break;
    }

    case 'submit':
      // submit 鏄犲皠涓?click 鎻愪氦鎸夐挳
      steps.push({ action: 'click', selector: event.target.selector || undefined });
      break;
  }
}

function pushTabStep(steps: SequenceStep[], event: TabEvent): void {
  if (event.event === 'navigated') {
    steps.push({ action: 'wait_navigation' });
  }
  // 鍏朵粬 tab 浜嬩欢锛坒ocus_changed/reloaded/created/closed锛夎烦杩嘰n}

function pushMutationSteps(steps: SequenceStep[], event: MutationEvent): void {
  for (const change of event.changes) {
    if (change.op === 'appeared') {
      // mutation 浜嬩欢娌℃湁 selector锛屽彧鏈?tag/role/label
      // 浣跨敤 role + label 鏋勫缓浼?selector锛堜笉淇濊瘉鍙潬锛塡n      const selector = buildMutationSelector(change);
      if (selector) {
        steps.push({ action: 'wait', selector, timeout: 5000 });
      }
    }
  }
}

function buildMutationSelector(change: {
  tag: string;
  role?: string;
  label?: string;
}): string | undefined {
  // 浼樺厛鐢?role锛屽叾娆＄敤 label锛屾渶鍚庣敤 tag
  // 灞炴€у€间腑鐨勫弻寮曞彿闇€瑕佽浆涔夛紝閬垮厤鐢熸垚鏃犳晥 CSS 閫夋嫨鍣╘n  if (change.role) {
    return `[role="${change.role.replace(/"/g, '\\"')}"]`;
  }
  if (change.label) {
    return `[aria-label="${change.label.replace(/"/g, '\\"')}"]`;
  }
  // 绾?tag 澶娉涳紙濡?div銆乻pan锛夛紝涓嶇敓鎴?selector
  const genericTags = new Set(['div', 'span', 'p', 'section', 'article', 'main', 'header', 'footer', 'nav']);
  if (!genericTags.has(change.tag.toLowerCase())) {
    return change.tag.toLowerCase();
  }
  return undefined;
}

// 鈹€鈹€鈹€ 鏅鸿兘浼樺寲 鈹€鈹€鈹€

/**
 * 瀵瑰師濮嬫楠よ繘琛屾櫤鑳戒紭鍖栵細
 * 1. 鍚堝苟鍚屼竴鍏冪礌鐨勮繛缁?type锛坕nput 浜嬩欢姣忔鍙戦€佸畬鏁村€硷紝鍙繚鐣欐渶缁堝€硷級
 * 2. 鍚堝苟鍚屼竴鍏冪礌鐨勮繛缁?scroll锛堢疮鍔?delta锛塡n * 3. 鍘婚櫎杩炵画閲嶅 click锛堝悓涓€ selector 杩炵画鐐瑰嚮瑙嗕负璇搷浣滐級
 * 4. 鍘婚櫎鏃犲悗缁?type 鐨勫绔?clear
 */
function optimizeSteps(steps: SequenceStep[]): SequenceStep[] {
  // Pass 1: 鍚堝苟鍚屼竴 selector 鐨勮繛缁?clear+type 瀵筡n  // input 浜嬩欢姣忔鎼哄甫瀹屾暣鍊硷紝鎵€浠ヨ繛缁殑 clear+type("a") + clear+type("ab")
  // 鍙互浼樺寲涓?clear+type("ab")锛堝彧淇濈暀鏈€鍚庝竴缁勶級銆俓n  // 褰撻亣鍒伴潪褰撳墠 selector 鐨?clear+type 瀵规垨鍏朵粬 action 鏃剁珛鍗冲仠姝㈠悎骞讹紝
  // 闃叉璺ㄨ秺鍏朵粬浜や簰鍔ㄤ綔璇悎骞躲€俓n  const merged: SequenceStep[] = [];
  let i = 0;
  while (i < steps.length) {
    const step = steps[i];
    // 妫€娴?clear+type 瀵筡n    if (
      step.action === 'clear' &&
      i + 1 < steps.length &&
      steps[i + 1].action === 'type' &&
      step.selector === steps[i + 1].selector
    ) {
      const selector = step.selector;
      let lastTypeStep = steps[i + 1];
      let j = i + 2;
      // 绾挎€ф壂鎻忥細璺宠繃鎵€鏈夊悓 selector 鐨勮繛缁?clear+type 瀵筡n      while (
        j + 1 < steps.length &&
        steps[j].action === 'clear' &&
        steps[j + 1].action === 'type' &&
        steps[j].selector === selector &&
        steps[j + 1].selector === selector
      ) {
        lastTypeStep = steps[j + 1];
        j += 2;
      }
      // 鍙繚鐣欐渶鍚庝竴缁?clear+type
      merged.push({ action: 'clear', selector });
      merged.push({ ...lastTypeStep });
      i = j;
    } else {
      merged.push(step);
      i++;
    }
  }

  // Pass 2: 鍚堝苟杩炵画 scroll锛堝悓 selector锛岀疮鍔?delta锛塡n  const scrollMerged = merged.reduce<SequenceStep[]>((acc, step) => {
    const prev = acc[acc.length - 1];
    if (prev && step.action === 'scroll' && prev.action === 'scroll' && prev.selector === step.selector) {
      prev.deltaX = (prev.deltaX ?? 0) + (step.deltaX ?? 0);
      prev.deltaY = (prev.deltaY ?? 0) + (step.deltaY ?? 0);
      return acc;
    }
    return [...acc, step];
  }, []);

  // Pass 3: 鍘婚櫎杩炵画閲嶅 click锛堝悓 selector锛塡n  const deduped = scrollMerged.reduce<SequenceStep[]>((acc, step) => {
    const prev = acc[acc.length - 1];
    if (prev && step.action === 'click' && prev.action === 'click' && prev.selector === step.selector) {
      return acc;
    }
    return [...acc, step];
  }, []);

  // Pass 4: 鍘婚櫎鏃犲悗缁?type 鐨勫绔?clear
  return deduped.filter((step, idx, arr) => {
    if (step.action === 'clear') {
      const next = arr[idx + 1];
      return next?.action === 'type' && next.selector === step.selector;
    }
    return true;
  });
}

