/**
 * `bgFetch` skill RPC handler 鈥?runs in the background service worker so it
 * inherits the extension's `<all_urls>` host_permissions and bypasses CORS.
 *
 * 璺?`fs-save-url` 鐨勫樊鍒細fs-save-url 鏄?agent-facing 宸ュ叿锛坅gent 鐩存帴璋冦€佸搷搴擻n * 钀?VFS锛夛紱bgFetch 鏄?skill-facing 鑳藉姏锛岀敱 skill script 閫氳繃 sandbox 鍏ㄥ眬璋冪敤锛孿n * 鍝嶅簲 body 瀹屾暣杩斿洖锛堜笉钀?VFS锛夛紝浜ょ粰 skill 鑷繁澶勭疆鈥斺€旇繖鏍?azure-image-gen 杩欑
 * 銆岃皟 API 鈫?瑙ｇ爜 鈫?钀藉湴 鈫?杩斿洖 markdown銆嶇殑娴佺▼鑳藉湪涓€涓剼鏈噷璧板畬銆俓n *
 * 瀹夊叏妯″瀷锛歕n * - 璋冪敤 URL 蹇呴』鏄?http(s)锛涘叾瀹?scheme 鐩存帴鎷抃n * - URL 蹇呴』鍛戒腑璋冪敤鏂瑰湪 `metadata.permissions` 閲屽０鏄庣殑 bgFetch pattern锛沺atterns
 *   鐢?sandbox-rpc 鍦?runInSandbox 鏃惰绠楀ソ锛屽瓨杩?pendingRuns 鍚庣敱 handler 鍙嶆煡鈥斺€擻n *   sandbox 閭ｄ晶鐨勮姹?envelope 瀛楁鍏ㄩ儴涓嶈淇′换
 * - 涓ゅ眰澶у皬妫€鏌ワ細Content-Length 棰勬 + 杈硅杈圭疮璁★紝瓒?maxBytes 绔嬪埢 abort
 */

import type { MatchPattern } from './url-pattern';
import { formatMatchPattern, matchUrl } from './url-pattern';

/** Default body 涓婇檺銆傚鐢?fs-save-url 鐨勫彇鍊硷紝璺?SW 鍐呭瓨棰勭畻瀵归綈銆?*/
const DEFAULT_MAX_BYTES = 50 * 1024 * 1024;
/** 纭笂闄愩€傝秴杩囪鍊肩殑璇锋眰涓嶅厑璁?skill 鑷鎶珮 鈥斺€?闃?SW OOM銆?*/
const HARD_MAX_BYTES = 1024 * 1024 * 1024;

/** Skill 鐪嬪埌鐨?init 瀛愰泦锛坧ostMessage/JSON 鍙嬪ソ锛沚ody 浜岃繘鍒跺凡缁忚
 *  binary envelope 杩樺師鎴?Uint8Array / ArrayBuffer / string锛夈€?*/
export interface BgFetchInit {
  method?: string;
  /** Header 宸茶 sandbox 绔?flatten 鎴?`Record<string,string>`锛圚eaders 瀹炰緥
   *  浼氬厛鍦?sandbox 閭ｄ晶杩唬灞曞紑锛夈€?*/
  headers?: Record<string, string>;
  body?: string | Uint8Array | ArrayBuffer;
  redirect?: 'follow' | 'error' | 'manual';
  referrer?: string;
  referrerPolicy?: ReferrerPolicy;
  cache?: RequestCache;
}

/** 璺?RPC 杈圭晫浼犲洖 sandbox 鐨勫師濮嬪搷搴旓紱sandbox 涓€渚у啀鍖呮垚 fetch-like 瀵硅薄銆?*/
export interface RawBgFetchResponse {
  status: number;
  statusText: string;
  redirected: boolean;
  url: string;
  /** 鎵佸钩鍖栫殑鍝嶅簲澶达紱sandbox 渚?`new Headers(headersFlat)` 杩樺師銆?*/
  headersFlat: Record<string, string>;
  body: Uint8Array;
}

/** Skill 涓嶅厑璁歌皟鐢ㄧ殑 URL scheme 鈥斺€?鍗充娇 pattern 閫氶厤涔熻鎷掋€?*/
function assertHttpUrl(parsed: URL): void {
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new Error(`bgFetch only supports http(s) URLs, got "${parsed.protocol}"`);
  }
}

function normalizeInit(init: unknown): RequestInit {
  if (!init || typeof init !== 'object') return {};
  const i = init as BgFetchInit;
  const out: RequestInit = {};
  if (typeof i.method === 'string') out.method = i.method;
  if (i.headers && typeof i.headers === 'object') out.headers = i.headers;
  if (i.body !== undefined) {
    // sandbox-rpc 宸茬粡璧?decodeBinary 鎶?binary envelope 杩樺師锛涜繖閲岀洿鎺ラ€忎紶缁欏師鐢焅n    // fetch锛坒etch 鑷繁鎺?string / Uint8Array / ArrayBuffer锛夈€俓n    out.body = i.body as BodyInit;
  }
  if (i.redirect) out.redirect = i.redirect;
  if (typeof i.referrer === 'string') out.referrer = i.referrer;
  if (i.referrerPolicy) out.referrerPolicy = i.referrerPolicy;
  if (i.cache) out.cache = i.cache;
  return out;
}

/**
 * 鎵ц涓€娆?skill 鍙戣捣鐨?bgFetch 璇锋眰銆俓n *
 * `signal` 鍏宠仈鍒?skill 鏁翠釜 run 鐨?abort signal锛堢敱 sandbox-rpc 鎸佹湁锛夛紝
 * skill cancel / run 瓒呮椂 / agent abort 閮戒細瑙﹀彂锛屽悓鏃朵腑鏂?fetch 鎻℃墜闃舵
 * 鍜屾鍦ㄨ繘琛岀殑 body 璇诲彇銆俓n */
export async function handleBgFetch(
  rawUrl: unknown,
  rawInit: unknown,
  patterns: readonly MatchPattern[],
  signal?: AbortSignal,
): Promise<RawBgFetchResponse> {
  if (typeof rawUrl !== 'string') {
    throw new Error('bgFetch url must be a string');
  }

  let parsed: URL;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new Error(`Invalid URL: ${rawUrl}`);
  }
  assertHttpUrl(parsed);

  if (!patterns.some(p => matchUrl(parsed, p))) {
    const declared = patterns.map(formatMatchPattern).join(', ');
    throw new Error(
      `URL "${parsed.href}" not allowed by bgFetch patterns. Declared: ${declared}`,
    );
  }

  // 鎶?skill 鐨?abort 妗ユ帴鍒板唴閮?controller 鈥斺€?skill cancel 鏃舵棦瑕佷腑鏂?fetch
  // handshake锛屼篃瑕佷腑鏂?body 娴佽鍙栥€俓n  const controller = new AbortController();
  const onAbort = () => controller.abort(signal?.reason);
  if (signal) {
    if (signal.aborted) controller.abort(signal.reason);
    else signal.addEventListener('abort', onAbort, { once: true });
  }

  try {
    let resp: Response;
    try {
      const init = normalizeInit(rawInit);
      init.signal = controller.signal;
      resp = await fetch(parsed.href, init);
    } catch (err) {
      // AbortError 鍘熸牱鍚戜笂鎶ワ紝淇濈暀 cancellation 璇箟銆俓n      if ((err as Error).name === 'AbortError' || signal?.aborted) throw err;
      throw new Error(`Network error fetching ${parsed.href}: ${(err as Error).message}`);
    }
    if (signal?.aborted) throw signal.reason ?? new DOMException('aborted', 'AbortError');

    // 鈹€鈹€ Content-Length 棰勬 鈹€鈹€
    const maxBytes = DEFAULT_MAX_BYTES;
    const declaredLen = parseInt(resp.headers.get('content-length') ?? '', 10);
    if (Number.isFinite(declaredLen) && declaredLen > maxBytes) {
      controller.abort();
      throw new Error(
        `Response too large: Content-Length declares ${declaredLen} bytes > maxBytes ${maxBytes}`,
      );
    }

    // 鈹€鈹€ 娴佸紡璇诲彇 + running tally 鈹€鈹€
    const chunks: Uint8Array[] = [];
    let total = 0;
    const reader = resp.body?.getReader();
    if (reader) {
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          total += value.byteLength;
          if (total > maxBytes) {
            controller.abort();
            throw new Error(
              `Response exceeded maxBytes (${maxBytes}) at ${total} bytes`,
            );
          }
          if (total > HARD_MAX_BYTES) {
            controller.abort();
            throw new Error(`Response exceeded hard cap ${HARD_MAX_BYTES} bytes`);
          }
          chunks.push(value);
        }
      } finally {
        reader.releaseLock();
      }
    }

    // 鍚堝苟 chunks 鎴愬崟涓?Uint8Array銆俓n    const body = new Uint8Array(total);
    let offset = 0;
    for (const c of chunks) {
      body.set(c, offset);
      offset += c.byteLength;
    }

    const headersFlat: Record<string, string> = {};
    resp.headers.forEach((v, k) => {
      headersFlat[k] = v;
    });

    return {
      status: resp.status,
      statusText: resp.statusText,
      redirected: resp.redirected,
      url: resp.url,
      headersFlat,
      body,
    };
  } finally {
    if (signal) signal.removeEventListener('abort', onAbort);
  }
}

