// 鈹€鈹€鈹€ Tool definition 鈹€鈹€鈹€

export const chromeApiTool: AgentTool<typeof ChromeApiParameters> = {
  name: TOOL_CHROME_API,
  label: 'Chrome API',
  description:
    'Call Chrome browser APIs directly via structured parameters. ' +
    'Use for: querying/managing tabs and windows, bookmarks, browsing history, cookies, ' +
    'downloads, alarms, notifications, sessions, top sites, and frame inspection. ' +
    'Supported namespaces: tabs, windows, bookmarks, history, cookies, ' +
    'topSites, sessions, downloads, alarms, notifications, webNavigation. ' +
    'Arguments are passed as an array 鈥?each element is one function argument. ' +
    'Get tab IDs and window IDs from the context block. ' +
    'IMPORTANT: If unsure about argument format, first call with namespace="help" and method=<namespace> ' +
    'to see method signatures and examples. Use method="list" to see all available namespaces. ' +
    'Returns the JSON-serialized result.',
  parameters: ChromeApiParameters,

  async execute(_toolCallId, params, signal): Promise<AgentToolResult<{}>> {
    signal?.throwIfAborted();
    const { namespace, method, args = [] } = params;

    // Handle help requests 鈥?return API documentation
    if (namespace === 'help') {
      if (method === 'list') {
        return { content: [{ type: 'text', text: formatHelpList() }], details: {} };
      }
      return { content: [{ type: 'text', text: formatHelpNamespace(method) }], details: {} };
    }

    // Validate against whitelist
    if (!isChromeCallAllowed(namespace, method)) {
      const supported = Object.keys(CHROME_API_WHITELIST).join(', ');
      throw new Error(`chrome.${namespace}.${method} is not allowed. Supported namespaces: ${supported}.`);
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- 鍔ㄦ€?chrome.* 鍙栧€糪n    let target: any = (chrome as any)[namespace];
    if (!target) {
      throw new Error(`chrome.${namespace} is not available in this environment.`);
    }

    // Resolve nested method path (e.g. storage 鈫?local 鈫?get)
    const parts = method.split('.');
    for (let i = 0; i < parts.length - 1; i++) {
      target = target[parts[i]];
      if (!target) {
        throw new Error(`chrome.${namespace}.${method} path not found.`);
      }
    }

    const finalMethod = parts[parts.length - 1];
    if (typeof target[finalMethod] !== 'function') {
      throw new Error(`chrome.${namespace}.${method} is not a function.`);
    }

    const result = await target[finalMethod](...args);

    let text: string;
    try {
      text = result !== undefined ? JSON.stringify(result, null, 2) : '(no return value)';
    } catch {
      // 搴忓垪鍖栧け璐ヤ笉绠楃湡閿欙紙chrome API 杩斿洖浜嗭紝鍙槸鍖呭惈 circular ref / Symbol /
      // class instance 涔嬬被锛夆€斺€?鍛婅瘔 agent 绫诲瀷锛岃瀹冩崲涓柟娉曟垨鍙傛暟
      text = `(result returned but could not be serialized 鈥?type: ${typeof result})`;
    }

    return {
      content: [{ type: 'text', text }],
      details: {},
    };
  },
};

import { Type } from 'typebox';
import type { AgentTool, AgentToolResult } from '@earendil-works/pi-agent-core';
import { TOOL_EXECUTE_JS } from '@/lib/types';
import { executeViaDebugger } from '@/lib/tab-helpers';
import { vfs } from '@/lib/vfs';

/** Sentinel value returned by the injected func when CSP blocks new Function(). */
const CSP_BLOCKED = '__cebian_csp_blocked__';

const ExecuteJsParameters = Type.Object({
  code: Type.String({
    description:
      'JavaScript code to execute in the target tab. ' +
      'The code is inserted as the body of `async () => { YOUR_CODE }` 鈥?use `return` directly to produce a result ' +
      '(e.g. `return document.title`). You can use `await` directly. ' +
      'NEVER wrap code in an IIFE like `(()=>{ return x })()` 鈥?the outer async function has no top-level `return`, so the result comes back as `(no return value)`. Use a bare top-level `return x` instead. ' +
      'The return value is JSON-serialized and returned to you in full 鈥?there is no hidden size limit, so do not pre-chunk results or probe for a maximum size. ' +
      'For results small enough to reason about inline, return them directly; for results large enough to bloat the conversation (full-page extracts, generated reports, structured data dumps), set `outputPath` to land them in VFS instead.',
  }),
  outputPath: Type.Optional(
    Type.String({
      description:
        'If set, the return value is written to this absolute VFS path (e.g. "/workspaces/abc/page.md") and only a short summary is returned to you. ' +
        'Use this whenever the natural result is large enough that returning it inline would bloat the conversation 鈥?the bytes go straight to disk and never enter your context. ' +
        'Strings are written verbatim; other values are written as pretty-printed JSON (2-space indent). ' +
        'Parent directories are created automatically. Existing files are overwritten. ' +
        'The script must `return` a non-empty value 鈥?returning null/undefined is an error.',
    }),
  ),
  frameId: Type.Optional(
    Type.Number({
      description:
        'Frame ID to execute in. Omit or 0 for the top frame. ' +
        'Use tab({ action: "list_frames" }) to discover frame IDs.',
    }),
  ),
  tabId: Type.Number({
    description:
      'Required. Tab ID to execute in. Read it from the `tabId:` line under `[Active Tab]` (or the windows list) in the context block. ' +
      'Never omit 鈥?the active tab may have changed since the last context snapshot.',
  }),
});

export const executeJsTool: AgentTool<typeof ExecuteJsParameters> = {
  name: TOOL_EXECUTE_JS,
  label: 'Execute JavaScript',
  description:
    'Execute JavaScript code in a browser tab and return the result. ' +
    'The code runs as an async function body 鈥?use `return` to produce a result (e.g. `return document.title`). ' +
    'Use for DOM operations, data extraction, page modifications, ' +
    'calling page APIs, or reading localStorage/sessionStorage. ' +
    'The code runs in the page context with full access to the DOM and page globals. ' +
    'The return value is JSON-serialized and returned in full 鈥?do not pre-chunk or probe for a size limit.',
  parameters: ExecuteJsParameters,

  async execute(_toolCallId, params, signal): Promise<AgentToolResult<{}>> {
    signal?.throwIfAborted();
    const tabId = params.tabId;

    const target = params.frameId != null
      ? { tabId, frameIds: [params.frameId] }
      : { tabId };

    // Try executing via chrome.scripting.executeScript (MAIN world).
    // If the page has a strict CSP that blocks eval/new Function, the injected
    // func catches the error and returns a sentinel so we can fall back to CDP.
    const results = await chrome.scripting.executeScript({
      target,
      func: async (code: string, cspSentinel: string) => {
        try {
          return await new Function(`return (async () => { ${code} })()`)();
        } catch (e: any) {
          if (e.message && /unsafe-eval|Content Security Policy/i.test(e.message)) {
            return cspSentinel;
          }
          throw e;
        }
      },
      args: [params.code, CSP_BLOCKED],
      ...({ world: 'MAIN' } as any),
    });

    const result = results?.[0];

    // Compute a single display-formatted `text` for both execution paths and
    // both output sinks (inline return / outputPath write):
    //   - MAIN-world success: `result.result` is the raw return value. We
    //     format with "string verbatim, else JSON.stringify(_, null, 2)" 鈥擻n    //     the same rule executeViaDebugger uses for the CSP fallback path.
    //     Aligning these means `return "foo"` produces `foo` (not `"foo"`)
    //     regardless of which execution path was taken.
    //   - CSP fallback: the helper already returns a display-formatted string;
    //     we use it as-is.
    // `canWrite` is true iff `text` represents a real payload 鈥?undefined /
    // null returns, serialization failures, and the helper's sentinel
    // strings all flip it false so the outputPath branch refuses to write.
    let text: string;
    let canWrite: boolean;
    if (result?.result === CSP_BLOCKED) {
      text = await executeViaDebugger(tabId, params.code);
      // CDP 璧扮殑 fallback 杩斿洖鐨勬槸瀛楃涓诧紙鍖呭惈 sentinel锛夛細
      //   "(no return value)" 鈫?娌℃湁杩斿洖鍊糪n      //   "Error: <msg>"      鈫?椤甸潰閲屾姏浜嗗紓甯竆n      //   鍏跺畠                鈫?姝ｅ父杩斿洖鍊硷紙宸茬粡琚樉绀烘牸寮忓寲杩囷級
      // 鐪熷紓甯稿繀椤?throw 鍑哄幓锛屽惁鍒欎細琚綋浣淺

銆俓n      if (text.startsWith('Error: ')) {
        throw new Error(text.slice('Error: '.length).trim());
      }
      canWrite = text !== '(no return value)';
    } else {
      const rawValue = result?.result;
      // null and undefined are treated identically: neither is a usable
      // payload, so both render as the same sentinel inline and are both
      // rejected by outputPath. Pre-refactor this only short-circuited on
      // undefined; `return null` used to leak through as the literal string
      // "null", which the model could mistake for the error info actually
      // being null instead of "the script returned nothing meaningful".
      if (rawValue === undefined || rawValue === null) {
        text = '(no return value)';
        canWrite = false;
      } else {
        canWrite = true;
        try {
          text = typeof rawValue === 'string' ? rawValue : JSON.stringify(rawValue, null, 2);
        } catch {
          text = `(result could not be serialized 鈥?got ${typeof rawValue})`;
          canWrite = false;
        }
      }
    }

    // 鈹€鈹€ outputPath branch 鈹€鈹€
    // Bytes land directly in VFS; the agent only sees path + size + preview.
    if (params.outputPath) {
      if (!canWrite) {
        throw new Error(`Nothing written to ${params.outputPath} 鈥?script produced no usable return value: ${text}. Use 'return <value>' with a serializable, non-empty payload.`);
      }
      await vfs.writeFile(params.outputPath, text, 'utf8');

      const byteLen = new TextEncoder().encode(text).length;
      const preview = text.length > 1024
        ? text.slice(0, 1024) + '\n鈥?preview truncated; full content is on disk)'
        : text;
      return {
        content: [{ type: 'text', text: `Wrote ${params.outputPath} (${byteLen} bytes)\nPreview:\n---\n${preview}\n---` }],
        details: {},
      };
    }

    // 鈹€鈹€ Inline-return branch 鈹€鈹€
    return {
      content: [{ type: 'text', text }],
      details: {},
    };
  },
};

import { Type, type Static } from 'typebox';
import type { AgentTool, AgentToolResult } from '@earendil-works/pi-agent-core';
import { TOOL_FS_SAVE_URL } from '@/lib/types';
import { vfs } from '@/lib/vfs';
import { extensionForMime, isTextualMime } from '@/lib/mime';
import { formatSize } from './fs-helpers';

/** Default ceiling on response body bytes if the caller doesn't override
 *  via `save.maxBytes`. Comfortably fits typical screenshots, short clips,
 *  and JSON payloads while keeping a single tool call from spending hundreds
 *  of MB of browser memory. */
const DEFAULT_MAX_BYTES = 50 * 1024 * 1024;
/** Hard upper bound regardless of caller-supplied `save.maxBytes`. Keeps
 *  an over-eager agent from instructing the tool to buffer multi-GB
 *  responses that would crash the service worker. */
const HARD_MAX_BYTES = 1024 * 1024 * 1024;
/** Number of bytes returned as a textual preview when `save.sample` is on
 *  and the MIME is textual. Tuned to surface enough JSON / HTML / source
 *  for the agent to recognize the payload shape without bloating tool
 *  output token cost. */
const SAMPLE_BYTES = 1024;

/** RequestInit subset we accept from the agent. Only fields that make sense
 *  for a from-the-LLM call are exposed. Notably, `body` is restricted to
 *  string 鈥?LLMs don't have a way to construct ArrayBuffer / FormData, and
 *  serialising those through tool args would defeat the token-saving point
 *  of this tool. JSON bodies go through `JSON.stringify` in the agent. */
const FsSaveUrlInit = Type.Object({
  method: Type.Optional(Type.Union([
    Type.Literal('GET'), Type.Literal('POST'), Type.Literal('PUT'),
    Type.Literal('PATCH'), Type.Literal('DELETE'), Type.Literal('HEAD'),
  ], { description: 'HTTP method. Defaults to GET.' })),
  headers: Type.Optional(Type.Record(Type.String(), Type.String(), {
    description: 'HTTP request headers as a flat string-to-string object.',
  })),
  body: Type.Optional(Type.String({
    description: 'Request body. Only string bodies are supported 鈥?JSON-encode it yourself.',
  })),
  redirect: Type.Optional(Type.Union([
    Type.Literal('follow'), Type.Literal('error'), Type.Literal('manual'),
  ], { description: 'Redirect handling, mirrors fetch RequestInit.redirect. Defaults to "follow".' })),
  referrer: Type.Optional(Type.String({
    description:
      'Referrer URL for the request. Use "about:client" for the default ' +
      'or "no-referrer" to omit. Mirrors fetch RequestInit.referrer.',
  })),
  referrerPolicy: Type.Optional(Type.Union([
    Type.Literal(''), Type.Literal('no-referrer'), Type.Literal('no-referrer-when-downgrade'),
    Type.Literal('origin'), Type.Literal('origin-when-cross-origin'),
    Type.Literal('same-origin'), Type.Literal('strict-origin'),
    Type.Literal('strict-origin-when-cross-origin'), Type.Literal('unsafe-url'),
  ], { description: 'Referrer policy, mirrors fetch RequestInit.referrerPolicy.' })),
  credentials: Type.Optional(Type.Union([
    Type.Literal('omit'), Type.Literal('include'),
  ], { description: 'Cookie / auth credentials policy.' })),
  mode: Type.Optional(Type.Union([
    Type.Literal('cors'), Type.Literal('no-cors'),
  ], { description: 'Request mode, mirrors fetch RequestInit.mode.' })),
}, { description: 'Optional fetch init 鈥?subset of RequestInit.' });

/** Knobs that control how the response is saved into VFS. Kept under a
 *  separate `save` sub-object so the top-level signature stays focused on
 *  the fetch-equivalent shape. */
const FsSaveUrlSave = Type.Object({
  overwrite: Type.Optional(Type.Boolean({
    description: 'If false and `dest` already exists, the call fails. Defaults to true.',
  })),
  maxBytes: Type.Optional(Type.Number({
    description:
      'Abort and reject if the response body exceeds this many bytes. ' +
      'Defaults to 50 MB. Capped at a hard ceiling of 1 GB regardless of value. ' +
      'The check uses Content-Length as a pre-flight when present, and a running ' +
      'tally during streaming so oversized responses abort early without buffering.',
  })),
  sample: Type.Optional(Type.Boolean({
    description:
      `Include the first ${SAMPLE_BYTES / 1024} KB of the saved content as a Preview block in the ` +
      'return text, but only for textual MIME types (text/*, application/json, ' +
      'application/xml, application/javascript, *+json, *+xml, etc.). ' +
      'Defaults to true. Binary MIME types never sample. Useful when the agent ' +
      'wants to peek at a fetched JSON/HTML without a follow-up fs_read_file call.',
  })),
}, { description: 'Optional save-behavior knobs.' });

const FsSaveUrlParameters = Type.Object({
  url: Type.String({
    description: 'The URL to fetch. Must be http(s).',
  }),
  dest: Type.String({
    description:
      'VFS path to save to. Pass a full file path (e.g. "/tmp/cat.jpg") to use ' +
      'it verbatim, OR a directory path ending with "/" (e.g. "/tmp/") to let ' +
      'the tool derive the filename from the response Content-Disposition ' +
      'header, the URL\'s last segment, or the MIME type 鈥?in that order.',
  }),
  init: Type.Optional(FsSaveUrlInit),
  save: Type.Optional(FsSaveUrlSave),
});

export const fsSaveUrlTool: AgentTool<typeof FsSaveUrlParameters> = {
  name: TOOL_FS_SAVE_URL,
  label: 'Save URL',
  description:
    'Fetch a URL and save the response body to a VFS file. ' +
    'Use this to put remote resources (images, videos, PDFs, JSON, etc.) into VFS without ' +
    'round-tripping bytes through the conversation 鈥?never base64-encode binary content ' +
    'and pass it to fs_create_file. Parameters mirror fetch(url, init).',
  parameters: FsSaveUrlParameters,

  async execute(_toolCallId, params, signal): Promise<AgentToolResult<{}>> {
    signal?.throwIfAborted();

    // 鈹€鈹€ Input validation 鈹€鈹€
    let parsedUrl: URL;
    try {
      parsedUrl = new URL(params.url);
    } catch {
      throw new Error(`Invalid URL: ${params.url}`);
    }
    if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
      throw new Error(`Unsupported URL scheme "${parsedUrl.protocol}". Only http(s) is allowed.`);
    }

    const overwrite = params.save?.overwrite ?? true;
    // For a plain file dest (no trailing slash) we can short-circuit the
    // overwrite check before doing any network I/O. Directory dest needs
    // the response headers to derive a filename, so its overwrite check
    // is performed AFTER the fetch (see below).
    const destIsDirectory = params.dest.endsWith('/');
    if (!destIsDirectory && !overwrite && (await vfs.exists(params.dest))) {
      throw new Error(`File already exists at ${params.dest}; pass save.overwrite=true to replace it.`);
    }

    // 鈹€鈹€ Network I/O 鈹€鈹€
    // Bridge the agent's abort signal into our request so a user-issued
    // cancel reliably aborts BOTH the fetch handshake AND the streaming
    // body read. The listener stays registered until the very end of the
    // network/write section so a cancellation mid-stream actually tears
    // down the in-flight fetch at the network layer 鈥?not just on the
    // next loop iteration's throwIfAborted check.
    const controller = new AbortController();
    const onAbort = () => controller.abort(signal?.reason);
    signal?.addEventListener('abort', onAbort, { once: true });
    try {
      let response: Response;
      try {
        response = await fetch(parsedUrl.href, buildRequestInit(params.init, controller.signal));
      } catch (err) {
        // AbortError / 琚彇娑堢殑璇锋眰锛氬師鏍锋姏锛屼繚鐣?cancellation 璇箟锛沑n        // 鐪熺綉缁滈敊璇紙DNS / TCP / TLS handshake锛夌殑 fetch 鍘熺敓 message
        // ("TypeError: Failed to fetch") 涓嶅甫 URL锛屽姞涓€灞傝 LLM 鐭ラ亾鏄摢涓姹傛寕鐨勩€俓n        if ((err as Error).name === 'AbortError' || signal?.aborted) throw err;
        throw new Error(`Network error fetching ${parsedUrl.href}: ${(err as Error).message}`);
      }
      signal?.throwIfAborted();

      // `manual` redirect mode returns an opaque-redirect response (status 0,
      // empty body, no headers exposed). Saving that to VFS would write a
      // zero-byte file with no useful information 鈥?reject loud and steer
      // the agent toward `redirect: 'follow'` if it actually wants content.
      if (response.type === 'opaqueredirect') {
        throw new Error(
          'Got opaque-redirect response (init.redirect="manual") 鈥?nothing to save. ' +
          'Use init.redirect="follow" to fetch the redirect target.',
        );
      }
      if (!response.ok) {
        // HTTP/2 omits the reason phrase, so statusText is often empty 鈥擻n        // avoid the resulting double space between status and "from".
        const statusPart = response.statusText
          ? `${response.status} ${response.statusText}`
          : String(response.status);
        throw new Error(`HTTP ${statusPart} from ${parsedUrl.href}`);
      }

      // 鈹€鈹€ Read body (streaming, with size cap) 鈹€鈹€
      // Two-layer guard: a pre-flight check on Content-Length (when the
      // server provides it) lets us reject obviously-oversized responses
      // before reading a single byte, and a running tally during the read
      // loop catches servers that lie about Content-Length or omit it.
      const maxBytes = Math.min(params.save?.maxBytes ?? DEFAULT_MAX_BYTES, HARD_MAX_BYTES);

      const declaredLength = parseInt(response.headers.get('content-length') ?? '', 10);
      if (Number.isFinite(declaredLength) && declaredLength > maxBytes) {
        throw new Error(
          `Response too large: Content-Length declares ${formatSize(declaredLength)} ` +
          `> maxBytes ${formatSize(maxBytes)}. Pass save.maxBytes to raise the limit ` +
          `(hard cap ${formatSize(HARD_MAX_BYTES)}).`,
        );
      }

      const chunks: Uint8Array[] = [];
      let total = 0;
      const reader = response.body?.getReader();
      if (reader) {
        // try/finally 鍙负璧勬簮娓呯悊锛堥噴鏀?reader lock锛夈€俓n        // 涓嶅啀 try/catch + wrap锛歳eader 鎶涢敊锛堝惈 AbortError 鍜屾垜浠嚜宸?throw 鐨刓n        // maxBytes 閿欒锛夐兘鍘熸牱鍚戜笂浼犳挱銆俓n        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            total += value.byteLength;
            if (total > maxBytes) {
              // Tear down the fetch immediately so we don't burn bandwidth
              // pulling the rest of an oversized body we're going to throw
              // away.
              controller.abort();
              throw new Error(
                `Response exceeded maxBytes (${formatSize(maxBytes)}) at ${formatSize(total)}. ` +
                `Pass save.maxBytes to raise the limit (hard cap ${formatSize(HARD_MAX_BYTES)}).`,
              );
            }
            chunks.push(value);
          }
        } finally {
          reader.releaseLock();
        }
      }
      signal?.throwIfAborted();

      // Concatenate the streamed chunks into one contiguous buffer for VFS.
      const buf = new Uint8Array(total);
      let offset = 0;
      for (const chunk of chunks) {
        buf.set(chunk, offset);
        offset += chunk.byteLength;
      }
      const mime = (response.headers.get('content-type') ?? 'application/octet-stream').split(';')[0]!.trim();

      // 鈹€鈹€ Resolve final dest path 鈹€鈹€
      // For directory dest we now have the headers needed to derive a
      // filename. The overwrite check moves here so it runs against the
      // actual file path we're about to write to.
      let finalDest = params.dest;
      if (destIsDirectory) {
        const filename = deriveFilename(parsedUrl, response.headers.get('content-disposition'), mime);
        finalDest = params.dest + filename;
        if (!overwrite && (await vfs.exists(finalDest))) {
          throw new Error(`File already exists at ${finalDest}; pass save.overwrite=true to replace it.`);
        }
      }

      // 鈹€鈹€ Write 鈹€鈹€
      // `vfs.writeFile` accepts Uint8Array directly and auto-creates parent
      // dirs. The vfs change event fires automatically on success, so any
      // listeners (e.g. the skill index cache invalidator in scanner.ts)
      // pick up writes under ~/.cebian/skills/ without per-tool plumbing.
      await vfs.writeFile(finalDest, buf);

      // 鈹€鈹€ Optional text sample 鈹€鈹€
      // For textual MIMEs we attach a short preview to the return so the
      // agent can decide what to do with the saved file without a separate
      // fs_read_file call. `fatal: false` lets us decode whatever happens
      // to land in the first 1 KB even if it splits a multi-byte character.
      let summary = `Saved ${finalDest} (${formatSize(total)}, ${mime}) from ${parsedUrl.href}`;
      const sample = params.save?.sample ?? true;
      if (sample && total > 0 && isTextualMime(mime)) {
        const previewBytes = buf.subarray(0, Math.min(SAMPLE_BYTES, total));
        const previewText = new TextDecoder('utf-8', { fatal: false }).decode(previewBytes);
        summary += `\n\nPreview (first ${formatSize(previewBytes.byteLength)}):\n${previewText}`;
      }

      return {
        content: [{ type: 'text', text: summary }],
        details: {},
      };
    } finally {
      // Always remove the abort listener 鈥?fires whether the body succeeded,
      // threw, or was cancelled. Mirrors the AbortController itself living
      // only inside this try.
      signal?.removeEventListener('abort', onAbort);
    }
  },
};

/** Build a RequestInit from the agent-supplied subset. Filters to only the
 *  fields we accept so we never accidentally forward unsanitized properties
 *  to fetch. */
function buildRequestInit(
  init: Static<typeof FsSaveUrlInit> | undefined,
  signal: AbortSignal,
): RequestInit {
  const out: RequestInit = { signal };
  if (!init) return out;
  if (init.method) out.method = init.method;
  if (init.headers) out.headers = init.headers;
  if (init.body !== undefined) out.body = init.body;
  if (init.redirect) out.redirect = init.redirect;
  if (init.referrer !== undefined) out.referrer = init.referrer;
  if (init.referrerPolicy !== undefined) out.referrerPolicy = init.referrerPolicy as ReferrerPolicy;
  if (init.credentials) out.credentials = init.credentials;
  if (init.mode) out.mode = init.mode;
  return out;
}

/** Derive a filename for a directory-style `dest`. Tries in order:
 *  1. RFC 6266 / RFC 5987 `Content-Disposition` `filename*=` then `filename=`
 *  2. The URL pathname's last segment, but only if it has a `.` (so we
 *     don't end up with `download` from a path like `/api/download`)
 *  3. `Untitled-<timestamp>.<ext from MIME>` as the final fallback
 *
 *  Output is always sanitized so path separators and `..` can't escape the
 *  caller's `dest` directory. */
function deriveFilename(
  url: URL,
  contentDisposition: string | null,
  mime: string,
): string {
  // 1. Content-Disposition 鈥?server knows best when present.
  const fromCd = parseContentDispositionFilename(contentDisposition);
  if (fromCd) {
    const safe = sanitizeFilename(fromCd);
    if (safe) return safe;
  }

  // 2. URL last path segment, only if it carries an extension.
  try {
    const segments = url.pathname.split('/').filter(Boolean);
    const last = segments[segments.length - 1];
    if (last) {
      const decoded = decodeURIComponent(last);
      if (decoded.includes('.')) {
        const safe = sanitizeFilename(decoded);
        if (safe) return safe;
      }
    }
  } catch {
    // decodeURIComponent can throw on malformed input 鈥?just fall through.
  }

  // 3. Fallback. Timestamp keeps successive saves to the same dir distinct.
  return `Untitled-${Date.now()}.${extensionForMime(mime)}`;
}

/** Pull the filename out of a `Content-Disposition` header. RFC 6266 says
 *  the RFC 5987-encoded `filename*` parameter wins over the legacy ASCII
 *  `filename` when both are present. Both regexes anchor on a parameter
 *  boundary (`^` or `;`) so we never match the value half of an adjacent
 *  parameter like `xfilename=...`. */
function parseContentDispositionFilename(header: string | null): string | null {
  if (!header) return null;
  // filename*=<charset>'<lang>'<percent-encoded>  (RFC 5987)
  const star = header.match(/(?:^|;)\s*filename\*\s*=\s*([^']*)'[^']*'([^;]+)/i);
  if (star) {
    const charset = (star[1] ?? '').toUpperCase();
    // RFC 5987 forbids quoting the ext-value, but tolerate non-conforming
    // servers that wrap it in quotes anyway.
    const encoded = (star[2] ?? '').trim().replace(/^"|"$/g, '');
    if (charset === '' || charset === 'UTF-8' || charset === 'US-ASCII') {
      try { return decodeURIComponent(encoded); } catch { /* malformed, fall through */ }
    }
  }
  // filename="..." or filename=...
  const plain = header.match(/(?:^|;)\s*filename\s*=\s*("([^"]*)"|([^;]+))/i);
  if (plain) {
    return (plain[2] ?? plain[3] ?? '').trim() || null;
  }
  return null;
}

/** Sanitize a filename string so it cannot escape its parent directory.
 *  Strips path separators, null bytes, and leading dots (so `.htaccess`
 *  becomes `htaccess` 鈥?acceptable trade-off; the rule also kills the `.`
 *  / `..` special cases); collapses `..` sequences; caps length so a
 *  pathological multi-KB filename from a misbehaving server can't poison
 *  the VFS file tree. Returns empty string if nothing usable remains. */
function sanitizeFilename(name: string): string {
  const cleaned = name
    .replace(/[/\\\0]/g, '_')
    .replace(/\.\.+/g, '_')
    .replace(/^\.+/, '')
    .trim();
  // 255 chars is the typical filesystem limit; IndexedDB doesn't enforce
  // it but downstream UI (breadcrumbs, file tree) renders poorly past it.
  return cleaned.slice(0, 255);
}

import { Type } from 'typebox';
import type { AgentTool, AgentToolResult } from '@earendil-works/pi-agent-core';
import { TOOL_FS_SEARCH } from '@/lib/types';
import { vfs } from '@/lib/vfs';
import { walkDir, globMatch, isBinaryContent, MAX_SEARCH_RESULTS } from './fs-helpers';

const FsSearchParameters = Type.Object({
  pattern: Type.String({
    description:
      'Search pattern. For mode "name": a glob pattern matched against file paths (e.g. "**/*.ts", "src/**/*.json"). ' +
      'For mode "content": a regular expression matched against file contents (e.g. "TODO|FIXME", "function\\s+main").',
  }),
  path: Type.Optional(Type.String({
    description: 'Directory to search in. Defaults to "/" (entire filesystem). Use to narrow the search scope.',
  })),
  mode: Type.Union([Type.Literal('name'), Type.Literal('content')], {
    description: '"name" to search file paths by glob pattern, "content" to search file contents by regex.',
  }),
  case_sensitive: Type.Optional(Type.Boolean({
    description: 'Whether content search is case-sensitive. Default: false. Only applies to mode "content".',
  })),
});

export const fsSearchTool: AgentTool<typeof FsSearchParameters> = {
  name: TOOL_FS_SEARCH,
  label: 'Search Files',
  description:
    'Search the virtual filesystem by file name (glob) or file content (regex). ' +
    'Mode "name": matches file paths against a glob pattern (e.g. "**/*.ts"). ' +
    'Mode "content": searches file contents with a regular expression. ' +
    `Returns up to ${MAX_SEARCH_RESULTS} results.`,
  parameters: FsSearchParameters,

  async execute(_toolCallId, params, signal): Promise<AgentToolResult<{}>> {
    signal?.throwIfAborted();
    const searchRoot = params.path ?? '/';

    if (!(await vfs.exists(searchRoot))) {
      throw new Error(`Directory not found: ${searchRoot}`);
    }

    const allFiles = await walkDir(searchRoot, signal);

    if (params.mode === 'name') {
      const matches = allFiles
        .filter(f => globMatch(params.pattern, f))
        .slice(0, MAX_SEARCH_RESULTS);

      if (matches.length === 0) {
        // 0 鍛戒腑鏄甯哥粨鏋?鈥斺€?pattern 鏄悎娉曠殑锛屽彧鏄病鍖归厤涓奬n        return {
          content: [{ type: 'text', text: `No files matching "${params.pattern}" in ${searchRoot}` }],
          details: {},
        };
      }

      const suffix = matches.length === MAX_SEARCH_RESULTS ? `\n(truncated at ${MAX_SEARCH_RESULTS} results)` : '';
      return {
        content: [{ type: 'text', text: matches.join('\n') + suffix }],
        details: {},
      };
    }

    // mode === 'content'
    const flags = params.case_sensitive ? 'g' : 'gi';
    let regex: RegExp;
    try {
      regex = new RegExp(params.pattern, flags);
    } catch (e) {
      throw new Error(`Invalid regex: ${(e as Error).message}`);
    }

    const results: string[] = [];
    for (const filePath of allFiles) {
      if (results.length >= MAX_SEARCH_RESULTS) break;
      signal?.throwIfAborted();
      try {
        const raw = await vfs.readFile(filePath);
        const data = raw instanceof Uint8Array ? raw : new TextEncoder().encode(raw as string);
        if (isBinaryContent(data)) continue;
        const content = new TextDecoder().decode(data);
        const lines = content.split('\n');
        for (let i = 0; i < lines.length; i++) {
          if (results.length >= MAX_SEARCH_RESULTS) break;
          regex.lastIndex = 0;
          if (regex.test(lines[i])) {
            results.push(`${filePath}:${i + 1}: ${lines[i].trim()}`);
          }
        }
      } catch {
        // 璺宠繃鏃犳硶璇诲彇鐨勬枃浠讹紙鎹熷潖 / 鏉冮檺闂锛夛紝涓嶈鍗曚釜鍧忔枃浠朵腑鏂暣娆℃悳绱n      }
    }

    if (results.length === 0) {
      // 0 鍛戒腑鏄甯哥粨鏋淺n      return {
        content: [{ type: 'text', text: `No matches for /${params.pattern}/ in ${searchRoot}` }],
        details: {},
      };
    }

    const suffix = results.length === MAX_SEARCH_RESULTS ? `\n(truncated at ${MAX_SEARCH_RESULTS} results)` : '';
    return {
      content: [{ type: 'text', text: results.join('\n') + suffix }],
      details: {},
    };
  },
};

import { Type } from 'typebox';
