  })),
  tabId: Type.Number({
    description: 'Required for EVERY action (including wait, wait_hidden, wait_navigation) 鈥?all actions run by injecting into a specific tab. Read it from the `tabId:` line under `[Active Tab]` (or the windows list) in the context block. If no tab ID is available in context, call `tab({ action: "list" })` first to discover one. Never omit, never guess, and never pass 0 or a placeholder value.',
  }),
  steps: Type.Optional(Type.Array(
    Type.Object({
      action: Type.Union([...stepActions], { description: 'Step action. `wait_navigation` not allowed here 鈥?call it separately after the sequence.' }),
      selector: selectorField,
      x: xField,
      y: yField,
      text: textField,
      key: keyField,
      modifiers: modifiersField,
      deltaX: deltaXField,
      deltaY: deltaYField,
      timeout: timeoutField,
      condition: Type.Optional(Type.Union([
        Type.Literal('visible'),
        Type.Literal('hidden'),
      ], { description: 'Skip this step if condition is not met. "visible" = skip if selector element is not visible. "hidden" = skip if selector element is visible.' })),
    }),
    {
      description:
        'Array of interaction steps for "sequence" action. ' +
        'Each step uses the same parameters as the top-level interact tool (selector, x/y, text, key, etc.). ' +
        'Steps are executed in order. Execution stops on the first error.',
