});

// 鈹€鈹€鈹€ In-page interaction function (self-contained) 鈹€鈹€鈹€

/** 鍦ㄩ〉闈笂涓嬫枃涓墽琛屽崟涓氦浜掑姩浣溿€傝嚜鍖呭惈锛屽彲琚?chrome.scripting.executeScript 娉ㄥ叆銆?*/
export function performInteraction(params: {
  action: string;
  selector?: string;
  x?: number;
  y?: number;
  text?: string;
  key?: string;
  modifiers?: string[];
  deltaX?: number;
  deltaY?: number;
  timeout?: number;
}): Promise<string> {
  const { action, selector, x, y, text, key, modifiers, deltaX, deltaY, timeout = 3000 } = params;

  /** Whether the element was found by coordinates (skip scrollIntoView). */
  let resolvedByCoords = false;

  /**
   * 鍏冪礌瀹氫綅鍥為€€閾撅細
   * 1. CSS 閫夋嫨鍣紙selector锛塡n   * 2. 鏂囨湰鍖归厤锛坰elector 浠?"text=" 寮€澶达級
   * 3. Role+Label锛坰elector 浠?"role=" 寮€澶达紝鏍煎紡 role:xxx,label:yyy锛塡n   * 4. 鍧愭爣鍥為€€锛坸/y锛塡n   */
  function getEl(): HTMLElement {
    if (selector) {
      // 1. CSS 閫夋嫨鍣紙鍙兘鍥犻潪鏍囧噯鏍煎紡鎶涘紓甯革紝闇€瑕?try-catch锛塡n      try {
        const el = document.querySelector<HTMLElement>(selector);
        if (el) return el;
      } catch { /* 闈炴爣鍑?selector锛堝 text=xxx锛夛紝缁х画鍥為€€閾?*/ }

      // 2. 鏂囨湰鍖归厤锛歴elector 鏍煎紡 "text=鎻愪氦鎸夐挳"
      if (selector.startsWith('text=')) {
        const searchText = selector.slice(5);
        const found = findByText(searchText);
        if (found) return found;
      }

      // 3. Role+Label锛歴elector 鏍煎紡 "role:button,label:鎻愪氦"
      if (selector.startsWith('role:')) {
        const found = findByRoleLabel(selector);
        if (found) return found;
      }

      // 4. 鍧愭爣鍥為€€
      if (x != null && y != null) {
        const coordEl = document.elementFromPoint(x, y) as HTMLElement | null;
        if (coordEl) {
          resolvedByCoords = true;
          return coordEl;
        }
      }

      throw new Error(`Element not found: ${selector}${x != null && y != null ? ` (coordinate fallback (${x}, ${y}) also failed)` : ''}`);
    }
    if (x != null && y != null) {
      const el = document.elementFromPoint(x, y) as HTMLElement | null;
      if (!el) throw new Error(`No element at coordinates (${x}, ${y})`);
      resolvedByCoords = true;
      return el;
    }
    throw new Error('Either selector or x/y coordinates are required.');
  }

  /** 閫氳繃鍙鏂囨湰鍐呭鏌ユ壘鍏冪礌 */
  function findByText(searchText: string): HTMLElement | null {
    // 浼樺厛鍖归厤鎸夐挳/閾炬帴/鏍囩鐨勬枃鏈琝n    const candidates = document.querySelectorAll<HTMLElement>(
      'button, a, label, span, [role="button"], [role="link"], [role="tab"], h1, h2, h3, h4, h5, h6, option, summary'
    );
    // 绗竴閬嶏細绮剧‘鍖归厤
    for (const el of candidates) {
      if (el.textContent?.trim() === searchText) {
        return el;
      }
    }
    // 绗簩閬嶏細瀛愪覆鍖归厤锛堜綔涓?fallback锛岄伩鍏嶈鍖归厤杩囩煭鏂囨湰锛塡n    if (searchText.length >= 2) {
      for (const el of candidates) {
        const text = el.textContent?.trim() ?? '';
        if (text.length > searchText.length && text.includes(searchText)) {
          return el;
        }
      }
    }
    // 鍥為€€鍒?XPath 鍏ㄦ枃鎼滅储
    try {
      const xpath = `//*[contains(text(), ${xpathEscape(searchText)})]`;
      const result = document.evaluate(
        xpath, document, null,
        XPathResult.FIRST_ORDERED_NODE_TYPE, null,
      );
      return result.singleNodeValue as HTMLElement | null;
    } catch {
      return null;
    }
  }

  /** 閫氳繃 role + label 鏌ユ壘鍏冪礌锛屾牸寮?"role:button,label:鎻愪氦" */
  function findByRoleLabel(selectorStr: string): HTMLElement | null {
    const parts = selectorStr.slice(5).split(','); // 鍘绘帀 "role:" 鍓嶇紑
    let role = '';
    let label = '';
    for (const part of parts) {
      if (part.startsWith('label:')) {
        label = part.slice(6);
      } else if (!role) {
        role = part;
      }
    }
    if (role) {
      const selector = label
        ? `[role="${role}"][aria-label*="${cssEscape(label)}"]`
        : `[role="${role}"]`;
      const el = document.querySelector<HTMLElement>(selector);
      if (el) return el;
    }
    return null;
  }

  /** XPath 瀛楃涓茶浆涔?*/
  function xpathEscape(str: string): string {
    if (!str.includes("'")) return `'${str}'`;
    if (!str.includes('"')) return `"${str}"`;
    return `concat('${str.replace(/'/g, "',\"'\",'")}')`;
  }

  /** CSS 閫夋嫨鍣ㄧ壒娈婂瓧绗﹁浆涔?*/
  function cssEscape(str: string): string {
    return str.replace(/([[\]{}()*+?.\\^$|])/g, '\\$1');
  }

  /** Description of what was targeted, for result messages. */
  const targetDesc = selector ?? `(${x}, ${y})`;

  function modInit() {
    return {
      ctrlKey: modifiers?.includes('ctrl') ?? false,
      shiftKey: modifiers?.includes('shift') ?? false,
      altKey: modifiers?.includes('alt') ?? false,
      metaKey: modifiers?.includes('meta') ?? false,
    };
  }

  /**
   * Map `KeyboardEvent.key` 鈫?legacy `keyCode` / `which` numeric value.
   *
   * `new KeyboardEvent(type, { key })` does NOT auto-derive `keyCode` 鈥?it
   * stays `0` unless explicitly set. Lots of real-world pages (鐧惧害鎼滅储妗嗐€乗n   * 鑰?jQuery 鎻掍欢銆丅aidu/Alipay 鍐呭祵缁勪欢) still gate behavior on
   * `e.keyCode === 13` / `=== 8`, so a synthetic event with `keyCode: 0`
   * is silently ignored. We populate it best-effort.
   *
   * Naming key table covers the keys an automation agent realistically
   * sends. For single-character keys we approximate: letters 鈫?uppercase
   * char code (matches the physical-key semantics of keyCode regardless of
   * the typed case), digits 鈫?char code. Shifted symbols (`!`, `@`, 鈥?
   * fall through to char code 鈥?not the unshifted physical-key code per
   * spec, but agents almost never `keypress` a single shifted symbol.
   */
  function keyCodeFor(k: string): number {
    const named: Record<string, number> = {
      Backspace: 8, Tab: 9, Enter: 13,
      Shift: 16, Control: 17, Alt: 18,
      Pause: 19, CapsLock: 20, Escape: 27, Space: 32,
      PageUp: 33, PageDown: 34, End: 35, Home: 36,
      ArrowLeft: 37, ArrowUp: 38, ArrowRight: 39, ArrowDown: 40,
      Insert: 45, Delete: 46,
      Meta: 91, ContextMenu: 93,
      F1: 112, F2: 113, F3: 114, F4: 115, F5: 116, F6: 117,
      F7: 118, F8: 119, F9: 120, F10: 121, F11: 122, F12: 123,
      NumLock: 144, ScrollLock: 145,
      ';': 186, '=': 187, ',': 188, '-': 189, '.': 190, '/': 191, '`': 192,
      '[': 219, '\\': 220, ']': 221, "'": 222,
    };
    if (k in named) return named[k];
    // Spec spelling for spacebar is the literal " "; the friendly alias
    // "Space" is also accepted because agents commonly invent that name.
    if (k === ' ') return 32;
    if (k.length === 1) {
      const c = k.charCodeAt(0);
      // Letters: keyCode is the uppercase code regardless of typed case.
      if (c >= 0x61 && c <= 0x7A) return c - 32; // a-z 鈫?A-Z
      return c;
    }
    return 0;
  }

  /**
   * Map `KeyboardEvent.key` 鈫?DOM `KeyboardEvent.code` (physical key id,
   * layout-independent). Modern shortcut libs (tinykeys, CodeMirror 6) read
   * `code` rather than `key`. Best-effort: letters 鈫?`Key{X}`, digits 鈫抃n   * `Digit{n}`, named keys 鈫?table lookup, otherwise empty string.
   */
  function domCodeFor(k: string): string {
    const named: Record<string, string> = {
      Backspace: 'Backspace', Tab: 'Tab', Enter: 'Enter',
      Shift: 'ShiftLeft', Control: 'ControlLeft', Alt: 'AltLeft',
      Pause: 'Pause', CapsLock: 'CapsLock', Escape: 'Escape',
      PageUp: 'PageUp', PageDown: 'PageDown', End: 'End', Home: 'Home',
      ArrowLeft: 'ArrowLeft', ArrowUp: 'ArrowUp',
      ArrowRight: 'ArrowRight', ArrowDown: 'ArrowDown',
      Insert: 'Insert', Delete: 'Delete',
      Meta: 'MetaLeft', ContextMenu: 'ContextMenu',
      F1: 'F1', F2: 'F2', F3: 'F3', F4: 'F4', F5: 'F5', F6: 'F6',
      F7: 'F7', F8: 'F8', F9: 'F9', F10: 'F10', F11: 'F11', F12: 'F12',
      NumLock: 'NumLock', ScrollLock: 'ScrollLock',
      ';': 'Semicolon', '=': 'Equal', ',': 'Comma', '-': 'Minus',
      '.': 'Period', '/': 'Slash', '`': 'Backquote',
      '[': 'BracketLeft', '\\': 'Backslash', ']': 'BracketRight',
      "'": 'Quote',
    };
    if (k in named) return named[k];
    if (k === ' ') return 'Space';
    if (k.length === 1) {
      const c = k.charCodeAt(0);
      if ((c >= 0x41 && c <= 0x5A) || (c >= 0x61 && c <= 0x7A)) {
        return 'Key' + k.toUpperCase();
      }
      if (c >= 0x30 && c <= 0x39) return 'Digit' + k;
    }
    return '';
  }

  /**
   * Resolve the target element + concrete click point for pointer-based actions
   * (click / dblclick / rightclick / hover). Unlike `getEl()` this always
   * produces a `{ clientX, clientY }` pair so downstream `MouseEvent` /
   * `PointerEvent` dispatches carry real coordinates 鈥?many pages read
   * `event.clientX/Y` (canvas, maps, editors, Radix/shadcn popovers) and
   * silently mis-handle events with the default 0,0.
   *
   * Selector path: scroll into view, point = center of bounding rect.
   * Coordinate path: auto-correct DPR mistakes (agents reading screenshots
   * often pass screenshot-pixel coords), then pick the topmost element whose
   * `pointer-events !== none` via `elementsFromPoint` 鈥?`elementFromPoint`
   * alone can return a transparent overlay that swallows the event.
   */
  function resolveTarget(): { el: HTMLElement; point: { clientX: number; clientY: number } } {
    if (selector) {
      // 1. CSS 閫夋嫨鍣紙鍙兘鍥犻潪鏍囧噯鏍煎紡鎶涘紓甯革紝闇€瑕?try-catch锛塡n      try {
        const el = document.querySelector<HTMLElement>(selector);
        if (el) {
          el.scrollIntoView({ block: 'center', behavior: 'instant' });
          const r = el.getBoundingClientRect();
          return { el, point: { clientX: r.left + r.width / 2, clientY: r.top + r.height / 2 } };
        }
      } catch { /* 闈炴爣鍑?selector锛堝 text=xxx锛夛紝缁х画鍥為€€閾?*/ }

      // 2. 鏂囨湰鍖归厤锛歴elector 鏍煎紡 "text=鎻愪氦鎸夐挳"
      if (selector.startsWith('text=')) {
        const searchText = selector.slice(5);
        const found = findByText(searchText);
        if (found) {
          found.scrollIntoView({ block: 'center', behavior: 'instant' });
          const r = found.getBoundingClientRect();
          return { el: found, point: { clientX: r.left + r.width / 2, clientY: r.top + r.height / 2 } };
        }
      }

      // 3. Role+Label锛歴elector 鏍煎紡 "role:button,label:鎻愪氦"
      if (selector.startsWith('role:')) {
        const found = findByRoleLabel(selector);
        if (found) {
          found.scrollIntoView({ block: 'center', behavior: 'instant' });
          const r = found.getBoundingClientRect();
          return { el: found, point: { clientX: r.left + r.width / 2, clientY: r.top + r.height / 2 } };
        }
      }

      // 4. 鍧愭爣鍥為€€
      if (x != null && y != null) {
        let cx = x;
        let cy = y;
        const dpr = window.devicePixelRatio || 1;
        if (dpr > 1
          && (cx > window.innerWidth || cy > window.innerHeight)
          && cx / dpr <= window.innerWidth
          && cy / dpr <= window.innerHeight) {
          cx = cx / dpr;
          cy = cy / dpr;
        }
        const stack = document.elementsFromPoint(cx, cy) as HTMLElement[];
        if (stack.length > 0) {
          const coordEl = stack.find(e => getComputedStyle(e).pointerEvents !== 'none') ?? stack[0];
          return { el: coordEl, point: { clientX: cx, clientY: cy } };
        }
      }

      throw new Error(`Element not found: ${selector}${x != null && y != null ? ` (coordinate fallback (${x}, ${y}) also failed)` : ''}`);
    }
    if (x != null && y != null) {
      let cx = x;
      let cy = y;
      const dpr = window.devicePixelRatio || 1;
      if (dpr > 1
        && (cx > window.innerWidth || cy > window.innerHeight)
        && cx / dpr <= window.innerWidth
        && cy / dpr <= window.innerHeight) {
        cx = cx / dpr;
        cy = cy / dpr;
      }
      const stack = document.elementsFromPoint(cx, cy) as HTMLElement[];
      if (stack.length === 0) throw new Error(`No element at coordinates (${x}, ${y})`);
      const el = stack.find(e => getComputedStyle(e).pointerEvents !== 'none') ?? stack[0];
      return { el, point: { clientX: cx, clientY: cy } };
    }
    throw new Error('Either selector or x/y coordinates are required.');
  }

  /**
   * Dispatch a realistic pointer + mouse event sequence at a specific point.
   * Modern frameworks (React synthetic events, Radix, Floating UI, CodeMirror,
   * Monaco, map libs, canvas games) split their handlers across PointerEvents
   * and MouseEvents and read `clientX/Y` for hit-testing 鈥?sending only a bare
   * `el.click()` at (0,0) misses most of them.
   */
  function dispatchPointerSequence(
    el: HTMLElement,
    point: { clientX: number; clientY: number },
    kind: 'click' | 'dblclick' | 'rightclick' | 'hover',
  ): void {
    const button = kind === 'rightclick' ? 2 : 0;
    // `buttons` is the set of buttons currently held. During press-phase events
    // (pointerdown, mousedown) it is the button's bitmask; during release-phase
    // events (pointerup, mouseup, click, contextmenu) it must go back to 0.
    // Drag-detection libraries (dnd-kit, react-dnd, some canvas apps) gate on
    // this 鈥?a non-zero `buttons` on the up-phase confuses them.
    const pressedBit = kind === 'rightclick' ? 2 : (kind === 'hover' ? 0 : 1);
    const baseInit = {
      bubbles: true, composed: true, cancelable: true,
      view: window, button,
      clientX: point.clientX, clientY: point.clientY,
      ...modInit(),
    };
    const mDown: MouseEventInit = { ...baseInit, buttons: pressedBit };
    const mUp: MouseEventInit = { ...baseInit, buttons: 0 };
    const pExtras = {
      pointerId: 1, pointerType: 'mouse', isPrimary: true,
      width: 1, height: 1,
    };
    const pDown: PointerEventInit = { ...mDown, ...pExtras, pressure: kind === 'hover' ? 0 : 0.5 };
    const pUp: PointerEventInit = { ...mUp, ...pExtras, pressure: 0 };

    if (kind === 'hover') {
      el.dispatchEvent(new PointerEvent('pointerover', pUp));
      el.dispatchEvent(new MouseEvent('mouseover', mUp));
      el.dispatchEvent(new PointerEvent('pointerenter', { ...pUp, bubbles: false }));
      el.dispatchEvent(new MouseEvent('mouseenter', { ...mUp, bubbles: false }));
      el.dispatchEvent(new PointerEvent('pointermove', pUp));
      el.dispatchEvent(new MouseEvent('mousemove', mUp));
      return;
    }

    el.dispatchEvent(new PointerEvent('pointerdown', pDown));
    el.dispatchEvent(new MouseEvent('mousedown', mDown));
    el.dispatchEvent(new PointerEvent('pointerup', pUp));
    el.dispatchEvent(new MouseEvent('mouseup', mUp));

    if (kind === 'rightclick') {
      // Spec note: `contextmenu` ordering varies across platforms (Windows fires
      // between mousedown and mouseup, Linux/macOS fire after mouseup). We use
      // the Linux/macOS order, which matches what most modern libs expect.
      el.dispatchEvent(new MouseEvent('contextmenu', mUp));
      return;
    }

    el.dispatchEvent(new MouseEvent('click', { ...mUp, detail: 1 }));
    if (kind === 'dblclick') {
      // Second click + dblclick, per the DOM spec sequence.
      el.dispatchEvent(new PointerEvent('pointerdown', pDown));
      el.dispatchEvent(new MouseEvent('mousedown', mDown));
      el.dispatchEvent(new PointerEvent('pointerup', pUp));
      el.dispatchEvent(new MouseEvent('mouseup', mUp));
      el.dispatchEvent(new MouseEvent('click', { ...mUp, detail: 2 }));
      el.dispatchEvent(new MouseEvent('dblclick', { ...mUp, detail: 2 }));
    }
  }

  switch (action) {
    case 'click': {
      const { el, point } = resolveTarget();
      dispatchPointerSequence(el, point, 'click');
      return Promise.resolve(`Clicked: ${targetDesc}`);
    }

    case 'dblclick': {
      const { el, point } = resolveTarget();
      dispatchPointerSequence(el, point, 'dblclick');
      return Promise.resolve(`Double-clicked: ${targetDesc}`);
    }

    case 'rightclick': {
      const { el, point } = resolveTarget();
      dispatchPointerSequence(el, point, 'rightclick');
      return Promise.resolve(`Right-clicked: ${targetDesc}`);
    }

    case 'hover': {
      const { el, point } = resolveTarget();
      dispatchPointerSequence(el, point, 'hover');
      return Promise.resolve(`Hovered: ${targetDesc}`);
    }

    case 'type': {
      const el = getEl();
      el.scrollIntoView({ block: 'center', behavior: 'instant' });
      el.focus();
      if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) {
        const proto = el instanceof HTMLTextAreaElement
          ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
        const nativeSetter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
        if (nativeSetter) {
          nativeSetter.call(el, (el.value ?? '') + (text ?? ''));
        } else {
          el.value = (el.value ?? '') + (text ?? '');
        }
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
      } else if (el.isContentEditable) {
        document.execCommand('insertText', false, text ?? '');
      }
      return Promise.resolve(`Typed "${text}" into: ${selector}`);
    }

    case 'clear': {
      const el = getEl();
      el.focus();
      if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) {
        const proto = el instanceof HTMLTextAreaElement
          ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
        const nativeSetter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
        if (nativeSetter) {
          nativeSetter.call(el, '');
        } else {
          el.value = '';
        }
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
      } else if (el.isContentEditable) {
        el.focus();
        document.execCommand('selectAll', false);
        document.execCommand('delete', false);
      }
      return Promise.resolve(`Cleared: ${selector}`);
    }

    case 'select': {
      const el = getEl();
      if (el instanceof HTMLSelectElement) {
        const option = Array.from(el.options).find(o => o.text === text || o.value === text);
        if (!option) throw new Error(`Option not found: ${text}`);
        el.value = option.value;
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
        return Promise.resolve(`Selected "${text}" in: ${selector}`);
      }
      throw new Error(`Element is not a <select>: ${selector}`);
    }

    case 'scroll': {
      const target = selector ? getEl() : document.documentElement;
      target.scrollBy({ left: deltaX ?? 0, top: deltaY ?? 300, behavior: 'smooth' });
      return Promise.resolve(
        selector
          ? `Scrolled ${selector} by (${deltaX ?? 0}, ${deltaY ?? 300})`
          : `Scrolled page by (${deltaX ?? 0}, ${deltaY ?? 300})`,
      );
    }

    case 'focus': {
      const el = getEl();
      if (!resolvedByCoords) el.scrollIntoView({ block: 'center', behavior: 'instant' });
      el.focus();
      if (document.activeElement !== el) {
        return Promise.resolve(
          `Error: Element did not accept focus (not focusable): ${targetDesc}. ` +
          `Target an actual input/textarea/button/contenteditable, or an element with tabindex.`
        );
      }
      return Promise.resolve(`Focused: ${targetDesc}`);
    }

    case 'keypress': {
      if (!key) throw new Error('"key" is required for keypress action.');
      // If selector provided, focus that element first so the keystroke is guaranteed
      // to reach the intended target (activeElement may have drifted since last action).
      let target: Element;
      if (selector) {
        const el = getEl();
        el.scrollIntoView({ block: 'center', behavior: 'instant' });
        el.focus();
        if (document.activeElement !== el) {
          return Promise.resolve(
            `Error: Element did not accept focus, cannot send keypress reliably: ${selector}. ` +
            `Target an actual input/textarea/button/contenteditable 鈥?a wrapper div will receive the event but won't trigger form submit.`
          );
        }
        target = el;
      } else {
        target = document.activeElement ?? document.body;
      }
      const code = keyCodeFor(key);
      const init: KeyboardEventInit = {
        key,
        code: domCodeFor(key),
        keyCode: code,
        which: code,
        bubbles: true,
        cancelable: true,
        composed: true,
        ...modInit(),
      };
      target.dispatchEvent(new KeyboardEvent('keydown', init));
      // Real browsers only fire `keypress` for character-producing keys.
      // Modifier keys (Shift/Control/Alt/Meta/CapsLock/NumLock/ScrollLock)
      // and non-printable named keys (Backspace/Tab/Escape/Arrow*/F*/Home/
      // End/PageUp/PageDown/Delete/Insert) do NOT get a keypress. Enter is
      // kept by all engines for back-compat.
      if (key.length === 1 || key === 'Enter') {
        target.dispatchEvent(new KeyboardEvent('keypress', init));
      }
      target.dispatchEvent(new KeyboardEvent('keyup', init));
      return Promise.resolve(selector ? `Pressed key ${key} on: ${selector}` : `Pressed key: ${key}`);
    }

    case 'wait': {
      if (!selector) throw new Error('"selector" is required for wait action.');
      return new Promise<string>((resolve, reject) => {
        const existing = document.querySelector(selector);
        if (existing) { resolve(`Element found: ${selector}`); return; }
        const timer = setTimeout(() => {
          observer.disconnect();
          reject(new Error(`Timeout: element ${selector} not found within ${timeout}ms`));
        }, timeout);
        const observer = new MutationObserver(() => {
          if (document.querySelector(selector)) {
            observer.disconnect();
            clearTimeout(timer);
            resolve(`Element appeared: ${selector}`);
          }
        });
        observer.observe(document.body, { childList: true, subtree: true });
      });
    }

    case 'wait_hidden': {
      if (!selector) throw new Error('"selector" is required for wait_hidden action.');
      const isHidden = (sel: string) => {
        const el = document.querySelector<HTMLElement>(sel);
        if (!el) return true;
        const style = getComputedStyle(el);
        return style.display === 'none' || style.visibility === 'hidden';
      };
      return new Promise<string>((resolve, reject) => {
        if (isHidden(selector)) { resolve(`Element already hidden: ${selector}`); return; }
        const timer = setTimeout(() => {
          observer.disconnect();
          reject(new Error(`Timeout: element ${selector} still visible after ${timeout}ms`));
        }, timeout);
        const observer = new MutationObserver(() => {
          if (isHidden(selector)) {
            observer.disconnect();
            clearTimeout(timer);
            resolve(`Element disappeared: ${selector}`);
          }
        });
        observer.observe(document.body, { childList: true, subtree: true, attributes: true });
      });
    }

    case 'drag': {
      // Drag from source element/coords to target element/coords
      // Uses selector/x+y for source, deltaX/deltaY for offset
      const sourceEl = getEl();
      if (!resolvedByCoords) sourceEl.scrollIntoView({ block: 'center', behavior: 'instant' });

      const sourceRect = sourceEl.getBoundingClientRect();
      const startX = x ?? (sourceRect.left + sourceRect.width / 2);
      const startY = y ?? (sourceRect.top + sourceRect.height / 2);
      const endX = startX + (deltaX ?? 0);
      const endY = startY + (deltaY ?? 0);

      // Fire drag events sequence: mousedown 鈫?mousemove 鈫?mouseup
      const downEvent = new MouseEvent('mousedown', {
        bubbles: true, cancelable: true,
        clientX: startX, clientY: startY,
        ...modInit(),
      });
      sourceEl.dispatchEvent(downEvent);

      // Simulate drag movement with intermediate mousemove events
      const steps = 5;
      for (let i = 1; i <= steps; i++) {
        const progress = i / steps;
        const moveX = startX + (endX - startX) * progress;
        const moveY = startY + (endY - startY) * progress;
        const moveEvent = new MouseEvent('mousemove', {
          bubbles: true, cancelable: true,
          clientX: moveX, clientY: moveY,
          ...modInit(),
        });
        document.dispatchEvent(moveEvent);
      }

      const upEvent = new MouseEvent('mouseup', {
        bubbles: true, cancelable: true,
        clientX: endX, clientY: endY,
        ...modInit(),
      });
      document.dispatchEvent(upEvent);

      return Promise.resolve(
        `Dragged ${targetDesc} by (${deltaX ?? 0}, ${deltaY ?? 0})`
      );
    }

    default:
      // Resolve (don't reject) 鈥?chrome.scripting.executeScript silently swallows
      // rejections from injected functions, which would surface to the model as an
      // empty success and trigger hallucinations. Returning the error as a string
      // ensures the model sees the failure.
      return Promise.resolve(
        `Error: Unknown action "${action}".`
      );
  }
}

// 鈹€鈹€鈹€ Tool definition 鈹€鈹€鈹€

export const interactTool: AgentTool<typeof InteractParameters> = {
  name: TOOL_INTERACT,
  label: 'Interact',
  description:
    'Simulate user interactions on a browser tab (defaults to the active tab). ' +
    'Actions: click, dblclick, rightclick, hover (target by CSS selector or x/y coordinates), ' +
    'focus (give an element keyboard focus without clicking 鈥?useful before keypress, or to reveal focus-only UI like autocompletes), ' +
    'type (text input), clear, select (dropdown), scroll (page or element via selector), ' +
    'keypress (pass a selector to focus that element first 鈥?strongly recommended when submitting forms via Enter), ' +
    'drag (drag an element by offset using deltaX/deltaY, or from x/y coordinates), ' +
    'wait (element appears), wait_hidden (element disappears), ' +
    'wait_navigation (page load completes). ' +
    'Selector fallback chain: CSS selector 鈫?text=visible text 鈫?role:roleName,label:ariaLabel 鈫?x/y coordinates. ' +
    'Use "text=Submit" to find by visible text, "role:button,label:Submit" by role+label. ' +
    'For element discovery, use the dedicated `inspect` tool 鈥?it returns absolute selectors, role, label, and state. ' +
    'Use "sequence" with a "steps" array to batch multiple actions in one call ' +
    '(e.g. click 鈫?wait 鈫?type 鈫?keypress). Each step supports the same parameters. ' +
    'Steps support a "condition" field: "visible" skips if selector element is not visible, "hidden" skips if visible. ' +
    'Execution stops on the first error and returns all results so far. ' +
    'Elements are scrolled into view automatically before interaction.',
  parameters: InteractParameters,

  async execute(_toolCallId, params, signal): Promise<AgentToolResult<{}>> {
    signal?.throwIfAborted();
    const tabId = params.tabId;

    // wait_navigation runs in extension context (not in-page)
    if (params.action === 'wait_navigation') {
      const result = await waitForNavigation(tabId, params.timeout ?? 3000);
      return {
        content: [{ type: 'text', text: result }],
        details: {},
      };
    }

    // sequence: run multiple steps in order, in-page
    if (params.action === 'sequence') {
      // Some models (notably DeepSeek) serialize nested array params as a JSON
      // string instead of a real array. Without this rescue we'd iterate the
      // string char-by-char, injecting hundreds of bogus actions before the
      // model sees any feedback. Try to parse, otherwise fail loudly with a
      // message that names the real problem.
      let steps = params.steps as unknown;
      if (typeof steps === 'string') {
        try {
          steps = JSON.parse(steps);
        } catch {
          throw new Error('"steps" was passed as a string but is not valid JSON. Pass it as a JSON array of step objects, e.g. [{"action":"click","selector":"#btn"}].');
        }
      }
      if (!Array.isArray(steps)) {
        throw new Error(`"steps" must be a JSON array of step objects (received ${typeof steps}).`);
      }
      if (steps.length === 0) {
        throw new Error('"steps" array is required for sequence action.');
      }

      const frameId = params.frameId;
      const results: string[] = [];

      for (let i = 0; i < steps.length; i++) {
        signal?.throwIfAborted();
        const step = steps[i] as Record<string, unknown>;

        // 鏉′欢妫€鏌ワ細濡傛灉 step 鏈?condition 瀛楁锛屽厛鍦ㄩ〉闈腑妫€鏌n        if (step.condition && step.selector) {
          const conditionResult = await executeInTabWithArgs(
            tabId,
            checkElementVisibility,
            [{ selector: step.selector as string, condition: step.condition as string }],
            frameId,
          );
          if (!conditionResult) {
            results.push(`[${i + 1}] Skipped (condition "${step.condition}" not met for ${step.selector})`);
            continue;
          }
        }

        try {
          const result = await runInPageStep(tabId, step, frameId);
          results.push(`[${i + 1}] ${result}`);
        } catch (err) {
          // 涓€斿け璐ワ細鎶婂凡缁忚窇杩囩殑 step 缁撴灉杩炲悓澶辫触鍘熷洜涓€璧锋姏鍑猴紝璁?agent 鐪嬪埌鍏ㄨ矊
          results.push(`[${i + 1}] Error: ${(err as Error).message}`);
          throw new Error(`Sequence stopped at step ${i + 1}:\n${results.join('\n')}`);
        }
      }

      return {
        content: [{ type: 'text', text: `Sequence completed (${steps.length} steps):\n${results.join('\n')}` }],
        details: {},
      };
    }

    // All other actions run in-page
    const result = await runInPageStep(tabId, params, params.frameId);
    return {
      content: [{ type: 'text', text: result }],
      details: {},
    };
  },
};

/**
 * 鍦ㄧ洰鏍?tab 璺戜竴娆?in-page interaction锛屽苟鎶?chrome.scripting 鐨勪袱绉峔n * 闈欓粯澶辫触閫氶亾杞垚鐪熸鐨?throw锛歕n *
 * 1. 娉ㄥ叆鍑芥暟 `throw new Error(...)` 鈫?chrome.scripting 鍚炴帀 rejection锛孿n *    `executeInTabWithArgs` 杩斿洖 `undefined`銆俓n * 2. 娉ㄥ叆鍑芥暟杩斿洖 `"Error: <msg>"` sentinel 瀛楃涓诧紙`performInteraction`
 *    鍦ㄥ唴閮?catch 鍚庨噰鐢ㄨ繖绉嶆柟寮忎笂鎶ワ紝鍥犱负 reject 浼氳鍚烇級銆俓n *
 * 涓よ€呴兘璁╀笂灞傜湅鍒扮湡鐨勫紓甯革紝pi-agent-core 浼氭妸 `isError: true` 璁惧埌
 * 杩欐 tool call 鐨勭粨鏋滀笂銆俓n */
async function runInPageStep(
  tabId: number,
  step: unknown,
  frameId?: number,
): Promise<string> {
  // `performInteraction` 鑷韩鏍￠獙 step.action锛屽苟瀵规湭鐭?/ 缂哄弬鎯呭喌杩斿洖
  // 甯?"Error:" 鍓嶇紑鐨勫瓧绗︿覆 sentinel锛涜繖閲岀洿鎺ヨ浆浜わ紝涓嬮潰缁熶竴澶勭悊銆俓n  const result = await executeInTabWithArgs(tabId, performInteraction, [step as Parameters<typeof performInteraction>[0]], frameId);
  const action = (step as { action?: string })?.action ?? 'unknown';
  if (result === undefined) {
    throw new Error(`in-page execution of "${action}" returned no result (likely an uncaught exception in the page).`);
  }
  if (typeof result === 'string' && result.startsWith('Error:')) {
    // 鍘绘帀 in-page sentinel 鍓嶇紑锛宨sError 鐜板湪鎵挎媴淇″彿璐ｄ换
    throw new Error(result.slice('Error:'.length).trim());
  }
  return result as string;
}

import type { TSchema } from 'typebox';
import type { AgentTool, AgentToolResult } from '@earendil-works/pi-agent-core';
import type { MCPServerConfig } from '@/lib/storage';
import type { MCPTool } from '@/lib/mcp/client';
import { getMCPManager, ThrottleError } from '@/lib/mcp/manager';

/**
 * Per-tool-call metadata for rendering an MCP App iframe in the chat.
 *
 * Populated by `createMCPAgentTool` whenever the bound MCP tool declares
 * a UI resource (`_meta.ui.resourceUri` per SEP-1865). The sidepanel
 * reads this from `AgentToolResult.details.mcpApp` to:
 *
 *   1. Look up the HTML for `resourceUri` via the BG `mcp_read_resource`
 *      port message (cached at the sidepanel level). Server identity
 *      comes from the sibling `details.server` already on every MCP
 *      tool result 鈥?we deliberately don't duplicate it here.
 *   2. Push `toolInput` to the iframe via `ui/notifications/tool-input`.
 *   3. Push the `CallToolResult` to the iframe via
 *      `ui/notifications/tool-result`. We do NOT persist a second copy of
 *      the result envelope here 鈥?the agent runtime already stores the
 *      `content` blocks on the sibling `ToolResultMessage` (and
 *      `structuredContent` on `details.structured`), so the consumer
 *      synthesises the `CallToolResult` from those fields at render time.
 *      Avoids triplicating the same payload in IndexedDB.
 *
 * Stored alongside the message so re-opening an old chat can re-render
 * the iframe (the HTML itself is re-fetched, not persisted).
 */
export interface MCPAppDetails {
  /** UI resource URI from `_meta.ui.resourceUri`. Always `ui://...` in practice. */
  resourceUri: string;
  /** Verbatim tool call arguments 鈥?pushed to the iframe on init. */
  toolInput: Record<string, unknown>;
}

/**
 * Structural type guard for a tool result that should render as an MCP App
 * iframe. Validates the persisted shape rather than trusting a cast 鈥?DB
 * rows survive code refactors and third-party servers ship arbitrary
 * `_meta`, so a truthy check on `details.mcpApp` is not enough.
 *
 * Sidepanel `details` is typed `any` (per `ToolResultMessage<TDetails = any>`),
 * so this is the boundary where the contract is enforced. Co-located with
 * the producer (`createMCPAgentTool`) so the guard stays in sync if the
 * persisted shape evolves.
 */
export function isMcpAppResult(details: unknown): details is {
  server: { id: string; name: string };
  tool: string;
  /** Optional `structuredContent` set by `createMCPAgentTool`. The guard
   *  doesn't verify its shape (it's `unknown` per MCP spec); declared
   *  here so consumers synthesising a `CallToolResult` can read it
   *  without an extra cast. */
  structured?: unknown;
  mcpApp: MCPAppDetails;
} {
  if (!details || typeof details !== 'object') return false;
  const d = details as { server?: unknown; tool?: unknown; mcpApp?: unknown };
  const server = d.server as { id?: unknown } | undefined;
  const mcpApp = d.mcpApp as { resourceUri?: unknown } | undefined;
  return (
    typeof server?.id === 'string' && server.id.length > 0 &&
    typeof d.tool === 'string' && d.tool.length > 0 &&
    typeof mcpApp?.resourceUri === 'string' && mcpApp.resourceUri.length > 0
  );
}

/**
 * Build an `AgentTool` that proxies to one MCP tool on one server.
 *
 * The agent invokes by name `mcp__<slug>__<toolName>` where `<slug>` is a
 * sanitized form of the server's user-given name (which is enforced unique
 * by the store). Encoding the slug rather than an opaque short id keeps tool
 * calls readable in logs and lets the chat UI render a human label without a
 * runtime registry lookup. See `getToolLabel` in `lib/tools/tool-labels.ts`.
 */
export function createMCPAgentTool(
  server: MCPServerConfig,
  mcpTool: MCPTool,
): AgentTool<TSchema> {
  const slug = slugifyServerName(server.name);
  // Sanitize remote tool name: providers (OpenAI/Anthropic/Gemini) require
  // ^[a-zA-Z0-9_-]+$. Keep the combined name within OpenAI's 64-char limit:
  // `mcp__` (5) + slug (鈮?0) + `__` (2) = 27 prefix chars, leaving 37 for
  // the tool name.
  const safeName = mcpTool.name.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 37);
  if (safeName !== mcpTool.name) {
    console.warn(`[mcp] sanitized tool name "${mcpTool.name}" 鈫?"${safeName}" for server "${server.name}"`);
  }
  const name = `mcp__${slug}__${safeName}`;
  const label = `${server.name} / ${mcpTool.name}`;
  const description = `[MCP: ${server.name}] ${mcpTool.description ?? mcpTool.name}`;
  // MCP tool inputSchema is JSON Schema; TypeBox TSchema is structurally
  // compatible (it's JSON Schema with extra metadata). The cast is safe at
  // the boundary 鈥?the agent runtime treats the schema opaquely.
  const parameters = mcpTool.inputSchema as unknown as TSchema;

  // Type-guard the UI metadata at construction time: only treat the tool
  // as MCP-App-capable when `_meta.ui.resourceUri` is a non-empty string.
  // Third-party MCP servers ship arbitrary `_meta` values; an undefined
  // / non-string slot must not produce a phantom `mcpApp` payload that
  // the renderer would then fail to load.
  //
  // Lenient on the scheme: spec says the URI MUST start with `ui://` but
  // we accept anything non-empty and let `resources/read` surface the
  // real failure. We warn here so an off-spec server is still observable
  // in the BG console rather than producing a silent later-stage error.
  const rawResourceUri = mcpTool._meta?.ui?.resourceUri;
  const uiResourceUri = typeof rawResourceUri === 'string' && rawResourceUri.length > 0
    ? rawResourceUri
    : undefined;
  if (uiResourceUri && !uiResourceUri.startsWith('ui://')) {
    console.warn(`[mcp] tool "${mcpTool.name}" on "${server.name}" has non-ui:// resourceUri "${uiResourceUri}" 鈥?SEP-1865 requires "ui://" scheme`);
  }

  return {
    name,
    label,
    description,
    parameters,
    async execute(_toolCallId, params, signal): Promise<AgentToolResult<{
      server: { id: string; name: string };
      tool: string;
      structured?: unknown;
      mcpApp?: MCPAppDetails;
    }>> {
      signal?.throwIfAborted();
      const manager = getMCPManager();
      try {
        const result = await manager.callTool(server.id, mcpTool.name, params as Record<string, unknown>);
        if (result.isError) {
          // v1 limitation: an errored MCP-App tool call is reported to
          // the LLM via the thrown error but does NOT push a `tool-result`
          // notification to the iframe 鈥?the iframe simply never renders
          // for this call. Per SEP-1865 "Data Passing", strictly the
          // iframe should receive the errored CallToolResult so it can
          // render its own error state, but draw.io and other v1-target
          // apps have nothing useful to render without a successful
          // result anyway. Revisit if a future app needs error-state UX.
          throw new Error(extractText(result.content) || `MCP tool "${mcpTool.name}" returned an error`);
        }
        const toolInput = (params as Record<string, unknown>) ?? {};
        const mcpApp: MCPAppDetails | undefined = uiResourceUri
          ? { resourceUri: uiResourceUri, toolInput }
          : undefined;
        return {
          content: convertContent(result.content),
          details: {
            server: { id: server.id, name: server.name },
            tool: mcpTool.name,
            structured: result.structuredContent,
            ...(mcpApp ? { mcpApp } : {}),
          },
        };
      } catch (err) {
        if (err instanceof ThrottleError) {
          const seconds = Math.max(1, Math.ceil(err.rejection.retryAfterMs / 1000));
          throw new Error(`MCP server "${server.name}" is throttled (${err.rejection.reason}); retry in ${seconds}s`);
        }
        throw err;
      }
    },
  };
}

interface RawContentBlock { type: string; [k: string]: unknown }

function convertContent(blocks: RawContentBlock[]): Array<{ type: 'text'; text: string } | { type: 'image'; data: string; mimeType: string }> {
  const out: Array<{ type: 'text'; text: string } | { type: 'image'; data: string; mimeType: string }> = [];
  for (const block of blocks) {
    if (block.type === 'text' && typeof block.text === 'string') {
      out.push({ type: 'text', text: block.text });
    } else if (block.type === 'image' && typeof block.data === 'string' && typeof block.mimeType === 'string') {
      out.push({ type: 'image', data: block.data, mimeType: block.mimeType });
    } else {
      // audio / resource / unknown 鈥?surface as text so the model sees something.
      out.push({ type: 'text', text: `[unsupported MCP content type: ${block.type}]` });
    }
  }
  if (out.length === 0) out.push({ type: 'text', text: '(empty result)' });
  return out;
}

function extractText(blocks: RawContentBlock[]): string {
  return blocks
    .filter((b) => b.type === 'text' && typeof b.text === 'string')
    .map((b) => b.text as string)
    .join('\n');
}

/**
 * Convert a server's user-facing name into a tool-name-safe slug.
 *
 * Lowercase, ASCII-only ([a-z0-9_-]), capped at 20 chars. The store enforces
 * case-insensitive uniqueness on display names, but two distinct display
 * names CAN slugify to the same value (e.g. "GitHub Personal" and
 * "github_personal"). That collision would surface as a tool-name conflict
 * inside the agent runtime 鈥?acceptable for v1; the user can rename to
 * resolve. Keep this in sync with `parseMCPToolName` in tool-labels.ts.
 */
export function slugifyServerName(name: string): string {
  const slug = name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, '_') // collapse runs of disallowed chars to one '_'
    .replace(/^_+|_+$/g, '')
    .slice(0, 20);
  // Always return at least something 鈥?empty slug would produce `mcp____tool`.
  return slug || 'server';
}

import { Type } from 'typebox';
import type { AgentTool, AgentToolResult } from '@earendil-works/pi-agent-core';
import { TOOL_READ_PAGE } from '@/lib/types';
import { executeInTabWithArgs } from '@/lib/tab-helpers';
import { ensureOffscreen } from './offscreen';
import { isLikelyPdfUrl, pdfRedirectHint } from './pdf';
import type { OffscreenRequest, OffscreenResponse } from '@/entrypoints/offscreen/main';
import { vfs } from '@/lib/vfs';

const ReadPageParameters = Type.Object({
  mode: Type.Union(
    [
      Type.Literal('text'),
      Type.Literal('html'),
      Type.Literal('markdown'),
      Type.Literal('article'),
      Type.Literal('outline'),
    ],
    {
      description:
        'Extraction mode. ' +
        '"markdown" (default): full-page content as markdown 鈥?works for any page type. ' +
        '"article": article/reader-mode extraction as markdown 鈥?use for news, blogs, docs. ' +
        '"outline": page structure overview 鈥?shows visual regions with selectors, positions, interactive element counts, and text previews. Lower token cost than markdown/html. Use to understand page layout before acting. ' +
        '"text": plain innerText. ' +
        '"html": cleaned innerHTML (no script/style/svg).',
      default: 'markdown',
    },
  ),
  selector: Type.Optional(
    Type.String({
      description:
        'CSS selector to limit extraction scope. Defaults to document.body.',
    }),
  ),
  maxLength: Type.Optional(
    Type.Number({
      description:
        'Maximum character length of the returned content. Defaults to 20000. ' +
        'If you expect or observe truncation, raise this value in a single call (a few times the default is typically enough) 鈥?do NOT loop the tool with multiple selectors or repeated calls to stitch a larger result together. ' +
        'Truncated responses end with a "...(truncated at N chars)" marker. ' +
        'Ignored entirely when `outputPath` is set.',
    }),
  ),
  outputPath: Type.Optional(
    Type.String({
      description:
        'If set, the full extracted content is written to this absolute VFS path (e.g. "/workspaces/abc/page.md") and only a short summary is returned to you. ' +
        'Use this whenever the natural extraction is large enough that returning it inline would bloat the conversation 鈥?the bytes go straight to disk and never enter your context. ' +
        '`maxLength` is ignored when this is set: the full extraction is written regardless of size, then a 1KB preview is returned. ' +
        'Parent directories are created automatically. Existing files are overwritten.',
    }),
  ),
  frameId: Type.Optional(
    Type.Number({
      description:
        'Frame ID to read from. Omit or 0 for the top frame. ' +
        'Use tab({ action: "list_frames" }) to discover frame IDs.',
    }),
  ),
  tabId: Type.Number({
    description:
      'Required. Tab ID to read from. Read it from the `tabId:` line under `[Active Tab]` (or the windows list) in the context block. ' +
      'Never omit 鈥?the active tab may have changed since the last context snapshot.',
  }),
});

// 鈹€鈹€鈹€ In-page functions (self-contained, no closures) 鈹€鈹€鈹€

/** Extract plain innerText from the page. */
function extractText(selector: string | null): string {
  const root = selector
    ? document.querySelector(selector) as HTMLElement | null
    : document.body;
  if (!root) return selector
    ? `(no element found for selector: ${selector})`
    : '(page has no body element)';
  return root.innerText;
}

/** Extract cleaned innerHTML (no script/style/svg). */
function extractHtml(selector: string | null): string {
  const root = selector
    ? document.querySelector(selector) as HTMLElement | null
    : document.body;
  if (!root) return selector
    ? `(no element found for selector: ${selector})`
    : '(page has no body element)';
  const clone = root.cloneNode(true) as HTMLElement;
  clone.querySelectorAll('script, style, svg, noscript').forEach(el => el.remove());
  return clone.innerHTML;
}

/** Extract cleaned HTML with extra noise removal (hidden elements, stylesheets). */
function extractCleanHtml(selector: string | null): string {
  const root = selector
    ? document.querySelector(selector) as HTMLElement | null
    : document.body;
  if (!root) return selector
    ? `(no element found for selector: ${selector})`
    : '(page has no body element)';
  const clone = root.cloneNode(true) as HTMLElement;
  clone.querySelectorAll('script, style, svg, noscript, link[rel="stylesheet"]').forEach(el => el.remove());
  clone.querySelectorAll('[aria-hidden="true"], [hidden]').forEach(el => el.remove());
  // Strip inline style attributes 鈥?they add noise without semantic value
  clone.querySelectorAll('[style]').forEach(el => el.removeAttribute('style'));
  return clone.innerHTML;
}

/** Get the full document HTML for Readability processing. */
function getDocumentHtml(selector: string | null): { html: string; url: string } {
  if (selector) {
    const el = document.querySelector(selector);
    if (!el) return { html: '', url: window.location.href };
    return { html: el.outerHTML, url: window.location.href };
  }
  return { html: document.documentElement.outerHTML, url: window.location.href };
}

/** Extract a structural outline of the page's visual regions. */
function extractOutline(selector: string | null): string {
  // 鈹€鈹€鈹€ Nested: blocking overlay detector 鈹€鈹€鈹€
  // Nested so it shares scope with extractOutline when serialized by
  // chrome.scripting.executeScript (which only injects a single function).
  // Pure read-only: never mutates DOM, triggers focus, scroll, or events.
  function detectOverlays(): {
    blocking: {
      selector: string;
      rect: { x: number; y: number; w: number; h: number };
      coverage: number;
      zIndex: number;
      label: string;
      signals: string[];
      score: number;
      confidence: 'normal' | 'high';
    } | null;
    notice: {
      selector: string;
      rect: { x: number; y: number; w: number; h: number };
      coverage: number;
      zIndex: number;
      label: string;
      signals: string[];
      score: number;
      confidence: 'normal' | 'high';
    } | null;
  } {
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const vArea = Math.max(1, vw * vh);

    function buildOverlaySelector(el: Element): string {
      if ((el as HTMLElement).id) return '#' + CSS.escape((el as HTMLElement).id);
      const path: string[] = [];
      let node: Element | null = el;
      while (node && node !== document.body && node !== document.documentElement) {
        let seg = node.tagName.toLowerCase();
        if ((node as HTMLElement).id) {
          path.unshift('#' + CSS.escape((node as HTMLElement).id));
          break;
        }
        const parent: Element | null = node.parentElement;
        if (parent) {
          const sameTag = Array.from(parent.children).filter(c => c.tagName === node!.tagName);
          if (sameTag.length > 1) seg += ':nth-of-type(' + (sameTag.indexOf(node) + 1) + ')';
        }
        path.unshift(seg);
        node = parent;
      }
      return path.join(' > ');
    }

    function describeLabel(el: Element): string {
      const aria = el.getAttribute('aria-label');
      if (aria) return aria.trim().slice(0, 60);
      const heading = el.querySelector('h1, h2, h3, [role="heading"]');
      const t = heading?.textContent?.trim() ?? '';
      if (t) return t.slice(0, 60);
      const own = Array.from(el.childNodes)
        .filter(n => n.nodeType === Node.TEXT_NODE)
        .map(n => (n.textContent ?? '').trim())
        .find(s => s.length > 0) ?? '';
      return own.slice(0, 60);
    }

    function topAtPoint(x: number, y: number): Element | null {
      let el = document.elementFromPoint(x, y);
      // Hard cap on shadow piercing to defend against pathological host-A 鈫?host-B 鈫?host-A cycles.
      for (let i = 0; i < 16 && el && (el as any).shadowRoot; i++) {
        let inner: Element | null = null;
        try {
          inner = ((el as any).shadowRoot as ShadowRoot).elementFromPoint?.(x, y) ?? null;
        } catch {
          inner = null;
        }
        if (!inner || inner === el) break;
        el = inner;
      }
      return el;
    }

    function bgAlpha(cs: CSSStyleDeclaration): number {
      const bg = cs.backgroundColor;
      if (!bg || bg === 'transparent') return 0;
      const m = bg.match(/rgba?\(([^)]+)\)/i);
      if (!m) return 0;
      const parts = m[1].split(',').map(s => s.trim());
      if (parts.length === 4) return parseFloat(parts[3]) || 0;
      if (parts.length === 3) return 1;
      return 0;
    }

    const samples: Array<[number, number]> = [
      [vw / 2, vh / 2],
      [vw / 3, vh / 3],
      [(2 * vw) / 3, vh / 3],
      [vw / 3, (2 * vh) / 3],
      [(2 * vw) / 3, (2 * vh) / 3],
    ];

    const hitMap = new Map<Element, number>();
    for (const [x, y] of samples) {
      const top = topAtPoint(x, y);
      if (!top) continue;
      let cur: Element | null = top;
      while (cur && cur !== document.body && cur !== document.documentElement) {
        hitMap.set(cur, (hitMap.get(cur) ?? 0) + 1);
        cur = cur.parentElement;
      }
    }

    const NAME_RE = /(?:^|[-_ ])(modal|dialog|overlay|popup|mask|backdrop|login|signin|sign-?up|register|consent|gdpr|cookie|paywall|lightbox)(?:[-_ ]|$)/i;
    const NOTICE_RE = /(?:cookie|consent|gdpr|notice|banner)/i;

    const bodyCs = getComputedStyle(document.body);
    const htmlCs = getComputedStyle(document.documentElement);
    const bodyScrollLocked = bodyCs.overflow === 'hidden' || htmlCs.overflow === 'hidden';

    const ae = document.activeElement;
    const activeIsMeaningful = !!ae && ae !== document.body && ae !== document.documentElement;

    type Candidate = {
      el: Element;
      rect: DOMRect;
      coverage: number;
      cs: CSSStyleDeclaration;
      hits: number;
    };

    // Map keys are unique by definition, so no dedup Set needed. With 9 sample points and
    // the 15% coverage gate, hits>=1 is sufficient and lets small centered modals through.
    const candidates: Candidate[] = [];
    for (const [el, hits] of hitMap) {
      if (hits < 1) continue;

      let cs: CSSStyleDeclaration;
      try { cs = getComputedStyle(el); } catch { continue; }
      const pos = cs.position;
      if (pos !== 'fixed' && pos !== 'absolute' && pos !== 'sticky') continue;
      if (cs.display === 'none' || cs.visibility === 'hidden') continue;
      // Use Number.isFinite, not `|| 1` \u2014 opacity '0' parses to 0 which is falsy; we want to skip
      // transparent elements, not fall back to 1 and keep them.
      const op = parseFloat(cs.opacity);
      if (Number.isFinite(op) && op <= 0.1) continue;
      if (cs.pointerEvents === 'none') continue;

      const rect = el.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) continue;
      const coverage = (rect.width * rect.height) / vArea;
      if (coverage < 0.15) continue;

      candidates.push({ el, rect, coverage, cs, hits });
    }

    type Scored = {
      el: Element;
      rect: DOMRect;
      coverage: number;
      cs: CSSStyleDeclaration;
      score: number;
      signals: string[];
      zIndex: number;
    };

    function scoreCandidate(c: Candidate): Scored {
      const { el, cs, coverage } = c;
      const signals: string[] = [];
      let score = 0;

      const role = el.getAttribute('role');
      const ariaModal = el.getAttribute('aria-modal');
      const isNativeDialog = el.tagName === 'DIALOG' && (el as HTMLDialogElement).open;
      if (role === 'dialog' || role === 'alertdialog' || ariaModal === 'true' || isNativeDialog) {
        score += 3;
        if (role) signals.push(`role=${role}`);
        else if (isNativeDialog) signals.push('dialog[open]');
        if (ariaModal === 'true') signals.push('aria-modal=true');
      }

      const idStr = (el as HTMLElement).id || '';
      const clsStr = typeof (el as HTMLElement).className === 'string'
        ? (el as HTMLElement).className
        : '';
      const nameMatch = NAME_RE.exec(`${idStr} ${clsStr}`);
      if (nameMatch) {
        score += 2;
        signals.push(`name~=${nameMatch[1].toLowerCase()}`);
      }

      if (activeIsMeaningful && el.contains(ae)) {
        score += 2;
        signals.push('focus-trapped');
      }

      if (bodyScrollLocked) {
        score += 1;
        signals.push('body-scroll-locked');
      }

      const selfAlpha = bgAlpha(cs);
      if (selfAlpha > 0.3 && coverage >= 0.8) {
        score += 2;
        signals.push(`backdrop-alpha=${selfAlpha.toFixed(2)}`);
      } else if (el.parentElement) {
        for (const sib of el.parentElement.children) {
          if (sib === el) continue;
          let sCs: CSSStyleDeclaration;
          try { sCs = getComputedStyle(sib); } catch { continue; }
          if (sCs.position !== 'fixed') continue;
          const sr = (sib as HTMLElement).getBoundingClientRect();
          const sCov = (sr.width * sr.height) / vArea;
          if (sCov < 0.8) continue;
          const sa = bgAlpha(sCs);
          if (sa > 0.3) {
            score += 2;
            signals.push(`sibling-backdrop-alpha=${sa.toFixed(2)}`);
            break;
          }
        }
      }

      const zRaw = cs.zIndex;
      const zNum = zRaw === 'auto' ? 0 : (parseInt(zRaw, 10) || 0);
      if (zNum >= 1000) {
        score += 1;
        signals.push(`z=${zNum}`);
      }

      if (coverage >= 0.6) {
        score += 2;
        signals.push(`coverage=${Math.round(coverage * 100)}%`);
      }

      return { el, rect: c.rect, coverage, cs, score, signals, zIndex: zNum };
    }

    const scored = candidates.map(scoreCandidate);

    let blocking: Scored | null = null;
    for (const s of scored) {
      if (s.score < 3) continue;
      if (!blocking
        || s.score > blocking.score
        || (s.score === blocking.score && s.coverage > blocking.coverage)) {
        blocking = s;
      }
    }

    // \u2500\u2500 Notice bypass: fixed top/bottom bars matching cookie/consent naming \u2500\u2500
    // Filter by name attribute first via attribute selector \u2014 cheap text match in C++,
    // bounded result set \u2014 before paying for getComputedStyle / getBoundingClientRect.
    // Worst case the page has no matching nodes \u2192 empty NodeList, near-zero cost.
    let notice: Scored | null = null;
    const NOTICE_NAME_SELECTOR = [
      '[id*="cookie" i]', '[class*="cookie" i]',
      '[id*="consent" i]', '[class*="consent" i]',
      '[id*="gdpr" i]', '[class*="gdpr" i]',
      '[id*="banner" i]', '[class*="banner" i]',
      '[id*="notice" i]', '[class*="notice" i]',
    ].join(',');
    let noticeCandidates: HTMLElement[];
    try {
      noticeCandidates = Array.from(document.querySelectorAll<HTMLElement>(NOTICE_NAME_SELECTOR)).slice(0, 50);
    } catch {
      noticeCandidates = [];
    }
    for (const el of noticeCandidates) {
      if (blocking && blocking.el === el) continue;
      // Re-verify against the stricter regex (attribute selectors are broader than NOTICE_RE).
      const idStr = el.id || '';
      const clsStr = typeof el.className === 'string' ? el.className : '';
      if (!NOTICE_RE.test(`${idStr} ${clsStr}`)) continue;
      let cs: CSSStyleDeclaration;
      try { cs = getComputedStyle(el); } catch { continue; }
      if (cs.position !== 'fixed') continue;
      if (cs.display === 'none' || cs.visibility === 'hidden') continue;
      const op = parseFloat(cs.opacity);
      if (Number.isFinite(op) && op <= 0.1) continue;
      const rect = el.getBoundingClientRect();
      if (rect.width <= 0 || rect.height < 60) continue;
      const stuckBottom = rect.bottom >= vh - 10 && rect.bottom <= vh + 50;
      const stuckTop = rect.top >= -10 && rect.top <= 10;
      if (!stuckBottom && !stuckTop) continue;
      const coverage = (rect.width * rect.height) / vArea;
      const zRaw = cs.zIndex;
      const zNum = zRaw === 'auto' ? 0 : (parseInt(zRaw, 10) || 0);
      const signals = [stuckBottom ? 'stuck-bottom' : 'stuck-top'];
      notice = {
        el, rect, coverage, cs,
        score: 0, signals, zIndex: zNum,
      };
      break;
    }

    const toResult = (s: Scored) => ({
      selector: buildOverlaySelector(s.el),
      rect: { x: Math.round(s.rect.x), y: Math.round(s.rect.y), w: Math.round(s.rect.width), h: Math.round(s.rect.height) },
      coverage: Math.round(s.coverage * 100),
      zIndex: s.zIndex,
      label: describeLabel(s.el),
      signals: s.signals,
      score: s.score,
      confidence: (s.score >= 5 ? 'high' : 'normal') as 'normal' | 'high',
    });

    return {
      blocking: blocking ? toResult(blocking) : null,
      notice: notice ? toResult(notice) : null,
    };
  }

  const MIN_WIDTH = 50;
  const MIN_HEIGHT = 30;
  const MAX_DEPTH = 6;
  const MAX_NODES = 200;
  const MAX_RAW_DEPTH = 30;
  const TEXT_LEN = 60;
  const INLINE_TAGS = new Set(['SPAN', 'A', 'EM', 'STRONG', 'B', 'I', 'U', 'S', 'SMALL', 'SUB', 'SUP', 'BR', 'WBR', 'ABBR', 'CODE', 'KBD', 'MARK', 'Q', 'CITE', 'TIME', 'LABEL']);
  const SEMANTIC_TAGS = new Set(['NAV', 'HEADER', 'FOOTER', 'ASIDE', 'MAIN', 'SECTION', 'ARTICLE', 'FORM']);

  let nodeCount = 0;

  const root = selector
    ? document.querySelector(selector) as HTMLElement | null
    : document.body;
  if (!root) return selector
    ? `(no element found for selector: ${selector})`
    : '(page has no body element)';

  function getSelector(el: HTMLElement): string {
    if (el.id) return '#' + CSS.escape(el.id);
    const path: string[] = [];
    let node: HTMLElement | null = el;
    while (node && node !== document.body) {
      let seg = node.tagName.toLowerCase();
      if (node.id) {
        path.unshift('#' + CSS.escape(node.id));
        break;
      }
      const siblings = node.parentElement
        ? Array.from(node.parentElement.children).filter(c => c.tagName === node!.tagName)
        : [];
      if (siblings.length > 1) {
        seg += ':nth-of-type(' + (siblings.indexOf(node) + 1) + ')';
      }
      path.unshift(seg);
      node = node.parentElement;
    }
    return path.join(' > ');
  }

  /** Count interactive elements that are DIRECT children of el (not descendants). */
  function countDirectInteractive(el: HTMLElement) {
    const result = { inputs: 0, buttons: 0, links: 0, images: 0 };
    for (const child of el.children) {
      if (!(child instanceof HTMLElement)) continue;
      const tag = child.tagName;
      const type = child.getAttribute('type');
      if (tag === 'BUTTON' || child.getAttribute('role') === 'button'
        || (tag === 'INPUT' && (type === 'submit' || type === 'button'))) {
        result.buttons++;
      } else if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT'
        || child.getAttribute('contenteditable') === 'true') {
        result.inputs++;
      }
      if (tag === 'A' && child.hasAttribute('href')) result.links++;
      if (tag === 'IMG' || tag === 'SVG' || child.getAttribute('role') === 'img') result.images++;
    }
    return result;
  }

  /** Count ALL interactive descendants (used for the final summary line only). */
  function countAllInteractive(el: HTMLElement) {
    return {
      inputs: el.querySelectorAll('input, textarea, select, [contenteditable="true"]').length,
      buttons: el.querySelectorAll('button, [role="button"], input[type="submit"], input[type="button"]').length,
      links: el.querySelectorAll('a[href]').length,
      images: el.querySelectorAll('img, svg, [role="img"]').length,
    };
  }

  function getTextPreview(el: HTMLElement): string {
    let text = '';
    for (const child of el.childNodes) {
      if (child.nodeType === Node.TEXT_NODE) {
        text += (child.textContent ?? '').trim() + ' ';
      }
    }
    text = text.trim();
    return text.length > TEXT_LEN ? text.slice(0, TEXT_LEN) + '...' : text;
  }

  function getClues(el: HTMLElement): string[] {
    const clues: string[] = [];
    if (el.id) clues.push('id=' + el.id);
    if (el.className && typeof el.className === 'string') {
      clues.push('class=' + el.className.split(/\s+/).slice(0, 3).join(' '));
    }
    const role = el.getAttribute('role');
    if (role) clues.push('role=' + role);
    const ariaLabel = el.getAttribute('aria-label');
    if (ariaLabel) clues.push('aria=' + ariaLabel);
    if (el.shadowRoot) clues.push('shadow-root');
    return clues;
  }

  function getVisualRect(el: HTMLElement): DOMRect | null {
    if (el.offsetParent === null && el.getClientRects().length === 0) return null;
    const rect = el.getBoundingClientRect();
    if (rect.width < MIN_WIDTH || rect.height < MIN_HEIGHT) return null;
    const blockChildren = Array.from(el.children).filter(c => !INLINE_TAGS.has(c.tagName));
    if (blockChildren.length === 0 && !el.querySelector('input, button, a, select, textarea, img')) {
      const directText = Array.from(el.childNodes)
        .filter(n => n.nodeType === Node.TEXT_NODE)
        .map(n => (n.textContent ?? '').trim())
        .join('');
      if (directText.length < 20) return null;
    }
    return rect;
  }

  /** Determine if an element is a pure wrapper that should be skipped (not consume depth).
   *  Pre-computed values are passed in to avoid redundant DOM queries. */
  function isWrapper(
    el: HTMLElement,
    cs: CSSStyleDeclaration,
    textPreview: string,
    directInter: { inputs: number; buttons: number; links: number; images: number },
  ): boolean {
    if (el.id) return false;
    if (el.getAttribute('role')) return false;
    if (el.getAttribute('aria-label')) return false;
    if (el.getAttribute('aria-labelledby')) return false;
    if (el.hasAttribute('tabindex')) return false;
    if (SEMANTIC_TAGS.has(el.tagName)) return false;
    // Only fixed/absolute/sticky are meaningful positioning; relative is cosmetic
    if (cs.position === 'fixed' || cs.position === 'absolute' || cs.position === 'sticky') return false;
    if (cs.zIndex !== 'auto' && cs.zIndex !== '0') return false;
    if (cs.overflow !== 'visible') return false;
    if (textPreview) return false;
    if (directInter.inputs + directInter.buttons + directInter.links + directInter.images > 0) return false;
    return true;
  }

  /** Fingerprint for detecting repeated sibling patterns. */
  function getSiblingKey(el: HTMLElement): string {
    const tag = el.tagName;
    const cls = (typeof el.className === 'string') ? el.className : '';
    const role = el.getAttribute('role') ?? '';
    return `${tag}|${cls}|${role}`;
  }

  /** Check if two outline nodes have similar structure (same tag, similar interactive profile). */
  function isSimilarStructure(a: OutlineNode, b: OutlineNode): boolean {
    if (a.tag !== b.tag) return false;
    // Same direct interactive profile
    if (a.inter.inputs !== b.inter.inputs || a.inter.buttons !== b.inter.buttons
      || a.inter.links !== b.inter.links || a.inter.images !== b.inter.images) return false;
    // Similar child count (within 卤1)
    if (Math.abs(a.children.length - b.children.length) > 1) return false;
    return true;
  }

  interface OutlineNode {
    tag: string;
    sel: string;
    rect: { x: number; y: number; w: number; h: number };
    text: string;
    inter: { inputs: number; buttons: number; links: number; images: number };
    totalInter?: { inputs: number; buttons: number; links: number; images: number };
    clues: string[];
    style: { position: string; zIndex: string; overflow: string };
    children: OutlineNode[];
    /** If set, this node represents N collapsed siblings that were similar to previous nodes. */
    collapsedCount?: number;
    collapsedSelector?: string;
  }

  const SIBLING_SAMPLE_COUNT = 3;
  const SIBLING_COLLAPSE_THRESHOLD = 5;

  /** Generate a collapse key from an OutlineNode (for promoted nodes that have no DOM element). */
  function getNodeKey(node: OutlineNode): string {
    const cls = node.clues.find(c => c.startsWith('class='));
    const role = node.clues.find(c => c.startsWith('role='));
    return `${node.tag}|${cls ?? ''}|${role ?? ''}`;
  }

  /**
   * Traverse the DOM tree. `depth` counts meaningful nodes only.
   * `rawDepth` counts actual DOM nesting to prevent infinite recursion on wrapper chains.
   */
  function traverse(el: HTMLElement, depth: number, rawDepth: number): OutlineNode[] {
    if (depth > MAX_DEPTH || rawDepth > MAX_RAW_DEPTH || nodeCount >= MAX_NODES) return [];

    // Phase 1: collect all meaningful children (skipping wrappers)
    interface DomCandidate { type: 'dom'; el: HTMLElement; key: string; cs: CSSStyleDeclaration; textPreview: string; inter: ReturnType<typeof countDirectInteractive> }
    interface PromotedCandidate { type: 'promoted'; node: OutlineNode; key: string }
    type Candidate = DomCandidate | PromotedCandidate;

    const candidates: Candidate[] = [];
    for (const child of el.children) {
      if (nodeCount + candidates.length >= MAX_NODES + 50) break;
      if (!(child instanceof HTMLElement)) continue;

      const rect = getVisualRect(child);
      if (!rect) continue;

      const hasContent = (child.textContent?.trim().length ?? 0) > 0
        || child.querySelector('input, button, a, select, textarea, img') !== null;
      if (!hasContent) continue;

      const cs = getComputedStyle(child);
      const textPreview = getTextPreview(child);
      const inter = countDirectInteractive(child);

      if (isWrapper(child, cs, textPreview, inter)) {
        const promoted = traverse(child, depth, rawDepth + 1);
        candidates.push(...promoted.map(n => ({ type: 'promoted' as const, node: n, key: getNodeKey(n) })));
        continue;
      }

      candidates.push({ type: 'dom', el: child, key: getSiblingKey(child), cs, textPreview, inter });
    }

    // Phase 2: group by key, detect repeated patterns, collapse similar siblings
    const results: OutlineNode[] = [];
    const keyCount = new Map<string, number>();
    for (const c of candidates) {
      keyCount.set(c.key, (keyCount.get(c.key) ?? 0) + 1);
    }

    const keyEmitted = new Map<string, number>();
    const keySamples = new Map<string, OutlineNode[]>();

    for (const c of candidates) {
      if (nodeCount >= MAX_NODES) break;

      const count = keyCount.get(c.key)!;
      const emitted = keyEmitted.get(c.key) ?? 0;

      // Resolve candidate to an OutlineNode
      const resolveNode = (): OutlineNode => {
        if (c.type === 'promoted') return c.node;
        return buildNode(c.el, depth, rawDepth, c.cs, c.textPreview, c.inter);
      };

      if (count >= SIBLING_COLLAPSE_THRESHOLD) {
        if (emitted < SIBLING_SAMPLE_COUNT) {
          const node = resolveNode();
          results.push(node);
          keyEmitted.set(c.key, emitted + 1);
          const samples = keySamples.get(c.key) ?? [];
          samples.push(node);
          keySamples.set(c.key, samples);
        } else if (emitted === SIBLING_SAMPLE_COUNT) {
          const samples = keySamples.get(c.key) ?? [];
          const allSimilar = samples.length >= 2 && samples.every((s, i) =>
            i === 0 || isSimilarStructure(samples[0], s));

          if (allSimilar) {
            const remaining = count - SIBLING_SAMPLE_COUNT;
            const sampleNode = samples[0];
            const firstClass = sampleNode.clues.find(cl => cl.startsWith('class='));
            const clsSuffix = firstClass ? '.' + firstClass.slice(6).split(' ')[0] : '';
            const parentSel = c.type === 'dom'
              ? getSelector(c.el.parentElement!)
              : sampleNode.sel.replace(/ > [^>]+$/, '');
            results.push({
              tag: sampleNode.tag, sel: `(${remaining} more)`, text: '',
              rect: { x: 0, y: 0, w: 0, h: 0 }, inter: { inputs: 0, buttons: 0, links: 0, images: 0 },
              clues: [], style: { position: '', zIndex: '', overflow: '' }, children: [],
              collapsedCount: remaining,
              collapsedSelector: `${parentSel} > ${sampleNode.tag}${clsSuffix}`,
            });
            keyEmitted.set(c.key, emitted + 1);
          } else {
            const node = resolveNode();
            results.push(node);
            keyEmitted.set(c.key, emitted + 1);
            keyCount.set(c.key, SIBLING_COLLAPSE_THRESHOLD - 1);
          }
        }
        // else: already collapsed, skip
      } else {
        const node = resolveNode();
        results.push(node);
      }
    }

    return results;
  }

  /** Build an OutlineNode for a meaningful element using pre-computed values. */
  function buildNode(
    child: HTMLElement, depth: number, rawDepth: number,
    cs: CSSStyleDeclaration, textPreview: string, inter: ReturnType<typeof countDirectInteractive>,
  ): OutlineNode {
    nodeCount++;
    const style = {
      position: (cs.position === 'static' || cs.position === 'relative') ? '' : cs.position,
      zIndex: cs.zIndex === 'auto' ? '' : cs.zIndex,
      overflow: cs.overflow === 'visible' ? '' : cs.overflow,
    };
    return {
      tag: child.tagName.toLowerCase(),
      sel: getSelector(child),
      rect: (() => { const r = child.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; })(),
      text: textPreview,
      inter,
      clues: getClues(child),
      style,
      children: traverse(child, depth + 1, rawDepth + 1),
    };
  }

  /** Post-traversal: compute total descendant interactive counts for display. */
  function computeTotalInter(nodes: OutlineNode[]): void {
    for (const node of nodes) {
      computeTotalInter(node.children);
      const totals = { ...node.inter };
      for (const child of node.children) {
        const ct = child.totalInter!;
        totals.inputs += ct.inputs;
        totals.buttons += ct.buttons;
        totals.links += ct.links;
        totals.images += ct.images;
      }
      node.totalInter = totals;
    }
  }

  function formatNode(node: OutlineNode, indent: number): string[] {
    const pad = '  '.repeat(indent);

    // Collapsed sibling summary
    if (node.collapsedCount) {
      return [`${pad}... ${node.collapsedCount} more similar <${node.tag}> (selector: ${node.collapsedSelector})`];
    }

    const ti = node.totalInter ?? node.inter;

    const interParts: string[] = [];
    if (ti.inputs) interParts.push(ti.inputs + ' input');
    if (ti.buttons) interParts.push(ti.buttons + ' btn');
    if (ti.links) interParts.push(ti.links + ' link');
    if (ti.images) interParts.push(ti.images + ' img');
    const interStr = interParts.length ? ' | ' + interParts.join(', ') : '';

    const clueStr = node.clues.length ? ' {' + node.clues.join('; ') + '}' : '';
    const textStr = node.text ? ' "' + node.text + '"' : '';

    const styleParts: string[] = [];
    if (node.style.position) styleParts.push(node.style.position);
    if (node.style.zIndex) styleParts.push('z=' + node.style.zIndex);
    if (node.style.overflow) styleParts.push('overflow=' + node.style.overflow);
    const styleStr = styleParts.length ? ' [' + styleParts.join(', ') + ']' : '';

    const line = `${pad}${node.sel} <${node.tag}> [${node.rect.x},${node.rect.y} ${node.rect.w}脳${node.rect.h}]${styleStr}${interStr}${clueStr}${textStr}`;

    const lines = [line];
    for (const child of node.children) {
      lines.push(...formatNode(child, indent + 1));
    }
    return lines;
  }

  const tree = traverse(root, 0, 0);
  computeTotalInter(tree);
  const totalInter = countAllInteractive(root);

  const header: string[] = [];
  if (selector) {
    const rootRect = root.getBoundingClientRect();
    header.push(`Outline of ${selector} <${root.tagName.toLowerCase()}> [${Math.round(rootRect.x)},${Math.round(rootRect.y)} ${Math.round(rootRect.width)}脳${Math.round(rootRect.height)}]:`);
  } else {
    header.push(`Page outline (${tree.length} top regions):`);
  }

  const footer = [`[Total] ${totalInter.inputs} inputs, ${totalInter.buttons} buttons, ${totalInter.links} links, ${totalInter.images} images`];
  if (nodeCount >= MAX_NODES) {
    footer.push(`(outline truncated at ${MAX_NODES} nodes 鈥?use selector to drill into a specific region)`);
  }

  // Overlay detection: only for full-page outline (selector === null).
  // When the agent drills into a specific region, occlusion is not relevant.
  const overlayLines: string[] = [];
  if (selector === null) {
    let result: ReturnType<typeof detectOverlays> | null = null;
    try {
      result = detectOverlays();
    } catch (e) {
      // Visible only in the inspected page's console; harmless on hostile pages,
      // useful during development to catch regressions.
      console.warn('[cebian] detectOverlays failed:', e);
      result = null;
    }
    if (result?.blocking) {
      const o = result.blocking;
      const conf = o.confidence === 'high' ? ' (high confidence)' : '';
      overlayLines.push(`[!] Blocking overlay detected${conf}:`);
      overlayLines.push(`    selector: ${o.selector}`);
      overlayLines.push(`    rect: [${o.rect.x},${o.rect.y} ${o.rect.w}脳${o.rect.h}]  coverage: ${o.coverage}%  z-index: ${o.zIndex}`);
      if (o.label) overlayLines.push(`    label: "${o.label}"`);
      overlayLines.push(`    signals: ${o.signals.join(', ')}`);
      overlayLines.push(`    suggestion: this overlay likely intercepts clicks. Dismiss it (close button / ESC) or ask the user before interacting with the underlying page.`);
      overlayLines.push('');
    }
    if (result?.notice) {
      const o = result.notice;
      overlayLines.push(`[i] Notice bar detected (non-blocking):`);
      overlayLines.push(`    selector: ${o.selector}`);
      overlayLines.push(`    rect: [${o.rect.x},${o.rect.y} ${o.rect.w}脳${o.rect.h}]`);
      if (o.label) overlayLines.push(`    label: "${o.label}"`);
      overlayLines.push('');
    }
  }

  return [
    ...header,
    '',
    ...overlayLines,
    ...tree.flatMap(n => formatNode(n, 0)),
    '',
    ...footer,
  ].join('\n');
}

// 鈹€鈹€鈹€ Offscreen document helpers 鈹€鈹€鈹€

/** Send HTML to the offscreen document for markdown conversion. */
async function convertHtmlToMarkdown(html: string): Promise<string> {
  await ensureOffscreen();
  const msg: OffscreenRequest = { type: 'html-to-markdown', html };
  const resp: OffscreenResponse = await chrome.runtime.sendMessage(msg);
  if (resp.error) throw new Error(`Offscreen conversion failed: ${resp.error}`);
  return resp.result ?? '';
}

/** Send HTML to the offscreen document for Readability + markdown conversion. */
async function convertArticleToMarkdown(html: string, url: string): Promise<string | null> {
  await ensureOffscreen();
  const msg: OffscreenRequest = { type: 'html-to-markdown', html, readability: { url } };
  const resp: OffscreenResponse = await chrome.runtime.sendMessage(msg);
  if (resp.error === 'readability-failed') return null;
  if (resp.error) throw new Error(`Offscreen conversion failed: ${resp.error}`);
  return resp.result ?? '';
}

function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return text.slice(0, maxLength) + `\n\n...(truncated at ${maxLength} chars)`;
}

// 鈹€鈹€鈹€ Tool definition 鈹€鈹€鈹€

export const readPageTool: AgentTool<typeof ReadPageParameters> = {
  name: TOOL_READ_PAGE,
  label: 'Read Page',
  description:
    'Extract content from a browser tab (defaults to the active tab). ' +
    'Modes: "markdown" (default, full-page as markdown 鈥?works for any page), ' +
    '"article" (reader-mode extraction as markdown 鈥?for news/blogs/docs), ' +
    '"outline" (page structure overview 鈥?visual regions with selectors, positions, interactive elements; also reports any blocking overlay / modal that may intercept clicks; use to understand layout before acting), ' +
    '"text" (plain text), "html" (cleaned HTML). ' +
    'Optionally scope to a CSS selector. ' +
    'For large pages where the full content matters but would bloat the conversation, set `outputPath` to write the extraction directly to VFS. ' +
    'Use this before answering questions about page content.',
  parameters: ReadPageParameters,

  async execute(_toolCallId, params, signal): Promise<AgentToolResult<{}>> {
    signal?.throwIfAborted();
    const tabId = params.tabId;
    const mode = params.mode ?? 'markdown';
    const maxLength = params.maxLength ?? 20000;

    // 鈹€鈹€ PDF short-circuit 鈹€鈹€
    // Chrome's built-in PDF viewer renders text to canvas, so injecting
    // extractText / extractHtml just returns "(page has no body element)".
    // Detect by URL suffix (cheap, no script injection, no network) and
    // tell the agent to switch tools instead of returning empty content
    // that looks like a real failure.
    try {
      const tab = await chrome.tabs.get(tabId);
      if (isLikelyPdfUrl(tab.url)) {
        return {
          content: [{ type: 'text', text: pdfRedirectHint(tab.url, tabId) }],
          details: {},
        };
      }
    } catch {
      // chrome.tabs.get can fail when the tab was just closed; let the
      // existing tool path handle the error so we don't mask it with our
      // own message.
    }

    let content: string;

    switch (mode) {
      case 'text': {
        content = await executeInTabWithArgs(tabId, extractText, [params.selector ?? null], params.frameId);
        break;
      }
      case 'html': {
        content = await executeInTabWithArgs(tabId, extractHtml, [params.selector ?? null], params.frameId);
        break;
      }
      case 'markdown': {
        // Full-page cleaned HTML 鈫?markdown via offscreen document
        const html = await executeInTabWithArgs(tabId, extractCleanHtml, [params.selector ?? null], params.frameId);
        content = await convertHtmlToMarkdown(html);
        break;
      }
      case 'outline': {
        content = await executeInTabWithArgs(tabId, extractOutline, [params.selector ?? null], params.frameId);
        break;
      }
      case 'article': {
        if (params.selector) {
          const html = await executeInTabWithArgs(tabId, extractCleanHtml, [params.selector], params.frameId);
          content = await convertHtmlToMarkdown(html);
          break;
        }

        const { html, url } = await executeInTabWithArgs(tabId, getDocumentHtml, [null], params.frameId);
        const articleMd = await convertArticleToMarkdown(html, url);
        if (!articleMd) {
          const fallback = await executeInTabWithArgs(tabId, extractText, [null], params.frameId);
          content = '(Readability extraction failed, falling back to plain text)\n\n' + fallback;
          break;
        }
        content = articleMd;
        break;
      }
      default:
        content = await executeInTabWithArgs(tabId, extractText, [params.selector ?? null], params.frameId);
    }

    // 鈹€鈹€ outputPath branch 鈹€鈹€
    // Full extraction lands directly in VFS; the agent only sees path +
    // byte count + 1KB preview. maxLength is intentionally ignored 鈥?the
    // whole point of outputPath is to bypass the size limiter.
    if (params.outputPath) {
      await vfs.writeFile(params.outputPath, content, 'utf8');

      const byteLen = new TextEncoder().encode(content).length;
      const preview = content.length > 1024
        ? content.slice(0, 1024) + '\n鈥?preview truncated; full content is on disk)'
        : content;
      return {
        content: [{ type: 'text', text: `Wrote ${params.outputPath} (${byteLen} bytes, mode=${mode})\nPreview:\n---\n${preview}\n---` }],
        details: {},
      };
    }

    return {
      content: [{ type: 'text', text: truncate(content, maxLength) }],
      details: {},
    };
  },
};

import { Type, type Static } from 'typebox';
import type { AgentTool, AgentToolResult } from '@earendil-works/pi-agent-core';
import { TOOL_RUN_SKILL } from '@/lib/types';
