/**
 * Build a session-bound run_skill tool. The closure captures `sessionId`
 * so that sandbox scripts can have their vfs writes routed to the
 * session's workspace (`/workspaces/<sessionId>/<skill>/`).
 *
 * 宸ュ巶妯″紡璺?`createSessionAskUserTool` 鍚屾 鈥斺€?姣忎釜 session 鏈夌嫭绔嬪疄渚嬶紝
 * 浣?description / parameters / name 瀹屽叏澶嶇敤涓婇潰鐨勫叡浜畾涔夛紝閬垮厤婕傜Щ銆俓n */
export function createSessionRunSkillTool(sessionId: string): AgentTool<typeof RunSkillParameters> {
  return {
    ...runSkillTool,
    execute: (_toolCallId, params, signal) => executeRunSkill(sessionId, params, signal),
  };
}

async function executeRunSkill(
  sessionId: string,
  params: Static<typeof RunSkillParameters>,
  signal?: AbortSignal,
): Promise<AgentToolResult<{}>> {
  signal?.throwIfAborted();

  const { skill, script, args = {}, tabId, confirmation_nonce, always_allow = false } = params;

  // 鈹€鈹€鈹€ Path traversal protection 鈹€鈹€鈹€

  const normalizedSkillsRoot = normalizePath(CEBIAN_SKILLS_DIR);
  const normalizedSkillDir = normalizePath(`${CEBIAN_SKILLS_DIR}/${skill}`);
  if (!normalizedSkillDir.startsWith(normalizedSkillsRoot + '/')) {
    throw new Error('Invalid skill name 鈥?path traversal detected.');
  }
  const normalizedScriptPath = normalizePath(`${normalizedSkillDir}/${script}`);
  if (!normalizedScriptPath.startsWith(normalizedSkillDir + '/')) {
    throw new Error('Script path escapes skill directory.');
  }

  // 鈹€鈹€鈹€ 鈶?Read SKILL.md and parse permissions 鈹€鈹€鈹€

  const skillMdPath = `${normalizedSkillDir}/${SKILL_ENTRY_FILE}`;

  if (!(await vfs.exists(skillMdPath))) {
    throw new Error(`Skill "${skill}" not found. No SKILL.md at ${skillMdPath}`);
  }

  let permissions: string[] = [];
  const raw = await vfs.readFile(skillMdPath, 'utf8');
  const content = typeof raw === 'string' ? raw : new TextDecoder().decode(raw as Uint8Array);
  try {
    const { data } = parseFrontmatter(content);
    if (data.metadata && typeof data.metadata === 'object') {
      const meta = data.metadata as Record<string, unknown>;
      if (Array.isArray(meta.permissions)) {
        permissions = meta.permissions.filter((p): p is string => typeof p === 'string');
      }
    }
  } catch (err) {
    throw new Error(`Failed to parse SKILL.md: ${(err as Error).message}`);
  }

  // 鈹€鈹€鈹€ 鈶?Read script file 鈹€鈹€鈹€

  if (!(await vfs.exists(normalizedScriptPath))) {
    throw new Error(`Script not found: ${normalizedScriptPath}`);
  }
  const rawScript = await vfs.readFile(normalizedScriptPath, 'utf8');
  const code = typeof rawScript === 'string' ? rawScript : new TextDecoder().decode(rawScript as Uint8Array);

  // 鈹€鈹€鈹€ 鈶?Check permission grant 鈹€鈹€鈹€

  if (permissions.length > 0) {
    const grants = await getSkillGrants();
    const grant = grants[skill];
    const isGranted = grant?.granted === 'always' && permissionsMatch(grant.permissions, permissions);

    if (!isGranted) {
      // 宸茬粡甯︿簡 nonce 鈥斺€?鏍￠獙鏄笉鏄敤鎴风‘璁よ繃鐨勯偅娆n      if (confirmation_nonce) {
        const nonceData = pendingNonces.get(confirmation_nonce);
        pendingNonces.delete(confirmation_nonce);
        if (!nonceData || nonceData.skill !== skill || nonceData.expiresAt < Date.now()) {
          throw new Error('Invalid or expired confirmation nonce. Please retry the permission flow.');
        }
        // 鍚堟硶 nonce 鈥斺€?鎸佷箙鍖栨巿鏉僜n        if (always_allow) {
          await setSkillGrant(skill, permissions);
        }
      } else {
        // 娌?nonce 鈥斺€?鐢熸垚涓€涓苟杩斿洖 permission prompt銆傝繖鏄甯哥殑 next-step
        // 杩斿洖锛屼笉鏄敊璇細agent 璇诲埌鍐呭浼氬幓璋?ask_user 鐒跺悗鍐嶆潵涓€娆°€俓n        const nonce = crypto.randomUUID();
        pendingNonces.set(nonce, { skill, permissions, expiresAt: Date.now() + NONCE_TTL_MS });
        const permList = permissions.map((p) => `  鈥?${p}`).join('\n');
        return {
          content: [{
            type: 'text',
            text: `Permission required to execute skill code.\n\n` +
              `Skill: ${skill}\n` +
              `Script: ${script}\n` +
              `Requested permissions:\n${permList}\n\n` +
              `confirmation_nonce: ${nonce}\n\n` +
              `Use ask_user to ask the user for confirmation with three options in the user's language ` +
              `(equivalents of: Deny / Allow once / Always allow this skill). ` +
              `If approved, call run_skill again with the same skill/script/args plus confirmation_nonce="${nonce}". ` +
              `If "always allow", also set always_allow=true. If denied, do not call again.`,
          }],
          details: {},
        };
      }
    }
  }

  signal?.throwIfAborted();

  // 鈹€鈹€鈹€ 鈶?Execute in sandbox 鈹€鈹€鈹€

  const result = await runInSandbox(code, args as Record<string, unknown>, permissions, skill, sessionId, tabId);
  const serialized = result !== undefined ? JSON.stringify(result, null, 2) : '(no return value)';

  return {
    content: [{ type: 'text', text: serialized }],
    details: {},
  };
}

/**
 * Background-side RPC layer for communicating with the sandbox page.
 * Path: background 鈫?chrome.runtime.sendMessage 鈫?offscreen 鈫?postMessage 鈫?sandbox
 * Reverse: sandbox 鈫?postMessage 鈫?offscreen 鈫?chrome.runtime.sendMessage 鈫?background
 */

import { ensureOffscreen } from './offscreen';
import { executeViaDebugger } from '@/lib/tab-helpers';
import { isChromeCallAllowed } from './chrome-api-whitelist';
import { vfs } from '@/lib/vfs';
import { isVfsCallAllowed, resolveScopedPath, sessionSkillRoot } from './vfs-whitelist';
import { decodeBinaryArgs, decodeBinary, encodeBinary } from '@/lib/sandbox-binary';
import type { MatchPattern } from './url-pattern';
import { parseBgFetchPatterns } from './url-pattern';
import { handleBgFetch } from './bg-fetch';

// 鈹€鈹€鈹€ Pending run requests 鈹€鈹€鈹€

/** Per-run state. `vfsRoot` / `permissions` / `bgFetchPatterns` are kept on
 *  the trusted side so handlers look them up by `id` instead of trusting
 *  the sandbox-supplied envelope 鈥?a malicious skill cannot forge its scope
 *  or claim a permission / pattern it wasn't granted. */
interface PendingRun {
  resolve: (result: unknown) => void;
  reject: (error: Error) => void;
  timeoutId: ReturnType<typeof setTimeout>;
  vfsRoot: string | null;
  permissions: string[];
  bgFetchPatterns: MatchPattern[] | null;
  /** AbortController for in-flight bgFetch calls; aborted when the run
   *  times out or otherwise tears down. */
  abortCtrl: AbortController;
}

const pendingRuns = new Map<string, PendingRun>();

// 鈹€鈹€鈹€ Handle messages from sandbox (via offscreen relay) 鈹€鈹€鈹€

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (!message?.type?.startsWith('sandbox:')) return false;

  switch (message.type) {
    case 'sandbox:run_result': {
      const pending = pendingRuns.get(message.id);
      if (pending) {
        clearTimeout(pending.timeoutId);
        pendingRuns.delete(message.id);
        // run 缁撴潫鏃朵竴骞?abort锛屼腑鏂?skill 涓湭 await 鐨?bgFetch銆俓n        // 鑴氭湰宸茬粡杩斿洖锛岃繖浜涙偓绌?Promise 鎷夸笉鍒颁换浣曠粨鏋滐紝寮哄埗鎷嗛櫎鍙互鐪佷笅瀹冧滑鍗犵敤鐨勭綉缁滃拰鍐呭瓨銆俓n        pending.abortCtrl.abort();
        if (message.error) {
          pending.reject(new Error(message.error));
        } else {
          pending.resolve(message.result);
        }
      }
      return false;
    }

    case 'sandbox:chrome_call': {
      handleChromeCall(message).catch(err => console.error('[sandbox-rpc] chrome_call error:', err));
      return false;
    }

    case 'sandbox:page_exec': {
      handlePageExec(message).catch(err => console.error('[sandbox-rpc] page_exec error:', err));
      return false;
    }

    case 'sandbox:vfs_call': {
      handleVfsCall(message).catch(err => console.error('[sandbox-rpc] vfs_call error:', err));
      return false;
    }

    case 'sandbox:bg_fetch': {
      handleBgFetchCall(message).catch(err => console.error('[sandbox-rpc] bg_fetch error:', err));
      return false;
    }
  }

  return false;
});

async function handleChromeCall(msg: {
  id: string; callId: string; namespace: string; method: string; args: unknown[];
}): Promise<void> {
  let result: unknown;
  let error: string | undefined;

  try {
    if (!isChromeCallAllowed(msg.namespace, msg.method)) {
      throw new Error(`Chrome API call not allowed: chrome.${msg.namespace}.${msg.method}`);
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const ns = (chrome as any)[msg.namespace];
    if (!ns) throw new Error(`Unknown chrome namespace: ${msg.namespace}`);

    if (typeof ns[msg.method] !== 'function') {
      throw new Error(`Not a function: chrome.${msg.namespace}.${msg.method}`);
    }

    result = await ns[msg.method](...msg.args);
  } catch (err) {
    error = (err as Error).message;
  }

  // Send result back to sandbox via offscreen
  await chrome.runtime.sendMessage({
    type: 'sandbox:chrome_result',
    id: msg.id,
    callId: msg.callId,
    result,
    error,
  }).catch(() => {});
}

async function handlePageExec(msg: {
  id: string; callId: string; code: string; tabId?: number;
}): Promise<void> {
  let resultText: string | undefined;
  let error: string | undefined;

  try {
    if (msg.tabId == null) {
      throw new Error('executeInPage requires a tabId. Re-invoke run_skill with an explicit tabId parameter (read it from the [Active Tab] block in the context).');
    }
    resultText = await executeViaDebugger(msg.tabId, msg.code);
  } catch (err) {
    error = (err as Error).message;
  }

  await chrome.runtime.sendMessage({
    type: 'sandbox:page_exec_result',
    id: msg.id,
    callId: msg.callId,
    result: resultText,
    error,
  }).catch(() => {});
}

// 鈹€鈹€鈹€ VFS proxy handler 鈹€鈹€鈹€
// 鎶?skill 鑴氭湰閲?`vfs.<method>(rel, ...)` 璺敱鍒扮湡姝ｇ殑 lib/vfs銆傛墍鏈夎矾寰刓n// 杩?resolveScopedPath 闄愬畾鍦ㄨ run 鐨?vfsRoot 鍐咃紙鐢?run-skill 鍚姩鏃惰绠楀ソ
// 骞朵繚瀛樺湪 pendingRuns 閲岋級锛宻andbox 鑷繁鏃犳硶褰卞搷浣滅敤鍩熴€俓n// `stat` 鐨勮繑鍥炲€煎甫鏂规硶锛岀粨鏋勫寲鍏嬮殕浼氫涪锛岄渶瑕?flatten 鎴愮函瀵硅薄銆俓nasync function handleVfsCall(msg: {
  id: string;
  callId: string;
  method: string;
  args: unknown[];
}): Promise<void> {
  let result: unknown;
  let error: string | undefined;

  try {
    // 鍙嶆煡鏉冨▉ scope / permissions 鈥斺€?sandbox 閭ｄ晶鐨?message envelope 涓嶅彲淇°€俓n    const pending = pendingRuns.get(msg.id);
    if (!pending) {
      throw new Error('vfs call has no matching pending run (timed out or replayed)');
    }
    if (!pending.vfsRoot) {
      // 涓嶅彲杈惧垎鏀細sandbox 渚嬩互鏈０鏄?vfs.* 鏉冮檺鏃舵牴鏈笉浼氭瀯閫?vfs proxy锛岃蛋
      // 鍒拌繖閲岃鏄庝腑闂存煇涓€涓嶅彲淇＄幆鑺傝绡℃敼銆傛姤鍑?internal 鏍囪浠ュ厤 agent 鎶婅繖
      // 褰撴垚鍙搷浣滅殑鎻愮ず浼犲洖鐢ㄦ埛銆俓n      throw new Error('internal: vfs call received without scope (sandbox-rpc / offscreen relay tampering)');
    }
    if (!isVfsCallAllowed(msg.method, pending.permissions)) {
      throw new Error(`vfs.${msg.method} not allowed (requires vfs.read or vfs.write permission)`);
    }
    if (!Array.isArray(msg.args) || msg.args.length === 0) {
      throw new Error(`vfs.${msg.method} requires at least a path argument`);
    }

    // `chrome.runtime.sendMessage` 鍦?offscreen 鈫?background 杩欎竴璺宠蛋 JSON
    // 搴忓垪鍖栵紝sandbox 涓€渚у凡缁忔妸 Uint8Array / ArrayBuffer 鍖呮垚 base64 淇″皝锛沑n    // 杩欓噷閫愰」杩樺師鎴愬師鐢?Uint8Array 鍐嶄紶缁?vfs銆俓n    const callArgs = decodeBinaryArgs(msg.args);
    const rel = callArgs[0];
    const absPath = resolveScopedPath(rel, pending.vfsRoot);

    switch (msg.method) {
      case 'readFile': {
        // encoding 鍙傛暟鍘熸牱閫忎紶缁?vfs.readFile 鈥斺€?鏀寔 `'utf8'` / undefined /
        // `{ encoding: 'utf8' }` 涓夌褰㈠紡锛堣窡 Node `fs.promises` 涓€鑷达級銆備笉娉曠殑
        // encoding 鐢?lightning-fs / vfs 搴曞眰鎶?EINVAL锛屼笉鍦ㄨ繖涓€灞傛壂璇箟銆俓n        result = await vfs.readFile(absPath, callArgs[1] as 'utf8' | { encoding?: 'utf8' } | undefined);
        break;
      }
      case 'writeFile': {
        // skill 甯歌鏁版嵁鏉ユ簮锛歚new TextEncoder().encode(...)` 鈫?Uint8Array锛孿n        // `await response.arrayBuffer()` 鈫?ArrayBuffer銆備袱绉嶉兘鎺ワ紝鍓嶈€呭凡鏄痋n        // Uint8Array 鐩存帴璧帮紱鍚庤€呭寘涓€灞傝鍥俱€俿tring 鐩存帴閫忎紶銆備换浣曞彟澶栫殑
        // `opts` 锛堢涓変釜鍙傦級涔熼€忎紶缁?vfs.writeFile锛屼笉鍦ㄨ繖閲屾敹钘忋€俓n        const data = callArgs[1];
        let normalized: string | Uint8Array;
        if (typeof data === 'string' || data instanceof Uint8Array) {
          normalized = data;
        } else if (data instanceof ArrayBuffer) {
          normalized = new Uint8Array(data);
        } else {
          throw new Error('vfs.writeFile data must be a string, Uint8Array, or ArrayBuffer');
        }
        await vfs.writeFile(absPath, normalized, callArgs[2] as 'utf8' | { encoding?: 'utf8'; mode?: number } | undefined);
        result = undefined;
        break;
      }
      case 'mkdir': {
        // Caller 浼犲叆鐨?opts 閫忎紶缁?vfs.mkdir锛涙湭浼犳椂榛樿 `{ recursive: true }`
        // 璺熼」鐩叾浠?fs 宸ュ叿锛坒s_mkdir / writeFile 鑷姩寤虹埗鐩綍锛変綋楠屼竴鑷达紱
        // 鏄惧紡浼?`{ recursive: false }` 鑳借鐢ㄦ潵鎺㈡祴鐩綍瀛樺湪銆俓n        const mkdirOpts = (callArgs[1] as { recursive?: boolean; mode?: number } | undefined) ?? { recursive: true };
        await vfs.mkdir(absPath, mkdirOpts);
        result = undefined;
        break;
      }
      case 'readdir': {
        result = await vfs.readdir(absPath);
        break;
      }
      case 'stat': {
        const st = await vfs.stat(absPath);
        // Flatten 鈥斺€?鏂规硶灞炴€х粨鏋勫寲鍏嬮殕浼氫涪銆俓n        result = {
          size: st.size,
          mtimeMs: st.mtimeMs,
          isFile: st.isFile(),
          isDirectory: st.isDirectory(),
        };
        break;
      }
      case 'exists': {
        result = await vfs.exists(absPath);
        break;
      }
      case 'unlink': {
        await vfs.unlink(absPath);
        result = undefined;
        break;
      }
      default:
        throw new Error(`Unknown vfs method: ${msg.method}`);
    }
  } catch (err) {
    error = (err as Error).message;
  }

  await chrome.runtime.sendMessage({
    type: 'sandbox:vfs_result',
    id: msg.id,
    callId: msg.callId,
    // 鍙嶅悜鍚屾牱瑕佽繃 JSON 閫氶亾 鈥斺€?readFile 鍦ㄤ簩杩涘埗妯″紡涓嬭繑鍥?Uint8Array锛孿n    // 杩欓噷鍖呮垚 base64 淇″皝锛宻andbox 涓€渚х敤 decodeBinary 杩樺師銆俓n    result: encodeBinary(result),
    error,
  }).catch(() => {});
}

// 鈹€鈹€鈹€ bgFetch handler 鈹€鈹€鈹€
// 璺敱鍒?lib/tools/bg-fetch.ts锛沺atterns / abort signal 閮戒粠 pendingRuns 鍙嶆煡锛孿n// sandbox envelope 閲岀殑瀛楁鍙槸鏁版嵁杞戒綋锛屼笉鍙備笌鏉冮檺鍐崇瓥銆俓n
async function handleBgFetchCall(msg: {
  id: string;
  callId: string;
  url: unknown;
  init: unknown;
}): Promise<void> {
  let result: unknown;
  let error: string | undefined;

  try {
    const pending = pendingRuns.get(msg.id);
    if (!pending) {
      throw new Error('bgFetch call has no matching pending run (timed out or replayed)');
    }
    if (!pending.bgFetchPatterns) {
      // 涓嶅彲杈撅細sandbox 鏈０鏄?bgFetch 鏃舵牴鏈笉鏋勯€?bgFetch global銆俓n      throw new Error('internal: bgFetch call received without patterns (sandbox-rpc / offscreen relay tampering)');
    }

    // init.body 鍙兘鏄?binary envelope锛屽厛瑙ｅ寘鍐嶄氦缁?handler锛涜繖閲岃В鍖呮暣涓?init
    // 椤跺眰瀛楁锛坔eaders / body 绛夛級锛屼絾鍙湁 body 鐪熺殑浼氬甫 binary銆俓n    let normalizedInit: unknown = msg.init;
    if (msg.init && typeof msg.init === 'object') {
      const src = msg.init as Record<string, unknown>;
      if (src.body !== undefined) {
        normalizedInit = { ...src, body: decodeBinary(src.body) };
      }
    }

    const raw = await handleBgFetch(
      msg.url,
      normalizedInit,
      pending.bgFetchPatterns,
      pending.abortCtrl.signal,
    );

    // body 鍙嶅悜鍐嶈蛋 binary envelope 鎵嶈兘杩?chrome.runtime.sendMessage 杩欎竴璺炽€俓n    result = {
      status: raw.status,
      statusText: raw.statusText,
      redirected: raw.redirected,
      url: raw.url,
      headersFlat: raw.headersFlat,
      body: encodeBinary(raw.body),
    };
  } catch (err) {
    error = (err as Error).message;
  }

  await chrome.runtime.sendMessage({
    type: 'sandbox:bg_fetch_result',
    id: msg.id,
    callId: msg.callId,
    result,
    error,
  }).catch(() => {});
}

// 鈹€鈹€鈹€ Public API 鈹€鈹€鈹€

const SANDBOX_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes

/**
 * Execute a skill script in the sandbox page.
 * Manages the full lifecycle: ensure offscreen 鈫?send to sandbox 鈫?await result.
 *
 * `skill` + `sessionId` 鐢?run-skill.ts 娉ㄥ叆銆傚鏋?permissions 鍚?vfs.* 浠讳竴妗ｏ紝
 * 杩欓噷涓€娆℃€х畻鍑鸿 run 鐨?`vfsRoot`锛涘惈 bgFetch 浠讳竴妗ｅ垯瑙ｆ瀽 patterns銆俓n * 浜岃€呴兘瀛樿繘 pendingRuns 缁欏搴?handler 鍙嶆煡 鈥斺€?sandbox 鑷繁涓嶆寔鏈?涓嶈兘浼€犱綔鐢ㄥ煙銆俓n *
 * Pattern 瑙ｆ瀽澶辫触鏃?*绔嬪嵆鎶涢敊**锛堜笉绛?skill 绗竴娆¤皟鐢?bgFetch锛夛紝璁╂潈闄愬０鏄嶾n * 鐨?typo 鍦?run_skill 鍚姩鏃跺氨鏆撮湶銆俓n */
export async function runInSandbox(
  code: string,
  args: Record<string, unknown>,
  permissions: string[],
  skill: string,
  sessionId: string,
  tabId?: number,
): Promise<unknown> {
  await ensureOffscreen();

  const id = crypto.randomUUID();

  // 璁＄畻 vfsRoot 鈥斺€?鍙湁鍦ㄦ樉寮忓０鏄庝簡 vfs.* 鏃舵墠鏈夋剰涔夈€俓n  // 鏍￠獙澶辫触锛堟棤鏁?sessionId / 鏃犳晥 skill锛夌洿鎺ユ姏锛屽惁鍒欓敊璇細寤惰繜鍒?skill 璋冪敤
  // vfs.* 鏃舵墠鏆撮湶锛岃皟璇曟洿闅俱€俓n  const wantsVfs = permissions.includes('vfs.read') || permissions.includes('vfs.write');
  const vfsRoot = wantsVfs ? sessionSkillRoot(sessionId, skill) : null;

  // 鍚岀悊锛氳В鏋?bgFetch patterns锛沵alformed pattern 绔嬪嵆鎶涖€俓n  const bgFetchPatterns = parseBgFetchPatterns(permissions);

  const abortCtrl = new AbortController();
  const resultPromise = new Promise<unknown>((resolve, reject) => {
    const timeoutId = setTimeout(() => {
      if (pendingRuns.has(id)) {
        pendingRuns.delete(id);
        abortCtrl.abort(new Error('Sandbox execution timed out (5 min)'));
        reject(new Error('Sandbox execution timed out (5 min)'));
      }
    }, SANDBOX_TIMEOUT_MS);

    pendingRuns.set(id, {
      resolve, reject, timeoutId,
      vfsRoot, permissions, bgFetchPatterns, abortCtrl,
    });
  });

  // Send to offscreen (which relays to sandbox iframe)
  try {
    await chrome.runtime.sendMessage({
      type: 'sandbox:run',
      id,
      code,
      args,
      permissions,
      // sandbox 鍙敤 vfsRoot 鏉ユ毚闇?`vfs.cwd`锛涚湡姝ｇ殑浣滅敤鍩熸牎楠屽湪 background銆俓n      vfsRoot,
      tabId,
    });
  } catch (err) {
    const pending = pendingRuns.get(id);
    if (pending) {
      clearTimeout(pending.timeoutId);
      pendingRuns.delete(id);
    }
    throw err;
  }

  return resultPromise;
}

/**
 * Smart Interact 宸ュ叿 鈥?灏佽 interact锛屼紭鍏堣蛋 API 璺緞锛屽け璐ュ洖閫€ DOM銆俓n */

import { Type } from 'typebox';
import type { AgentTool, AgentToolResult } from '@earendil-works/pi-agent-core';
import { executeApiFirst, NoMatchError } from '@/lib/capture/api-executor';
import { interactTool } from './interact';

const smartInteractSchema = Type.Object({
  tabId: Type.Integer({ description: '鐩爣鏍囩椤?ID' }),
  action: Type.Union([
    Type.Literal('click'),
    Type.Literal('type'),
    Type.Literal('select'),
    Type.Literal('scroll'),
    Type.Literal('keypress'),
    Type.Literal('api_submit'),
    Type.Literal('api_fill_form'),
  ], { description: '鎿嶄綔绫诲瀷銆俛pi_submit/api_fill_form 璧?API 浼樺厛璺緞' }),
  url: Type.Optional(Type.String({ description: '褰?action=api_* 鏃讹紝鐩爣 API URL' })),
  intent: Type.Optional(Type.String({ description: '鎿嶄綔鎰忓浘鎻忚堪' })),
  data: Type.Optional(Type.Record(Type.String(), Type.Unknown(), { description: 'API 璇锋眰浣撴暟鎹? })),
  selector: Type.Optional(Type.String({ description: 'CSS 閫夋嫨鍣紙DOM 鍥為€€鏃朵娇鐢級' })),
  text: Type.Optional(Type.String({ description: '杈撳叆鏂囨湰锛圖OM 鍥為€€鏃朵娇鐢級' })),
});

export const smartInteractTool: AgentTool<typeof smartInteractSchema> = {
  name: 'smart_interact',
  label: 'Smart Interact',
  description: 'Interact with page. api_submit/api_fill_form try API-first, fall back to DOM.',
  parameters: smartInteractSchema,
  execute: async (_toolCallId, params) => {
    const { tabId, action, url, intent, data, selector, text } = params;

    if ((action === 'api_submit' || action === 'api_fill_form') && url) {
      try {
        const method = action === 'api_submit' ? 'POST' : 'GET';
        const result = await executeApiFirst(url, method, intent, data);

        return {
          content: [{
            type: 'text' as const,
            text: JSON.stringify({
              success: true,
              path: 'api',
              response: result.data,
              latency_ms: result.latencyMs,
              skill_id: result.skillName,
              confidence: result.confidence,
            }, null, 2),
          }],
          details: {},
        } satisfies AgentToolResult<any>;
      } catch (err) {
        if (err instanceof NoMatchError) {
          const fallbackAction = action === 'api_submit' ? 'click' : 'type';
          const fallback = await interactTool.execute(_toolCallId, {
            tabId,
            action: fallbackAction as 'click' | 'type',
            selector,
            text,
          });
          if (fallback.content[0]?.type === 'text') {
            return {
              ...fallback,
              content: [{
                type: 'text' as const,
                text: `[fallback: ${err.message}]\n\n${fallback.content[0].text}`,
              }],
            };
          }
          return fallback;
        }
        throw err;
      }
    }

    return interactTool.execute(_toolCallId, { tabId, action: action as 'click' | 'type' | 'select' | 'scroll' | 'keypress', selector, text });
  },
};

/**
 * Smart Read Page 宸ュ叿 鈥?灏佽 read_page锛屼紭鍏堣蛋 API 璺緞锛屽け璐ュ洖閫€ DOM銆俓n */

