import { Type } from 'typebox';
import type { AgentTool, AgentToolResult } from '@earendil-works/pi-agent-core';
import { TOOL_TAB } from '@/lib/types';

// 鈹€鈹€鈹€ Parameters: single flat object (OpenAI requires top-level "type": "object") 鈹€鈹€鈹€

const TabParameters = Type.Object({
  action: Type.Union([
    Type.Literal('open'), Type.Literal('close'), Type.Literal('switch'),
    Type.Literal('reload'), Type.Literal('list_frames'),
  ], { description: 'The tab action to perform.' }),
  url: Type.Optional(Type.String({
    description: 'URL to open. Required for "open" action (http/https only).',
  })),
  tabId: Type.Optional(Type.Number({
    description: 'Tab ID. Required for "close", "switch", "reload", and "list_frames". Ignored for "open". Read it from the `tabId:` line under `[Active Tab]` (or the windows list) in the context block.',
  })),
  windowId: Type.Optional(Type.Number({
    description: 'Window ID for the "open" action. Omit to use the current focused window. Get window IDs from the context block.',
  })),
});

// 鈹€鈹€鈹€ Tool definition 鈹€鈹€鈹€

export const tabTool: AgentTool<typeof TabParameters> = {
  name: TOOL_TAB,
  label: 'Manage Tab',
  description:
    'Manage browser tabs: open a new tab (http/https only, optionally in a specific window via windowId), ' +
    'close a tab, switch to a tab, reload, ' +
    'or list all frames (including iframes) in a tab. ' +
    'Use the tab list from the context block to find tab IDs and window IDs.',
  parameters: TabParameters,

  async execute(_toolCallId, params, signal): Promise<AgentToolResult<{}>> {
    signal?.throwIfAborted();

    switch (params.action) {
      case 'open': {
        if (!params.url) {
          throw new Error('"url" is required for open action.');
        }
        let parsed: URL;
        try {
          parsed = new URL(params.url);
        } catch {
          throw new Error(`Invalid URL for tab open: ${params.url}`);
        }
        if (!['http:', 'https:'].includes(parsed.protocol)) {
          throw new Error(`Only http/https URLs are allowed. Got: ${parsed.protocol}`);
        }
        const createProps: chrome.tabs.CreateProperties = { url: params.url };
        if (params.windowId != null) {
          try {
            await chrome.windows.get(params.windowId);
          } catch {
            throw new Error(`Window ${params.windowId} does not exist.`);
          }
          createProps.windowId = params.windowId;
        }
        const tab = await chrome.tabs.create(createProps);
        return {
          content: [{ type: 'text', text: `Opened new tab (id: ${tab.id}) in window ${tab.windowId}: ${params.url}` }],
          details: {},
        };
      }

      case 'close': {
        if (params.tabId == null) {
          throw new Error('"tabId" is required for close action.');
        }
        await chrome.tabs.remove(params.tabId);
        return {
          content: [{ type: 'text', text: `Closed tab: ${params.tabId}` }],
          details: {},
        };
      }

      case 'switch': {
        if (params.tabId == null) {
          throw new Error('"tabId" is required for switch action.');
        }
        await chrome.tabs.update(params.tabId, { active: true });
        const tab = await chrome.tabs.get(params.tabId);
        return {
          content: [{ type: 'text', text: `Switched to tab: ${tab.title ?? tab.url}` }],
          details: {},
        };
      }

      case 'reload': {
        if (params.tabId == null) {
          throw new Error('"tabId" is required for reload action.');
        }
        await chrome.tabs.reload(params.tabId);
        return {
          content: [{ type: 'text', text: `Reloaded tab: ${params.tabId}` }],
          details: {},
        };
      }

      case 'list_frames': {
        if (params.tabId == null) {
          throw new Error('"tabId" is required for list_frames action.');
        }
        const tabId = params.tabId;
        const results = await (chrome.scripting.executeScript as any)({
          target: { tabId, allFrames: true },
          func: () => ({
            url: window.location.href,
            title: document.title,
            isTop: window === window.top,
          }),
        });
        const frames = (results as chrome.scripting.InjectionResult[]).map(r => ({
          frameId: r.frameId,
          ...r.result,
        }));
        return {
          content: [{ type: 'text', text: JSON.stringify(frames, null, 2) }],
          details: {},
        };
      }

      default:
        throw new Error(`Unknown action: ${(params as { action?: string }).action}`);
    }
  },
};

/**
 * Human-readable labels for tool calls based on tool name + arguments.
 * Used by ToolCard to show concise descriptions instead of raw tool names.
 */

import { t } from '@/lib/i18n';

export function getToolLabel(name: string, args: Record<string, any> = {}): string {
  // MCP tools: name is `mcp__<slug>__<remoteToolName>`. Parse and prettify;
  // we don't have the original server name (slug is lossy: lowercase + `_`),
  // so we surface the slug with underscores 鈫?spaces, which is good enough
  // for users who recognize their own server names.
  if (name.startsWith('mcp__')) {
    const rest = name.slice(5); // strip "mcp__"
    const sep = rest.indexOf('__');
    if (sep > 0) {
      const slug = rest.slice(0, sep).replace(/_/g, ' ');
      const tool = rest.slice(sep + 2);
      return t('tools.mcpCall', [slug, tool]);
    }
  }
  switch (name) {
    case 'read_page': {
      const mode = args.mode ?? 'markdown';
      const detail = args.selector ? `${mode}, ${args.selector}` : mode;
      return t('tools.readPage', [detail]);
    }
    case 'execute_js':
      return t('tools.executeJs');
    case 'interact':
      return getInteractLabel(args);
    case 'inspect':
      return getInspectLabel(args);
    case 'tab':
      return getTabLabel(args);
    case 'screenshot':
      return t('tools.screenshot');
    case 'pdf':
      return getPdfLabel(args);
    case 'ask_user':
      return t('tools.askUser');
    case 'fs_create_file':
      return t('tools.fs.createFile', [truncPath(args.path)]);
    case 'fs_edit_file':
      return t('tools.fs.editFile', [truncPath(args.path)]);
    case 'fs_mkdir':
      return t('tools.fs.mkdir', [truncPath(args.path)]);
    case 'fs_rename':
      return t('tools.fs.rename', [truncPath(args.old_path)]);
    case 'fs_delete':
      return t('tools.fs.delete', [truncPath(args.path)]);
    case 'fs_read_file':
      return t('tools.fs.readFile', [truncPath(args.path)]);
    case 'fs_list':
      return t('tools.fs.list', [truncPath(args.path)]);
    case 'fs_search':
      return args.mode === 'content'
        ? t('tools.fs.searchContent', [truncPath(args.pattern)])
        : t('tools.fs.searchFiles', [truncPath(args.pattern)]);
    case 'fs_save_url':
      return t('tools.fs.saveUrl', [truncPath(args.dest)]);
    case 'run_skill':
      return t('tools.runSkill', [args.skill ?? '']);
    case 'chrome_api':
      if (args.namespace === 'help') return t('tools.chromeApi.help');
      return t('tools.chromeApi.call', [args.namespace ?? '', args.method ?? '']);
    default:
      return name;
  }
}

function truncPath(p?: string): string {
  if (!p) return '';
  return p.length > 30 ? '...' + p.slice(-27) : p;
}

function getInteractLabel(args: Record<string, any>): string {
  const target = args.selector
    ? ` ${args.selector}`
    : (args.x != null ? ` (${args.x}, ${args.y})` : '');
  const truncTarget = target.length > 40 ? target.slice(0, 37) + '...' : target;

  switch (args.action) {
    case 'click': return t('tools.interact.click', [truncTarget]);
    case 'dblclick': return t('tools.interact.dblclick', [truncTarget]);
    case 'rightclick': return t('tools.interact.rightclick', [truncTarget]);
    case 'hover': return t('tools.interact.hover', [truncTarget]);
    case 'focus': return t('tools.interact.focus', [truncTarget]);
    case 'type': return t('tools.interact.type', [truncTarget]);
    case 'clear': return t('tools.interact.clear', [truncTarget]);
    case 'select': return t('tools.interact.select', [truncTarget]);
    case 'scroll': return t('tools.interact.scroll');
    case 'keypress': return t('tools.interact.keypress', [args.key ?? '']);
    case 'wait': return t('tools.interact.wait', [truncTarget]);
    case 'wait_hidden': return t('tools.interact.waitHidden', [truncTarget]);
    case 'wait_navigation': return t('tools.interact.waitNavigation');
    case 'sequence': return t('tools.interact.sequence', [args.steps?.length ?? 0]);
    default: return t('tools.interact.unknown', [args.action ?? 'unknown']);
  }
}

function getInspectLabel(args: Record<string, any>): string {
  if (args.selector) {
    const sel = args.selector.length > 40 ? args.selector.slice(0, 37) + '...' : args.selector;
    return t('tools.inspect.selector', [sel]);
