 * skill 璋冪敤鏂瑰啓 `'cat.png'` 鎴?`'subdir/cat.png'`锛岃惤鍦拌矾寰勪細鏄痋n * `<root>/cat.png` 鎴?`<root>/subdir/cat.png`銆俓n */
export function resolveScopedPath(rel: unknown, root: string): string {
  if (typeof rel !== 'string') {
    throw new Error('vfs path must be a string');
  }
  // 鎷掔粷缁濆璺緞 / ~ 璧锋墜 鈥斺€?skill 鍙兘浼犵浉瀵硅矾寰勩€俓n  if (rel.startsWith('/') || rel === '~' || rel.startsWith('~/') || rel.startsWith('~\\')) {
    throw new Error(`vfs path must be relative to skill workspace, got: ${rel}`);
  }
  const candidate = normalizePath(`${root}/${rel}`);
  // candidate === root 鏄悎娉曟儏鍐碉紙濡?readdir('.')锛夛紱鍙嫤瀹為檯瓒婄晫銆俓n  if (candidate !== root && !candidate.startsWith(root + '/')) {
    throw new Error(`vfs path escapes skill workspace: ${rel}`);
  }
  return candidate;
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Runtime safety net for cross-chunk ReferenceError:
// When Rolldown code-splitting separates this module into its own chunk
// (utils-*.js), consumer chunks (e.g. MarkdownRenderer) that call cn()
// may lose the ES module import during optimization while the call site
// remains 鈥?causing "ReferenceError: cn is not defined".
// By registering on globalThis here AND in sidepanel-error-boundary.js,
// we guarantee cn() is always available regardless of chunk loading order.
if (typeof globalThis !== 'undefined') {
  (globalThis as any).__cebCn ??= cn;
}

/** Compact character-count formatter for UI tooltips: `999`, `1.2K`, `3.4M`.
 *  Drops trailing `.0` so `1000 鈫?1K`, not `1.0K`. Negatives are clamped to 0. */
export function formatCharCount(n: number): string {
  const v = Math.max(0, Math.floor(n));
  if (v < 1000) return String(v);
  const fmt = (x: number) => x.toFixed(1).replace(/\.0$/, '');
  if (v < 1_000_000) return `${fmt(v / 1000)}K`;
  return `${fmt(v / 1_000_000)}M`;
}

/** Format a millisecond duration as `M:SS` (or `H:MM:SS` past one hour). */
export function formatDuration(ms: number): string {
  const totalSec = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  const pad = (n: number) => (n < 10 ? `0${n}` : String(n));
  if (h > 0) return `${h}:${pad(m)}:${pad(s)}`;
  return `${m}:${pad(s)}`;
}

/** Short random id for collision-tolerant uses (event ids, filename suffixes,
 *  cache-buster keys). NOT a UUID 鈥?don't use for security or anything that
 *  must be globally unique. Default base is 36 (alphanumeric). */
export function randomId(length = 8, base: 16 | 36 = 36): string {
  let out = '';
  while (out.length < length) {
    out += Math.random().toString(base).slice(2);
  }
  return out.slice(0, length);
}

/** Trigger a browser download of `content` as a file named `name` with the
 *  given `mimeType`. Works for strings (JSON, text), Blobs, and ArrayBuffers.
 *  The object URL is revoked after a short delay so the download can start. */
export function downloadFile(name: string, content: string | Blob | ArrayBuffer, mimeType: string): void {
  const blob = content instanceof Blob ? content : new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/** Escape `&` and `<` (and `"` when `forAttribute: true`) for safe inclusion
 *  in XML. Use the default for element text content; pass `{forAttribute:true}`
 *  for attribute values.
 *
 *  `>` is intentionally left raw in most cases 鈥?XML 搂2.4 only requires it
 *  escaped in character data when it forms the sequence `]]>`, which we
 *  handle explicitly below. Keeping raw `>` saves noticeable tokens on
 *  selector-heavy payloads like recording bodies.
 *
 *  Attribute mode assumes the caller wraps values in double quotes (we
 *  never emit single-quoted attributes); `'` is therefore not escaped.
 *
 *  Order matters: `&` must come first so we don't double-escape the
 *  entities we just produced. */
export function escapeXml(s: string, opts?: { forAttribute?: boolean }): string {
  let out = s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/]]>/g, ']]&gt;');
  if (opts?.forAttribute) out = out.replace(/"/g, '&quot;');
  return out;
}

/** Reverse `escapeXml`. Still decodes `&gt;` so older payloads round-trip
 *  correctly, even though the current encoder no longer produces it. Order
 *  matters: `&amp;` must come last to avoid corrupting entity sequences that
 *  contain a literal `&` (e.g. text that originally said `&amp;lt;`). */
export function unescapeXml(s: string): string {
  return s
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

/** Escape regex metacharacters in a string so it can be embedded inside a
 *  `RegExp` source as a literal match. Generic 鈥?no callers required to
 *  be source code-related. */
export function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Workflow Engine 鈥?Resumable execution with per-step persistence.
 *
 * MV3 Service Workers can be terminated at any time. This engine writes
 * the current run state to Dexie after every step so that on SW restart
 * we can detect incomplete runs and resume from the last completed step.
 */

import { executeWorkflow, type ExecutionResult, type ExecutorOptions } from './executor';
import type { Workflow, WorkflowRunState } from './types';
import {
  createRunState,
  updateRunState,
  getWorkflow,
} from './repository';

// 鈹€鈹€鈹€ Public API 鈹€鈹€鈹€

/**
 * Start a new workflow run with automatic state persistence.
 * Returns the execution result together with the generated runId.
 */
export async function startWorkflowRun(
  workflow: Workflow,
  options?: Pick<ExecutorOptions, 'tabId' | 'signal' | 'onStepStart' | 'onStepEnd' | 'variables'>,
): Promise<ExecutionResult & { runId: string }> {
  const runId = crypto.randomUUID();

  // 鍚堝苟鍙橀噺锛歸orkflow.variables < options.variables
  const variables = { ...workflow.variables, ...options?.variables };

  await createRunState({
    workflowId: workflow.id,
    runId,
    status: 'running',
    currentStepIndex: 0,
    variables,
    startedAt: Date.now(),
  });

  const result = await executeWorkflow(workflow, {
    ...options,
    variables,
    onStepStart: (_step, index) => {
      void updateRunState(runId, {
        currentStepIndex: index,
        status: 'running',
      });
    },
    onStepEnd: (_step, index, stepResult) => {
      if (stepResult.success) {
        void updateRunState(runId, {
          currentStepIndex: index + 1,
          status: 'running',
          variables: stepResult.variables,
        });
      }
    },
  });

  await updateRunState(runId, {
    status: result.success ? 'success' : 'failure',
    endedAt: Date.now(),
    error: result.error,
    variables: result.variables,
  });

  return { ...result, runId };
}

/**
 * Resume a workflow from a previously persisted run state.
 * Used on Service Worker restart to recover interrupted runs.
 */
export async function resumeWorkflowRun(
  runState: WorkflowRunState,
): Promise<ExecutionResult & { runId: string }> {
  const workflow = await getWorkflow(runState.workflowId);
  if (!workflow) {
    throw new Error(`Workflow ${runState.workflowId} not found; cannot resume run ${runState.runId}`);
  }

  await updateRunState(runState.runId, {
    status: 'running',
  });

  const result = await executeWorkflow(workflow, {
    tabId: undefined, // rely on active tab when resuming
    startStepIndex: runState.currentStepIndex,
    variables: runState.variables,
    onStepStart: (_step, index) => {
      void updateRunState(runState.runId, {
        currentStepIndex: index,
        status: 'running',
      });
    },
    onStepEnd: (_step, index, stepResult) => {
      if (stepResult.success) {
        void updateRunState(runState.runId, {
          currentStepIndex: index + 1,
          status: 'running',
          variables: stepResult.variables,
        });
      }
    },
  });

  await updateRunState(runState.runId, {
    status: result.success ? 'success' : 'failure',
    endedAt: Date.now(),
    error: result.error,
    variables: result.variables,
  });

  return { ...result, runId: runState.runId };
}

/**
 * Check for any runs that were marked 'running' in the database and
 * attempt to resume them. Should be called once per Service Worker
 * startup (e.g. in background/index.ts).
 */
export async function recoverRunningWorkflows(): Promise<void> {
  const { listRunningStates } = await import('./repository');
  const states = await listRunningStates();
  if (states.length === 0) return;

  console.log('[WorkflowEngine] Recovering', states.length, 'interrupted workflow run(s)');

  for (const state of states) {
    try {
      await resumeWorkflowRun(state);
    } catch (err) {
      console.error('[WorkflowEngine] Failed to resume run', state.runId, err);
      // Mark as failed so we don't retry indefinitely on every SW boot
      const { updateRunState } = await import('./repository');
      await updateRunState(state.runId, {
        status: 'failure',
        endedAt: Date.now(),
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }
}

/**
 * Workflow Repository 鈥?鍩轰簬 Dexie 鐨?CRUD 涓庢煡璇㈠眰銆俓n *
 * 鎵€鏈夋搷浣滃潎涓哄紓姝ワ紝閿欒浠ユ姏鍑哄紓甯哥殑褰㈠紡浼犻€掋€俓n * 璋冪敤鏂瑰簲鑷澶勭悊 Dexie/DOMException銆俓n */

import { getDb } from '../db';
import type { Workflow, WorkflowStep, WorkflowRunStatus, WorkflowRunRecord, WorkflowRunStepRecord, WorkflowRunState } from './types';

// 鈹€鈹€鈹€ 楠岃瘉 鈹€鈹€鈹€

class WorkflowValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'WorkflowValidationError';
  }
}

function assertString(val: unknown, field: string): asserts val is string {
  if (typeof val !== 'string' || val.trim().length === 0) {
    throw new WorkflowValidationError(`${field} must be a non-empty string`);
  }
}

function assertArray(val: unknown, field: string): asserts val is unknown[] {
  if (!Array.isArray(val)) {
    throw new WorkflowValidationError(`${field} must be an array`);
  }
}

function assertStep(step: unknown): asserts step is WorkflowStep {
  if (typeof step !== 'object' || step === null) {
    throw new WorkflowValidationError('Step must be an object');
  }
  const s = step as Record<string, unknown>;
  if (typeof s.type !== 'string') {
    throw new WorkflowValidationError('Step must have a type field');
  }
  const validTypes = new Set([
    'navigate', 'click', 'type', 'select', 'scroll', 'keypress',
    'wait', 'wait_navigation', 'extract', 'focus', 'hover', 'dblclick', 'rightclick',
    'assert', 'if', 'export',
  ]);
  if (!validTypes.has(s.type)) {
    throw new WorkflowValidationError(`Unknown step type: ${s.type}`);
  }

  // 閫掑綊楠岃瘉 if 姝ラ鐨勫瓙姝ラ
  if (s.type === 'if') {
    if (typeof s.condition !== 'object' || s.condition === null) {
      throw new WorkflowValidationError('If step must have a condition object');
    }
    const cond = s.condition as Record<string, unknown>;
    if (typeof cond.variable !== 'string') {
      throw new WorkflowValidationError('If step condition must have a variable string');
    }
    const validOps = new Set(['eq', 'ne', 'contains', 'gt', 'lt']);
    if (typeof cond.operator !== 'string' || !validOps.has(cond.operator)) {
      throw new WorkflowValidationError(`If step condition operator invalid: ${cond.operator}`);
    }

    if (!Array.isArray(s.thenSteps)) {
      throw new WorkflowValidationError('If step must have a thenSteps array');
    }
    s.thenSteps.forEach((subStep: unknown, idx: number) => {
      try {
        assertStep(subStep);
      } catch (e) {
        throw new WorkflowValidationError(`If.thenSteps[${idx}] invalid: ${(e as Error).message}`);
      }
    });

    if (s.elseSteps !== undefined) {
      if (!Array.isArray(s.elseSteps)) {
        throw new WorkflowValidationError('If step elseSteps must be an array');
      }
      s.elseSteps.forEach((subStep: unknown, idx: number) => {
        try {
          assertStep(subStep);
        } catch (e) {
          throw new WorkflowValidationError(`If.elseSteps[${idx}] invalid: ${(e as Error).message}`);
        }
      });
    }
  }

  // 鏍￠獙 assert 鎿嶄綔绗n  if (s.type === 'assert') {
    const validAssertOps = new Set(['exists', 'not_exists', 'contains', 'eq', 'gt', 'lt']);
    if (typeof s.operator !== 'string' || !validAssertOps.has(s.operator)) {
      throw new WorkflowValidationError(`Assert operator invalid: ${s.operator}`);
    }
  }

  // 鏍￠獙 export 鐩爣
  if (s.type === 'export') {
    const validDestinations = new Set(['clipboard', 'csv', 'json']);
    if (typeof s.destination !== 'string' || !validDestinations.has(s.destination)) {
      throw new WorkflowValidationError(`Export destination invalid: ${s.destination}`);
    }
    if (s.variables !== undefined && !Array.isArray(s.variables)) {
      throw new WorkflowValidationError('Export variables must be an array of strings');
    }
  }
}

function toFlat(w: Workflow): import('../db').FlatWorkflow {
  return w as import('../db').FlatWorkflow;
}

function fromFlat(w: import('../db').FlatWorkflow): Workflow {
  return w as Workflow;
}

/** Validates Workflow structural integrity */
export function validateWorkflow(workflow: unknown): asserts workflow is Workflow {
  if (typeof workflow !== 'object' || workflow === null) {
    throw new WorkflowValidationError('Workflow must be an object');
  }
  const w = workflow as Record<string, unknown>;

  assertString(w.id, 'id');
  assertString(w.name, 'name');
  assertArray(w.steps, 'steps');
  w.steps.forEach((step, idx) => {
    try {
      assertStep(step);
    } catch (e) {
      throw new WorkflowValidationError(`Step[${idx}] invalid: ${(e as Error).message}`);
    }
  });

  if (typeof w.createdAt !== 'number' || w.createdAt <= 0) {
    throw new WorkflowValidationError('createdAt must be a positive integer timestamp');
  }
  if (typeof w.updatedAt !== 'number' || w.updatedAt <= 0) {
    throw new WorkflowValidationError('updatedAt must be a positive integer timestamp');
  }
  if (typeof w.runCount !== 'number' || w.runCount < 0) {
    throw new WorkflowValidationError('runCount must be a non-negative integer');
  }
}

// 鈹€鈹€鈹€ CRUD 鈹€鈹€鈹€

export async function createWorkflow(workflow: Workflow): Promise<void> {
  validateWorkflow(workflow);
  await getDb().workflows.add(toFlat(workflow));
}

export async function getWorkflow(id: string): Promise<Workflow | undefined> {
  if (!id) throw new WorkflowValidationError('id cannot be empty');
  const w = await getDb().workflows.get(id);
  return w ? fromFlat(w) : undefined;
}

export async function listWorkflows(): Promise<Workflow[]> {
  const items = await getDb().workflows.orderBy('updatedAt').reverse().toArray();
  return items.map(fromFlat);
}

export async function updateWorkflow(
  id: string,
  changes: Partial<Omit<Workflow, 'id' | 'createdAt'>>,
): Promise<void> {
  if (!id) throw new WorkflowValidationError('id cannot be empty');
  if (changes.steps) {
    assertArray(changes.steps, 'steps');
    changes.steps.forEach((step, idx) => {
      try {
        assertStep(step);
      } catch (e) {
        throw new WorkflowValidationError(`Step[${idx}] invalid: ${(e as Error).message}`);
      }
    });
  }
  await getDb().workflows.update(id, { ...changes, updatedAt: Date.now() } as any);
}

export async function deleteWorkflow(id: string): Promise<void> {
  if (!id) throw new WorkflowValidationError('id cannot be empty');
  await getDb().workflows.delete(id);
}

// 鈹€鈹€鈹€ 杩愯鐘舵€佹洿鏂?鈹€鈹€鈹€

export async function recordWorkflowRun(
  id: string,
  status: Extract<WorkflowRunStatus, 'success' | 'failure' | 'cancelled'>,
): Promise<void> {
  if (!id) throw new WorkflowValidationError('id cannot be empty');
  const workflow = await getDb().workflows.get(id);
  if (!workflow) throw new WorkflowValidationError(`Workflow ${id} does not exist`);

  await getDb().workflows.update(id, {
    runCount: workflow.runCount + 1,
    lastRunAt: Date.now(),
    lastRunStatus: status,
  } as any);
}

// 鈹€鈹€鈹€ 鏌ヨ杈呭姪 鈹€鈹€鈹€

export async function searchWorkflows(query: string): Promise<Workflow[]> {
  const q = query.trim().toLowerCase();
  if (!q) return listWorkflows();
  const all = await getDb().workflows.toArray();
  return all
    .filter(
      (w) =>
        w.name.toLowerCase().includes(q) ||
        (w.description ?? '').toLowerCase().includes(q),
    )
    .map(fromFlat);
}

export async function getMostUsedWorkflows(limit = 5): Promise<Workflow[]> {
  const items = await getDb().workflows.orderBy('runCount').reverse().limit(limit).toArray();
  return items.map(fromFlat);
}

