/**
 * 灏?RecordedSession 杞崲涓烘寔涔呭寲 Workflow銆俓n *
 * 澶嶇敤 session-to-sequence.ts 鐨勪紭鍖栭€昏緫锛屽皢 SequenceStep[] 浜屾鏄犲皠涓篭n * WorkflowStep[]锛屽苟濉厖 Workflow 鍏冩暟鎹紙id銆乶ame銆乼imestamp 绛夛級銆俓n */

import type { RecordedSession } from '@/lib/recorder/types';
import { sessionToSequence } from '@/lib/recorder/session-to-sequence';
import type { SequenceStep } from '@/lib/recorder/session-to-sequence';
import type { Workflow, WorkflowStep } from './types';

// 鈹€鈹€鈹€ SequenceStep 鈫?WorkflowStep 鈹€鈹€鈹€

/**
 * 灏嗗崟涓?SequenceStep 鏄犲皠涓?WorkflowStep銆俓n * 娉ㄦ剰锛歋equenceStep 涓殑 `clear` 浼氬悎骞跺埌鐩搁偦鐨?`type` 涓紝
 * 涓嶄細浣滀负鐙珛 WorkflowStep 杈撳嚭銆俓n */
function mapSequenceStep(step: SequenceStep): WorkflowStep | null {
  switch (step.action) {
    case 'click':
      return { type: 'click', selector: step.selector!, timeout: step.timeout };
    case 'type':
      return {
        type: 'type',
        selector: step.selector!,
        text: step.text!,
        clear: false,
        timeout: step.timeout,
      };
    case 'clear':
      // clear 鍦?WorkflowStep 涓笉鐙珛瀛樺湪锛岀敱鐩搁偦 type 鐨?clear: true 鎵胯浇
      return null;
    case 'select':
      return { type: 'select', selector: step.selector!, text: step.text!, timeout: step.timeout };
    case 'scroll':
      return { type: 'scroll', selector: step.selector, deltaX: step.deltaX, deltaY: step.deltaY };
    case 'keypress':
      return { type: 'keypress', selector: step.selector, key: step.key!, modifiers: step.modifiers };
    case 'wait':
      return { type: 'wait', selector: step.selector, timeout: step.timeout ?? 5000 };
    case 'wait_navigation':
      return { type: 'wait_navigation', timeout: step.timeout };
    case 'focus':
      return { type: 'focus', selector: step.selector! };
    case 'hover':
      return { type: 'hover', selector: step.selector! };
    case 'dblclick':
      return { type: 'dblclick', selector: step.selector! };
    case 'rightclick':
      return { type: 'rightclick', selector: step.selector! };
    default:
      return null;
  }
}

/**
 * 灏?SequenceStep[] 杞崲涓?WorkflowStep[]銆俓n * 鏍稿績宸紓澶勭悊锛歋equenceStep 涓殑 clear 鏄嫭绔嬪姩浣滐紝
 * WorkflowStep 灏嗗叾鍐呭寲涓?type 姝ラ鐨?clear 灞炴€с€俓n */
export function sequenceToWorkflowSteps(sequence: SequenceStep[]): WorkflowStep[] {
  const steps: WorkflowStep[] = [];
  let i = 0;
  while (i < sequence.length) {
    const curr = sequence[i];
    const next = sequence[i + 1];

    // 鍚堝苟鐩搁偦鐨?clear + type 瀵逛负鍗曚釜 TypeStep锛坈lear: true锛塡n    if (
      curr.action === 'clear' &&
      next?.action === 'type' &&
      curr.selector === next.selector
    ) {
      steps.push({
        type: 'type',
        selector: next.selector!,
        text: next.text!,
        clear: true,
        timeout: next.timeout,
      });
      i += 2;
      continue;
    }

    // 璺宠繃瀛ょ珛鐨?clear锛堟棤娉曞悎骞跺埌鐩搁偦 type锛塡n    if (curr.action === 'clear') {
      i++;
      continue;
    }

    const mapped = mapSequenceStep(curr);
    if (mapped) steps.push(mapped);
    i++;
  }
  return steps;
}

// 鈹€鈹€鈹€ RecordedSession 鈫?Workflow 鈹€鈹€鈹€

export type SessionToWorkflowOptions = {
  /** 鑷畾涔?Workflow 鍚嶇О锛岀己鐪佽嚜鍔ㄧ敓鎴?*/
  name?: string;
  /** 鑷畾涔夋弿杩?*/
  description?: string;
  /** 鏄惁鍖呭惈瀵艰埅姝ラ锛堥粯璁?true锛?*/
  includeNavigation?: boolean;
  /** 鏄惁鍖呭惈 mutation 姝ラ锛堥粯璁?false锛?*/
  includeMutations?: boolean;
};

/**
 * 浠?RecordedSession 鐢熸垚 Workflow銆俓n *
 * 娴佺▼锛歕n * 1. RecordedSession 鈫?SequenceStep[]锛堝鐢?sessionToSequence 浼樺寲閫昏緫锛塡n * 2. SequenceStep[] 鈫?WorkflowStep[]锛坈lear 鍚堝苟銆佸瓧娈垫槧灏勶級
 * 3. 濉厖 Workflow 鍏冩暟鎹甛n */
export function sessionToWorkflow(
  session: RecordedSession,
  options: SessionToWorkflowOptions = {},
): Workflow {
  const {
    name,
    description,
    includeNavigation = true,
    includeMutations = false,
  } = options;

  const sequence = sessionToSequence(session, {
    includeNavigation,
    includeMutations,
    smartOptimize: true,
  });

  const steps = sequenceToWorkflowSteps(sequence);
  const now = Date.now();

  // 鑷姩鐢熸垚鍚嶇О锛氬彇绗竴涓鑸?URL 鐨?hostname 鎴栭〉闈㈡爣棰榎n  const autoName = deriveWorkflowName(session);

  return {
    id: generateWorkflowId(),
    name: name?.trim() || autoName,
    description: description?.trim() || `Recorded on ${new Date(now).toLocaleString()}`,
    steps,
    trigger: { type: 'manual' },
    createdAt: now,
    updatedAt: now,
    runCount: 0,
  };
}

// 鈹€鈹€鈹€ 杈呭姪 鈹€鈹€鈹€

function generateWorkflowId(): string {
  return `wf-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

function deriveWorkflowName(session: RecordedSession): string {
  // 浼樺厛鍙栫涓€涓鑸簨浠剁殑 URL hostname
  const navEvent = session.events.find(
    (e) => e.kind === 'tab' && (e as any).event === 'navigated',
  );
  if (navEvent) {
    try {
      const url = new URL(navEvent.url);
      return `${url.hostname} Workflow`;
    } catch {
      // URL 瑙ｆ瀽澶辫触锛屽洖閫€
    }
  }
  // 鍥為€€锛氬彇绗竴涓簨浠剁殑 URL hostname
  if (session.events[0]) {
    try {
      const url = new URL(session.events[0].url);
      return `${url.hostname} Workflow`;
    } catch {
      // ignore
    }
  }
  return `Workflow ${new Date(session.startedAt).toLocaleDateString()}`;
}

/**
 * Trigger Manager 鈥?宸ヤ綔娴佽Е鍙戝櫒鐨勬敞鍐屻€佸尮閰嶄笌鎵ц銆俓n *
 * 褰撳墠鏀寔锛歕n * - manual: 鐢ㄦ埛鎵嬪姩鐐瑰嚮杩愯
 * - url: chrome.tabs.onUpdated URL 姝ｅ垯鍖归厤
 * - cron: chrome.alarms 瀹氭椂瑙﹀彂
 * - dom: Content Script MutationObserver 鍏冪礌鍑虹幇瑙﹀彂
 *
 * 娉ㄦ剰锛歁V3 Service Worker 鍙兘琚粓姝紝鐩戝惉鍣ㄥ湪 SW 閲嶅惎鏃惰嚜鍔ㄩ噸寤恒€俓n */

import type { Workflow } from './types';
import { listWorkflows } from './repository';
import { startWorkflowRun } from './engine';
import { getNextCronTime, isValidCron } from './cron-parser';

// 鈹€鈹€鈹€ 鐘舵€?鈹€鈹€鈹€

let urlTriggerInstalled = false;
let cronTriggerInstalled = false;
let domTriggerInstalled = false;
let activeUrlPatterns = new Map<string, { pattern: RegExp; workflowId: string }>();
let activeDomSelectors = new Map<string, { selector: string; workflowId: string }>();
const ALARM_PREFIX = 'cebian-cron-';

// 鈹€鈹€鈹€ URL 瑙﹀彂鍣?鈹€鈹€鈹€

/**
 * 瀹夎 chrome.tabs.onUpdated 鐩戝惉鍣ㄣ€俓n * 骞傜瓑锛氬娆¤皟鐢ㄤ笉浼氶噸澶嶆敞鍐屻€俓n */
export function installUrlTriggerListener(): void {
  if (urlTriggerInstalled) return;
  urlTriggerInstalled = true;

  chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
    if (changeInfo.status !== 'complete' || !tab.url) return;

    // 鎳掑姞杞藉尮閰嶈〃锛堥伩鍏嶅惎鍔ㄦ椂鍏ㄩ噺鏌ヨ锛塡n    if (activeUrlPatterns.size === 0) {
      await reloadUrlPatterns();
    }

    for (const { pattern, workflowId } of activeUrlPatterns.values()) {
      if (pattern.test(tab.url)) {
        console.log('[TriggerManager] URL match', tab.url, '鈫?, workflowId);
        await runWorkflowById(workflowId, tabId);
        // 涓€涓?URL 鍙尮閰嶇涓€涓伐浣滄祦
        break;
      }
    }
  });
}

/**
 * 浠庢暟鎹簱閲嶆柊鍔犺浇鎵€鏈?URL 瑙﹀彂鍣ㄦā寮忋€俓n */
export async function reloadUrlPatterns(): Promise<void> {
  activeUrlPatterns.clear();
  try {
    const workflows = await listWorkflows();
    for (const wf of workflows) {
      if (wf.trigger?.type === 'url') {
        const config = wf.trigger.config as { pattern: string } | undefined;
        if (config?.pattern) {
          try {
            activeUrlPatterns.set(wf.id, {
              pattern: new RegExp(config.pattern),
              workflowId: wf.id,
            });
          } catch {
            console.warn('[TriggerManager] Invalid URL pattern for workflow', wf.id, config.pattern);
          }
        }
      }
    }
  } catch (err) {
    console.error('[TriggerManager] Failed to reload URL patterns', err);
  }
}

/**
 * 鍦ㄤ繚瀛?鏇存柊宸ヤ綔娴佸悗锛屽埛鏂板搴旇Е鍙戝櫒銆俓n */
export async function refreshWorkflowTrigger(workflow: Workflow): Promise<void> {
  activeUrlPatterns.delete(workflow.id);
  activeDomSelectors.delete(workflow.id);
  await clearCronAlarm(workflow.id);
  if (workflow.trigger?.type === 'url') {
    const config = workflow.trigger.config as { pattern: string } | undefined;
    if (config?.pattern) {
      try {
        activeUrlPatterns.set(workflow.id, {
          pattern: new RegExp(config.pattern),
          workflowId: workflow.id,
        });
      } catch {
        console.warn('[TriggerManager] Invalid URL pattern', config.pattern);
      }
    }
  }
  if (workflow.trigger?.type === 'cron') {
    const config = workflow.trigger.config as { expression: string } | undefined;
    if (config?.expression && isValidCron(config.expression)) {
      await scheduleCronAlarm(workflow.id, config.expression);
    }
  }
  if (workflow.trigger?.type === 'dom') {
    const config = workflow.trigger.config as { selector: string } | undefined;
    if (config?.selector) {
      activeDomSelectors.set(workflow.id, {
        selector: config.selector,
        workflowId: workflow.id,
      });
    }
  }
  // Notify content scripts that DOM triggers may have changed
  if (workflow.trigger?.type === 'dom' || workflow.trigger === undefined) {
    void broadcastDomTriggersUpdated();
  }
}

// 鈹€鈹€鈹€ Cron 瑙﹀彂鍣?鈹€鈹€鈹€

function alarmName(workflowId: string): string {
  return `${ALARM_PREFIX}${workflowId}`;
}

async function clearCronAlarm(workflowId: string): Promise<void> {
  try {
    await chrome.alarms.clear(alarmName(workflowId));
  } catch {
    /* ignore */
  }
}

async function scheduleCronAlarm(workflowId: string, expression: string): Promise<void> {
  const next = getNextCronTime(expression);
  if (!next) {
    console.warn('[TriggerManager] Invalid cron expression', expression);
    return;
  }
  const delayMinutes = Math.max(1, Math.ceil((next.getTime() - Date.now()) / 60000));
  await chrome.alarms.create(alarmName(workflowId), { delayInMinutes: delayMinutes });
  console.log('[TriggerManager] Scheduled cron', workflowId, 'at', next.toISOString(), '(in', delayMinutes, 'min)');
}

/**
 * 瀹夎 chrome.alarms.onAlarm 鐩戝惉鍣ㄣ€俓n */
export function installCronTriggerListener(): void {
  if (cronTriggerInstalled) return;
  cronTriggerInstalled = true;

  chrome.alarms.onAlarm.addListener(async (alarm) => {
    if (!alarm.name.startsWith(ALARM_PREFIX)) return;
    const workflowId = alarm.name.slice(ALARM_PREFIX.length);
    console.log('[TriggerManager] Cron alarm fired', workflowId);
    await runWorkflowById(workflowId);

    // 閲嶆柊璋冨害涓嬩竴娆¤Е鍙慭n    try {
      const { getWorkflow } = await import('./repository');
      const wf = await getWorkflow(workflowId);
      if (wf?.trigger?.type === 'cron') {
        const config = wf.trigger.config as { expression: string } | undefined;
        if (config?.expression) {
          await scheduleCronAlarm(workflowId, config.expression);
        }
      }
    } catch (err) {
      console.error('[TriggerManager] Failed to reschedule cron', workflowId, err);
    }
  });
}

/**
 * 浠庢暟鎹簱閲嶆柊鍔犺浇鎵€鏈?Cron 瑙﹀彂鍣ㄣ€俓n */
export async function reloadCronAlarms(): Promise<void> {
  // 娓呴櫎鎵€鏈夊凡鏈夌殑 cron alarm
  const existing = await chrome.alarms.getAll();
  for (const alarm of existing) {
    if (alarm.name.startsWith(ALARM_PREFIX)) {
      await chrome.alarms.clear(alarm.name);
    }
  }

  try {
    const workflows = await listWorkflows();
    for (const wf of workflows) {
      if (wf.trigger?.type === 'cron') {
        const config = wf.trigger.config as { expression: string } | undefined;
        if (config?.expression && isValidCron(config.expression)) {
          await scheduleCronAlarm(wf.id, config.expression);
        }
      }
    }
  } catch (err) {
    console.error('[TriggerManager] Failed to reload cron alarms', err);
  }
}

// 鈹€鈹€鈹€ DOM 瑙﹀彂鍣?鈹€鈹€鈹€

/**
 * 瀹夎 chrome.runtime.onMessage 鐩戝惉鍣ㄤ互澶勭悊 DOM 瑙﹀彂鍣ㄧ浉鍏虫秷鎭€俓n * 骞傜瓑锛氬娆¤皟鐢ㄤ笉浼氶噸澶嶆敞鍐屻€俓n */
export function installDomTriggerListener(): void {
  if (domTriggerInstalled) return;
  domTriggerInstalled = true;

  chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
    if (typeof msg !== 'object' || msg === null) return false;

    // get_dom_triggers 鈥?content script queries active selectors
    if ((msg as any).type === 'get_dom_triggers') {
      void (async () => {
        // Lazy-load if empty (SW restart)
        if (activeDomSelectors.size === 0) {
          await reloadDomTriggers();
        }
        const triggers = Array.from(activeDomSelectors.values());
        sendResponse({ triggers });
      })();
      return true; // async response
    }

    // dom_trigger_fired 鈥?content script reports element appearance
    if ((msg as any).type === 'dom_trigger_fired') {
      const { workflowId, selector, url } = msg as {
        workflowId: string;
        selector: string;
        url?: string;
      };
      console.log('[TriggerManager] DOM trigger fired', selector, url ?? '', '->', workflowId);
      void runWorkflowById(workflowId);
      return false;
    }

    return false;
  });
}

/**
 * 浠庢暟鎹簱閲嶆柊鍔犺浇鎵€鏈?DOM 瑙﹀彂鍣ㄣ€俓n */
export async function reloadDomTriggers(): Promise<void> {
  activeDomSelectors.clear();
  try {
    const workflows = await listWorkflows();
    for (const wf of workflows) {
      if (wf.trigger?.type === 'dom') {
        const config = wf.trigger.config as { selector: string } | undefined;
        if (config?.selector) {
          activeDomSelectors.set(wf.id, {
            selector: config.selector,
            workflowId: wf.id,
          });
        }
      }
    }
  } catch (err) {
    console.error('[TriggerManager] Failed to reload DOM triggers', err);
  }
}

/**
 * 鍚戞墍鏈夊唴瀹硅剼鏈箍鎾?DOM 瑙﹀彂鍣ㄥ凡鏇存柊銆俓n */
async function broadcastDomTriggersUpdated(): Promise<void> {
  try {
    const tabs = await chrome.tabs.query({});
    const msg = { type: 'dom_triggers_updated' };
    for (const tab of tabs) {
      if (tab.id != null) {
        chrome.tabs.sendMessage(tab.id, msg).catch(() => {});
      }
    }
  } catch {
    // ignore
  }
}

// 鈹€鈹€鈹€ 鎵ц 鈹€鈹€鈹€

async function runWorkflowById(workflowId: string, tabId?: number): Promise<void> {
  try {
    const { getWorkflow } = await import('./repository');
    const wf = await getWorkflow(workflowId);
    if (!wf) return;
    await startWorkflowRun(wf, tabId ? { tabId } : undefined);
  } catch (err) {
    console.error('[TriggerManager] Workflow execution failed', workflowId, err);
  }
}

